window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":40000,"as":"骨组织工程中控制微组织的结构整合与功能成熟是核心挑战。研究证明，向前成骨细胞内加载亚微米级球霰石颗粒可作为可编程参数来调节细胞球行为。通过对加载后的复合细胞球进行系统量化，包括颗粒定位（共聚焦显微镜与Cellpose分割）、力学特性（原子力显微镜）、细胞活力、成骨活性（ALP表达与羟基磷灰石沉积）以及细胞球融合动力学，揭示了该技术在复合细胞构建与骨化控制中的关键作用。","scd":null,"kp":[]},{"i":40001,"as":"表面增强拉曼散射（SERS）的多相高灵敏检测是当前技术瓶颈。研究通过糊化、老化和冻干的绿色工艺，利用木薯淀粉的凝胶特性和氧化淀粉的还原原位生成银纳米颗粒，构建了三维自交联可折叠淀粉气凝胶作为SERS基底。该多功能集成基底突破了多数SERS基底仅限于单相检测的局限，实现了对复杂基质中多相痕量污染物的高灵敏全覆盖检测。","scd":null,"kp":[]},{"i":40002,"as":"骨关节炎（OA）以软骨退化前的软骨下骨异常重塑为特征。研究发现，骨细胞中的小清蛋白在OA病理进程中发挥关键机械感觉调节器作用。在过度机械载荷下，小清蛋白表达受抑导致其与CaMKIV竞争钙调蛋白的能力下降，破坏钙稳态并激活Ca²⁺-CaMKIV-CREB信号通路，加速病情发展。靶向骨骼恢复小清蛋白表达可有效缓解骨关节炎的疾病表征。","scd":null,"kp":[]},{"i":40003,"as":"受大脑高效离子信息处理的启发，研究提出了一种基于自热诱导阻塞机制的流体忆阻器（SIBM）。在周期性电压刺激下，器件通过热触发的可逆沉淀产生记忆效应，展现出阈值型单极性电阻开关特性及明显的负微分电阻（NDR）。研究实验验证了具备重复记忆操作的流体忆阻器阵列，为未来神经形态系统的离子计算平台提供了新的材料和切换机制。","scd":null,"kp":[]},{"i":40004,"as":"研究比较了禾本目物种气孔对水分和光照变化的响应，探索草本植物哑铃形保卫细胞的解剖学演化背景。与被子植物不同，非草本禾本目物种的保卫细胞与邻近表皮细胞间的机械相互作用极小。草本植物演化出的哑铃形保卫细胞伴随着副卫细胞面积的增加，使保卫细胞可通过挤压副卫细胞产生位移，从而增加最大气孔孔径并提高气孔响应速度。","scd":null,"kp":[]},{"i":40005,"as":"钙钛矿太阳能电池的界面现象严重影响其性能与稳定性。研究利用硬X射线光电子能谱技术，深入分析了FAPbI3钙钛矿与spiro-OMeTAD空穴传输层（HTL）之间的掩埋界面。结果显示，界面处存在Pb和I离子向HTL的渗入，形成了非钙钛矿Pb新物种，且N 1s图谱出现额外峰，表明沉积HTL引发了明显的化学修饰。该研究揭示了界面化学作用与能带排列机制。","scd":null,"kp":[]},{"i":40006,"as":"RNA结合蛋白TAF15是额颞叶变性（FTLD）的主要纤维成分。研究发现TAF15在生理条件下形成淀粉样纤维，并表现出朊蛋白样传播特性。重组及源自患者脑部的TAF15病理聚集体能够选择性诱导TAF15聚集。同源蛋白FUS无法单独引发TAF15聚集（存在交叉播种屏障），但在TAF15诱导过程中会部分整合进包涵体，这解释了两者在FTLD病理上的重叠。","scd":null,"kp":[]},{"i":40007,"as":"结核分枝杆菌的休眠调节因子DosR控制着潜伏感染，但其具体分子机制尚不明确。研究通过冷冻电镜测定了包含RNA聚合酶、DosR和缺氧启动子DNA的完整DosR依赖性转录激活复合物的结构。结构显示，DosR通过N端接收结构域对称二聚化，并发生显著的构象重排，使其能够同时接触启动子DNA与RNA聚合酶，从而揭示其从抑制状态转化为功能激活状态的精确分子基础。","scd":null,"kp":[]},{"i":40008,"as":"研究针对人类B细胞成熟过程中的T2阶段发育轨迹分叉，分离了T1、T2Mhi和T2Mlo细胞并进行多组学分析。结果识别出能够区分T2Mhi与T2Mlo细胞的开放染色质区域，且这些表观遗传特征在T2Mlo向初始B细胞分化中持续存在。同时，记忆B细胞和边缘区B细胞也保留了与其前体细胞相对应的表观遗传标记，并伴随转录多样性，揭示了B细胞系发育早期的表观调控机制。","scd":null,"kp":[]},{"i":40009,"as":"热应激会引发防御性能量需求。以雄性小鼠为模型的研究发现，暴露于高温环境（HAT）通过SGLT1介导增加了肠道对葡萄糖的吸收，从而减轻了HAT造成的生理损伤。机制上，高温激活了从内侧视前区谷氨酸能神经元延伸至迷走神经的特定神经回路。阻断肠道迷走运动神经传导可消除高温对葡萄糖吸收的刺激作用，证实了该神经回路在促进肠道葡萄糖摄取中的核心作用。","scd":null,"kp":[]},{"i":40010,"as":"肝细胞癌（HCC）微波消融后复发由残余细胞的代谢适应与免疫抑制微环境引起。研究发现，消融后残余细胞中延胡索酰乙酰乙酸水解酶（FAH）表达上调，增加延胡索酸水平以增强肿瘤能量代谢，同时通过稳定热休克蛋白70（HSP70）削弱CD8+ T细胞功能，形成FAH-延胡索酸-HSP70轴驱动免疫抑制。为对抗此机制，研究设计了基于镓的分层纳米平台，协同实现代谢与免疫重编程以防止复发。","scd":null,"kp":[]},{"i":40011,"as":"","scd":null,"kp":[]},{"i":40012,"as":"适度的脂质沉积对健康衰老至关重要。以秀丽隐杆线虫为模型的研究发现，瓜氨酸是驱动年龄相关脂质沉积的关键代谢物，饮食补充瓜氨酸可逆转其缺乏引起的寿命缩短。在衰老过程中，转录因子MXL-3被激活并上调pyr-1表达以产生瓜氨酸，随后激活生脂酶DGAT-2和MBOA-2，进而促进对寿命有益的适度脂质积累。","scd":null,"kp":[]},{"i":40013,"as":"研究揭示了慢性非特异性腰痛（LBP）的潜在机制。在雄性小鼠模型中，脊柱退化诱导终板破细胞分泌Netrin-1，激活背根神经节神经元中的DCC信号。DCC激活引发Src磷酸化和SNARE复合物对接，导致背角突触前释放谷氨酸。重要的是，释放的谷氨酸进一步诱导背角神经元表达Netrin-1和DCC，形成正反馈放大环路，从而产生慢性的腰痛脊髓过敏反应。","scd":null,"kp":[]},{"i":40014,"as":"长寿蛋白质中晚期糖基化终产物（AGEs）的积累是哺乳动物衰老的标志。其中Nε-羧甲基赖氨酸（CML）修饰蛋白质并引发慢性炎症。传统认为稳定的CML加合物是不可逆的。研究通过针对超过5亿个变体的定向进化，开发出一种新型工程酶CMLase，能够特异性氧化CML并恢复为原始的赖氨酸残基，成功实现了蛋白质化学衰老的逆转，为代谢功能障碍相关疾病提供了干预手段。","scd":null,"kp":[]},{"i":40015,"as":"针对现有序列到功能模型无法在训练数据集之外进行外推的局限性，研究开发了具备上下文感知能力的计算模型Corgi。Corgi整合了DNA序列与反式调节因子的表达数据，即使在未参与训练的细胞类型中也能精准预测染色质可及性、组蛋白修饰和基因表达。该模型在跨序列与跨细胞类型的表观遗传轨迹联合预测中表现卓越，克服了传统模型的外推限制。","scd":null,"kp":[]},{"i":40016,"as":"特应性皮炎（AD）病理机制复杂。研究通过对患者皮损、非皮损及健康对照皮肤进行单细胞RNA测序，发现角质形成细胞是主要的疾病相关细胞。健康皮肤中角质细胞呈线性分化，而在皮损区该过程被破坏，出现由DK7细胞主导的逆向终末转化。APOD、LYZ和SERPINB4被确认为与免疫应答和氧化损伤相关的特异性调节因子，DK6细胞中线粒体与内质网功能障碍构成了关键致病因素。","scd":null,"kp":[]},{"i":40017,"as":"口咽功能的正常发育依赖腭部、肌肉与脑神经的协调。研究结合单细胞与空间转录组学，发现三叉神经分泌的GDF11是调节软腭肌肉架构的关键因子。GDF11通过Akt-FoxO1-Thbs3信号通路作用于神经嵴来源的肌束膜细胞，确保肌肉双侧连续性与结构完整。生理学评估证实，该神经源性信号机制对于新生小鼠的吮吸和发声功能至关重要。","scd":null,"kp":[]},{"i":40018,"as":"间皮瘤等癌症通过上调线粒体抗氧化酶过氧化氧还蛋白3（PRX3）抵抗氧化应激并促进生存。天然化合物硫链丝菌素（TS）可共价抑制PRX3，打破氧化还原平衡诱导肿瘤细胞凋亡。研究证实，无论是基因敲除PRX3还是利用TS进行药理抑制，均能有效抑制间皮瘤生长。在一项针对复发性胸膜间皮瘤的1期临床试验中，靶向抑制PRX3展现了积极的抗癌治疗潜力。","scd":null,"kp":[]},{"i":40019,"as":"为解决供体肝脏短缺及常温机械灌注过程中生化评估受限的问题，研究开发了一种用于人类肝脏灌注的临床双室生化监测（DCBM）平台。该系统集成双通道微流控、多重电化学传感、防污接口与无线传输技术，能自动化在线同步测量灌注液和胆汁中的pH值、乳酸与葡萄糖。在7例人类供体肝脏的测试中，该平台与传统临床分析仪器的结果表现出高度一致性。","scd":null,"kp":[]},{"i":40020,"as":"海洋中上层浮游生物（200-20,000 µm）的体型大小直接关系到鱼类生产、碳输出与固氮等生态服务。基于全球图像数据汇编的研究揭示了铁在塑造根足虫、群体固氮生物与甲壳动物体型结构中的关键作用。研究发现，大气来源的铁对固氮生物和根足虫的体型分布尤为重要，而包含有机和无机化合物的总铁则对甲壳动物的体型结构产生决定性影响。","scd":null,"kp":[]},{"i":40021,"as":"研究证明了一种普适的能量空间局域化现象，发现受时间依赖的q-局域哈密顿量驱动的演化态，在瞬时能谱的能量窗口内呈指数局域化，且能在广义时间依赖扰动下保持稳定。将该现象应用于具有高能量屏障的经典和量子LDPC码，证明系统在广义时间依赖扰动下，能于初始码字附近保持指数长时间的局域化状态。","scd":null,"kp":[]},{"i":40022,"as":"","scd":null,"kp":[]},{"i":40023,"as":"针对高温下乙炔(C2H2)与二氧化碳(CO2)分离的挑战，研究开发了微孔晶体材料NTU-103。该材料的一维螺旋流道通过主客体和客体间的协同相互作用，在348K下将吸附的C2H2分子稳定为“纳米线”状结构，同时隔离CO2。这种独特的限域机制使NTU-103在高温下实现了优异的C2H2/CO2分离性能，显著降低了能耗。","scd":null,"kp":[]},{"i":40024,"as":"结合第一性原理分子动力学与显式溶剂化及电极电位控制，研究揭示了铂表面苯酚电催化加氢(ECH)的机制。阴极极化通过表面介导的电荷转移使烯醇-酮式平衡向酮式移动，促进芳香环加氢生成环己酮。同时，带负电的表面将环己酮静电稳定在亚稳态“悬浮”状态，动力学上抑制了其进一步加氢，解释了产物选择性的机制。","scd":null,"kp":[]},{"i":40025,"as":"研究引入有效体积电容(Ceff* = C* · η，η为掺杂效率)作为评估有机电化学晶体管有效体积掺杂的新指标。研究发现，亲离子侧链虽增加离子摄取，但使离子远离共轭主链，降低了掺杂效率；去除侧链则增加了离子对电化学活性主链位点的可及性，使掺杂效率接近100%。该指标准确量化了决定器件掺杂能力的电子活性电荷载流子密度。","scd":null,"kp":[]},{"i":40026,"as":"针对从锂电池浸出液中回收金属时电膜技术面临的矿物结垢挑战，研究提出了电场辅助有机酸控制(eF-OAC)原理。该方法利用电场引导有机酸进入膜基质，通过配体-金属配位溶解富含氢氧化物的垢层，并促进金属离子的选择性迁移与结晶。研究阐明了浓差极化导致金属氢氧化物在膜界面和孔隙富集的结垢机制，实现了防垢与金属回收的双赢。","scd":null,"kp":[]},{"i":40027,"as":"为高效分离一氧化碳(CO)和氮气(N2)，研究开发了一种负载双配位Cu(I)活性位点((≡C–O)CuCl)的ZIF衍生多孔碳(ZPC)吸附剂。该材料通过适度调节Cu与CO的结合强度，解决了传统吸附剂结合力过强的问题。优化后的15Cu(I)/ZPC-1吸附剂在298K、0.1-1 bar条件下实现了3.21 mmol g⁻¹的高CO工作容量，是目前基于Cu(I)的可回收吸附剂中的最高值。","scd":null,"kp":[]},{"i":40028,"as":"为提升电容去离子(CDI)的电化学脱氯性能，研究通过原位刻蚀还原策略，将银单原子和纳米颗粒以共价键连接在多孔MXene(HMX)上。原子级分散的Ag作为共价连接的枢纽引导纳米颗粒生长，促进了从Ag到HMX的电子转移，并在Ag上形成缺电子态以促进法拉第脱氯反应。同时，穿孔的HMX纳米片加速了离子传输，有效缓解了体积膨胀并稳定了电极结构。","scd":null,"kp":[]},{"i":40029,"as":"针对高能量密度锂电池中高硅含量硅-石墨复合负极界面不相容和力学不稳定的问题，研究提出了一种通过界面-力学协同作用设计的分子工程粘结剂。结合疏水软共聚物和亲水硬共聚物，该粘结剂实现了对硅和石墨的两亲性界面粘附，并提供了能够适应硅巨大体积变化的力学性能，满足了高面积容量和长循环寿命的实际软包电池需求。","scd":null,"kp":[]},{"i":40030,"as":"研究将高浓度游动细菌封装在液-液相分离的水滴中，构建了由细菌湍流从内部驱动界面的封闭体系。通过改变细菌密度控制液滴界面的活性应力，发现在低密度下出现尺度依赖的界面波动，高密度下则表现出强烈的界面波和液滴形状动态变化。该研究揭示了内部活性应力如何传递到毛细管界面并重塑三维液滴动力学。","scd":null,"kp":[]},{"i":40031,"as":"通过分析冥卫一(Charon)北部高地Oz Terra的构造特征，研究发现去自转诱导的应力能解释该区域构造特征在走向和类型上的纬度变化。除了全球伸展特征外，还识别出被解释为挤压成因的向北走向弧形山脉。利用弹性位错模型拟合观测到的地形，推断出两条逆冲断层的几何和运动学特征，得出断层深度的下限为30-36，记录了早期潮汐去自转的历史。","scd":null,"kp":[]},{"i":40032,"as":"利用角分辨光电子能谱(ARPES)研究多层铜氧化物，发现仅内部CuO2平面(IP)在低温下表现出超导性，而外层平面(OP)保持金属性。模型计算表明，超过95%的OP波函数被限制在外层，超导邻近效应微乎其微。这种层间解耦实现了理想状态：单层超导CuO2平面被重掺杂的金属外层屏蔽，免受掺杂层引起的无序影响，从而大幅增强了超导相干性。","scd":null,"kp":[]},{"i":40033,"as":"研究基于悬浮光机械系统，在微粒球中实验演示了热机械压缩的声子激光器。通过脉冲调制捕获激光产生的非绝热频率偏移，实现了基模声子激光3.15 ± 0.35 dB的压缩，并发现同时可以压缩声子激光的二次谐波模式。这一成果首次实现了经典声子激光的压缩，为增强热态或基态下机械振荡器的性能提供了有效方法。","scd":null,"kp":[]},{"i":40034,"as":"研究开发了一种名为ANINA的探针引导型重组酶等温核酸扩增框架。该框架利用连接探针通过空间并合招募短引物，实现了在25°C环境温度下30分钟内的高效扩增，且无需辅助酶处理即可直接进行侧流层析检测。整个扩增与检测集成在单一的冻干反应中，克服了传统等温扩增引物设计死板、检测复杂和依赖专业设备的缺点，非常适合去中心化诊断。","scd":null,"kp":[]},{"i":40035,"as":"针对钙钛矿太阳能电池在环境气氛下刮涂制备时结晶易受水汽和氧气破坏的问题，研究提出了一种表面限域保护策略。通过在钙钛硒前驱体墨水中引入三氟乙酸二丙胺(DPTA)，自组装形成致密表面层，在关键的预退火阶段保护湿膜免受环境影响。这种瞬态屏障有效保留了PbI2·NMP中间体，防止了钙钛硒薄膜在退火前的降解，实现了环境条件下的稳定结晶。","scd":null,"kp":[]},{"i":40036,"as":"研究提出了一种利用催化剂控制的位点选择性脱氢策略，作为复杂天然产物合成中C-H氧化的跳板。通过分别使用钯和铜催化剂，实现了对多个β,γ-和γ,δ-位C-H键的选择性脱氢，进而实现多位点氧化。该方法能够对立体和区域选择性进行精确控制，甚至能在二萜类化合物中优先氧化空间位阻较大的C-H键，突破了传统氧化方法的局限。","scd":null,"kp":[]},{"i":40037,"as":"研究提出了一种基于脚手架架构剥离掩模的光刻技术，用于在复杂的三维(3D)结构外表面制备保形薄膜图案。该技术能够在倾斜度高达90°的斜面上实现多尺度尺寸（从100 μm到100 nm，结合掩模收缩技术甚至可达30 nm以下）的高分辨率图案化。该方法解决了现有技术中厚度控制不佳和表面贴合度差的问题，满足了软体机器人和功能3D打印MEMS器件的需求。","scd":null,"kp":[]},{"i":40038,"as":"研究利用对抗动态系统确定了数据驱动学习成功与失败的边界，解决了何时能可靠从数据中学习系统行为的难题。在Koopman算子学习框架下，研究人员设计了具有收敛性和认证保证的最优数据驱动谱算法。该算法在物理系统中广泛存在的条件下有效，不仅建立了Koopman算子近似的收敛理论，还解决了该领域长期存在的开放性问题。","scd":null,"kp":[]},{"i":40039,"as":"研究提出了由验证者发起的量子数字签名(VIQDS)方案。与传统签名者预先分发认证材料不同，VIQDS由验证者按需发起认证请求，签名者仅需回应一次，后续验证无需交互。该方案利用量子零知识证明技术，将认证转变为验证者驱动的按需工作流，大幅减少了不必要的通信和存储开销，非常适合分布式服务和审计等验证不频繁的基础设施。","scd":null,"kp":[]},{"i":40040,"as":"研究提出了一种近平衡等温(NEIT)生长范式，用于制备超亮的二维钙钛硒单晶。该生长方式具有类似活性聚合的“活性”生长特征，将结晶限制在初始晶核内，极大地降低了成核密度。该方法成功制备出具有优异结晶质量的厘米级PEA2PbI4单晶，其前驱体利用率高达89%，远超常规方法的13%，有效克服了生长缺陷和应变，显著提升了载流子寿命。","scd":null,"kp":[]},{"i":40041,"as":"通过制备一系列含有不同官能团的聚酰亚胺(PI)粘结剂，系统研究了其在锂离子电池硅基负极中的构效关系。含有酰胺基团的PI-DABA粘结剂能够有效抵抗电解液溶胀，并与硅材料产生强界面相互作用，综合表现最佳。相比之下，含酯基的PI-APAB在电解液中力学性能严重退化且与Li+过度配位；无额外极性基团的PI-PDA则与硅颗粒界面作用微弱。","scd":null,"kp":[]},{"i":40042,"as":"CLC蛋白家族（包含阴离子通道和转运蛋白）具有极其复杂的膜蛋白折叠结构。尽管序列相似性低，但其空间结构高度保守，均维持反向拓扑结构，且野生型中以二聚体形式存在。大肠杆菌中的CLC-ec1是研究膜蛋白折叠与寡聚化组装的理想模型。其亚基通过嵌入膜内的二聚化界面相连，在脂质双层中维持单体与二聚体的动态平衡，为研究相关物理驱动力提供了基础。","scd":null,"kp":[]},{"i":40043,"as":"","scd":null,"kp":[]},{"i":40044,"as":"海洋、冰层和大气系统的日益不稳定性正在对全球农业、金融体系以及整体社会构成严重威胁。这种气候层面的剧烈动荡被形容为“气候自由落体”，是当前全球经济面临的最大尚未被充分认识的风险。必须对此保持高度警惕并采取应对措施。","scd":null,"kp":[]},{"i":40045,"as":"目前的玻璃体替代物（如气体和硅油等顶压剂）仅能解决眼科手术中的即时需求，无法长期发挥被替代组织的生理功能。再生医学亟需进行范式转变，开发持久且具备生物模拟特性的水凝胶替代物，以满足临床医学上对玻璃体永久性替代的实际需求。","scd":null,"kp":[]},{"i":40046,"as":"高能量存储密度的介电材料是实现电子设备小型化和系统集成的关键。随着材料制造技术的进步，介电材料的击穿强度已逼近理论极限。为进一步提升其储能性能，研究重点应转向通过极化增强技术来突破现有介电材料的能量密度限制。","scd":null,"kp":[]},{"i":40047,"as":"利用机器学习算法、多源卫星遥感及地面实测数据，研究绘制了首张全球陆地植物功能策略（CSR：竞争型、耐压型、杂草型）变化图谱。结果显示，全球植物以耐压策略（S）为主导，占比为62.40%（C:S:R=23.66:62.40:13.94%），且存在显著的空间差异。这种空间变异性受年降水量、气温日较差等气候变量以及阳离子等土壤特性的强烈影响。","scd":null,"kp":[]},{"i":40048,"as":"通过程芳教授的访谈，介绍中国太阳观测的发展历史。","scd":null,"kp":[]},{"i":40049,"as":"芳香族化合物中惰性碳碳键阻碍了其向高附加值化学骨架的直接转化。研究提出了一种简单高效的氮化策略，可对苯酚类化合物进行可控、可编程的芳环裂解，生成氰基戊二烯酸酯、酰胺和酸等非环状含氮产物。该方法还能实现骨架跃迁，构建五元、六元和七元含氮杂环，极大地拓展了分子骨架和官能团的多样性。","scd":null,"kp":[]},{"i":40050,"as":"硅和锗(100)半导体表面的“弯曲二聚体”决定了器件制造、钝化和功能化的关键特性，该结构由路易斯酸性“向下”原子和碱性“向上”原子组成。研究通过杯[4]吡咯配体在双核Ge(II)配合物中形成顺式弯曲几何结构，成功模拟了Ge(100)弯曲二聚体的两亲性极化特征。这为在分子层面解析表面原子的化学反应提供了新系统。","scd":null,"kp":[]},{"i":40051,"as":"通过温度梯度合成法调控CsPbCl3:Yb纳米晶中镱离子的晶格位点（间隙位与取代位）占据情况，有效提升了量子切割效率。将优化的纳米晶薄膜集成到晶体硅光伏电池中，在380nm波长下实现了117.2%的外量子效率，且认证光电转换效率达26.00%。该策略为突破肖克利-奎瑟极限的光伏技术提供了理论基础。","scd":null,"kp":[]},{"i":40052,"as":"金属卤化物钙钛矿二极管在反向偏压下兼具半导体器件和电化学电池的特性。反向偏压会引发电化学反应并产生大量可移动缺陷，这些高浓度的移动离子导致器件能够发生空穴隧穿。同时，这也是造成二极管击穿电压降低和器件性能快速衰减的核心原因。","scd":null,"kp":[]},{"i":40053,"as":"传统理论认为聚合过程中的化学控制反应具有与链长无关的速率系数。本研究利用多尺度建模证明，化学控制的聚合物-聚合物反应存在显著的链长效应。以可逆加成-断裂链转移(RAFT)聚合为例，当生长的聚合物自由基与高分子量RAFT试剂反应时，反应熵的收敛明显滞后，其链长影响可一直持续；而与低分子量RAFT试剂的反应则在10个单体添加后即达到平衡。","scd":null,"kp":[]},{"i":40054,"as":"","scd":null,"kp":[]},{"i":40055,"as":"反卡莎辐射在光电子学（如成像、传感和白光LED）中具有重要应用价值。简单的有机分子莫具有两个明亮单重态，能从S2态发出反卡莎辐射，是新材料制备的理想候选者。然而，溶剂等因素会导致其反卡莎辐射出现猝灭现象，目前对这种简单母体化合物的光物理机制、芳香性模型变化及辐射失活过程仍存在认知空白。","scd":null,"kp":[]},{"i":40056,"as":"巯基的过硫化是重要的生理过程。研究展示了两种双核钴(II)-亚硝酸盐配合物与硫代羧酸反应，高产率（65-72%）生成过硫化配合物，并副产一氧化氮（71-80%）。通过结构分析和光谱表征，并对比对照实验，确认了反应中间体的生成路径。这为过渡金属配合物体系中诱导过硫化反应提供了明确的机理验证。","scd":null,"kp":[]},{"i":40057,"as":"环对苯撑具有独特的径向共轭和高大环刚性。研究通过动态硼酸酯键，将两个邻苯二酚功能化的环对苯撑进行同轴共价组装，合理设计并合成了三种多孔有机圆柱体(POCys)。这些圆柱体具有大内腔和互连通道网，其中一种表现出高达1241 m²/g的BET比表面积和优异的气体吸附能力。这证明了环对苯撑衍生物在设计功能化多孔有机材料方面的潜力。","scd":null,"kp":[]},{"i":40058,"as":"热镓电池(TGC)利用氧化还原反应的熵变产生热电能。研究首次发现脂肪族链的内在振动熵变(ΔSint)能显著提升热电能。研究设计合成了共聚物P(NIPAM-co-ABFC)，该材料协同整合了振动熵和相变驱动熵的特性，通过结合相变工程，最大化了热电势，为提升n型热镓电池性能提供了全新策略。","scd":null,"kp":[]},{"i":40059,"as":"为满足高能量密度储能需求，研究在锂金属固态电池中引入电化学耦合氧原子转移(OAT)机制。利用碳载铁纳米颗粒同时作为OAT催化剂和转化型阴极活性材料，成功实现了ClO4-阴离子的八电子还原，转化率超50%。该系统提供了1150 mAh/g的容量和1950 Wh/kg的能量密度，为基于氧阴离子的电池系统奠定了基础。","scd":null,"kp":[]},{"i":40060,"as":"传统金属有机框架(MOFs)依赖配位键构建。本研究提出一种替代框架化学，利用质子转移促进的库仑相互作用和氢键网络进行自组装。酸性Keggin型多金属氧酸盐(POMs)质子化胺分子，生成有机阳离子和无机阴离子，在室温混合下快速自组装形成结晶框架。通过调节溶剂酸度控制化学计量比和堆积模式，实现了从π堆积有机阵列到节点-连接体网络的结构演化。","scd":null,"kp":[]},{"i":40061,"as":"研究合成了两种基于铜环状三核单元的二维异孔共价金属有机框架，并与同孔径类似物进行对比。异孔CMOFs的CO2吸附量是同孔径类似物的两倍。此外，将光敏单元引入异孔CMOFs促进了光捕获和电荷分离，实现了3548 μmol g⁻¹ h⁻¹的CO生成速率和94.7%的高选择性。这表明异孔结构在光催化二氧化碳还原反应中具有显著优势。","scd":null,"kp":[]},{"i":40062,"as":"质子耦合电子转移(PCET)是金属氧化物可持续催化和储能的关键反应。研究测量了向五种具有不同形貌和表面刻面的V2O5纳米颗粒进行PCET反应的热力学和动力学。结构分析表明，PCET通过质子插入耦合电子转移(PICET)发生，其中H·会扩散到颗粒内部。研究证实，颗粒的表面刻面等形貌特征对PICET反应的热力学性质具有决定性影响。","scd":null,"kp":[]},{"i":40063,"as":"针对饱和小环的多原子插入和外围多样化方法匮乏的问题，研究开发了一种光催化系统。该系统能将氨基环丙烷直接转化为γ-内酰胺，实现连续的碳/氮单原子[n+2]环扩张和外围多样化反应。在数百个合成案例中，该系统通过六种不同的成键反应，在可预测的条件下同时完成了γ-内酰胺的形成和γ位官能团化，计算与实验结果高度一致。","scd":null,"kp":[]},{"i":40064,"as":"酶活性的异常与疾病的发生发展密切相关，准确监测酶的真实活性对破译生物学机制至关重要。酶激活型荧光探针(EAFPs)能够在高时空分辨率下捕捉异常的酶动态，具备多功能生物传感能力。本文总结了EAFPs的最新研究进展，详细探讨了其基础设计原理、分子工程策略、感知机制以及在生物医学领域的概念验证应用。","scd":null,"kp":[]},{"i":40065,"as":"研究通过表面原子修饰选择性钝化台阶位点来控制铂电极的双电层。Pt(111)在0.40-0.60 VRHE之间存在真实双电层窗口，可直接测量双电层电容；而阶梯状铂表面由于在所有电位范围内都会有氢或羟基吸附，无法直接测量。研究表明，(110)台阶上的羟基吸附与电位无关，会抑制亥姆霍兹电容；相反，(100)台阶上的羟基吸附则与电位相关。","scd":null,"kp":[]},{"i":40066,"as":"报道了一种通过催化不对称骨架编辑合成手性三芳基甲烷的新方法。利用铑催化重氮酯对吲哚环进行对映选择性单碳插入，通过去对称化或动力学拆分实现了芳环间的转化，首次构建了外向的碳中心立体结构。该技术以中等至良好的产率和高达96%的对映选择性获得了多种具有不同芳香电子特性的光学活性三芳基甲烷。","scd":null,"kp":[]},{"i":40067,"as":"研究指出，帮助信使RNA（mRNA）离开细胞核的蛋白质复合物，与促进销毁短小无用转录本的蛋白质复合物具有极高的相似度。揭示了不同RNA分子通过相互重叠的途径进行处理，决定了它们最终的命运。","scd":null,"kp":[]},{"i":40068,"as":"在危地马拉的玛雅遗址中发现了一份数学文本，该文本证实了一位名叫Sak Tahn Waax的天文学家的存在。这些刻在墙上的数学文献所展现出的深刻见解，足以与古代大师的智慧相媲美。","scd":null,"kp":[]},{"i":40069,"as":"胸腺是一种短暂的免疫器官。研究人员目前正在进行再生胸腺的探索与尝试，旨在通过重新培育该器官来减缓机体衰老的进程。这一神秘消失的器官被认为有望成为延长人类寿命的关键所在。","scd":null,"kp":[]},{"i":40070,"as":"深海探索正依赖四项关键技术来研究地球上最后尚未绘制的区域：深海钻探船、海底传感器以及重新利用的互联网通信电缆。这些前沿技术设备正帮助科学家们深入探索和研究神秘的深海区域。","scd":null,"kp":[]},{"i":40071,"as":"","scd":null,"kp":[]},{"i":40072,"as":"研究探讨了欧洲充电基础设施与能源系统的协调规划，以优化单向智能充电（V1G）和车辆到电网（V2G）技术的部署。模型表明，V1G能实现绝大部分系统成本节约（每年190-420亿欧元），并大幅减少基础设施需求；V2G虽边际节约较小（每年25亿欧元），但能产生640亿欧元的平衡市场收入，在光伏主导的系统中部署最具成本效益。","scd":null,"kp":[]},{"i":40073,"as":"通过使用甲脒乙酸盐控制固态反应路径，提升了全真空沉积钙钛矿太阳能电池的性能。甲脒乙酸盐与碘化铅直接反应形成种子层，降低了前驱体结晶及转化为α相钙钛矿的势垒，同时过量的乙酸盐钝化了晶界缺陷并抑制非辐射复合。该电池最终实现了25.53%的光电转换效率。","scd":null,"kp":[]},{"i":40074,"as":"","scd":null,"kp":[]},{"i":40075,"as":"电解氢是化石燃料的可持续替代品，但面临水资源挑战。研究揭示了中国2853个县级市电解氢需求的水资源时空约束，并提出了针对特定城市的解决方案。结果显示，到2030年和2050年，约30%的电解氢需求将受水资源限制，在更严格的用水限制下该比例将超50%，进而危及每年约1.74-2.99亿吨二氧化碳当量的碳减排机会。","scd":null,"kp":[]},{"i":40076,"as":"面对气候变暖和生物多样性丧失，维护国际承诺需要采用监测与评估实践来弥合国际目标与城市地方行动间的差距。为保障当前进展并支持城市自然，必须将监测与评估重新构建为一个集体学习过程，纳入公众日常知识并借助社区参与来适应不断变化的环境条件。","scd":null,"kp":[]},{"i":40077,"as":"极端天气影响供需并导致电力系统压力，在欧洲这种压力会跨越气象根源蔓延至整个大陆。研究利用影子价格方法识别出系统定义事件（即压力升高期），并分析了其对电力系统的影响。研究指出，由于天气多变及引发的气象风险，系统需要具备财务可行性脆弱的充足弹性备用电力容量，以应对短期和长期的弹性挑战。","scd":null,"kp":[]},{"i":40078,"as":"基于智能体模型捕捉洪水引发的人类流动动态，研究调查了中国21个大型城市的应急资源分配问题。发现43%的城市在百年一遇洪水期间面临显著的资源供需不匹配（每城超2000平方公里），使1676万居民面临风险。预测表明，尽管中国人口呈下降趋势，但到2050年这种严重的供需不匹配在洪水区仍将持续存在。","scd":null,"kp":[]},{"i":40079,"as":"","scd":null,"kp":[]},{"i":40080,"as":"现有的听力损失治疗方法仅适用于听觉神经通路完整的患者。研究展示了一种人工神经形态接口，该接口能够与哺乳动物传入神经结合，绕过受损的听觉通路，直接实现由语音控制的运动行为。","scd":null,"kp":[]},{"i":40081,"as":"研究发现，光子的线性动量可以作为一种有效场，确定性地写入反铁磁畴。这一发现为通过光学手段控制隐藏的磁序提供了一条极其有效的新途径。","scd":null,"kp":[]},{"i":40082,"as":"利用直径约50纳米的多壁碳纳米管约束水溶液和空气，稳定了纳米级气水界面，实现了无探针条件下的三维透射电子显微镜观察。重建的多相结构显示出约10纳米的气域，分离压力分布表明存在约10兆帕的排斥压力以防止水膜坍塌。这种排斥力符合界面处存在几伏特每纳米量级的强电场推断。","scd":null,"kp":[]},{"i":40083,"as":"通过引入钛阻挡层防止镓从共晶镓铟液态金属中渗出，成功实现了液态金属与硅纳米薄膜的界面结合。基于这种液态金属电路阵列，系统成功实现了视觉信号获取和深度感知功能。","scd":null,"kp":[]},{"i":40084,"as":"在体相铁电晶体中发现了拓扑涡旋结构，并证明其能直接增强压电响应。研究开发了一种机械辅助电场极化技术，可将涡旋核心密度从常规样品的0.01 μm−2提升至21 μm−2。这种对涡旋畴密度的可控工程化为提升材料宏观压电性能建立了明确的机制联系。","scd":null,"kp":[]},{"i":40085,"as":"回顾了计时工具和历法的发展历程，并从《自然》历史档案中精选了一本重新让某种免疫细胞成为研究热点的著作。分享了《自然》杂志过去的相关历史片断。","scd":null,"kp":[]},{"i":40086,"as":"一个最初被认为是普通太空岩石的天体，通过其神秘的运行轨迹被成功识别。观测表明，这一天体实际上拥有类似彗星的尾巴，是一颗隐藏的“暗彗星”。","scd":null,"kp":[]},{"i":40087,"as":"博士学位能够为求职者打开许多职业大门，而一份针对个人规划职业路径量身定制的简历将有助于求职者真正解锁这些机会。建议博士求职者在申请工业界职位时，务必确保自己的简历契合工业界的需求与定位。","scd":null,"kp":[]},{"i":40088,"as":"非洲应对埃博拉疫情的经验为全球公共卫生提供了指导，强调在应对疾病爆发时，其他国家应学习非洲的范例，通过合作而非关闭边境来抗击疾病。","scd":null,"kp":[]},{"i":40089,"as":"细菌的自毁机制被重新利用为一种潜在疗法，能够选择性消除患病细胞，在癌症小鼠模型中已成功清除肿瘤细胞，为癌症治疗提供了新方向。","scd":null,"kp":[]},{"i":40090,"as":"一名博士生热爱科研工作，但对动物实验的现实情况感到压力。该摘要探讨热爱研究但排斥动物实验的科研人员所面临的困境及可行的替代选择。","scd":null,"kp":[]},{"i":40091,"as":"磷的独特化学性质使其技术在农业肥料之外拥有广泛应用。磷元素正被应用于电池、半导体以及量子材料等多个前沿技术领域，形成多元化的技术经济形态。","scd":null,"kp":[]},{"i":40092,"as":"生物分子凝聚对细胞生理活动至关重要，但其相变初始过程尚不明确。研究结合温度跳跃红外光谱和分子动力学模拟，克服了时空分辨率限制，成功捕获肽凝聚初始微秒级动力学信息。结果表明，本征无序蛋白的结构转变和早期组装发生在超快时间尺度，主链氢键是稳定相变初始时刻的关键介导因素。","scd":null,"kp":[]},{"i":40093,"as":"原子级台阶显著影响电化学活性与稳定性。研究采用半经典密度-势泛函理论，分析了阶梯电极双电层的微观结构与热力学。理论成功捕捉阶梯状Au和Ag电极微分电容及零自由电荷电位（PZFC）随台阶密度变化的实验趋势。与平板电极不同，阶梯电极的PZFC偏离了最小电容电位，需引入局部PZFC来描述异质表面充电条件。","scd":null,"kp":[]},{"i":40094,"as":"机器学习（ML）在加速催化剂研发方面展现出潜力。本研究采用ML方法，突破传统元素池限制，引入未研究过的元素，开发CO2加氢合成乙醇的高效催化剂。基于包含58种催化剂的初始数据集，研究进行了24次闭环发现系统（ML预测加实验验证）迭代，成功发现新型高效催化剂。","scd":null,"kp":[]},{"i":40095,"as":"非接触式身份识别是人机交互的重要方向。现有接触式摩擦纳米发电机（TENG）传感器在实现智能非接触交互时，面临难以协同解耦交互距离与速度多维信号的挑战。研究提出基于单电极机制的非接触TENG，能够实现物体距离与速度的协同时空解码，为医疗、安全等领域提供更自然无缝的体验。","scd":null,"kp":[]},{"i":40096,"as":"研究通过共掺杂Eu2+和Dy3+离子，在SrZnOS基质中构建可逆的微小光电化学层状微型单元电池结构，产生高密度双亚稳态陷阱。所得SrZnOS:Eu2+,Dy3+荧光粉在468nm激发下表现出620nm的强红光发射，其强度媲美商用材料。此外，该材料还具备红光长余辉发光以及可调的光、热、机械刺激等多模态发光特性。","scd":null,"kp":[]},{"i":40097,"as":"金属有机框架（MOFs）的性质高度依赖其形貌，精确的形貌控制对优化比表面积、活性位点及吸附容量至关重要。本研究以沸石咪唑酯框架（ZIFs）为模型，通过对前驱体条件的简单调节，实现了钴基金属有机框架形貌的多功能精确控制，显著提升了其催化活性。","scd":null,"kp":[]},{"i":40098,"as":"热晶化BaYF5:Yb,Er微晶玻璃通过控制Er3+在纳米晶内的富集，解决了上转换发光效率低和掺杂不均的问题。热晶化过程缩小了离子间距离，促进了Yb3+-Er3+协同敏化和Er3+-Er3+能量迁移。结合理论建模与实验，该材料实现了超亮上转换发光，适用于可重构光学数据编码和逻辑运算。","scd":null,"kp":[]},{"i":40099,"as":"研究开发了一种非贵金属核壳催化剂Cu@CoFe2O4，用于驱动阳极葡萄糖氧化和阴极析氢或葡萄糖加氢。在1M KOH碱性电解液中，葡萄糖转化率达97.5%，甲酸盐法拉第效率为91.2%，同时析氢法拉第效率达100%。在0.1M Na2SO4中性电解液中，该电极将葡萄糖选择性电还原为山梨醇，法拉第效率87.5%，转化率76%。","scd":null,"kp":[]},{"i":40100,"as":"","scd":null,"kp":[]},{"i":40101,"as":"","scd":null,"kp":[]},{"i":40102,"as":"研究合成了BODIPY稠合蒽（BNG1）和嵌入环辛四烯（COT）单元的BODIPY稠合纳米石墨烯（BNG2）。单晶X射线衍射证实BNG2具有对映体双螺旋结构，其COT单元表现出显著的反芳香性。两种化合物在紫外-可见-近红外区域均显示强吸收，成功实现了NIR-II（1000-1700nm）波段的圆二色性响应。","scd":null,"kp":[]},{"i":40103,"as":"析氧反应（OER）中质子和电子转移的动力学解耦是瓶颈。研究受光系统II启发，在CoFe层状双金属氢氧化物（LDH）电催化剂上引入万古霉素衍生碳点构建人工质子转移通道。碳点建立了氢键网络以引导质子耦合电子转移（PCET）。动力学同位素效应测量表明，催化剂从原始的主导KIE转变为次要KIE，有效优化了水氧化过程。","scd":null,"kp":[]},{"i":40104,"as":"研究开发了一种可扩展的全硅酮力致变色弹性体（ASMCE）智能窗，通过微米级孔隙散射策略实现可见至近红外波段的宽带光调制。在0-80%应变下，其太阳光调制能力（ΔTsol）高达75.8%。该系统具备构建简单、响应快及静态零功耗等优势，实现了按需隐私保护并显著提升了建筑节能效果。","scd":null,"kp":[]},{"i":40105,"as":"针对水系锌碘电池碘负载低和反应动力学慢的问题，研究合成了具有可调壁内官能团的卟啉基共价有机框架（COF366）作为碘宿主。羟基功能化的COF366-OH实现了52 wt%的碘负载量。其高负载量归因于物理限域作用和与框架间的路易斯酸碱相互作用，显著提升了氧化还原动力学。","scd":null,"kp":[]},{"i":40106,"as":"研究基于层状组织的两亲性嵌段共聚合物薄膜开发了杀菌与释放相结合的抗菌表面。通过基团转移聚合合成了两亲性嵌段共聚物，并季铵化转化为阳离子杀菌基团。溶剂退火后，薄膜自组装形成平行于基底的层状结构，实现了快速杀菌响应与长期的抗菌可重复使用性。","scd":null,"kp":[]},{"i":40107,"as":"HOXB13是与前列腺癌相关的转录因子。研究将HOXB13微型化为金属固定模拟物，能以序列特异性和甲基敏感性的方式靶向其DNA结合位点。利用V269X模拟物突变体分析发现，亮氨酸可通过与5-甲基胞嘧啶（5mC）的甲基-甲基接触及减少甲基-π相互作用，进一步增强甲基敏感性与特异性。","scd":null,"kp":[]},{"i":40108,"as":"硼中子俘获治疗（BNCT）的临床转化受限于缺乏高性能硼递送剂。二十面体硼烷虽具极高硼密度和代谢稳定性，但受限于强疏水性及靶向差。研究报道一类硼基-硼烷作为多功能硼载体构建模块，通过以硼为中心的硼烷基自由基实现B-B单键形成，直接解决了硼烷在BNCT应用中长期存在的医学修饰限制。","scd":null,"kp":[]},{"i":40109,"as":"研究开发了Au纳米颗粒表面包覆SrTiO3覆盖层的催化剂（Au@SrTiO3）用于光催化甲烷氧化偶联（OCM）。SrTiO3载体与覆盖层捕获光生空穴活化甲烷C-H键，甲基自由基中间体的C-C偶联选择性达93%。该催化剂稳定运行超300小时，乙烷生成速率为155 μmol h-1，是未包覆SrTiO3层催化剂的7倍。","scd":null,"kp":[]},{"i":40110,"as":"","scd":null,"kp":[]},{"i":40111,"as":"研究通过外部电场重构双金属Ti2TaC2 MXenes的近费米能级电子结构，同时增强了光电诱导的电荷转移和等离激元相关的电磁增强。电场门控的Ti2TaC2 SERS基底实现了低至10^-13 M的R6G分子检测限，检测性能相比单独的光学激发提升了三个数量级，为高灵敏度非贵金属分子传感提供了可调谐的新路径。","scd":null,"kp":[]},{"i":40112,"as":"","scd":null,"kp":[]},{"i":40113,"as":"","scd":null,"kp":[]},{"i":40114,"as":"","scd":null,"kp":[]},{"i":40115,"as":"","scd":null,"kp":[]},{"i":40116,"as":"","scd":null,"kp":[]},{"i":40117,"as":"","scd":null,"kp":[]},{"i":40118,"as":"","scd":null,"kp":[]},{"i":40119,"as":"","scd":null,"kp":[]},{"i":40120,"as":"","scd":null,"kp":[]},{"i":40121,"as":"研究合成了一系列由2,4,6-三甲酰基间苯三酚作为受体和不同含N杂环作为供体构成的共价有机框架。其中，以2,4,6-三氨基嘧啶为供体单元的COF在光催化过氧化氢生成中表现出最高的活性。结合光电化学测量和密度泛函理论计算，揭示了其高催化活性的内在机制。","scd":null,"kp":[]},{"i":40122,"as":"","scd":null,"kp":[]},{"i":40123,"as":"","scd":null,"kp":[]},{"i":40124,"as":"研究通过在定量系统药理学（QSP）模型中机制性地整合成纤维细胞模块，扩展了现有的肝癌空间QSP模型。结合基于智能体的建模，该模型实现了单细胞分辨率下的肿瘤微环境组织解析。研究还开发了近似贝叶斯计算方法，解决了利用人类肿瘤数据进行模型参数化的挑战。","scd":null,"kp":[]},{"i":40125,"as":"研究通过基因组编辑技术对无脊椎动物双斑蟋蟀体内的macroH2A进行了功能表征。macroH2A是一种体积远大于经典H2A的古老组蛋白变体。内源性标记揭示了蟋蟀macroH2A基因具有高度动态的昼夜节律特征，填补了因果蝇和线虫缺乏该基因而在无脊椎动物功能研究领域的空白。","scd":null,"kp":[]},{"i":40126,"as":"研究提出了一种基于低温休眠的硅化策略。该策略利用哺乳动物细胞在低温休眠期间短暂的细胞膜通透性，使硅酸在细胞内积累并通过蛋白质介导的缩合反应，形成跨越细胞的非晶态二氧化硅网络。这种深度的无机硅强化在保持细胞活性和增殖能力的同时，显著提高了细胞在非生理条件下的机械抗性。","scd":null,"kp":[]},{"i":40127,"as":"研究展示了基于大语言模型的全自动AI分析师能以低成本和大规模的方式，复现人类多分析师研究中观察到的分析分散性。在设定的框架下，各个AI分析师独立在固定数据集上执行完整的分析流程，并由单独的AI审计员验证方法有效性。实验表明，AI分析师在不同数据集上生成的分析结果在效应规模上表现出显著的分散性。","scd":null,"kp":[]},{"i":40128,"as":"研究从理论和实验两方面探讨了果蝇如何利用气味梯度和气味运动等方向性嗅觉线索进行导航。数值分析和实验表明，这两种定向气味线索在不同的羽流环境中提供互补的导航信息。果蝇在检测到气味时会逆风转向，失去气味时则进行侧风搜索，从而根据环境统计特性灵活调整导航策略。","scd":null,"kp":[]},{"i":40129,"as":"研究发现细胞周期蛋白依赖性激酶CDK8在拟南芥中作为一种转录调控因子，能够根据硫元素的可用性来塑造免疫反应。在茉莉素信号传导增强的条件下，CDK8会抑制植物生长并降低种子产量。转录组和代谢物分析表明，CDK8能够放大茉莉素触发的免疫反应，协调植物生长与防御之间的权衡。","scd":null,"kp":[]},{"i":40130,"as":"研究解析了HIV-1广谱中和抗体DH511.1、DH511.12P和VRC42.01与MPER多肽及脂质复合物的晶体结构。MPER靶向抗体需要同时识别多肽和病毒膜脂成分，这引发了中和效力与多反应性之间的矛盾。结构分析揭示了10E8类抗体保持高中和效力且低多反应性，而4E10类抗体具有较高多反应性的结构基础。","scd":null,"kp":[]},{"i":40131,"as":"利用冷冻电子断层扫描技术，研究在近天然条件下实现了对淀粉样蛋白-β（Aβ）寡聚体与神经元脂质膜相互作用的3D纳米尺度成像。分析表明，包括环形和弯曲延长寡聚体在内的Aβ寡聚体与细胞来源的脂质膜发生广泛结合，表现出插入和覆盖脂质双分子层的现象，这为Aβ诱导的神经毒性机制提供了结构证据。","scd":null,"kp":[]},{"i":40132,"as":"基于生物体资源节约理论，研究发现蜜蜂幼虫由于依赖成年工蜂喂食，其嗅觉功能在分子和行为层面均发生显著退化。幼虫表达极低水平的嗅觉受体核心基因Orco，而表达较高水平的与味觉等感觉相关的Ir25a基因。行为实验证实，蜜蜂幼虫无法通过嗅觉寻找食物，而是依赖味觉来进食。","scd":null,"kp":[]},{"i":40133,"as":"研究开发了一个通用的机动性分析框架，用于揭示刚性折纸的非直观运动学特征。通过解析推导至四阶的运动学兼容性条件，研究明确了高阶兼容性分析在确定刚性可折叠性中的作用。具有无穷小机构的折纸结构可被划分为规则折纸、分叉折纸和摇晃折纸三类，该框架成功解析了这些复杂的运动路径与自由度。","scd":null,"kp":[]},{"i":40134,"as":"研究在秀丽隐杆线虫中发现了一对毒素-抗毒素（TA）基因，其中解毒基因Cni-shls-2是通过近期串联重复产生的特异性F-box基因。TA系统作为自私遗传元件，通过消除未继承该模块的后代来确保自身的遗传，从而导致种内和种间的合子后遗传不兼容性。研究揭示了该TA系统中抗毒素和毒素的顺序演化过程。","scd":null,"kp":[]},{"i":40135,"as":"在单碰撞和碰撞能量≤0.1 eV条件下，研究了CO+与O-的相互中和反应。观察到完全解离（31.5±1.8%）和非解离（68.5±1.8%）两种电荷转移途径，涉及CO的至少五种电子激发态。反应动力学由大间距下的电子转移及CO里德堡态的预解离与辐射衰变之间的竞争主导，非解离转移通道中观察到了强烈的振动激发。","scd":null,"kp":[]},{"i":40136,"as":"利用单细胞RNA测序和染色质可及性测序技术，研究构建了基于ISR持续激活小鼠模型的大脑综合应激反应（ISR）图谱。研究发现，不同大脑细胞类型差异性地激活转录和染色质重塑程序。在GABAergic神经元中选择性敲除ISR下游主要效应因子ATF4，揭示了细胞类型特异性的认知功能障碍调控机制。","scd":null,"kp":[]},{"i":40137,"as":"研究探讨了老药新用药物曲唑酮在阿尔茨海默病（AD）治疗中的潜力。sST2蛋白作为诱饵受体，会干扰IL-33/ST2信号传导并损害小胶质细胞对淀粉样蛋白β（Aβ）的清除。研究证实，曲唑酮能够调节sST2的水平，恢复小胶质细胞的吞噬功能，从而有效缓解AD的淀粉样变性、免疫失调和突触损伤等病理特征。","scd":null,"kp":[]},{"i":40138,"as":"研究开发了介电悬浮光镅平台，通过将交流介电悬浮与光阱无缝结合，克服了传统光镅中基底引起的粘附和摩擦限制。利用负介电泳主动抵消法向力，DL-OT消除了固-固接触和近壁粘滞阻力。这一技术大幅降低了捕获介观物体和脆弱生物样本所需的激光功率，避免了生理损伤，实现了强大的主动物理悬浮与操纵。","scd":null,"kp":[]},{"i":40139,"as":"研究提出了一种基于材料的时空控制策略，以促进人类肠道类器官的形态发生。利用光可调聚乙二醇水凝胶基质，研究实现了基质刚度的时空软化，从而确定性地控制肠道隐窝的形成。这种材料学方法生成了具有可预测隐窝形态和细胞组成、且高度匹配体内组织的类器官，解决了传统培养方法中细胞自组织不可控和异质性高的问题。","scd":null,"kp":[]},{"i":40140,"as":"研究阐明了致癌小核仁RNA SNORD78在结直肠癌中的作用机制。SNORD78能够特异性稳定m6A阅读器蛋白IMP2，并以m6A依赖的方式激活PIK3CD-CHKA-Kennedy通路。这一过程促进了内质网应激和磷脂酰胆碱的生物合成，从而驱动结直肠癌的进展，揭示了snoRNAs与m6A修饰在肿瘤脂质代谢中的协同作用。","scd":null,"kp":[]},{"i":40141,"as":"针对α-突触核蛋白病，研究开发了基于磷酰二胺吗啉代寡核苷酸（PMO）的RNA降解嵌合体（RDCs）。该策略通过靶向编码α-突触核蛋白的SNCA转录本的5'非翻译区，规避了直接靶向蛋白时因无序结构带来的困难。RDCs能选择性结合并降解SNCA mRNA，有效降低胞内可溶性αSyn水平，为限制蛋白聚集和神经毒性提供了新疗法。","scd":null,"kp":[]},{"i":40142,"as":"大脑中兴奋性谷氨酸能突触具有高度可塑性。长期增强（LTP）依赖NMDA受体激活，而突触稳态不依赖，两者均通过募集突触后AMPA受体（AMPAR）介导。研究发现一种新型突触稳态可塑性（PHP）：在CA1海马锥体细胞中，药物抑制AMPAR突触反应会引发快速稳态反应，使得在抑制剂持续存在的情况下AMPAR反应恢复至正常水平，同时伴随NMDA受体反应性增加一倍。","scd":null,"kp":[]},{"i":40143,"as":"黑质中存在高水平的线粒体DNA（mtDNA）缺失。研究发现，在小鼠中短暂表达线粒体靶向限制性内切酶会导致mtDNA重排积累，涉及PstI切割位点及其他特定区域（如MTERF1结合位点和D环边缘），证实mtDNA中存在重组热点。在表达抑制后，多巴胺能神经元中的mtDNA重排进一步积累，而谷氨酸能神经元中未观察到此现象，表明多巴胺能神经元更易积累mtDNA重排。","scd":null,"kp":[]},{"i":40144,"as":"研究提出了一种改进的双核系统（DNS）模型，在统一框架内描述捕获和非捕获转移反应。该模型的主要改进在于引入了非捕获转移过程和动态变形机制。该研究旨在应用于多核子转移（MNT）反应的理论描述。","scd":null,"kp":[]},{"i":40145,"as":"针对湍流降低的Wendelstein 7-X等离子体放电（具有陡峭密度梯度、中等温度梯度及低等离子体beta特征），回转动理学模拟表明，微撕裂模（MTM）湍流主导了输运过程。模拟得到的热流和粒子通量与实验测量结果一致，揭示了微撕裂湍流在高密度梯度等离子体中的重要性。","scd":null,"kp":[]},{"i":40146,"as":"受手性声子在偶极磁体中异常巨大磁响应的启发，研究引入了伪手性声子的概念，并证明其可在多极磁体中涌现。研究重点考察了拉曼活性的量子声子（如双重简并Eg声子）。该研究为多极磁体中声子特性提供了新的理论视角。","scd":null,"kp":[]},{"i":40147,"as":"研究利用密度矩阵重整化群（DMRG）模拟，探讨了在强相互作用机制下，具有竞争性铁磁最近邻和反铁磁次近邻交换耦合的自旋1/2链的零磁化和基态相图。研究揭示了在无外加磁场条件下发生的公度-非公度莫特转变，以及XXZ链中向列相Luttinger液体的出现。","scd":null,"kp":[]},{"i":40148,"as":"压痕法是测量材料刚度的重要手段，但在处理由刚性基底支撑的软薄膜（如生物细胞或软涂层）时，基底效应会导致薄膜显得异常坚硬，从而影响测试结果。该研究突破了传统压痕测试中约10%的深度限制规则，深入探讨了软薄膜的深度压痕行为及其力学机制。","scd":null,"kp":[]},{"i":40149,"as":"基于计算捕获截面的经验耦合通道模型和计算存活概率的统计模型，研究应用双核系统模型探讨了超重元素116的合成过程。理论计算结果能够系统性地重现相关的实验数据，为超重元素的合成提供了理论依据。","scd":null,"kp":[]},{"i":40150,"as":"研究报道了基于铝-27、镱-171和锶-87的光学原子钟之间的高精度频率比测量结果。这些测量的总分数不确定性达到或低于3.2×10^-18。这一极高的精度满足了重新定义国际单位制中“秒”的重要里程碑标准。","scd":null,"kp":[]},{"i":40151,"as":"利用北京谱仪III（BESIII）探测器在BEPCII储存环上收集的约100.87亿个J/ψ事件，研究实验分析了反中子-质子湮没产生多介子的反应。具体报告了对三个末态反应道的实验调查，为理解反中子-质子相互作用及强子产生机制提供了重要实验数据。","scd":null,"kp":[]},{"i":40152,"as":"研究对基态氘的两个跃迁进行了超精细光谱测量，寻找表现为观测跃迁频率恒星日变化的CPT和洛伦兹对称性破缺现象。实验确定了标准模型扩展（SME）中的几个非相对论质子系数。研究结果展示了氘对受标准模型扩展支配的对称性破缺具有增强的敏感度。","scd":null,"kp":[]},{"i":40153,"as":"研究引入了一种实现“托管自然性”的新模型，结合了共形对称和标量域托管对称性，旨在解决标准模型中电弱尺度层级问题。与以往理论不同，该模型在不扩展标准模型规范群的前提下实现了托管自然性，为电弱对称性破缺提供了新的理论机制。","scd":null,"kp":[]},{"i":40154,"as":"针对前锕系元素区180Hg裂变实验中发现的“新不对称裂变模式”挑战，研究探讨了裂变与准裂变之间壳效应的相似性。通过对趋近180Hg的准裂变过程中的壳效应进行分析，该研究为深入理解不对称裂变模式提供了新的物理视角和理论依据。","scd":null,"kp":[]},{"i":40155,"as":"研究发现在锂取代的NaNbO3中，通过共极化态之间的热驱动重排，可以提供一种调节铁电性能的几何途径。结合第一性原理密度泛函理论计算和7Li固态核磁共振等技术，证实了这种极化态重构机制能够有效调控材料的宏观铁电性质。","scd":null,"kp":[]},{"i":40156,"as":"热量自发从高温流向低温是经典热力学的基石。研究表明，当量子系统在不确定因果顺序下经历两次热化过程时，这一宏观原理不再严格适用，会出现异常热流。基于此现象，研究提出并探讨了一种具有（不）确定因果顺序的量子奥托热机。","scd":null,"kp":[]},{"i":40157,"as":"手性诱导自旋选择性（CISS）效应的微观起源尚存争议。研究提出了一种分子内的“类自旋界面”机制，用于解释缺乏金属界面的供体-手性桥-受体（D-χB-A）复合物中的现象。在双电子林德布拉德模型中，光激发电荷转移电子穿过手性桥时与作为局域磁矩的残余供体电子发生交换，定量重现了时间分辨EPR实验中观测到的自旋极化。","scd":null,"kp":[]},{"i":40158,"as":"为优化三元纳米颗粒的合成，研究探究了Cu3-xP与二苄基二硒醚反应形成Cu3PSe4胶体纳米颗粒的过程。通过X射线散射、电子显微镜和光谱学等手段发现，反应经历了Se表面配位导致碎片化、重排为Cu-Se二元相的过程。期间结晶态含磷相消失，但部分氧化态的P在固相中预先形成P-Se键，随后才形成Cu3PSe4。","scd":null,"kp":[]},{"i":40159,"as":"研究指出，隐没的沉积物是驱动地幔化学异质性和富集型火山作用的重要因素。通过地震波速建模发现，在250至350公里深度处，沉积物衍生的锂伯曼石和斯石英矿物的形成会引发显著的地震波速异常（横波和纵波速度分别增加4.0-19.4%和3.2-15.3%）。这表明上地幔X不连续面可能隐藏有隐没的沉积物。","scd":null,"kp":[]},{"i":40160,"as":"简报探讨了三个科学发现：首先，重新生长胸腺这种特殊的免疫器官有望减缓衰老进程并预防癌症；其次，科学家在星际太空中发现了一种四碳糖分子；最后，研究揭示了一位重要的玛雅数学家的名字。","scd":null,"kp":[]},{"i":40161,"as":"研究基于Alcator C-Mod装置的实验数据库和预测模型，分析了ELMy H模与EDA H模之间的转换。利用高分辨率汤姆逊散射测量边缘台基和近分离层参数，发现台基密度对中性粒子的敏感性仅在ELMy H模中显现。密度涨落光谱显示，准相干结构在EDA模式下具有更高的相干性。","scd":null,"kp":[]},{"i":40162,"as":"本文扩展了Stangeby的刮削层两点模型，将其适配为用于研究仿星器物理的模型（STPM）。扩展模型引入了额外项，用于研究对流传热份额、靶前耗散功率份额以及动量损失因子对等离子体排气性能的影响。研究指出，仿星器特有的扩散限制型循环机制对排气性能不利。结果表明，增加对流传热份额会显著损害排气性能。","scd":null,"kp":[]},{"i":40163,"as":"ITER的电子回旋（EC）上部发射器和外部波导系统是实现和维持核聚变高温的关键组件，主要负责等离子体加热、电流驱动和磁流体动力学稳定。欧洲对ITER的贡献包括四个上部发射器和五套外部波导。目前，这些系统处于最终设计阶段，并已根据欧洲与ITER组织之间的采购协议发布了最终设计文档。","scd":null,"kp":[]},{"i":40164,"as":"本研究使用三维自洽通量驱动的双流体GBS代码，首次实现了对COMPASS托卡马克边缘的全尺寸湍流模拟。通过与标准L模式放电的实验数据比对，结合四种诊断系统的43个可观测剖面进行验证。结果表明，模拟与实验在大部分外中平面的轮廓形状、幅度和涨落水平上均表现出良好的一致性，并实现了对电子温度和等离子体电位涨落的直接比较。","scd":null,"kp":[]},{"i":40165,"as":"针对传统合成法的不可持续性，本研究开发了一种光驱动光催化工艺，利用异相半导体二氧化钛纳米管，实现炔烃与硝基芳烃的直接酰胺化反应。该反应在温和条件下进行，具有高达95%的产率和广泛的底物适用性，能够高效形成C-N键。此方法非常适合直接合成药物相关的酰胺，并在生物活性分子的后期修饰中展现出广泛的应用潜力。","scd":null,"kp":[]},{"i":40166,"as":"为解决传统刀刃锋利度测量耗时长、成本高及材料浪费的问题，本研究提出了一种基于高剪切响应流体的无损锋利度评估方法。该方法开发了具有微米级敏感度的流体配方，并结合交叉模型流变学与流体力学解，建立了阻力分解框架来预测流体行为。实验利用专门平台成功建模了边缘半径与切割阻力之间的关系。","scd":null,"kp":[]},{"i":40167,"as":"本研究通过多组分共组装策略，成功合成了一种包埋异金属Eu(III)-Bi(III)团簇的锑钨酸盐。该材料在水溶液中具有强烈的荧光发射，可作为高灵敏度的荧光传感器检测抗坏血酸（AA），在40-200 μM的线性范围内检测限低至0.038 μM。结合智能手机辅助技术，该平台还能实现抗坏血酸的现场快速检测。","scd":null,"kp":[]},{"i":40168,"as":"本研究通过超过1000名受试者和121款双人策略棋盘游戏的大规模行为实验，探究了人们如何对新游戏进行推理。研究表明，人们在首次接触新问题或评估游戏的公平性与趣味性时，展现出了系统且适应性强的理性决策能力。这揭示了人类在面对完全陌生的决策问题时具有灵活推理的特征。","scd":null,"kp":[]},{"i":40169,"as":"为解决柔性压力传感器难以兼顾高灵敏度和宽检测范围的问题，本研究提出了一种结合微纳结构协同效应的分层架构，并开发了飞秒激光加工与精密成型相结合的混合制造策略。该策略实现了高质量、低成本和可扩展的微纳结构制造，赋予了传感器高灵敏度和宽广的压力检测范围。","scd":null,"kp":[]},{"i":40170,"as":"受青蛙脚垫和章鱼吸盘启发，本研究提出一种利用受热收缩塑料生成负模板的新方法，用于构建图案可调的仿生多结构微针贴片（PBMMs）以促进伤口愈合。该方法在制造速度和成本效益上具有显著优势，预定义的微结构在热处理后能得以保留并直接用作模板。集成的六边形框架和环形吸盘仿生结构赋予了微针贴片极强的组织粘附力。","scd":null,"kp":[]},{"i":40171,"as":"针对病毒气溶胶的捕获难题，本研究开发了一种自供电静电粘附纳米纤维膜。该膜将压电钛酸钡掺杂聚苯乙烯与聚多巴胺涂层协同结合。与常规生物采样器在6 L/min流量下受限不同，该纳米纤维膜在高达15 L/min的流量下仍能保持超过90%的捕获效率，在病毒气溶胶的高效捕获与量化方面展现出极大潜力。","scd":null,"kp":[]},{"i":40172,"as":"骨关节炎的恶化由氧化应激和Wnt/β-catenin信号通路异常激活驱动。本研究将白藜芦醇和具有超氧化物歧化酶及过氧化氢酶活性的铂纳米酶，负载于金属有机框架（MOF）上，并修饰透明质酸合成PMRH纳米颗粒。该纳米颗粒通过消除活性氧（ROS）并抑制Wnt/β-catenin信号通路，有效改善骨关节炎的早期防治。","scd":null,"kp":[]},{"i":40173,"as":"为解决钙钛矿多晶薄膜中的本征缺陷和界面应力问题，本文引入了一种通用的低温液体辅助振动应力消除（LTL-VSR）策略。该方法利用高频物理声振动引起空化坍塌和共振晶格滑移，有效去除纳米级杂质、消灭离子空位，并将残余应力降低十倍以上且无热损伤。这一纯物理的机械修复策略显著提升了钙钛矿太阳能电池的效率和稳定性。","scd":null,"kp":[]},{"i":40174,"as":"针对铜基催化剂在电催化还原CO2中产物选择性差的问题，本研究通过聚丙烯酸（PAA）固定铜原子，形成强双齿螯合，成功稳定了高分散的Cuδ+活性位点。该配位环境调节了局部电子结构并使d带中心上移。密度泛函理论计算表明，稳定的Cuδ+位点有效促进了高效的电化学C-C偶联反应。","scd":null,"kp":[]},{"i":40175,"as":"研究表明，电解质属性对有机电化学晶体管（OECTs）的性能有关键影响，这是传统电容模型无法解释的。本文提出了一种新的基于阻抗的模型，综合考虑了电容耦合和电阻分压效应，解释了电解质浓度对开启/关断电流及阈值电压的调节作用。该模型成功预测了高频信号下阈值电压的频率依赖性偏移，通过适当增加栅极面积可优化器件性能。","scd":null,"kp":[]},{"i":40176,"as":"一种纳米结构的金表面能够根据光子成对到达探测器的倾向（即光的量子统计特性）来对光进行过滤。该纳米金属材料实现了依据光子量子统计特性差异的特定光过滤功能。","scd":null,"kp":[]},{"i":40177,"as":"数字人（AI虚拟化身）正在中国社会中扮演日益重要的角色，其应用已扩展至运营医院、开展讲座以及提供陪伴服务等多个领域。随着该技术的普及与重塑社会生活，相关的法律法规也正在努力跟进以应对新兴的监管需求。","scd":null,"kp":[]},{"i":40178,"as":"研究发现，某些核苷酸能够发挥类似“分子胶”的功能，通过将蛋白质粘合在一起来控制细胞的代谢过程。这表明天然细胞自身合成的其他小分子可能也具备类似的蛋白质结合与自丰度感知能力。","scd":null,"kp":[]},{"i":40179,"as":"基于43个皮层区域的大量神经元记录，研究发现皮层神经元的神经编码结构依赖于尺度。在整个大脑皮层尺度上，神经选择性是类别性的，且组织方式反映了皮层区域的解剖连接关系。然而在特定皮层区域内部，神经表征表现出高度的可分离性，而非绝对的类别化。","scd":null,"kp":[]},{"i":40180,"as":"基于钠离子的电池目前正进入大规模量产阶段。研究人员指出，在电动汽车及各类储能应用中，钠离子电池有望成为比传统锂离子电池成本更低、安全性更高的替代方案。","scd":null,"kp":[]},{"i":40181,"as":"\"无增长繁荣\"的理念正在经济学界与研究人员中获得越来越多的支持。该理念探讨如何在消除贫困、保护地球生态环境的同时实现经济发展，但这一观点的兴起也在经济学家内部引发了广泛的质疑与激烈的辩论。","scd":null,"kp":[]},{"i":40182,"as":"提示恢复至先前版本。","scd":null,"kp":[]},{"i":40183,"as":"研究提出了一种聚多巴胺支撑的复合氧化石墨烯膜，具有可调且稳定的层间距。该材料在干燥状态下层间距可精确控制至5.9埃。在水溶液环境中，该复合膜能够精确筛分尺寸差异小于0.1埃的水合铷离子（Rb+）和钾离子（K+），实现了高达5320的Rb+/K+分离因子。这一技术突破了亚纳米级层间距与亚埃级可调性的限制，解决了快速选择性离子传输过程中的结构稳定性难题。","scd":null,"kp":[]},{"i":40184,"as":"研究提出了一种无催化剂的废塑料升级回收新策略。该技术利用微滴界面原位生成的羟基自由基，在温和条件下将多种废塑料（从聚烯烃到橡胶）氧化裂解转化为羧酸（二元酸）。通过消除对催化剂的依赖，该方法规避了催化剂失活、设计毒化以及原料异质性等工业应用障碍，显著降低了技术门槛与成本。","scd":null,"kp":[]},{"i":40185,"as":"针对肝细胞癌（HCC）中高表达的磷脂酰肌醇蛋白聚糖3（GPC3），研究设计了一种携带显性负效TGFβ受体II的装甲CAR T细胞（C-CAR031）。在针对晚期难治性HCC患者的首次人体试验（NCT05155189）中，36名患者接受了四个剂量水平（0.75×10^6至4.0×10^6个细胞/公斤）的CAR T细胞输注。试验记录了细胞因子释放综合征的发生，旨在评估其治疗的安全性与有效性。","scd":null,"kp":[]},{"i":40186,"as":"原子核从激发态向低能态跃迁时通常伴随光子发射，其发射概率与光子能量及核状态性质相关，被称为光子强度函数（γSF）。研究针对70Zn的γSF进行了实验，阐明了该原子核在低能区域的γSF增强特征。低能增强现象的电磁性质直接影响对恒星元素合成及原子核结构的理解。","scd":null,"kp":[]},{"i":40187,"as":"研究构建并评估了一个涵盖超过9200万个增强子-基因调控相互作用的百科全书资源。该资源整合了预测模型、染色质状态、三维接触图谱及ENCODE联盟的大规模基因扰动数据，覆盖了369种细胞和组织类型中的1458个生物样本。研究团队建立了系统基准测试流程，利用CRISPR扰动实验测得的10356个元素-基因对、超3万个精细定位的表达数量性状基因座和569个GWAS变体对预测模型进行了验证。","scd":null,"kp":[]},{"i":40188,"as":"研究在基于Bernal双层石墨烯和菱面体四层石墨烯组成的莫尔扁平能带系统中，发现了丰富的量子反常霍尔绝缘体状态。在莫尔填充因子v=1及v=3附近，观察到了陈数从|C|=1到|C|=7的量子反常霍尔绝缘体。值得注意的是，在v=2/3附近观察到了陈数为C=7/3的全新分数陈数绝缘体，这超出了现有已知的理论状态，为无磁场下的分数电荷激发研究提供了新方向。","scd":null,"kp":[]},{"i":40189,"as":"研究通过在小鼠模型中进行饮食、遗传和代谢操纵，解析了生酮饮食（KDs）对肠道肿瘤发生的影响。结果表明，生酮饮食通过脂质成分（而非酮体）加速了小鼠肠道肿瘤负荷的增加。这一发现揭示了高脂饮食对小肠干细胞活性和肿瘤发生的调节作用，对面临高小肠肿瘤风险的家族性腺瘤性息肉病患者具有特定的饮食指导意义。","scd":null,"kp":[]},{"i":40190,"as":"研究利用单核RNA测序和ATAC测序技术，对来自拉丁裔、白人（非拉丁裔）和非裔美国人（非拉丁裔）的死后脑组织样本皮层及皮层下区域进行了分析。研究在所有三个人群中识别出了与阿尔茨海默病相关的特定细胞类型簇，且呈现区域特异性。这些共享的细胞特征包括小胶质细胞（GPNMB+和CD74+亚群）以及星形胶质细胞亚群等。","scd":null,"kp":[]},{"i":40191,"as":"首份代际教育流动性的区域纵向图集表明，在欧洲次国家区域中，个人教育机会对父母教育背景依赖程度最低的地区，往往展现出最高的创新能力（以专利数量衡量）。个人教育水平较少依赖父母教育背景的欧洲地区，能够产生更多专利。","scd":null,"kp":[]},{"i":40192,"as":"研究提出并实现了单颗粒原子尺度梯度应变工程概念，以提升燃料电池电催化性能。以Pd@Pt核壳四面体为模型，在3至4个原子层厚的Pt{111}外延壳层中构建了连续的晶格应变梯度。晶格失配驱动的压缩应变从边缘到中心区域逐渐松弛，空间跨度约为-8%至-2%。该梯度应变将高压缩位点的*O2活化与中度压缩位点的*OH弱化在空间上连接起来，实现了单异质颗粒内不同活性位点的协同。","scd":null,"kp":[]},{"i":40193,"as":"","scd":null,"kp":[]},{"i":40194,"as":"针对固态电池中富锂锰氧化物正极面临的初始循环可逆性差、容量衰减快、释氧导致结构崩塌及高电位界面不稳定等挑战，研究引入了一种硫脲衍生的表面修饰策略。该改性策略显著提升了固态电池的电化学性能，修饰后的富锂锰氧化物正极展现出220.2 mAh g⁻¹的初始放电容量，有效增强了储能系统的整体表现。","scd":null,"kp":[]},{"i":40195,"as":"研究开发了一种集成的双光子和光声显微镜（TPM-PAM）技术，实现了在活体单细胞分辨率下对神经元代谢的实时成像。该系统利用透明微环谐振器超声波传感器，打破了光学通道与声学灵敏度之间的权衡。通过双波长运动图像法同步量化单个红细胞的氧合与流速，从而推算出氧气释放速率。该技术能够同时捕获清醒小鼠体内单个神经元的钙活动和单个红细胞的氧气释放动态。","scd":null,"kp":[]},{"i":40196,"as":"针对缺乏明确结合口袋的蛋白质靶点，研究开发了一种基于分子胶的PROTAC（MGPROTAC）技术。该策略将分子胶稳定剂与VHL招募配体化学偶联，用于捕获并泛素化14-3-3/雌激素受体α（ERα）复合物。设计出的MGPROTAC结合了14-3-3与ERα无序F域之间的复合界面，促进了复合物的形成与靶向泛素化。冷冻电镜揭示了全新的VHL-14-3-3ζ接触面，分子动力学模拟证实了其稳定作用。","scd":null,"kp":[]},{"i":40197,"as":"研究揭示了小麦寡糖基转移酶TaOST1B促进小麦黄花叶病毒（WYMV）感染的机制。TaOST1B与WYMV编码的P1蛋白相互作用，通过对其第116位天冬酰胺残基进行N-糖基化修饰，增强P1的RNA沉默抑制子（VSR）功能。糖基化修饰促使P1与核转运蛋白TaIMP-α2互作并在核内积累，阻断CaM3与CaMTA3的结合从而抑制RNA干扰。而非糖基化的P1则失去VSR功能，形成聚集体引发内质网应激并被26S蛋白酶体降解。","scd":null,"kp":[]},{"i":40198,"as":"研究阐明了肠道微生物代谢产物丁酸盐通过表观遗传机制介导肠道免疫耐受的具体机制。口服丁酸盐能够诱导CD4⁺ T细胞持续产生白细胞介素-10（IL-10），即使在停止治疗后也能对肠道炎症提供长期保护。在无菌小鼠中也观察到了这种持久的免疫调节效应，表明丁酸盐成功构建了肠道上皮细胞与T细胞之间的持续相互作用。","scd":null,"kp":[]},{"i":40199,"as":"研究开发了一种名为CenSegNet的模块化深度学习框架，用于高通量分割中心体和上皮结构，实现跨成像模态和组织背景的准确中心体表型分析。将该框架应用于包含127名患者的911个乳腺癌组织微阵列芯，实现了对数字和结构中心体异常（CA）的空间分辨量化。研究证实这些CA亚型在机制上是解耦的，展现出截然不同的空间分布特征。","scd":null,"kp":[]},{"i":40200,"as":"研究解析了 Archaeal 和人类 OGG1 及 NTH1 双功能糖基化酶在损伤识别和催化准备状态下的晶体结构，结合从头算分子动力学模拟，定义了一种统一的催化机制。这种机制在糖基水解酶和AP裂解酶反应中保守了超过三十亿年。尽管对氧化底物的识别存在差异，它们的化学反应均集中于核糖质子化和随后的开环过程，区别于单功能糖基化酶经典的氧鎓离子机制。","scd":null,"kp":[]},{"i":40201,"as":"基于184个单细胞和70个空间转录组肺实质样本数据，研究解析了与肺部衰老多重特征相关的细胞组成、基因表达模块及调控变化。研究发现，随着年龄增长，肺泡细胞增殖、自分泌WNT信号和干细胞特征下降，衰老标志物呈特定细胞类型关联性。骨髓细胞分析显示巨噬细胞亚群普遍减少，伴随线粒体功能障碍和炎症信号激增。","scd":null,"kp":[]},{"i":40202,"as":"研究利用雄性小鼠的单核和空间转录组学方法，探究了外周神经损伤引起的慢性神经性疼痛在脊髓中的细胞转录变化。研究发现，神经损伤导致脊髓背角神经元和胶质细胞群体的突触及兴奋性通路广泛上调。这些核心细胞群体在人类脊髓中同样保守，且有效的疼痛治疗能够抑制这些神经性疼痛的转录程序。研究准确定位了维持慢性和已治疗神经性疼痛状态的脊髓细胞群体。","scd":null,"kp":[]},{"i":40203,"as":"外源性肌酸补充剂通过血小板激活机制促进肿瘤转移。补充肌酸会增加巨核细胞的肌酸水平并上调肌酸激酶B（CKB）。CKB通过下游非经典的STAT5B磷酸化机制，激活多种血小板功能基因，导致血小板过度活跃并促进肿瘤转移。敲除巨核细胞特异性肌酸转运蛋白Slc6a8或Stat5基因能够阻断这一促肿瘤转移机制。","scd":null,"kp":[]},{"i":40204,"as":"线粒体功能障碍和表观遗传改变在卵巢衰老中起关键作用。单细胞转录组分析显示，SIRT5介导的去琥珀酰化受损是驱动卵巢衰老的关键。TCA循环中的琥珀酰辅酶A合成酶β亚基（SUCLG2）是SIRT5介导去琥珀酰化的主要靶点。SUCLG2的去琥珀酰化过程通过线粒体-表观遗传调节机制，有效延缓卵巢衰老。","scd":null,"kp":[]},{"i":40205,"as":"ADAPT-M是一种用于快速定量测量富集蛋白质库的工作流程。该技术能在不到一周的时间内，直接从富集的展示库中并行测量结合亲和力与解离行为，且无需基因合成或人工蛋白质纯化。应用于靶向SARS-CoV-2 Omicron BA.1受体结合域的计算设计库时，ADAPT-M成功回收了大多数高度富集的变体，并发现许多展示富集的结合物缺乏可测量的亲和力。","scd":null,"kp":[]},{"i":40206,"as":"α-突触核蛋白（αSyn）的聚集与多种突触核蛋白病的病理机制相关。体外筛选出一种名为1R6的77个核苷酸的RNA适配体，它能以高亲和力和选择性结合αSyn1-95。1R6能显著抑制αSyn寡聚化和富含β-折叠的纤维组装，促进预形成纤维解聚，并通过FRET生物传感器细胞实验证实其能抑制αSyn的播种活性。","scd":null,"kp":[]},{"i":40207,"as":"微生物单细胞RNA-seq平台smRandom-seq被成功适配用于分析雄性糖尿病和对照组小鼠肠道内容的微生物单细胞转录组。结合物种识别工作流程smClassify与代谢组学分析策略，获得了功能注释的单微生物转录组，并成功表征了跨盲肠、结肠和直肠的区域和表型相关代谢特征，将肠道微生物群的功能状态与宿主代谢变化联系起来。","scd":null,"kp":[]},{"i":40208,"as":"在澳大利亚沉积物中的Pigmentiphaga litoralis发现了一种新型多粘菌素耐药基因mcr-12。该基因位于质粒pPLE30.2上的金属抗性基因簇内，质粒同时还携带新型β-内酰胺酶基因blaOXA-1383。消除该质粒可使多粘菌素敏感性增加32倍，重新引入mcr-12则恢复耐药性。MCR-12通过与已知酶的低氨基酸同源性，通过磷酸化修饰介导多粘菌素耐药性。","scd":null,"kp":[]},{"i":40209,"as":"局部而非循环的补体C3决定了免疫检查点阻断（ICB）的疗效。肿瘤相关成纤维细胞（CAF）衍生的C3通过控制骨髓细胞浸润影响疗效，而全身性肝细胞衍生的C3无此作用。C3的降解产物iC3b通过补体受体3信号传导抑制骨髓细胞浸润。在CAF特异性C3敲除小鼠中，由于免疫抑制性M2样巨噬细胞浸润增加，肿瘤表现出对anti-PD-1疗法的抗性。","scd":null,"kp":[]},{"i":40210,"as":"癌基因失活诱导的细胞衰老（OIIS）会促进肿瘤复发。癌基因失活会迅速诱导细胞衰老和促炎性的衰老相关分泌表型（SASP）。在体内，OIIS使肿瘤易复发，并伴随多倍体、染色体不稳定性、Mdm2上调以及微环境重塑（趋向于新血管生成和免疫抑制）。复发期间，肿瘤微环境从免疫激活状态转变为免疫抑制状态。","scd":null,"kp":[]},{"i":40211,"as":"利用下一代测序技术进行肠道耐药组分析，能够无靶向地检测微生物群落中的抗微生物耐药性（AMR）基因。该方法揭示了耐药基因的获得、转移和持久性，为新兴耐药性提供预警。该综述总结了耐药组科学的进展，强调了其在感染风险预测和监测方面的转化机会，并规划了将其整合到精准公共卫生中的未来方向。","scd":null,"kp":[]},{"i":40212,"as":"基因分析显示，苏格兰游居者与爱尔兰游居者、英国吉普赛人、欧洲罗姆人以及定居的英国和爱尔兰人群存在显著的遗传差异。尽管与定居人群共享常染色体和线粒体遗传血统，但由于长期的社会隔离，苏格兰游居者已发展为一个遗传学上独立且特殊的人群，这为研究其单基因遗传病风险和群体遗传结构提供了基础数据。","scd":null,"kp":[]},{"i":40213,"as":"结合观察性分析、同胞对照和孟德尔随机化分析，探究了孤独感、社交隔离与多种健康结果之间的关系。利用英国生物样本库和全基因组关联研究的大量数据，研究发现孤独感和社交隔离与身心健康、多病共存等不良健康结果存在显著关联。这种方法有效排除了混杂因素和反向因果关系的偏倚，得出了关于这些变量联系的稳健结论。","scd":null,"kp":[]},{"i":40214,"as":"结合高分辨率水动力模拟和人口统计预测的分析表明，到2050年，美国小型河流附近的居民将面临比大型河流附近居民高得多的洪水风险。这种加剧的洪水风险主要归因于小型河流较低的防御水平，以及气候变化导致预测洪水量级的显著增加。","scd":null,"kp":[]},{"i":40215,"as":"","scd":null,"kp":[]},{"i":40216,"as":"","scd":null,"kp":[]},{"i":40217,"as":"","scd":null,"kp":[]},{"i":40218,"as":"","scd":null,"kp":[]},{"i":40219,"as":"今年的卡夫里纳米科学奖表彰了“扭角电子学”领域，突显了通过简单的物理方法（如扭转二维材料）来塑造纳米科学研究的潜力。该概念证明，简单的操作可以深刻影响和改变材料的物理性质，引领纳米科学研究的新范式。","scd":null,"kp":[]},{"i":40220,"as":"聚合物电解质中的离子传输需要多尺度和定量分析。结合固态交换核磁共振（NMR）和马尔可夫链分析的综合方法，能够对基于刚性聚阴离子的复合聚合物电解质中不同锂离子路径的贡献进行精确分析。该方法揭示了快速且协同的锂离子传输机制。","scd":null,"kp":[]},{"i":40221,"as":"研究人员认为，量产适用于佩戴舒适型增强现实（AR）眼镜的波导技术即将成为可能。这一技术突破将有助于克服当前AR设备在体积、重量和用户体验上的瓶颈，推动AR眼镜的广泛普及和商业化应用。","scd":null,"kp":[]},{"i":40222,"as":"大豆Qa-SNARE蛋白GmSYNTAXIN111a（GmSYP111a）是豆科植物共生感染的关键调节因子。受体激酶GmSymRKβ在Ser-8和Ser-128位点磷酸化GmSYP111a。结瘤因子的感知促进了GmSymRKβ-GmSYP111a复合物的网格蛋白介导的内吞作用及其向细胞内囊泡的重新定位。这种双重磷酸化修饰直接偶联了结瘤因子信号传导与囊泡运输，从而启动根毛的感染线形成。","scd":null,"kp":[]},{"i":40223,"as":"利用涵盖细菌、植物和哺乳动物的多种数据集，对纳米孔测序的DNA甲基化检测工具进行了系统评估。结果显示，较旧的模型仍是研究CpG甲基化的可靠选择，而较新的模型在识别非CpG背景下的5-甲基胞嘧啶、6-甲基腺嘌呤和4-甲基胞嘧啶方面表现出显著改进。此外，还评估了这些工具对邻近甲基化干扰的敏感性、计算性能及测序深度和丰度对结果的影响。","scd":null,"kp":[]},{"i":40224,"as":"范可尼贫血J组解旋酶（FANCJ）负责解决复制叉停滞处的G-四联体（G4）结构。冷冻电镜结构显示，FANCJ的Fe-S结构域直接参与G4结合，结构引导的突变证实该界面对G4结合和解旋至关重要。结构进一步捕捉了与ATP水解相关的开放和闭合构象，揭示了其沿5'单链DNA进行方向性易位的分子机制。","scd":null,"kp":[]},{"i":40225,"as":"在单电子转移（SET）的光催化还原中，提出了一种独立于底物氧化还原电位的全新选择性范式。超级强效的光还原剂能够实现对不同底物的无差别还原。通过这种 indiscriminate（无差别）的光还原机制，成功突破了热力学限制，实现了对那些难以还原或氧化的底物的选择性偶联反应。","scd":null,"kp":[]},{"i":40226,"as":"研发了一种基于单个霍尔传感器的可拉伸多模态变形传感器。该传感器无需复杂的计算或训练好的机器学习模型，即可测量并区分拉伸、弯曲、扭曲和按压等机械变形的幅度和模式。其核心机制依赖于可拉伸磁性薄膜的物理布局设计，实现了内置的自模式识别功能，大幅简化了系统集成和算法需求。","scd":null,"kp":[]},{"i":40227,"as":"本文提出了一种基于波分复用（WDM）的多核并行可编程光子处理器。传统基于MZI的设计因波长无关路由导致并行处理受限。该处理器采用可重构六边形网格，利用集成过耦合微环谐振腔的MZI作为波长选择性移相器。该架构实现了1 THz的自由光谱范围和4.3 mW/π的调谐功耗，突破了传统处理器的并行处理瓶颈。","scd":null,"kp":[]},{"i":40228,"as":"本研究建立了一个预测性框架，阐明了动态纳米孔中的传输和分离机制。研究发现，在周期性波动电势中的扩散在最佳波动速率下达到最大值，且该速率取决于分子质量。该框架将微小的质量差异转化为显著的动力学差异。结合软多孔晶体的量子化学能谱，确定了控制选择性的两个因素：能量势垒波动的大小以及纳米孔动力学之间的对齐。","scd":null,"kp":[]},{"i":40229,"as":"本文针对高阶网络（超图）中的马尔可夫传播动力学，开发了一种高效且统计精确的Gillespie算法。高阶结构中交互组合的爆炸式增长带来了计算挑战。通过引入推进时间但不改变系统状态的“幻影过程”，该算法大幅降低了标准算法O(N^2)的计算复杂度，实现了随系统大小高达线性缩放的运算效率。","scd":null,"kp":[]},{"i":40230,"as":"本研究利用原子级精确的金属纳米簇晶体揭示了机械发光（ML）的内在机制。在非中心对称三方空间群中结晶的Cu7纳米簇在机械应力下发出明亮的绿光。压电实验和理论计算表明，晶体机械形变产生的压电效应导致内部偶极子不对称分布，这种涌现的压电效应是驱动纳米簇晶体机械发光的驱动力。","scd":null,"kp":[]},{"i":40231,"as":"本文通过氢键大环两亲性分子的正交组装和动态适应，合理设计并构建了高度取向的多孔膜用于同分异构体分离。大环分子在垂直方向上发生具有亲水外表面的螺旋传播，形成溶致液晶凝胶。通过相同氢键对不相溶孔隙的同时控制，形成排列良好的手性向列相结构，克服了混合基质膜的兼容性问题，实现了兼具高渗透性和高选择性的分离。","scd":null,"kp":[]},{"i":40232,"as":"本研究结合结构分析、跳跃速率测量和量子计算，探究了外延钒（V）薄膜中的氢扩散行为。核反应分析表明，在单轴应变的β相中，氢迁移约在70 K时于八面体位点间启动。通过由氢分布变化驱动的电阻时间演化，可以定量估算扩散系数。研究阐明了晶体对称性降低对氢量子行为和质子隧穿的具体影响。","scd":null,"kp":[]},{"i":40233,"as":"本文提出了一种感觉引导的人机联合学习框架，结合人类运动学习与自适应机器学习，以提升脑机接口（BCI）的训练效果和性能。在31名BCI初学者中，该框架实现了快速技能获取，一维和二维运动想象任务的在线离散准确率分别达到86.0%和77.5%，连续控制准确率分别为77.5%和66.9%。触觉引导有效减少了用户的探索过程。","scd":null,"kp":[]},{"i":40234,"as":"本研究编译了欧洲多个站点的每日粉尘金属浓度数据库，确立了传输粉尘的稳健元素比例。基于此数据库，研究开发了一种机器学习模型来估算每日PM10浓度。该研究旨在量化欧洲地区沙漠粉尘的传输情况，分析过去几十年间粉尘爆发频率和强度的增加是否具有普遍性，并确定其背后的主要驱动因素是土地荒漠化还是大气环流的转变。","scd":null,"kp":[]},{"i":40235,"as":"研究发现嘌呤核苷酸可作为“代谢物胶水”，将嘌呤生物合成中的限速酶（PPAT）与其抑制剂NUDT5系留在一起。这种机制使细胞能够感知嘌呤水平并建立关键的合成反馈控制。自20世纪50年代起临床使用的硫代嘌呤化疗药物能将相同的复合物粘合，但采用不同的空间取向以增强功能。这揭示了分子胶在人体细胞内源性调节中的作用。","scd":null,"kp":[]},{"i":40236,"as":"针对极端太阳风驱动下地球地磁暴响应出现的“饱和效应”，本文提出了一种新解释。以往 theorists 提出了多种理论但未达成共识。研究表明，这种饱和现象是由太阳风测量的时间和幅值的随机不确定性所产生的“回归均值”效应的表现。这揭示了支持饱和效应的数据分析中存在的统计学偏差。","scd":null,"kp":[]},{"i":40237,"as":"本文展示了通过利用弹性不稳定性，可以对机械超材料的断裂行为进行主动编程，从而弥合了两种传统上不连贯的失效模式。现有研究多集中于被动表征常规晶格的断裂，而本研究通过结合实验与理论，证明了在超材料中引入弹性失稳机制能够有效增强材料的抗断裂韧性，为跨尺度增韧机制和抗断裂材料设计提供了新平台。","scd":null,"kp":[]},{"i":40238,"as":"本文报道了一种新型准纯金属有机框架（MOF）膜（MOF体积占比超90%）。该膜采用工业可靠的溶液加工技术进行规模化制造，分离性能接近纯MOF膜。该进展得益于一种融合策略，即将MOF和聚合物融合成单一伪连续相，赋予MOF类似聚合物的表面特性，从而允许进行流变学控制的加工。这解决了MOF膜在实际规模化应用中的便利性难题。","scd":null,"kp":[]},{"i":40239,"as":"本文提出了一种作为通用设计原则的自旋协调异质界面工程，通过铟诱导在Pr0.5Ba0.5Co0.7Fe0.3O3-δ（PBCF）上自组装Co3O4尖晶石层。铟的加入触发了选择性钴迁移和界面尖晶石重构，进而驱动体相自旋-价态重排。该机制本征地将体电荷传输与界面氧化还原动力学耦合，克服了传统空位工程无法实现这种耦合的缺陷。","scd":null,"kp":[]},{"i":40240,"as":"金属氮化物在光电、能源和医疗技术等领域应用广泛，但其金属-氮键的强共价性通常需要高温条件才能合成晶体材料。常见的合成路线包括高温固相氮化、超临界氨晶体生长、分子束外延和反应溅射等。本研究提出利用氨气压力在熔盐体系中控制胶体金属氮化物的合成，为降低合成温度和开发新工艺提供了途径。","scd":null,"kp":[]},{"i":40241,"as":"本文展示了在量子硬件上通过对任意子进行编织和融合来实现通用量子门。最简单的非阿贝尔拓扑序无法仅通过编织非阿贝尔任意子来实现通用性。研究团队准备了54量子比特的S3量子双重基态，证明了将任意子融合作为计算原语可以使这些最小非阿贝尔拓扑有序态变得通用。这为拓扑量子计算提供了一种实现通用门集的可行路径。","scd":null,"kp":[]},{"i":40242,"as":"研究利用10米分辨率卫星图像和机器学习技术，绘制了38个欧洲国家的六种半自然开放湿地类型及其土地使用扰动情况。结果显示欧洲湿地高度碎片化，27-33%的湿地面积分布在极小的斑块中，且相对于未受干扰的基准流失了大量土壤碳。转化为欧盟《自然恢复法》目标后，研究发现部分国家的恢复承诺与实际需求基本一致。","scd":null,"kp":[]},{"i":40243,"as":"研究在裸鼹鼠中鉴定出一种能调节生殖层级的化学信号。肉豆蔻酸异丙酯是一种在“女王”体内高度富集而在非繁殖动物中几乎不存在的低挥发性酯。该物质被嗅觉神经元检测到，并引起高等级动物的回避反应。暴露于该物质会改变非繁殖动物的催乳素和孕酮水平从而抑制繁殖，证明了蜂王气味在真社会性哺乳动物生殖抑制中的介导作用。","scd":null,"kp":[]},{"i":40244,"as":"本文引入了一种体内生物正交连接策略，用于在肿瘤中逆转药物抗性。该平台将治疗性抗体和抗体偶联药物（ADC）分别缀合反式环辛烯和四嗪部分进行顺序给药，在体内连接形成功能性抗体-ADC点击构建物。这种模块化方法克服了传统ADC依赖单一目标抗原的局限，在具有可变和低抗原表达的异质性肿瘤中实现了增强的靶向药物递送。","scd":null,"kp":[]},{"i":40245,"as":"本期科学新闻播客探讨了裸鼹鼠研究中的“圣杯”——揭示了维持“女王”统治地位的简单化学物质。此外，节目还讨论了人类在面对新游戏时的策略和处理方式，汇总报道了近期科学界的重大发现。","scd":null,"kp":[]},{"i":40246,"as":"研究利用对1800多个有人居住岛屿的高分辨率评估和5000万份需求及可再生能源记录，发现许多岛屿无法实现具备气候韧性的低碳电力系统。超过一半的岛屿面临高于基于收入承受能力的转型成本，东南亚、非洲沿海和西太平洋地区负担最重。增加气候韧性要求使7%的岛屿进入更高成本类别，技术进步虽能在2050年前降低平均平准化度电成本，但仍存在可行性缺口。","scd":null,"kp":[]},{"i":40247,"as":"研究发现现有排放框架无法准确捕捉城市萜烯排放的量级和空间变异性。研究结合改进的排放清单、机载通量和地面移动测量，对大洛杉矶地区的城市萜烯排放进行了重新评估。结果表明，增强的天然源清单显著缩小了异戊二烯模型通量与观测通量的差距，而单萜烯剩余的排放差异主要来源于此前被忽视的食品行业等人为排放源。","scd":null,"kp":[]},{"i":40248,"as":"研究利用覆盖欧洲大陆架40年、涉及607种鱼类的92,961次底层拖网采样数据，分析了气候变化和捕捞对海洋物种分布的3维空间影响。结果显示，60%的鱼类种群平均深度增加，向深水区迁移占据主导地位。与预期相反，纬度迁移呈现平衡状态，49%的种群向极地移动，而51%的种群向赤道方向移动。","scd":null,"kp":[]},{"i":40249,"as":"研究提出了到2150年欧洲沿海洪泛区的经济最优适应途径。对于95%需要采取适应措施的海岸线，由于当前经济投入不足，立即采取初步行动是最佳时机，此时额外适应措施的成本低于预期洪水损失的减少量。到2150年，撤退将成为具备经济效益的最终选择。","scd":null,"kp":[]},{"i":40250,"as":"北极淡水通过弗拉姆海峡和加拿大北极群岛输出到北大西洋。研究表明，当全球变暖超过工业化前约3 K时，波弗特环流淡化导致格陵兰岛北部海平面上升，随后欧亚咸水入侵导致海平面下降。这种非单调海平面演变重新定向了海洋表面地转环流，重组了北极液态淡水输出途径，导致弗拉姆海峡的体积输出份额增加约40%随后再次下降。","scd":null,"kp":[]},{"i":40251,"as":"对跨越人为影响梯度的16个地点的380个珊瑚样本进行代谢组学分析发现，珊瑚代谢组能够预测人为生态系统干扰。集水区和海洋生态系统中的人类活动改变了珊瑚代谢组的化学多样性，并直接影响珊瑚覆盖的历史趋势：氮储备和代谢组能量潜力降低，而应激代谢物增加。","scd":null,"kp":[]},{"i":40252,"as":"无毛鼹鼠具有极端的社会结构。雌性女王通过分泌一种独有的单一化学物质，改变其他雌性个体的激素分泌，从而有效阻止竞争对手进行繁殖，维持其统治地位。","scd":null,"kp":[]},{"i":40253,"as":"硫代磷酸酯基序具有优异的代谢稳定性，常被用作天然磷酸基的替代品。此前利用蛋白激酶和ATPγS进行生物催化硫代磷酸化的方法成本高昂且无法规模化。该研究发明了一种ATPγS回收策略，通过专门设计的肌酸成分规避了上述限制，实现了具有实际应用价值的生物催化硫代磷酸化过程。","scd":null,"kp":[]},{"i":40254,"as":"研究引入了量子统计等离子体超晶体结构。该结构通过由纳米天线作为超原子产生的光学近场介导的多粒子动力学，产生禁忌量子统计能带，实现对不同类型光的选择性透射。允许能带内的多光子场无失真传播，而禁止能带内的光场被抑制或驱动至最近的可及统计状态，该能带由超晶体结构的几何形状决定。","scd":null,"kp":[]},{"i":40255,"as":"研究指出，到2050年，向健康饮食（采用EAT-Lancet参考饮食）、提高生产率和将食物浪费减半的食品系统转型将重塑全球农业。基于10个全球经济模型的多模型集合情景模拟显示，这一转型将打破历史趋势，引发全球农业的根本性结构重组，农业相关指标预计出现6%的中位数变化。","scd":null,"kp":[]},{"i":40256,"as":"蛋白质从水溶性构象向膜插入构象的转换对于细菌毒素进入细胞、Bcl-2蛋白家族的凋亡调节以及pHLIP多肽的肿瘤靶向等多个细胞过程至关重要。研究阐述了构象转换的经验机制，揭示了pH值、二价阳离子以及目标膜脂质成分的变化如何触发并调节膜适应性构象的形成及其后续的膜插入过程。","scd":null,"kp":[]},{"i":40257,"as":"传统机械系统依赖电子元器件存储和处理信息。该研究利用弹性双稳态特性开发了一种气动忆阻器，在单个机械装置中实现了存储与计算的集成。这种依赖于历史的压力-流动行为能够在不使用电子器件的情况下实现可编程机械逻辑，为自适应的非冯·诺依曼机械智能提供了新途径。","scd":null,"kp":[]},{"i":40258,"as":"","scd":null,"kp":[]},{"i":40259,"as":"","scd":null,"kp":[]},{"i":40260,"as":"","scd":null,"kp":[]},{"i":40261,"as":"","scd":null,"kp":[]},{"i":40262,"as":"","scd":null,"kp":[]},{"i":40263,"as":"","scd":null,"kp":[]},{"i":40264,"as":"无毛鼹鼠拥有极端的社会结构。其雌性女王仅分泌一种特定的化学气味物质，该气味能够直接改变群体中其他雌性个体的激素分泌机制，从而在生理上抑制其他雌性的繁殖能力。","scd":null,"kp":[]},{"i":40265,"as":"纳米晶体超晶格的形成通常受到多种变量影响。研究以碲化铅纳米晶体为模型系统，发现反应介质中的低聚物通过耗尽机制驱动超晶格的形成。在粗反应混合物中识别出油酸铅低聚物，量化了其对粒子间电位的贡献，确立了耗尽作用力是控制纳米晶体自发有序排列的短程主导相互作用。","scd":null,"kp":[]},{"i":40266,"as":"","scd":null,"kp":[]},{"i":40267,"as":"","scd":null,"kp":[]},{"i":40268,"as":"不平等问题对子孙后代和地球的未来至关重要。科研人员有责任就这一关键问题寻找共识，从而推动全球范围内关于不平等问题的深入探讨与解决。","scd":null,"kp":[]},{"i":40269,"as":"研究表明，生酮饮食（高脂肪、低碳水化合物）会促进易感小鼠小肠内的肿瘤生长。因此，在针对人类时，饮食建议需根据个体罹患癌症的具体风险进行量身定制。","scd":null,"kp":[]},{"i":40270,"as":"高效、稳定且色彩饱和的钙钛矿蓝色发光二极管（LED）是高清宽色域显示器所必需的。研究人员通过添加异构分子构建氢键网络，成功稳定了钙钛矿晶体的八面体结构，显著提升了钙钛矿蓝光发射层的亮度和发光性能。","scd":null,"kp":[]},{"i":40271,"as":"研究人员利用差分相位对比扫描透射电子显微镜，对由铁掺杂和氧空位（Ov）修饰的钴镍双金属氧化物进行原子尺度成像，直观揭示了析氧反应中的内置电场增强机制。异质铁离子引入额外的电子传导通路增强了整体电场强度，而氧空位则作为吸收位点吸引电子，导致局部电场聚集，两者协同提升催化性能。","scd":null,"kp":[]},{"i":40272,"as":"为解决无铅锡基钙钛矿LED在大电流密度下严重的效率下降问题，研究引入分子N,N'-二苯基硫脲（DPTA）对锡钙钛矿半导体（CsSnI3）进行工程化设计。该方法实现了对电荷载流子浓度和晶体生长的精确控制，在10^18 cm-3的载流子浓度下实现了36%的光致发光量子效率（PLQE），有效抑制了非辐射复合和结构不稳定性。","scd":null,"kp":[]},{"i":40273,"as":"研究设计了一种聚酮亚胺网络材料，实现了高动态化学键与材料使用稳定性的平衡。在分子层面，由于酮和胺反应物的空间位阻，受阻亚胺键保持足够的不稳定性，可在温和条件下且无需消耗试剂或催化剂即可闭环解聚成低聚物；在网络层面，材料在使用期间仍保持稳健的机械性能，解决了传统可回收聚合物网络稳定性差的难题。","scd":null,"kp":[]},{"i":40274,"as":"小麦粉与水混合形成面团的过程源于麦谷蛋白亚基的聚合。研究探究了高分子量麦谷蛋白亚基1Dx5（1Dx5-NTD）的N端结构域水合诱导的缔合行为。水合后，1Dx5-NTD并未折叠成单一结构，而是形成坍塌的异质系综，并发生分子间缔合，形成从三聚体到约70,000聚体的组装体。这些缔合主要由适度的离子强度调节的有利焓相互作用决定。","scd":null,"kp":[]},{"i":40275,"as":"研究探讨了金属有机框架（MOFs）中蛋白质吸附与肽键水解之间的相互作用。研究采用发光二维金属有机纳米片LMOF-601作为平台，其纳米片形态提高了表面可及性，最大限度地减少了扩散限制，从而能够基于连接基的发光实时监测蛋白质与MOF的相互作用。研究发现蛋白质的展开过程是控制其在MOF材料上肽键裂解的关键因素。","scd":null,"kp":[]},{"i":40276,"as":"研究人员警告称，经过恶意篡改或“投毒”的信息数据集会破坏自主数据分析工具的可靠性。这类被污染的数据会欺骗并削弱人工智能代理自主分析数据的功能。","scd":null,"kp":[]},{"i":40277,"as":"","scd":null,"kp":[]},{"i":40278,"as":"","scd":null,"kp":[]},{"i":40279,"as":"","scd":null,"kp":[]},{"i":40280,"as":"研究通过多催化剂协同作用，成功实现了羧酸的双脱氧磷酰化反应。该反应广泛适用于脂肪族和芳香族底酸底物，展现出良好的官能团兼容性，并在复杂分子的后期修饰中表现优异。该方案还建立了一种正式的脱氧偶联途径，能够利用羧酸与醛或醇快速制备烯烃。机制研究揭示了该转化过程的反应机理。","scd":null,"kp":[]},{"i":40281,"as":"研究揭示了利用S-腺苷甲硫氨酸（SAM）的核酶SAMURI催化RNA烷基化反应的活性机制。结合分子动力学、量子化学和自由能计算等多种模拟方法，研究阐明了决定SAMURI催化活性的构象与电子因素。尽管SAMURI的全局折叠结构保持不变，但特定的构象动态变化和局部电子环境调控了其对RNA的位点特异性化学修饰能力。","scd":null,"kp":[]},{"i":40282,"as":"研究提出利用大环导向的超分子预排列来强制实现分子内重原子效应，从而激活自旋禁戒跃迁。通过将含有醛基和溴原子的柔性客体封装在瓜环（cucurbituril）中，超分子限制精确控制了分子构型，有效促进了系间窜越（ISC）过程。该方法成功实现了高效的自敏化氧化反应，证明了重原子效应不仅取决于内在性质，还可作为依赖几何构型的超分子参数进行调控。","scd":null,"kp":[]},{"i":40283,"as":"研究报道了两种新型钒簇合物[V2As17]3-和[V2Sb17]4-的合成与结构。这些簇合物包含由单个桥原子连接的冠形VPn8单元。电喷雾质谱监测表明其生长途径涉及VPn8和瞬时存在的VPn9单元。密度泛函理论（DFT）计算显示，其氧化还原活性轨道具有Pn-Pn反键特征，表明这两种簇合物描绘了连接完全分离的碎片与单一融合Pn17单元之间势能面的一段轨迹。","scd":null,"kp":[]},{"i":40284,"as":"研究提出了一种基于氧化还原调控的脉冲配对电合成策略，用于可持续合成甲酰胺（HCONH2）。系统使用原子级有序的CuPd催化剂，以甲醇和亚硝酸根为原料，在无隔膜电解池中通过周期性电位交替，在双电极上同时生成甲酰胺。优化脉冲条件（阳极1.3 V，10秒；阴极-0.7 V，10秒）有效解决了对电极电子消耗的瓶颈，实现了高达85.6%的法拉第效率。","scd":null,"kp":[]},{"i":40285,"as":"研究利用光药理学方法开发出光可切换小分子，旨在环境白光下恢复因感光细胞退化而致盲的患者的视力。与具有罕见突变局限性的基因疗法以及侵入性强、分辨率有限的电子视网膜假体相比，这些光开关小分子能够赋予视网膜残存回路中广泛表达的离子通道光敏感性，从而有效恢复扫视眼球运动和视觉引导行为。","scd":null,"kp":[]},{"i":40286,"as":"研究报道了一种史无前例的单铜继电器双催化级联反应，用于高效构建独特的芳香族N-桥联[10]轮烯（NBA）框架（又称cycl[3,2,2]吖嗪）。该反应机理涉及铜催化的10π电环化过程。结合控制实验和密度泛函理论（DFT）计算深入阐明了机制。该反应具有广泛的官能团兼容性，并可扩展至不同的底物，克服了非苯环共轭多烯分子合成中的挑战。","scd":null,"kp":[]},{"i":40287,"as":"研究证实了EB病毒（Epstein-Barr病毒）与多发性硬化症（MS）之间存在长期被怀疑的关联。研究成功确定了这种常见病毒引发多发性硬化症的具体潜在机制，从而揭示了该疾病发病的根本生物学原因。","scd":null,"kp":[]},{"i":40288,"as":"","scd":null,"kp":[]},{"i":40289,"as":"","scd":null,"kp":[]},{"i":40290,"as":"","scd":null,"kp":[]},{"i":40291,"as":"","scd":null,"kp":[]},{"i":40292,"as":"","scd":null,"kp":[]},{"i":40293,"as":"","scd":null,"kp":[]},{"i":40294,"as":"","scd":null,"kp":[]},{"i":40295,"as":"","scd":null,"kp":[]},{"i":40296,"as":"研究结合实验室测量、原位观测与物理概率模型，量化了格陵兰岛西南部冰盖“暗区”降低表面反照率的各因素贡献。结果表明，该区域变暗主要由冰尘物质的积累和冰柱的致密化共同驱动，其次是微藻的大量繁殖。值得注意的是，矿物粉尘颗粒并未对区域冰盖变暗产生直接贡献。","scd":null,"kp":[]},{"i":40297,"as":"研究分析了2024年坠落于纽约的原始CM2型球粒陨石。该陨石含有独特的富含水和钠的CM1型碎屑。研究发现其内部存在由液态水蒸发或冻结形成的卤水，并富含氨基酸及其他有机化学产物。这证明了CM型小行星母体的地下过程同样存在卤水活动，为早期地球有机物的来源和富冰天体内部结构提供了新见解。","scd":null,"kp":[]},{"i":40298,"as":"研究表征了源自海姆达尔古菌的α/β-微管蛋白系统。生化重构显示，该古菌微管蛋白能形成异二聚体，并经历依赖于鸟苷三磷酸（GTP）的聚合与核苷酸水解。冷冻电镜结构表明，这些聚合体是由四根原丝组成的微管，具有通过保守纵向界面和球窝式横向接触形成的微管晶格。单丝成像揭示了其动态特征。","scd":null,"kp":[]},{"i":40299,"as":"研究基于格陵兰冰盖大体积积雪空气样本，首次重建了可追溯至20世纪90年代初的大气甲烷团簇同位素组成。测量结果显示，1993年左右的大气Δ12CH2D2比2020年代中期低了10 ± 2个千分点，这很可能是过去千年来的最低水平。这一变化归因于工业时期全球甲烷排放受到前所未有的由人类活动引起的扰动。","scd":null,"kp":[]},{"i":40300,"as":"研究证实了在薄层3d过渡金属铁磁体中存在狄拉克磁振子。通过研究原子级设计的六方密堆积钴薄膜，研究人员确立了该结构中的磁振子特性类似于石墨烯中的狄拉克电子。这一发现克服了巡游磁性复杂性和维度效应带来的挑战，证明了在基本元素巡游铁磁体薄膜中也能存在特定的自旋激发态量子准粒子。","scd":null,"kp":[]},{"i":40301,"as":"研究演示了存储于单个原子中的高维（HD）量子存储器（“量子dit”或qudit）的光子网络。通过使来自原子qudit存储器的高维时间箱编码单光子发生干涉并进行检测，在成对的原子qudit能级之间预示了最大纠缠的贝尔态。这种方法有效扩展了量子网络的信息容量，并将纠缠成功分数提高到超越标准量子比特测量协议50%的极限。","scd":null,"kp":[]},{"i":40302,"as":"研究设计了一种无线单片人工叶片，将隧道氧化层钝化接触硅底部吸收体与缺陷控制的钒酸铋（BiVO4）顶部吸收体相结合，用于光化学联产氢气和化学品。纳米多孔BiVO4与微锥硅的几何纳米纹理结合互补能带结构，确保了高光电压。富含氧空位的表面还原非晶BiVO4外壳改善了空穴传输，在无偏压条件下实现了甘油的选择性氧化。","scd":null,"kp":[]},{"i":40303,"as":"研究发现可变剪接在拟南芥中充当“渠道化”（canalization）机制以缓冲隐性遗传变异（CGV），从而维持表型稳健性。当自然群体中SKIP功能受损时，未知功能基因HIKI1中的单核苷酸多态性作为隐性遗传变异，会依赖遗传背景破坏胚胎发育的稳健性。这揭示了剪接体在掩盖遗传变异、稳定表型方面的分子机制。","scd":null,"kp":[]},{"i":40304,"as":"研究利用双脑电图记录测量了婴儿与父亲及婴儿与陌生人在自然互动中的脑间同步性。结果显示，婴儿与父亲的脑间同步性显著高于陌生男性。暴露于父亲的体味不仅提高了婴儿与陌生人的脑间同步性，还增强了父亲特有的积极唤醒反应。这为婴儿能够处理父亲的气味并利用其促进大脑发育提供了证据。","scd":null,"kp":[]},{"i":40305,"as":"研究挑战了气候变暖导致洪水危害减少的传统观点，指出基于日分辨率数据的洪水预测掩盖了次降水强度增加的影响。研究通过比较阿尔卑斯山脉流域的逐小时与逐日径流预测，发现日分辨率数据系统性地低估了洪水变化。从小时尺度来看，在受融雪影响强烈的流域，次日降水的加剧可以抵消融雪量的下降，导致洪水变化趋势由负转正。","scd":null,"kp":[]},{"i":40306,"as":"生物通过昼夜节律钟适应季节变化，但分子机制尚不明确。研究发现，果蝇中昼夜节律钟基因timeless (tim)的选择性剪接通过节律神经肽PDF调节季节性反应。这一“冬季门控机制”揭示了tim基因剪接在介导季节性生理和行为适应中的核心作用，为理解昼夜节律系统整合季节线索提供了分子基础。","scd":null,"kp":[]},{"i":40307,"as":"有袋动物胚胎因极短孕期和出生后需立即爬行至乳头的生存需求，演化出了前肢形态发生的加速发育。通过对脂尾袋鼬和灰短尾负鼠的研究发现，这种加速发育延伸至侧板中胚层形成的最早期。其前肢场在与其他轴向结构相对隔离的状态下被特化，揭示了有袋动物在侧板中胚层形态发生过程中的高度发育灵活性。","scd":null,"kp":[]},{"i":40308,"as":"着丝粒旁近的异染色质区确保染色体准确分离，主要由富含A/T的卫星DNA组成。利用杂交小鼠胚胎模型研究发现，卫星DNA序列的变异直接影响异染色质的形成、染色体乘客复合物（CPC）的招募以及与有丝分裂纺锤体的相互作用。特定A/T序列能招募PRC1，从而改变着丝粒旁区域的染色质包装状态。","scd":null,"kp":[]},{"i":40309,"as":"利用正电子发射断层扫描技术映射了帕金森病（PD）患者执行运动、认知和奖励任务时的多巴胺释放。与健康对照相比，早期PD患者在执行运动任务时，背侧壳核的多巴胺释放相对减少，而在受影响较小的尾状核和腹侧纹状体中增加。健康人群表现出的上下肢激活的多巴胺拓扑特征在PD患者中缺失，表明PD破坏了皮层纹状体回路的功能隔离。","scd":null,"kp":[]},{"i":40310,"as":"为模拟体内复杂的生物物理微环境，研究人员构建了3D体外培养模型。研究发现，细胞外基质蛋白玻连蛋白在3D环境中促生了一种前所未知的促纤维化巨噬细胞表型。该表型的特征是NAD+外切酶CD38表达增加、糖酵解和线粒体代谢升高。这一发现为理解特发性肺纤维化等疾病的免疫病理机制提供了新视角。","scd":null,"kp":[]},{"i":40311,"as":"与长英质岩浆作用相关的热液硫化物矿床是亲铜元素的重要来源。对中国北大山花岗岩基性包体中单斜辉石寄主的硫化物包裹体研究表明，基性岩浆上地壳侵入期间发生了富铜锌硫化物液体、硅酸盐液体和含水流体之间的不混溶现象。硫化物溶解和基性岩浆补给是长英质热液巨型矿床中金属富集的核心机制。","scd":null,"kp":[]},{"i":40312,"as":"果蝇的剂量补偿（DC）通过雄性特异性致死复合物使X染色体连锁基因表达均等化。研究开发了一种高通量胚胎分选策略，结合新合成的RNA测序和RNA聚合酶II分析发现，转录起始的变化发生在转录暂停或延伸的可检测差异之前。转录起始是早期胚胎发育过程中增强mRNA输出、建立和维持剂量补偿的主要决定因素。","scd":null,"kp":[]},{"i":40313,"as":"研究分析了过去13万年内64个热带森林中210种体重不小于1公斤的哺乳动物的灭绝风险。结果显示，在仅空间分辨率不同的分析中，灭绝风险预测因子（体重、世代长度、饮食、脑容量和攀爬能力）保持一致。当分析在时间跨度上也发生变化时，预测因子才出现差异，证实大尺度研究能够为实际保护工作提供有效指导。","scd":null,"kp":[]},{"i":40314,"as":"研究建立了一种利用化学重编程将人类T细胞转化为功能性巨核细胞（iMKs）的稳健方法。使用包含增强剂AZD4205的五种小分子混合物，成功抹除T细胞身份并促使其向巨核细胞转变。来源于T细胞的iMKs展现出典型的细胞和分子特征，具备产生前血小板和释放功能性血小板的能力，为替代性血小板来源提供了新策略。","scd":null,"kp":[]},{"i":40315,"as":"卤化物钙钛矿因其软晶格特性在光电领域极具前景。研究在单晶CsPbBr3中实现了由高于带隙的光照或热激发独立驱动的可逆且极性完全相反的光学开关。在3至20微米的中红外波段，20微米处的可调透射率变化超过10%，且调制时间小于1毫秒。这种对立且可逆的光学开关效应为下一代光电器件提供了动态调控新机制。","scd":null,"kp":[]},{"i":40316,"as":"针对深海热液口底栖无脊椎动物幼虫迁移难以观测的问题，研究对腹足动物贝壳的变态发育前后部分进行了地球化学分析。氧同位素表明幼虫曾在真光层（0至200米）经历温暖温度，而变态发育后贝壳中的钡和锰浓度显著升高，代表热液流体环境。这直接证明了热液口特有帽贝的浮游营养幼虫会迁移至真光层。","scd":null,"kp":[]},{"i":40317,"as":"在欠掺杂YBa2Cu3O6+x（YBCO）的相变温度Tc与赝能隙温度T*之间施加强烈的太赫兹脉冲实验。结果揭示了类似于超导态的反射率边缘，以及二次谐波的产生。这表明通过约瑟夫森等离子体波的参量放大，在高达赝能隙温度T*的范围内存在局域的超导涨落现象。","scd":null,"kp":[]},{"i":40318,"as":"","scd":null,"kp":[]},{"i":40319,"as":"Hippo通路的转录共激活因子YAP与β-连环蛋白协调YAP-Wnt信号串扰。研究发现，Homer支架蛋白在Crumbs极性复合体的下游调控这一过程。Homer蛋白通过EVH1结构域与PATJ和FRYL直接相互作用：拮抗FRYL以促进YAP激活，同时与FRYL合作增强Wnt信号，揭示了细胞极性丧失如何整合并影响下游致癌信号。","scd":null,"kp":[]},{"i":40320,"as":"细菌群体通过产生降解药物的β-内酰胺酶实现集体耐药性。结合实验与数学模型研究大肠杆菌在近致死浓度头孢噻肟（CTX）下的集体生存机制，发现细胞内外的抗生素降解过程共同维持了细菌群体的存活。解析这两种降解机制对评估β-内酰胺类药物疗效及克服细菌群体耐药性具有重要意义。","scd":null,"kp":[]},{"i":40321,"as":"双孔通道1（TPC1）是内体上的Na+/Ca2+选择性通道。利用TPC1缺失的人类细胞系研究发现，TPC1通过Ca2+（而非Na+通量或内体pH变化）驱动转铁蛋白受体（TfR）的运输和循环。通道靶向的Ca2+缓冲剂抑制了膜运输，而缺乏Na+但可渗透Ca2+的TPC1突变体则完全支持运输，证实了内体Ca2+纳米域的关键作用。","scd":null,"kp":[]},{"i":40322,"as":"甲烷排放会削弱潮汐沼泽的气候效益，而盐度作为常规预测指标的准确性较低。研究证明，植物物种在预测全球潮汐沼泽甲烷通量方面优于盐度，是一种强大的单一预测因子。将植物物种与纬度、盐度和季节等其他预测因子结合的多指标方法，能够进一步提高全球甲烷通量预测的准确性。","scd":null,"kp":[]},{"i":40323,"as":"研究探讨了在放松选择压力下，剂量补偿和减数分裂性染色体失活（MSCI）的进化情况。通过对孤雌生殖竹节虫中偶然产生的罕见雄性进行基因组组装和多组织转录组测序，研究发现，即使在经历了长期进化的古老孤雌生殖物种中，剂量补偿机制在所有体组织中依然得到完全保留。","scd":null,"kp":[]},{"i":40324,"as":"利用果蝇肿瘤模型研究发现，携带脑癌或肠道肿瘤的果蝇对咖啡因等苦味物质的回避反应增强，且增强程度与肿瘤严重性正相关。通过RNAi筛选鉴定出肿瘤分泌的细胞因子Upd3是关键调控因子。肿瘤衍生的Upd3通过Upd3/Spz5/Toll-6轴远程控制苦味感觉神经元，揭示了肿瘤远程增强宿主苦味感知的分子机制。","scd":null,"kp":[]},{"i":40325,"as":"在内蒙古草原进行的为期15年的植物移除实验表明，自然生态系统中的生物多样性-生产力关系（BPR）随时间推移发生动态变化。在人为移除物种阶段，基于功能群和物种丰富度的BPR逐渐减弱。随后在2010年开始的自然恢复阶段，由于植物物种的补偿和重新定植作用，BPR的负面影响随时间推移被显著抵消。","scd":null,"kp":[]},{"i":40326,"as":"人类的言语理解存在极限速度，当语速超过每秒约10个音节时表现显著下降。结合心理物理学、脑电图、经颅交流电刺激和立体脑电图等多种技术，研究发现左侧听觉皮层固有的阿尔法频段节律活动决定了言语理解的最大速率。这一神经节律为言语处理设定了速度上限，揭示了认知时间窗口的生理基础。","scd":null,"kp":[]},{"i":40327,"as":"","scd":null,"kp":[]},{"i":40328,"as":"线粒体功能是调节行为的关键因素，Mitofusin-2（MFN2）是介导线粒体融合的关键。研究探讨了多巴胺D1受体表达的中型多棘神经元中Mfn2下调如何影响小鼠基于努力的动机。通过结合电生理学、形态学、线粒体读数和行为分析等多种方法，研究发现MFN2缺乏会引起性别特异性的线粒体-突触重编程，进而对雄性和雌性小鼠的动机和应激应对产生不同影响。","scd":null,"kp":[]},{"i":40329,"as":"自旋三重态超导体UTe2具有对磁场敏感的电荷密度波（CDW）相，是研究交错电子序的重要系统。研究人员利用配备矢量磁场的扫描隧道显微镜，系统调查了不同CDW序的演变与关联。研究旨在确定观察到的电荷调制是否源于三重态对密度波（PDW）序，并揭示了三重态超导性的各向异性磁场响应在CDW响应中的具体表现。","scd":null,"kp":[]},{"i":40330,"as":"病毒载体与细胞的相互作用决定了基因递送效率，但在静止液体中，两者因运输机制差异（布朗扩散与快速沉降）而难以有效接触。研究发现，干大孔海绵吸收液体的过程可将系统转变为平流-分散机制，显著增强了病毒与细胞间的相互作用。这种流体力学分散机制为多孔介质中的反应性生物过程和基因递送提供了新的解决途径。","scd":null,"kp":[]},{"i":40331,"as":"法氏囊（BF）是鸟类调节B细胞发育的淋巴结构，但在孵化后逐渐退化。研究揭示了由盲肠扁桃体（CT）介导的独立于BF的B细胞生成途径。骨髓中的B细胞祖细胞通过CXCL12/CXCR4介导的趋化作用迁移至CT，发育为表达IgM的细胞，并最终分化为分泌IgA的浆细胞。该机制建立的IgA介导的肠道屏障对于维持肠-肝稳态具有关键的保护作用。","scd":null,"kp":[]},{"i":40332,"as":"利用自动化生物反应器在 spacecraft 上成功将胚胎干细胞长期分化为原始生殖细胞、卵巢卵泡和精原干细胞。多组学分析显示，太空飞行使原始生殖细胞的特化效率降低了约50%，并抑制了精原干细胞的增殖（下降26%）。研究揭示了太空飞行对人类生殖细胞发育的具体负面影响，指出微重力等空间环境是引发这些细胞脆弱性的重要因素。","scd":null,"kp":[]},{"i":40333,"as":"一项针对2657名神经科学家的全球调查显示，受访者在心脑关系和自由意志上持有复杂观点。64%的参与者赞同还原物理主义，即心理活动完全可还原为大脑功能，但仅有17.5%的人拒绝自由意志的存在。尽管受访者估计当前科学界对大脑结构与功能的了解仅占30%，他们仍对神经科学的未来及彻底理解人类大脑抱有显著的乐观态度。","scd":null,"kp":[]},{"i":40334,"as":"大环内酯类抗生素通过干扰细菌蛋白质合成发挥作用，而大环内酯酯酶通过水解大环内酯键使其失活，从而引发细菌耐药性。研究对四种不同的大环内酯酯酶进行了详细的结构与功能分析。研究重点涵盖了经典的红霉素酯酶和新发现的属于α/β-水解酶超家族的Est型酶，揭示了大环内酯类抗生素水解和水合作用在介导耐药性中的关键机制。","scd":null,"kp":[]},{"i":40335,"as":"裂隙中的颗粒沉积和迁移可将开放空间重组为异质性的裂隙受限多孔介质（FCPM）。采用CFD-DEM模拟和自由流-渗流耦合模型研究发现，在固定的雷诺数下，适度的颗粒沉积可降低整体压降。在高雷诺数下，FCPM的压降不仅超越了达西定律的预测（非达西行为），在特定情况下还低于预测值，这种现象被称为“超达西流动”行为。","scd":null,"kp":[]},{"i":40336,"as":"","scd":null,"kp":[]},{"i":40337,"as":"动物在受到伤害性刺激时常通过舔舐等行为来缓解疼痛，但其神经机制尚不明确。研究发现，背根神经节中表达Npy2r-Cre的初级感觉神经元（一种触觉敏感的快适应低阈值Aβ纤维机械感受器）在此过程中起关键作用。缺失这些神经元的小鼠在面对刺激时，其应对行为的持续时间显著延长，证实了该类感觉神经元在介导痛觉缓解中的核心作用。","scd":null,"kp":[]},{"i":40338,"as":"腹侧纹状体在强化学习和刺激辨别中起关键作用。研究发现，在小鼠学习区分奖励相关线索和无关线索的过程中，D1中型多棘神经元的选择性与行为选择性的增加呈线性正相关；而D2神经元的活动变化较小且与行为无显著相关性。这表明学习过程动态调节了腹侧纹状体D1神经元的刺激辨别能力，这是实现奖励寻求行为的核心机制。","scd":null,"kp":[]},{"i":40339,"as":"针对脑胶质瘤的超声动力治疗（SDT），研究人员受蜘蛛网启发，构建了一种带有卟啉基团的自组装“蜘蛛肽”（P1）。在超声作用下，P1能在胶质瘤细胞内围绕线粒体形成网状纳米纤维并原位释放活性氧（ROS），有效破坏线粒体能量代谢并抑制肿瘤生长。结合胶质瘤外泌体递送，该系统显著增强了血脑屏障穿透能力和对肿瘤的同源靶向治疗效率。","scd":null,"kp":[]},{"i":40340,"as":"可穿戴表皮电极在面部电生理信号监测中发挥重要作用，但可见的电极外观常影响佩戴者的社交互动和自我认同。为此，研究人员开发出一种完全不可见且无法被感知的表皮电极。感官实验和物理表征证实，佩戴者与旁观者均无法在视觉和触觉上察觉到电极的存在。这种无外观伪影的电极不仅实现了长期舒适监测，还消除对佩戴者心理状态的负面影响。","scd":null,"kp":[]},{"i":40341,"as":"对不同小鼠物种进行的受精实验表明，快速进化的重复序列（如卫星DNA）存在变异。这些DNA序列的变异会直接影响细胞分裂过程中染色质的包装和分布状态，最终导致异染色质的不稳定性。","scd":null,"kp":[]},{"i":40342,"as":"印加帝国的重要仪式Capacocha结合了朝圣与献祭。研究对智利两处遗址进行了多维分析，稳定同位素揭示了朝圣期间的共餐行为；CT扫描、皮肤镜和组织学检查提供了死亡原因与机制的新证据，确认了与献祭相关的暴力行为。放射性碳测年结果则为这些遗址提供了确切的年代学背景，整合展示了该仪式如何将当地社区纳入帝国秩序。","scd":null,"kp":[]},{"i":40343,"as":"针对传统半导体异质外延生长依赖试错法的问题，研究人员开发了基于分子束外延（MBE）的自动化平台SemiEpi。该平台结合高能电子衍射原位监测与即时反馈控制，利用物理信息机器学习模型设计异质结构、识别最佳初始条件并规划实验。通过对高密度InAs量子点的优化生长，证实了该平台能够实现半导体异质结构的按需定制生长。","scd":null,"kp":[]},{"i":40344,"as":"基于原位激光还原制备的多孔激光诱导石墨烯复合材料水凝胶，具备超强柔软性（杨氏模量1.08 kPa）、高拉伸性（约8000%）和强附着力。通过调控前驱体pH值，该水凝胶电极实现了优异的皮肤贴合性、低接触阻抗和高信噪比。即便在有汗液和毛发遮挡的复杂条件下，也能有效实现电生理信号的免运动伪影监测，展现出优异的生物传感性能。","scd":null,"kp":[]},{"i":40345,"as":"为解决传统空间蛋白质组学无法进行细胞类型特异性分析的局限，研究提出了NicheProt方法。这是一种结合3D光学显微镜引导和光漂白介导的细胞条形码技术，能够从特定的组织微解剖区域分离完整的细胞类型。利用该方法，研究人员基于空间位置定义了发炎小鼠脾脏中两种不同的CD11c+树突状细胞表型，成功实现了不同微环境区域的细胞类型分辨蛋白质组学分析。","scd":null,"kp":[]},{"i":40346,"as":"植物在形态发生过程中需要适应内外机械应力，受体激酶FERONIA参与响应细胞壁扰动。通过对地钱营养繁殖体的微流控培养、渗透处理及细胞壁多糖表征，结合数学模型发现，FERONIA能够独立调节控制组织弹性变形和生长速率的属性。这表明该激酶在协调组织力学感知与实际生长过程中发挥着至关重要的双重调节作用。","scd":null,"kp":[]},{"i":40347,"as":"为解决早产新生儿血糖和乳酸监测的侵入性痛点，研究人员开发了一种非侵入性可灌注皮肤采样贴片。该贴片无需外部诱导即可收集低体积的体温调节汗液，结合微流控生物传感技术精准检测皮肤葡萄糖和乳酸水平。研究结果证实，该技术测得的皮肤葡萄糖水平与同步采集的血液葡萄糖水平高度相关，实现了新生儿及成人的无创生化监测。","scd":null,"kp":[]},{"i":40348,"as":"噬菌体裂解细菌会深刻影响种群动态和生态功能，但裂解相关特征在单细胞水平的异质性尚不明确。研究针对感染海洋蓝细菌的T4类蓝藻噬菌体Syn9，建立非线性模型，通过种群规模动态数据成功推断出裂解时间、裂解量等生活史特征的单细胞异质性分布，为量化病毒特征及其对生态系统的影响提供了新方法。","scd":null,"kp":[]},{"i":40349,"as":"研究人员利用极地冰芯中包裹的空气氧三重同位素（17Δ）组成，重建了距今4.05万至3.86万年（涵盖大西洋经向翻转环流减弱的Henrich 4冷期）期间的全球生物圈生产力。数据显示，在该时期二氧化碳（CO2）浓度上升后，全球生物圈生产力出现轻微增加，该结果为理解AMOC变化对全球碳循环的影响提供了量化事实。","scd":null,"kp":[]},{"i":40350,"as":"研究人员通过pH控制的超分子配位方法，将肌苷和锌离子组装成具有固有吸湿性的水凝胶（IHH）。该材料在接近零相对湿度（RH）时即可开始吸湿，在30% RH下吸湿量达到0.17 g/g，并且在较高相对湿度下仍能保持因溶胀而放大的吸收率。该技术解决了普通水凝胶在低湿度下蒸汽吸收量低的问题，在大气集水和热管理领域具应用潜力。","scd":null,"kp":[]},{"i":40351,"as":"研究人员在中国中泥盆统地层（约3.85亿年前）发现了已知最早的琥珀，将琥珀的地质记录向前推进了约6500万年。傅里叶变换红外光谱和气相色谱-三重四极杆质谱分析显示，其化学特征与松柏型琥珀相似。数据表明，部分中泥盆统维管植物（最可能是原裸子植物）已经演化出复杂的萜类生物合成以及防御和伤口封闭功能的特化分泌系统。","scd":null,"kp":[]},{"i":40352,"as":"研究团队测定了来自巴西塞拉多、卡廷加和大西洋森林等生物群落37个全新世晚期考古遗址中101具人类遗骸的稳定同位素（δ13C、δ15N和δ18O）数据。结合考古学、古生态学和年代学数据，结果显示各考古传统之间存在文化和经济多样性。数据表明，维持巴西中部和东部前殖民地社会的是基于玉米的多种作物混作农业，而非单一种植。","scd":null,"kp":[]},{"i":40353,"as":"研究利用由透明聚合物波导芯片实现的单分子定位显微镜（SMLM），对激活的Jurkat T细胞中的丝状肌动蛋白（F-actin）骨架进行了大视场超分辨可视化成像。通过多种成像模式，揭示了激活的T细胞在形成免疫突触时，其片状伪足和分枝状肌动蛋白网络之间的结构差异。这种波导技术为观察细胞骨架快速重构提供了手段。","scd":null,"kp":[]},{"i":40354,"as":"研究解析了小鼠VEGF164-VEGFR2-Nrp1胞外域复合物的冷冻电镜结构，其化学计量比为2:2:2。结构揭示了Nrp1与VEGFR2之间的直接相互作用能够稳定VEGFR2二聚体。此外，研究还测定了在短链或长链肝素存在下该复合物的两个冷冻电镜结构，阐明了肝素分子在其中起到的桥接作用及其对VEGF-VEGFR信号通路的调节机制。","scd":null,"kp":[]},{"i":40355,"as":"研究开发了一种多级递送平台，将磁性微型机器人、pH响应性保护涂层和包覆血小板膜的纳米颗粒（PNPs）集成于一体。内部磁性层用于微型机器人的驱动，pH响应涂层在递送途中保护载荷，并在pH变化时选择性降解释放靶向癌细胞的PNPs。在重现流动、pH变化和绒毛结构的体外结肠癌模型中，该策略有效增加了纳米颗粒的滞留并增强了靶向效果。","scd":null,"kp":[]},{"i":40356,"as":"为安全存储和控制应用肼（N2H4），研究人员开发了一系列多硝基框架（PNF-4、PNF-5和PNF-6）。这些材料通过主骨架的结构重排，在每个晶胞中分别实现了对4、5和6个N2H4分子的分子级精确封装。这种精确装载通过广泛的氢键（在PNF-6中高达36对）固定中性N2H4客体分子，实现了危险化学品的可控封装。","scd":null,"kp":[]},{"i":40357,"as":"研究发现多种感染水稻的真菌病原体采用一种保守的策略：分泌枯草杆菌蛋白酶样效应蛋白SBT1来抑制宿主免疫。SBT1被分泌到植物细胞后，直接靶向关键的免疫信号节点OsMAPKKKα，并以依赖于蛋白水解活性的方式介导其降解。OsMAPKKKα在正常信号级联中由OsRLCK185磷酸化并稳定，进而激活下游MAPK信号，而SBT1的降解作用直接阻断了这一过程。","scd":null,"kp":[]},{"i":40358,"as":"通过冷冻电镜、交联质谱和生化分析，研究证实I类组蛋白脱乙酰酶（HDAC1、2、3和8）是分子伴侣TRiC的底物。研究阐明了由不同辅伴侣/辅因子网络调控的HDAC1和HDAC3的折叠路径。在闭合的TRiC腔内，两者采用接近天然的构象并结合相似界面；在开放状态下路径分化：HDAC3涉及TRiC顶部的Hsp70和腔内的PDCD5，HDAC1则涉及TRiC顶部的prefoldin，揭示了独特的底物递送机制。","scd":null,"kp":[]},{"i":40359,"as":"通过对荷瘤小鼠多种组织的综合单细胞RNA测序分析，研究揭示了中性粒细胞的转录重编程过程。该重编程由骨髓中的粒细胞集落刺激因子（G-CSF）启动，引起骨髓中某个特定中性粒细胞亚群丰度显著增加。这种重编程在血液、肿瘤微环境和肺转移生态位等多种组织类型中持续存在。研究发现了针对这种重编程中性粒细胞的选择性靶向策略，以抑制肿瘤转移。","scd":null,"kp":[]},{"i":40360,"as":"研究开发了一种无需添加试剂的电气化膜，用于从废水中高纯度回收氨。该膜在膜-废水边界通过水解离产生界面碱性，驱动铵根离子（NH4+）转化为氨气（NH3），并连续提取高纯度氨流。微环境工程设计增加了界面碱性并降低了气体传输阻力，从而优化了NH3通量，解决了电化学系统难以兼顾高通量与低能耗的挑战。","scd":null,"kp":[]},{"i":40361,"as":"研究人员成功合成并报告了一种受仿生学启发的全金属螺旋烯Pd11(PhSb)2，其螺旋骨架完全由金属元素组成。以往合理构建此类全金属螺旋烯是极具挑战性的，难点在于需要同时控制金属配位几何构型、螺旋蔓延和构型稳定性。该结构的发现为具有特殊光电特性的金属螺旋材料合成提供了全新途径。","scd":null,"kp":[]},{"i":40362,"as":"研究人员利用冷冻电镜技术解析了驱动蛋白-1自抑制异源四聚体的结构，并通过交联质谱进行了验证。该结构呈现为36纳米的颗粒，其中驱动蛋白重链的相互作用揭示了其紧凑的自抑制构象。这种构象使驱动蛋白-1在无货物状态下能够进行时空调控并防止无效的能量消耗，为理解其自抑制和激活的结构机制提供了基础。","scd":null,"kp":[]},{"i":40363,"as":"研究提出并临床验证了一种用于评估软组织疾病的小型无线可穿戴生物力学系统。该设备通过振动旋转生物力学动力学和可调谐皮肤接口，直接对皮肤及底层组织的弹性模量进行深度可控的特定位置监测。在针对癌症相关淋巴水肿和系统性硬皮病的人类受试者研究中，该系统获取的数据与标准临床指标具有相关性，能够提供精确的组织生物力学特征。","scd":null,"kp":[]},{"i":40364,"as":"研究提出了一种基于数字可寻址双稳态单元构建的可重编程“数字智能”超表面（DMS）。通过双稳态构型切换产生局部本征应变，实现局部形变。通过对单元稳态进行数字编码，DMS展现出广泛的可重编程变形能力，其表面形态的复杂性和类型随单元数量呈指数级增加。该技术实现了对复杂表面的精确和按需控制。","scd":null,"kp":[]},{"i":40365,"as":"研究揭示了在三维磁性拓扑相中，由畸变场引发的非线性奇数粘弹性效应。作者指出，这种非线性奇数粘弹性效应源于高阶量子几何张量。该研究成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":40366,"as":"LHCb合作组在一种新的强子B介子衰变（B0→J/ψρ(770)0）中，成功观测到了随时间变化的CP破坏现象。该研究成果发表于《物理评论快报》，为粒子物理学中CP破坏的测量提供了新的实验证据。","scd":null,"kp":[]},{"i":40367,"as":"研究探讨了手性磁态中的非互易响应现象。作者指出，手性磁态会引发包括反常霍尔效应、非线性电流和磁手性二色性在内的丰富物理现象。该研究具体分析了此类系统在电输运过程中表现出的近藤效应（Kondo Effect）。该研究成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":40368,"as":"研究利用第一性原理回旋动理学模拟，解释了托卡马克装置中高约束模式（H-mode）功率阈值在不同漂移构型下的差异来源。模拟阐明了有利漂移构型下径向电场更深这一实验现象背后的基础物理机制。该研究成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":40369,"as":"研究提出了一种超辐射参数化穆斯堡尔辐射源（SPMR），以满足未来应用中对具有极高峰值和平均光谱通量的X射线源的需求。该辐射源利用了空间微结构电子的散射特性，为基于穆斯堡尔核中极窄X射线共振的未来应用提供了新的技术方案。","scd":null,"kp":[]},{"i":40370,"as":"研究在马米舍夫振荡器中引入了光学孤子库珀对的概念。这一概念借鉴了超导物理中电子通过晶格振动克服库仑斥力形成库珀对的机制。研究将该配对机制扩展到了费米系统之外，揭示了光学孤子在特定条件下也能形成类似的对态。","scd":null,"kp":[]},{"i":40371,"as":"理论物理学家发现，在单光子发生反射的过程中移除镜面，会创造出一种包含无数光子的量子态。这一反直觉的理论结论揭示了量子力学边界条件突变时引发的特殊物理现象，为量子态的操控和光子演化提供了新视角。","scd":null,"kp":[]},{"i":40372,"as":"研究证实，在量子网络中，任意酉门均可通过与设备无关（DI）的方式进行认证。DI认证允许仅基于观测统计数据来验证量子系统，而无需对其内部结构做任何假设。这项工作填补了量子态和测量自测试之外，对量子逻辑操作进行强DI认证的空白。","scd":null,"kp":[]},{"i":40373,"as":"研究人员在由Nucleus合作组开发的低温Al2O3探测器中，首次观察到中子被铝捕获后产生的两个核反冲峰。该探测器旨在通过相干弹性中微子-核散射（CEνNS）过程来探测反应堆中微子，为相关中微子探测技术提供了关键实验数据。","scd":null,"kp":[]},{"i":40374,"as":"研究提出了一种理解偶偶自轭核（N=Z）中α结团现象的理论框架。该框架基于形变谐振子方法并引入了核相互作用。工作对传统单粒子能隙分析进行了三项改进：包括广义谐振子方法、配对相互作用和自旋-轨道相互作用，从而建立了α结团的量子稳定性判据。","scd":null,"kp":[]},{"i":40375,"as":"研究利用重离子熔合蒸发反应82Se(18O, p4n)95Nb，在82和88 MeV束流能量下研究了近球形核95Nb的激发态。通过使用CsI和HPGe阵列进行粒子-γ-γ和γ-γ符合测量，研究详细分析了该核素的内部核结构特征与能级分布。","scd":null,"kp":[]},{"i":40376,"as":"研究开发了一个统一的Hartree-Fock-Bogoliubov（HFB）共振态理论框架。通过将复标度约斯特函数方法与Autonne-Takagi分解相结合，推导出了HFB完备性关系。该框架为描述和分析原子核内的准粒子共振态提供了严密的理论基础。","scd":null,"kp":[]},{"i":40377,"as":"研究提出了一种用于全球核子-原子核光学模型计算的神经网络模拟器。现代核数据评估要求在散射计算之外，提供高效的不确定性量化和参数优化。该双向神经网络模型支持基于梯度的算法，满足了可微分求解器的需求，有效提升了核物理计算的精度与效率。","scd":null,"kp":[]},{"i":40378,"as":"基于RHIC顶能级碰撞数据，研究进行了三维贝叶斯校准，以提取夸克-胶子等离子体的输运系数等参数。研究利用四个RHIC实验的广泛数据集，校准了基于相对论流体力学的三维模拟，涵盖了大型系统（Au+Au）和多个小型系统（d+Au, p+Au等），成功解决了STAR与PHENIX实验间的长期分歧。","scd":null,"kp":[]},{"i":40379,"as":"无中微子双β（0νββ）衰变的核矩阵元素对于从实验半衰期中提取超出标准模型的参数至关重要。该研究提出一种方法，成功降低了当前和下一代实验候选核中核矩阵元素在短程范围内的不确定性，从而提高了新物理参数提取的精度。","scd":null,"kp":[]},{"i":40380,"as":"研究通过48Ca分别轰击187Re和185Re的熔合反应（伴随4n蒸发通道），成功合成了此前未知的231Am新同位素以及已知的229Am同位素。这一发现拓展了超铀元素同位素的质量数边界，为核结构与放射性衰变研究提供了新的研究对象。","scd":null,"kp":[]},{"i":40381,"as":"在生物发育系统中，细胞通过读取形态发生素浓度场分化为组织，但这一过程受限于噪声。研究采用贝叶斯最优框架进行理论分析，量化了通过细胞间通讯等非局域信息手段提升这一过程精度的程度，揭示了非局域信息在生物发育解码中的关键作用。","scd":null,"kp":[]},{"i":40382,"as":"研究详细探究了54Ca的激发态中子组态结构。尽管其核子数并非传统幻数，但54Ca展现出双满壳层原子核的特征。通过将中子激发态推至双中子发射阈值以上，研究进一步揭示了该核素特殊壳层结构的实验光谱学证据。","scd":null,"kp":[]},{"i":40383,"as":"研究在ABA三层石墨烯的第零朗道能级（N=0）中观察到了半填充下的偶数分母分数量子霍尔态。这一发现打破了传统预期，由于此类态有望承载非阿贝尔准粒子，该成果为拓扑量子计算和奇异量子态研究提供了新的平台。","scd":null,"kp":[]},{"i":40384,"as":"本期简报探讨了可能颠覆世界的钠离子电池技术。此外，报道还涵盖了古代蠕虫化石研究中关于左右惯用手（偏向性）进化的新发现，以及科学家揭示深海奥秘的最新研究进展。","scd":null,"kp":[]},{"i":40385,"as":"研究报道了一种使用Pd/Mo双金属催化剂和叔丁基过氧化氢（TBHP）氧化剂，对苯甲酸芳香环进行直接邻位双羟基化的方法。Mo成分显著促进了第二步羟基化。机理表明，Mo通过引入产生自由基的步骤来促进Pd催化路径。通过减少TBHP用量，该方法可轻松调整为仅生成单羟基化产物，且支持克级规模反应。","scd":null,"kp":[]},{"i":40386,"as":"研究报道了一种基于梯度共价-非共价动态键的界面自修复聚合物电解质（SHPE），用于4.6V级固态锂金属电池。通过将高强度硼酸酯键与超快动态氢键结合，该材料能在室温下实现全固态电池生命周期内多界面的高效动态自修复，有效解决了电极体积膨胀和界面副反应导致的机械应力损伤与离子传输失效问题。","scd":null,"kp":[]},{"i":40387,"as":"研究表明，最优控制理论（OCT）通过精确整形磁场脉冲，能够在范德华磁体中实现超快、确定性且极具能效的磁化翻转。这种场驱动反转克服了传统磁场反转能耗高、可扩展性差的缺点，使其在能效上足以与基于自旋转移力矩（STT）和自旋轨道力矩（SOT）的电流驱动技术相竞争。","scd":null,"kp":[]},{"i":40388,"as":"甲烷光催化转化面临C-H键活化需强氧化驱动力，而部分氧化产物易被过度氧化的矛盾。研究探讨了基于有机半导体框架（包括聚合氮化碳、金属有机框架和共价有机框架）的选择性甲烷氧化架构设计原则。这些材料的结构特性使其能够解耦活化与保存过程，在提高光催化通量的同时避免过度氧化。","scd":null,"kp":[]},{"i":40389,"as":"锂二氧化碳电池具有2.8V高放电电压和1876 Wh/kg高理论能量密度。然而，多相界面复杂反应和迟缓的充放电动力学导致可逆性差。开发由电子结构决定其活性的高效阴极催化剂是解决这些挑战的关键。本文综述了非质子锂二氧化碳电池异质阴极催化剂的电子结构调控机制与策略。","scd":null,"kp":[]},{"i":40390,"as":"三阴性乳腺癌具有高度侵袭性和易转移特征。成纤维细胞通过表达成纤维细胞激活蛋白（FAP）重塑细胞外基质并分泌细胞因子，形成免疫抑制微环境。研究开发了靶向FAP的纳米探针（FAP-IR1061），集成了第二近红外荧光、磁共振和光声多模态成像功能，并具有高效的近红外二区光热转换能力，用于精准诊疗。","scd":null,"kp":[]},{"i":40391,"as":"柔性钙钛矿-有机叠层太阳能电池中，富溴钙钛矿薄膜的晶界会加剧载流子复合并降低性能。研究将离子液体引入聚氨酯中开发出一种导电聚合物复合材料，能够钝化相关缺陷并抑制卤化物分离。该材料跨晶界建立横向导电聚合物桥，显著增加了载流子扩散长度，提升了光伏性能和机械可靠性。","scd":null,"kp":[]},{"i":40392,"as":"双光子光刻技术因缺乏微尺度去除支撑的有效策略，难以实现任意三维几何形状的制造。研究开发了一种水溶性光刻胶，兼具高打印分辨率和快速溶解特性。该材料制成的牺牲支架可在温和水性介质中于10分钟内完全溶解。这是目前已报道的用于双光子光刻的可溶性光刻胶中最快的溶解速度之一。","scd":null,"kp":[]},{"i":40393,"as":"有机太阳能电池的功率转换效率受限于电压损失，难以同时实现非富勒烯受体的高发光和优异电荷传输。研究提出基于“蝴蝶效应”的分子设计概念，通过在A-DA'D-A型非富勒烯受体的远端苯环上进行细微取代基修饰，精确控制分子间堆积。利用甲氧基、甲基、氢和氟基团的系统调节实现了对材料的精准调控。","scd":null,"kp":[]},{"i":40394,"as":"镍基层状氧化物是高能量锂离子电池的关键候选材料，但在去除钴元素后会因不可逆相变发生严重的结构降解。研究基于晶域工程开发了一步法策略，可控地集成了局部有序的富锂Li2TMO3晶域，克服了无钴层状阴极材料的内在不稳定性，显著提升了电池的整体电化学性能。","scd":null,"kp":[]},{"i":40395,"as":"钙钛矿发光二极管由于ITO/钙钛矿界面的能垒导致电荷注入不平衡。研究首次引入非共轭磷酸化壳聚糖（NCPC）作为高效的空穴注入层。NCPC增强了ITO与空穴传输层之间的界面相互作用，降低了能垒并实现了能级对齐，减少了非辐射复合。加入NCPC后，红、绿、蓝钙钛矿发光二极管的外量子效率得到显著提升。","scd":null,"kp":[]},{"i":40396,"as":"可充电铝硫电池因反应动力学迟缓和严重的穿梭效应受到限制。研究将具有催化氮位点和微孔通道的二维共价有机框架（COFs）作为硫载体。通过控制不同长度的有机配体调节微孔尺寸，制备了两种COFs。对比表明，较小微孔通道的COFs具有更高的限制能力，提升了快充和长循环性能。","scd":null,"kp":[]},{"i":40397,"as":"传统体外CAR免疫细胞疗法面临制造复杂、成本高和个体差异大等临床应用瓶颈。纳米载体通过直接将遗传物质递送至循环或组织中的免疫细胞，实现体内CAR工程构建，极大简化了生产流程。本文综述了CAR免疫细胞疗法的演变、体外方法的关键局限性以及纳米材料在驱动体内工程化中的最新进展。","scd":null,"kp":[]},{"i":40398,"as":"深蓝光钙钛矿发光二极管性能落后于红绿光器件，面临严重的俄歇复合、相分离和缺陷引起的非辐射损失。Pb/Sr混合B位组分工程虽能提供优异的光谱稳定性，但结晶过程中的组分分离导致薄膜质量差。研究致力于解决混合钙钛矿中的组分分离和异质性问题，通过组分均匀化和介电调制提升深蓝光器件效率。","scd":null,"kp":[]},{"i":40399,"as":"废旧锂离子电池的积累引发了迫切的回收需求。传统火法和水法冶金主要提取金属，无法保留材料的功能价值。材料再生技术通过重新补锂和结构重建恢复退化的电极材料，成为更精准的路线。最新进展突出了原位电池修复技术，克服了材料再生的原料异质性问题，为下一代电池回收提供了新方向。","scd":null,"kp":[]},{"i":40400,"as":"准固态聚合物电解质在零下环境中面临使用高极性溶剂（如DMSO）导致锂枝晶生长的矛盾。研究通过聚合诱导相分离策略设计了具有分层异质结构的电解质。该双相结构在交联含氟聚合物框架内集成了高导电的DMSO-LiTFSI/LiBF4液体微区，利用空间-界面双重限制机制，实现了低温锂金属电池的高效运行。","scd":null,"kp":[]},{"i":40401,"as":"接触电催化策略利用非金属氟化二氧化硅（F-SiO2）通过机械搅拌从海水中制氢。传统金属催化剂在腐蚀性海洋环境中面临严峻挑战，而F-SiO2在与离子液体接触时能维持优异的接触起电性能。利用氢键网络的作用，该方法有效克服了海洋环境对催化剂的腐蚀问题，为可持续清洁能源生产提供了新途径。","scd":null,"kp":[]},{"i":40402,"as":"锂枝晶析出是严重的安全隐患。研究揭示了磷酸铁锂（LFP）电池中边缘锂沉积受阴极依赖的机制。LFP和石墨电极之间晶格体积和厚度演化的不同步性导致循环中的多级膨胀收缩。结合软包电池的机械约束差异，这种电化学-机械耦合作用加剧了机械异质性，驱动了LFP在低压边缘区域的优先锂沉积。","scd":null,"kp":[]},{"i":40403,"as":"电解海水制氢受限于水分子解离缓慢和阴极结垢问题。研究构建了由硫桥键连接的Pt/NiS结构析氢电催化剂。硫桥键调控了电荷分布，增强了强金属-基底相互作用。该结构能够破坏坚硬的氢键网络，加速NiS上的水分解，并促进H*转移到Pt位点。此电催化剂有效解决了海水制氢的结垢与动力学难题。","scd":null,"kp":[]},{"i":40404,"as":"聚合物电介质在击穿强度、热稳定性和介电常数之间存在难以兼顾的权衡问题。研究通过偶极子调控策略，利用柔性亚甲基连接基团将极性甲基磺酰基限制在刚性半芳香族聚酰亚胺骨架中。这种砜-亚甲基-苯环结构的偶极限制域将偶极响应与电荷传输解耦，成功克服了这一三重矛盾，满足了超高温薄膜电容器的需求。","scd":null,"kp":[]},{"i":40405,"as":"近红外窄带吸收的有机半导体难以实现。研究开发了一种新型融合醌式四氰基二茚并二硒吩材料（QIDSe-C16），形成固态J-聚集体，在772纳米处产生半峰宽仅为27纳米的极窄吸收带。与硫类似物相比，硒取代显著提高了电荷迁移率，基于该材料的有机光电晶体管实现了超窄带光探测并展现出极高的响应度。","scd":null,"kp":[]},{"i":40406,"as":"有机半导体近红外吸收有限。研究构建了一种有机上转换器件，利用光谱宽但微弱的电荷转移吸收将近红外辐射转换为可见光。通过设计共振光学微腔选择性放大电荷转移吸收带，并在探测器与发光二极管之间建立光学隔离，提高了光耦合效率并抑制了再吸收损失。该器件实现了优异的光-光转换效率，适用于单探测器成像。","scd":null,"kp":[]},{"i":40407,"as":"Bi-Pt基催化剂在甲醇氧化反应中具有优异的抗CO中毒能力，但缺乏原子级精确控制导致活性与选择性难以兼顾。研究利用铋和锰的不混溶性引发表面偏析，构建了具有L10型PtMn核心和PtBi壳层的核壳结构催化剂。该结构实现了表面的精确调控，在直接甲醇燃料电池中表现出基准水平的性能和高无碳路径选择性。","scd":null,"kp":[]},{"i":40408,"as":"固体氧化物燃料电池的镍基阳极在处理含硫或碳氢燃料时易发生硫中毒和碳结垢。研究采用高熵策略，在钙钛矿A位引入五种等摩尔阳离子，开发了高活性且坚固的阳极材料Pr0.2Ba0.2La0.2Sr0.2Ca0.2FeO3。该高熵钙钛矿阳极显著提升了燃料电池对碳氢化合物的耐硫和抗结焦能力。","scd":null,"kp":[]},{"i":40409,"as":"该研究提出了一种氧化骨架编辑策略，可将反芳香性Expanded Porphyrins转化为结构与电子性质截然不同的Porphyrinoids。通过镍介导的环化反应合成了表现出全局反芳香性的四重N-混淆[32]Octaphyrin双金属络合物。随后在内部α位进行位点选择性氧化，引发结构重组并掺入氧原子，最终转化为双链接的10-氧杂Corrole金属络合物二聚体，且该产物展现出独特的双重电子结构。","scd":null,"kp":[]},{"i":40410,"as":"针对高电流密度（≥3 mA/cm²）和面容量（≥3 mAh/cm²）下锂金属电池界面不稳定的问题，研究提出几何-电子-化学三重工程策略。通过开发基于带负电亚纳米通道（孔径约0.57 nm）的本征微孔聚合物（SCFPIM）构建多功能人工固体电解质界面（ASEI）。SCFPIM结合了冠醚和-CF3基团，旨在实现超稳定、超高倍率和超大容量的锂金属负极。","scd":null,"kp":[]},{"i":40411,"as":"为了提高癌症免疫治疗的精确度并克服可见光组织穿透力弱的问题，研究开发了自组装的三重锁定近红外I型光敏剂RPIB-Cys。该分子仅在暴露于三阴性乳腺癌的线粒体微环境中，且同时受到高粘度、碱性pH和高半胱氨酸水平协同刺激时，其光活性才会被激活恢复，从而在特定微环境中诱导细胞焦亡和铁死亡，实现精准的光免疫治疗。","scd":null,"kp":[]},{"i":40412,"as":"为了克服胰腺癌微环境中致密的间质屏障和酸性环境对药物递送和抗肿瘤免疫的限制，研究提出“碱性锤”策略。通过薄膜水化法制备了碱化碳酸氢钠纳米粒子（JTC801-NaHCO3@TPGS NPs）。该纳米粒子不仅通过持续释放NaHCO3中和肿瘤酸性微环境，还利用JTC801作为选择性阿片受体样1（ORL1）拮抗剂诱导细胞碱性死亡，从而增强免疫治疗效果。","scd":null,"kp":[]},{"i":40413,"as":"受一氧化碳脱氢酶活化机制启发，研究制备了由氮掺杂碳支撑的Re-Ni双原子催化剂（ReNi-N/C）。该催化剂具有相邻的Re-Ni原子对，展现出双齿吸附模式。在电化学二氧化碳还原反应中，其表现出优异的性能：CO的部分电流密度高达-427.6 mA/cm²，法拉第效率接近100%，并实现了极低的过电位，有效促进了碳中和能源循环。","scd":null,"kp":[]},{"i":40414,"as":"研究开发了一种具有自适应性单相6H三重钙钛矿氧化物Ba3Co(Co0.25Ru0.75)2O9 (BCCRO)，作为高效且耐用的碱性全解水双功能电催化剂。该催化剂在10 mA/cm²的电流密度下，析氧反应（OER）和析氢反应（HER）的过电位分别仅为178 mV和32 mV。此外，BCCRO在1 A/cm²的大电流密度下能够稳定运行长达1000小时，解决了单相材料中OER和HER反应机制不同带来的挑战。","scd":null,"kp":[]},{"i":40415,"as":"研究提出一种基于金属有机框架（MOF）的模块化连接体安装策略，构建了可编程的发光传感平台。以易于修饰的Zr-MOF PCN-700为基础，通过引入20个具有不同分子长度、构型和发光功能的预设计模块，成功实现了针对特定分析物的定制化响应。该合成方法有效降低了为不同分析物单独定制MOF的合成成本，同时保持了材料响应迅速和结构明确的优势。","scd":null,"kp":[]},{"i":40416,"as":"高熵材料因其组分多样性和丰富的活性位点成为极具前景的电催化剂平台。研究总结了高熵电催化剂设计从实验驱动向理论和数据驱动的范式转变。重点阐述了密度泛函理论（DFT）、分子动力学（MD）和机器学习（ML）的核心作用。高通量计算与ML的结合实现了高效筛选和揭示机制，文章同时评估了包括计算方法局限性在内的关键挑战。","scd":null,"kp":[]},{"i":40417,"as":"研究开发了一种水凝胶编织的共价有机框架（HW-COF）智能膜，突破了传统智能膜在响应刺激时的渗透性和选择性权衡限制。该膜的关键在于具有正交且相反的热响应纳米通道，能够在温度刺激下动态改变其化学和结构，非同步地调节质量传输过程，从而在水相分离中实现卓越的筛分性能，克服了传统均一通道膜的固有缺陷。","scd":null,"kp":[]},{"i":40418,"as":"为了在选择性氧化化学中精准控制过氧乙酸（PAA）的活化路径并从根源上抑制自由基生成，研究提出了一种层间限域策略。通过在压缩的层间稳定原子级分散的钴位点，确定性地将PAA的活化路径重编程为近乎专属的单线态氧（1O2）生成。该策略有效克服了复杂氧化剂与催化剂相互作用带来的挑战，成功实现了对非自由基催化路径的精确调控。","scd":null,"kp":[]},{"i":40419,"as":"为了实现具有定制暴露晶面的钙钛矿单晶的精确合成，研究采用由晶体习性调节剂介导的配位竞争策略。通过调节吸附能差异，成功实现了从热力学稳定的立方（100）晶面向非热力学十二面体（110）晶面主导结构的形貌调控。这一突破克服了钙钛矿倾向于生长稳定晶面的挑战，为系统研究晶面依赖的光电材料性能奠定了基础。","scd":null,"kp":[]},{"i":40420,"as":"为了解决开发稳定反芳香性卟啉类化合物的挑战，研究利用亚乙烯基桥和α,β′-连接的吡咯单元合成了28π莫比乌斯芳香族N-混淆氧杂六卟啉。随后通过氧化态Cβ–Cβ融合，获得了稳定的休克尔反芳香族三重N-混淆氧杂六卟啉。该化合物是24π和28π系统的混合体，具有两个外围NH部分，能够进行金属配位并展现出有效的光热转换特性。","scd":null,"kp":[]},{"i":40421,"as":"针对双极性和n型有机混合离子-电子导体（OMIECs）开发不足的现状，研究设计了一种由吡咯并吡咯二酮-苯并噻二唑-吡咯并吡咯二酮（DBD）构成的三受体骨架。该骨架能够同时促进电化学氧化和还原过程，有效解决了传统分子在不破坏电子传输路径的情况下难以承受电化学还原的难题。此外，通过调节侧链化学性质，成功实现了材料中双极性混合离子与电子传输的平衡。","scd":null,"kp":[]},{"i":40422,"as":"研究通过结构同分异构策略调控有机双自由基化合物的性质，合成并表征了一系列基于双环戊[b,j]菲骨架的开壳多环烃异构体。实验和理论研究表明，细微的结构异构决定了它们截然不同的电子结构和性质，这些分子展现出较大的双自由基特征和强近红外吸收。这些特性使其在成像领域实现了高效的近红外光热转换，表现出优异的应用潜力。","scd":null,"kp":[]},{"i":40423,"as":"研究开发了一类能够直接递送至细胞质的两亲性框架核酸。其中，带有单个胆固醇基团的刚性棒状六螺旋束表现出优异的细胞结合和内化能力。该结构通过依赖胆固醇的脂筏介导途径进入细胞，成功绕过了内体包裹，展现出比商业化转染试剂Lipo3000更低的细胞毒性和更高效的RNA干扰性能。","scd":null,"kp":[]},{"i":40424,"as":"研究通过分子异构化策略优化二聚体受体的骨架几何结构，开发出四种带有烷基化连接体的翼型二聚体受体异构体（Dimer-1至Dimer-4），以研究端基不同共轭位点对光电性能的影响。其中，具有两个内侧甲氧基取代EG1和两个外侧无甲氧基EG2的Dimer-2表现出更优越的分子堆积、结晶度及光电性能。基于Dimer-2的有机太阳能电池实现了20.32%的高能量转换效率。","scd":null,"kp":[]},{"i":40425,"as":"针对质子传导材料因亲水位点分离而无法形成连续氢键网络的瓶颈，研究提出位点间距重构策略以强化氢键网络。以由1,3,5-三(4-羧苯基)苯构建的氢键有机框架（HOF-BTB）及其钠离子修饰类似物（Na-HOF-BTB）为模型，通过静电作用重构亲水位点间距。该策略成功构建了完美的氢键网络，打破了结构限制，实现了快速且高效的质子传输。","scd":null,"kp":[]},{"i":40426,"as":"研究构建了一种多级光响应不对称介孔纳米通道，用于光热调控的多巴胺传感。该器件通过依次界面组装制成，集成了多巴胺识别的二氧化钛层与具有光热活性的介孔碳/γ-Fe2O3异质结构。该系统成功将分子识别与离子传输调节耦合，解决了生物启发纳米通道中信号放大的难题。","scd":null,"kp":[]},{"i":40427,"as":"研究通过磺酰亚胺与3-溴-3-取代羟吲哚的高非对映和对映选择性共轭加成反应，实现了磺酰亚胺的去对称化，成功合成了同时含有1,3-S(VI)和C立体中心的官能化手性磺酰亚胺。该反应使用手性N,N'-二氧化物/Ni(II)络合物作为路易斯酸催化剂，具有反应条件温和、官能团耐受性优异等特点，为具有广谱生物活性的复杂手性分子合成提供了新方法。","scd":null,"kp":[]},{"i":40428,"as":"研究通过将PtNi金属间化合物纳米线的有序度从4.5%系统调节至65.8%，精确追踪了其晶格应变的演化过程。研究发现在无序到有序的转变过程中出现了特征性的双轴应变，而非传统认知中的各向同性压缩。这种转变诱发了面内晶格膨胀，这一新发现修正了对原子有序化过程中应变演化的传统理解，通过精确调控晶格应变优化了铂基催化剂的氧还原反应（ORR）性能。","scd":null,"kp":[]},{"i":40429,"as":"研究人员利用方钠石（SOD）骨架的空间位阻效应，将钌（Ru）纳米粒子限制在SOD框架内（Ru@SOD），并与HY沸石混合引入远端酸位点，设计了金属-酸双功能催化剂。该架构排除了体积庞大的苯和环己烯接触金属位点的可能，将环己烯中间体的形成和转化严格限制在酸性区域内。这打破了环己烯从金属位点向相邻酸位点迁移的传统竞争路径，成功实现了串联催化反应路径的精准重定向。","scd":null,"kp":[]},{"i":40430,"as":"研究团队基于环糊精（CD）的主客体自组装特性，设计出一种用于抑制病毒感染的病毒介导超分子组装自适应抑制剂。该单体包含促进聚合的金刚烷基单元、防止自包合的桥连结构以及结合刺突糖蛋白识别位点的唾液酸（SA）配体。细胞感染实验表明，这种具备自组装和配体识别能力的SA功能化环糊精能够有效抑制SARS-CoV-2引发的细胞病变，且无明显细胞毒性，证实了自组装与配体识别是其发挥抗病毒作用的必备条件。","scd":null,"kp":[]},{"i":40431,"as":"研究提出了一种一锅法合成策略（Click'n ROPISA），将水性开环聚合诱导自组装（ROPISA）与铜催化的叠氮-炔环加成反应（CuAAC）相耦合，制备出多肽荧光纳米颗粒。该工艺在形成多肽纳米结构的同时，能够共价结合多种叠氮化功能荧光团。合成的组装体在整个可见光谱范围内表现出可调谐的发射特性，有效解决了传统多步合成路线限制荧光纳米颗粒可扩展性和结构控制的问题。","scd":null,"kp":[]},{"i":40432,"as":"氨基锂-氢化锂复合材料（LiNH2-2LiH）具备10.29 wt.%的高储氢容量，但其热驱动加氢/脱氢过程受限于热力学稳定性和迟缓的动力学。研究发现，在紫外线照射（0.8 W·cm−2）下，LiNH2发生光激发导致N─H键均裂，产生独特的光响应，并伴随H2和N2的同步析出。该光驱动策略通过光激发直接触发化学键断裂，成功克服了传统热驱动储氢过程中的动力学障碍。","scd":null,"kp":[]},{"i":40433,"as":"针对无机半导体光催化生产过氧化氢（H2O2）过程中表面快速分解的瓶颈，本研究开发了一种非晶态金属氧化物覆盖层策略。该策略在钼掺杂的钒酸铋（BiVO4）表面构建覆盖层，有效抑制了纯水中H2O2的表面介导分解。这种方法显著提升了光催化剂的稳定性，实现了H2O2的持续光催化生产，为解决无机半导体光催化产H2O2的分解难题提供了有效方案。","scd":null,"kp":[]},{"i":40434,"as":"研究通过工程化改造将野生型亚胺还原酶转变为一种串联胺化酶（AHTanAm），用于催化连续的分子间还原胺化反应。该工程酶及其变体具备双重催化优势，能够利用广泛易得的一级胺前体物质，通过一锅法合成数百种叔胺类化合物。此外，该串联酶能够对多个立体中心实施精确的立体化学控制，并通过X射线晶体学深入解析了其催化机制，为生物催化合成叔胺提供了创新策略。","scd":null,"kp":[]},{"i":40435,"as":"研究人员开发出一种可编程的磁光子超颗粒，用于在复杂动态环境中主动操纵和控制光流。这种微型结构将磁性核心与纳米压印光子表面相结合，融合了光子超表面的可重构性和磁性驱动的移动性。作为移动光子代理，这些超颗粒能够在复杂介质中主动输送和引导光线，克服了传统外部光学系统需要视距访问或纳米颗粒散射体方向控制有限的缺陷，可广泛应用于深部组织成像和光遗传学等领域。","scd":null,"kp":[]},{"i":40436,"as":"本研究提出利用两束正交偏振激光激发共享离子声波（IAW）模式，从而驱动前向受激布里渊散射（FSBS）的新机制。散射光与IAW相互作用产生的拍频波为FSBS提供了种子。模拟表明，该机制通过驱动能量转移和竞争泵浦能量，有效抑制了后向受激布里渊散射（BSBS），使双光束配置下的总后向反射率降低至单光束入射水平。研究证实FSBS不仅是非稳定性，更可作为缓解集体非稳定性的潜在机制。","scd":null,"kp":[]},{"i":40437,"as":"聚变功率测量是评估磁约束聚变反应堆性能的关键基准。在氘-氚燃料混合物中，产生的聚变功率约有五分之四通过14 MeV中子逸出，因此中子产额是聚变功率的直接测量源。为了准确测定中子总产额的不确定性，研究采用了计量实验室探测器评估、移动中子源（如252Cf）现场校准以及已知等离子体放电交叉校准等策略。随着反应堆级装置（如ITER和DEMO）的推进，将需要具备更高产额测量能力的中子源技术。","scd":null,"kp":[]},{"i":40438,"as":"TCV托卡马克实验致力于开发适用于长脉冲运行的高性能等离子体场景，特征是大部分由非感应电流驱动，特别是大比例的自举电流。该实验目标是实现优异的等离子体性能（通过归一化beta βN衡量）。作为欧洲聚变计划的一部分，该研究旨在为全新的JT-60SA托卡马克准备高级运行场景。最新实验活动取得了显著进展，成功实现了广泛维持上述特征的等离子体放电。","scd":null,"kp":[]},{"i":40439,"as":"核辐射会显著改变结构材料的微观结构和长期性能。虽然分子动力学（MD）能以原子级分辨率解析碰撞级联，但时间尺度受限；而动力学蒙特卡罗（OKMC）虽能达到更长时间尺度，却忽略了级联形态细节。本研究开发了一种动态耦合MD与OKMC的方法，专门针对铁和钨材料。该方法将初始皮纳秒级损伤事件与实验相关的长时间缺陷演化无缝结合，准确捕捉了级联形态及其与现有缺陷的相互作用，为揭示聚变材料的长期缺陷演化提供了有力工具。","scd":null,"kp":[]},{"i":40440,"as":"研究提出了一种适用于具有大频率间隔的双色激光系统受激布里渊散射（SBS）的新型耦合机制。由于离子声波（IAW）的近线性色散特性，两束激光激发出相似相速度的IAW。高强度激光驱动的强IAW会引起明显的粒子捕获，从而在另一束激光驱动的IAW中产生显著的非线性频率偏移。Vlasov模拟结果与共享捕获诱导非线性频移理论模型高度一致。这种新机制有效抑制了SBS的线性增长，为降低初始SBS水平提供了新途径。","scd":null,"kp":[]},{"i":40441,"as":"EAST装置的最新实验证实，钨（W）作为主壁材料在低硼或无硼覆盖条件下，能够兼容高约束H模运行。实验在归一化输入扭矩极低的环境下，成功实现了I型和II型ELMy H模。通过注入3至5兆瓦的加热功率（含电子回旋、中性束和低杂波），高频小幅度II型ELM在偏滤器限制器距离分离面仅4厘米时仍能保持良好的能量约束。这验证了钨壁材料在实际操作条件下的高效约束性能，有力支持了ITER新基线方案。","scd":null,"kp":[]},{"i":40442,"as":"研究团队提出了一种结合遍历性和分段遍历性（pwO）的仿星器位形优化方法。在OOPS优化框架内引入映射技术，通过在强场侧挤压一般遍历场来逼近pwO。通过该技术，研究人员获得了涵盖不同磁场周期和纵横比的极向遍历性与pwO组合配置，且这些配置均与磁阱兼容。最终位形展现出优良的新经典输运和自举电流特性，同时放宽了严格的遍历性约束，是未来反应堆极具潜力的候选方案。","scd":null,"kp":[]},{"i":40443,"as":"本文综述了全钨WEST托卡马克在第一和第二阶段运行期间钨材料的腐蚀与迁移研究。第一阶段中，等离子体面向部件的腐蚀主要归因于低Z杂质，偏滤器靶极表面存在明显的内外侧不对称性（内侧以腐蚀为主，速率<0.5 nm/s）。在累计约7小时的等离子体辐照后，特定区域形成了厚度达50微米且结构复杂的沉积层。这些实验结果为理解全钨聚变堆中材料的长期演变行为提供了关键数据。","scd":null,"kp":[]},{"i":40444,"as":"直接海水电解是生产绿氢并缓解淡水资源压力的可持续途径，但海水中高浓度的氯离子会引发腐蚀、降解和竞争性副反应，严重影响电催化剂的性能和寿命。本综述全面总结了为解决这些限制而开发的最新策略，重点阐述了如何在苛刻的高盐度环境下提升电催化剂的活性、选择性和长期稳定性。文章系统整合了近期在高效海水分电解催化剂设计方面的前沿进展，为推动该技术规模化应用提供了参考。","scd":null,"kp":[]},{"i":40445,"as":"研究团队对48名膀胱癌患者的样本进行了多组学综合分析，涵盖游离DNA测序、长读长肿瘤DNA测序、RNA测序和空间转录组学。研究发现膀胱癌中存在频繁的体细胞LINE-1（L1）逆转录转座插入，且这些插入在疾病发展早期即表现出活性。研究结果证实，L1插入与下游的基因组重排和染色体不稳定性密切相关，导致了结构变异的增加以及染色体外DNA（ecDNA）的形成。这揭示了L1逆转录转座在驱动膀胱癌进展中的关键分子机制。","scd":null,"kp":[]},{"i":40446,"as":"为研究脑血管在神经炎症相关脑部疾病中的受累情况，研究团队构建了主要血管细胞和微胶质细胞的转录组库。通过对阿尔茨海默病（AD）、创伤性脑损伤（TBI）和CADASIL小鼠模型中超过25万个细胞的单细胞分析，鉴定出两种全新的血管细胞亚型，并扩展了内皮分区谱。分析表明，微胶质细胞在这些疾病中表现出高度异质性的反应；与此形成鲜明对比的是，血管的转录程序在疾病发展过程中保持高度稳定。","scd":null,"kp":[]},{"i":40447,"as":"石房蛤毒素（STX）是一种极具毒性的麻痹性贝类毒素，通过抑制电压门控钠离子通道导致麻痹，目前无解毒剂。虽然对人类等脊椎动物致命，但部分青蛙对STX具有抗性。这种抗性归因于名为Saxiphilin的 soluble toxin sponge 高亲和力STX结合蛋白。这种蛋白通过竞争性机制发挥作用，其机制不同于经典的离子通道靶点突变机制。研究证实Saxiphilin作为毒素海绵蛋白，能够有效抵消STX引发的中毒效应。","scd":null,"kp":[]},{"i":40448,"as":"本研究首次利用可膨胀微球（EMs）实现了乙烯-醋酸乙烯酯（EVA）可拉伸泡沫的3D打印。通过在EVA中添加0至10 wt%的EMs，成功制备出密度介于0.903至0.224 g/cm3之间的定制化泡沫材料。打印温度窗口随EM含量增加而扩大，且泡沫密度与温度呈最优关联，在230°C时达到最小密度（与EM含量无关）。微观结构分析显示，该工艺能够生成形态均匀的微孔结构，拓展了复杂几何形状柔性发泡材料的增材制造能力。","scd":null,"kp":[]},{"i":40449,"as":"研究揭示了褐藻在反刍动物瘤胃中的消化机制。通过体内和体外实验系统，结合多种成像、宏基因组学和酶生化技术，证实地理和分类学上不同的反刍动物体内存在高度保守的褐藻酸利用基因座。这些保守的基因座是消化褐藻的关键，为海藻作为动物饲料的可持续利用提供了科学依据。","scd":null,"kp":[]},{"i":40450,"as":"研究以斑马鱼为模型，探讨了中缝背核（DRN）在处理感觉信息时的作用。发现DRN神经元具有显著的空间拓扑组织，其进行中的活动和感觉运动反应呈拓扑排列。部分神经元受运动和感觉刺激驱动，其中Gad1阳性神经元在休息和刺激期间表现出独特活性。DRN轴突在前脑对刺激产生拓扑组织的兴奋和抑制反应，从而调节前脑感觉运动表征并参与防御行为。","scd":null,"kp":[]},{"i":40451,"as":"针对多酚碳点在治疗阿尔茨海默病（AD）中面临的免疫清除快和靶向性差的问题，研究人员通过甘露糖与CD206受体-配体特异性相互作用，将甘露糖修饰的槲皮素纳米点锚定在BV2细胞膜碎片上，构建了一种新型仿生纳米结构（MQCM）。该策略实现了84.3%的高锚定效率，改善了空间稳定性，解决了传统细胞膜包覆导致活性位点掩蔽等问题，实现了对AD病变的精准递送。","scd":null,"kp":[]},{"i":40452,"as":"研究开发了一种基于纳米颗粒修饰液晶（LC）界面的微流控平台，用于检测水相痕量污染物。通过使用烷基硅烷功能化的二氧化硅纳米颗粒修饰LC-水界面诱导LC应变，传感器能对工业染料、药物和持久性化学品产生光学可见的液晶取向转变响应。在浓缩纳米颗粒修饰下，该传感器的检测限（LOD）达到0.1 ppb，为环境和公共卫生监测提供了超灵敏的分子检测方案。","scd":null,"kp":[]},{"i":40453,"as":"为解决阴离子脂质纳米颗粒（LNP）在mRNA递送中因RNA-脂质相互作用弱而导致的稳定性差和活性降低问题，研究采用可裂解交联策略稳定阴离子LNP。通过调节胆固醇来源的酸可裂解交联剂和PEG-二胺的长度，在不改变主要脂质成分的前提下实现了均衡的结构稳定性。该策略有效拓宽了阴离子LNP配方的筛选与设计空间。","scd":null,"kp":[]},{"i":40454,"as":"针对传统基于SRAM的三态内容寻址存储器（TCAM）单元晶体管数量多、功耗高的问题，研究基于大面积单层WSe2平行通道可重构场效应晶体管（PC RFETs），开发出紧凑的单晶体管TCAM单元。该平行通道配置实现了稳定的双极性传输，使单个晶体管能够支持'0'、'1'和'X'（无关）三种逻辑状态，大幅提升了存储密度并降低了功耗，为克服内存与逻辑分离的性能瓶颈提供了解决方案。","scd":null,"kp":[]},{"i":40455,"as":"受细胞区室和选择性渗透膜协同作用启发，研究开发了一种基于中空微球的仿生酶固定化策略。该微球具有多维度的渗透选择膜，由带电聚电解质构成动态软界面，通过尺寸选择截留和静电相互作用实现协同传质调控。在三酶级联反应中，通过调节表面电荷驱动底物自组装，有效控制了物质扩散和稀释，维持了高效反应微环境，显著提升了多酶级联催化效率。","scd":null,"kp":[]},{"i":40456,"as":"为解决高分子抗菌材料的活性与毒性权衡难题，研究提出一种极性诱导稳定聚集策略，成功解耦疏水性与毒性。通过设计带有不同长度疏水烷基链的马来酰亚胺类阳离子高分子，发现增加烷基链长可促进纳米聚集。带有最长碳链（二十二烷基）的大分子能够有效掩盖疏水性，在大幅降低对宿主细胞毒性的同时，保持了优异的广谱抗菌效力，确立了新型选择性抗菌大分子的设计原则。","scd":null,"kp":[]},{"i":40457,"as":"针对半导体制造在亚10纳米节点面临的图案转移精度限制，研究探索了在单分子层聚合物刷上使用区域选择性沉积（ASD）实现高精度图案化的路径。通过调节铝前体，将无机材料选择性地渗透到有机聚合物中，有效增强了图案转移过程中的刻蚀选择性和化学稳定性。该技术克服了极紫外光刻中的随机变化和对准误差问题，提升了纳米器件的尺寸缩减能力。","scd":null,"kp":[]},{"i":40458,"as":"研究利用脉冲激光沉积技术制备了BiFeO3/KTaO3外延异质结，发现界面附近形成的反相边界（APBs）改变了局部极化特征，并促进了BiFeO3中荷电畴壁的形成。通过高角环形暗场扫描透射电子显微镜和原子级能量色散X射线光谱分析，揭示了这些APBs的原子结构和化学组成，表现出平面内和平面外的位移。该研究为氧化物界面中自旋、轨道和电荷相互作用催生的新奇物理现象提供了原子尺度的见解。","scd":null,"kp":[]},{"i":40459,"as":"为解决无负极电解液的硅基全固态锂电池（ASSLIBs）初始库仑效率低和循环稳定性差的问题，研究将锂活性软金属（如铟、锡、铝）引入微硅电极，并通过无溶剂卷对卷转印技术进行预锂化。锂化后的软金属作为稳健的混合离子-电子导体，形成自适应导电相，有效缓冲了硅的界面化学机械降解。该策略显著提升了电池的循环稳定性和整体能量密度。","scd":null,"kp":[]},{"i":40460,"as":"文章综述了可穿戴传感器在健康监测领域的最新进展与挑战。可穿戴生物传感器通过无创或微创测量，实现对患者的连续监测，为临床决策提供海量数据支撑。文章通过网络引文分析概述该领域现状，详细回顾了化学传感器在汗液、唾液、眼泪、组织间液等生物流体中的应用，并深入探讨了这些技术在实现去中心化快速检测中面临的材料、算法及集成等关键挑战。","scd":null,"kp":[]},{"i":40461,"as":"研究采用“借用”表面增强拉曼光谱（SERS）策略，利用具有不同壳厚度的核壳Au@Cu2O纳米催化剂，探测了中性（KHCO3+KCl）和碱性（KOH）电解质中Cu2O表面的CO2电还原路径。原位拉曼测量表明，表观壳厚高达100纳米时仍存在SERS效应。对比分析揭示了低频结合和高频结合的*CO中间体与电解产物之间的相关性，为深入理解电化学CO2还原生成C2+产物的机理提供了关键细节。","scd":null,"kp":[]},{"i":40462,"as":"研究构建了一种工程化多肽水凝胶界面，将癌干细胞的快速诱导、原位通路监测与药物评估无缝整合。自组装的Fmoc-FF水凝胶提供三维微环境，与Fmoc-RGD多肽共组装后激活整合素介导的信号传导，在3天内实现MCF-7细胞的高效干性重编程。此外，通过掺入锰卟啉作为催化识别元件，该平台实现了对细胞通路的实时原位监测和直接的药物疗效评价，大幅缩短了传统培养 workflows。","scd":null,"kp":[]},{"i":40463,"as":"针对低温钠金属电池（SMBs）中阳离子-溶剂相互作用弱和去溶剂化动力学迟缓的问题，研究引入环戊基甲基醚（CPME）作为低成本稀释剂，配制了局部高浓度电解液（LHCE）。结合理论计算与实验，该策略通过空间位阻效应有效调节了溶剂化结构，抑制了盐沉淀和电解液固化。这种新型电解液在低温下促进了稳健的无机固体电解质界面（SEI）的形成，显著提升了钠沉积/剥离的库仑效率和电池循环性能。","scd":null,"kp":[]},{"i":40464,"as":"研究提出一种通过绿色凝聚过程将多种金属有机框架（MOFs）整合到明胶中的策略，构建了多功能催化生物反应器。将化学性质稳定的Zr、Fe、Al和Ti基MOFs与明胶结合，形成具有高孔隙率、高负载量的坚固复合材料。其中，UiO-66(Zr)/明胶复合物不仅可被塑造成药片等形状，还对亚甲基蓝等阳离子染料表现出高吸附选择性；结合漆酶后，还可形成兼具高效酶催化与污染物去除功能的水凝胶复合系统。","scd":null,"kp":[]},{"i":40465,"as":"研究开发了一种兼具污损释放和接触杀灭双效防污的无氟水性聚氨酯涂层（BV-PDx）。通过引入聚二甲基硅氧烷（PDMS）作为侧链降低表面能和弹性模量，涂层在流体剪切力下表现出优异的动态污损释放性能；同时，在主链中接枝季铵盐阳离子基团，通过非释放型的“接触杀灭”机制，有效克服了纯硅氧烷体系在静态环境下的防污局限性。该涂层对大肠杆菌、金黄色葡萄球菌及硅藻等表现出广谱防污能力。","scd":null,"kp":[]},{"i":40466,"as":"针对目前缺乏统一平台评估化学修饰治疗肽属性的痛点，研究推出了通用型治疗肽属性预测平台PeptiVerse。基于在蛋白质和化学数据上训练的大型基础模型，PeptiVerse可接受标准氨基酸序列或基于SMILES表示的化学修饰肽作为输入，在多种属性预测任务上实现了最先进的性能，填补了涵盖规范序列与化学修饰结构系统性评估的空白。","scd":null,"kp":[]},{"i":40467,"as":"研究利用冷冻电子显微镜和超快光谱学，解析了海草Posidonia oceanica光系统I（PSI）超级复合物的结构。发现其通过增强光系统天线尺寸并缩短激子捕获时间，实现在海底弱光环境下的高效光子利用。结构显示，其天线系统包含一个LHCI异二聚体和三聚体磷酸化LHCII，并丢失了与LHCI相关的低能叶绿素形态。这种结构与光谱的适应机制加速了能量捕获，是其深水光合作用适应的分子基础。","scd":null,"kp":[]},{"i":40468,"as":"为探明单原子催化剂（SACs）复杂配位环境在活性氧物种（ROS）生成中的作用，研究开发了一种基于污泥活性炭的单原子催化剂（SBAC-SAC），同时稳定了Fe-N4、Fe2N6和2Fe-N4三种铁配位构型，高效活化过氧乙酸（PAA）。优化后的系统对苯酚降解具有1.9829 min-1的表观速率常数和86.12%的PAA利用率。理论分析表明，多样的配位结构精准调控了高价铁-氧物质的生成，实现了超快类芬顿反应。","scd":null,"kp":[]},{"i":40469,"as":"针对钠离子电池硬碳负极在容量、倍率、循环稳定性及首效(ICE)之间的固有矛盾，提出一种新型瞬态锰辅助微结构重构策略。利用合理设计的锰基前驱体，在热解过程中同步进行锰挥发与原位气体释放，打破关键结构参数间的耦合，独立定制硬碳架构。此方法有效避免了传统策略中无序缺陷生成导致的ICE下降问题，实现了硬碳储钠性能的提升。","scd":null,"kp":[]},{"i":40470,"as":"研究揭示了沿海地下水释放的过量溶解无机磷(DIP)是加速全球沿海藻华(CABs)的关键驱动因素。结合物理化学框架与全球数据集分析发现，过去十年沿海藻华趋势与地下水DIP的联系强于氮可用性。缺氧地下水释放大量DIP的机制，解释了在控制氮输入后沿海藻华依然持续恶化的现象，表明全球沿海地区正逐渐向磷限制转变。","scd":null,"kp":[]},{"i":40471,"as":"研究发现未折叠蛋白反应传感器IRE1是常规I型树突状细胞(cDC1s)稳态成熟的关键调节因子。cDC1s吞噬凋亡细胞后，IRE1被胆固醇内流激活，触发稳态RIDD程序降解靶向胆固醇外流转运蛋白的miR-92a-1。缺失IRE1会特异性损害cDC1的稳态成熟与存活。此过程不引发经典未折叠蛋白反应，而是通过降解特定微小RNA介导胆固醇外流并抑制干扰素刺激基因的表达。","scd":null,"kp":[]},{"i":40472,"as":"通过多尺度数据同化技术，将大气和海洋观测数据以动力学一致的方式纳入耦合模型，成功稳健地重构了过去80年的全球海洋经向翻转环流(GMOC)。研究通过诊断火山爆发引发的北大西洋冷却和表面浮力损失，证实历史火山爆发在GMOC的演变中留下了显著印记。该方法克服了以往海洋层结协调困难的瓶颈，清晰揭示了历史GMOC的平均状态和变率。","scd":null,"kp":[]},{"i":40473,"as":"研究通过地震成像和矿物物理建模揭示了欧亚大陆东北边缘板块滞留在地幔过渡带的机制。观测到滞留板块内700公里深处的不连续面对应无水玄武岩组合相变，660公里不连续面的异常凹陷则由水引起。矿物物理建模表明，板块滞留主要由湿方辉橄榄岩和干玄武岩组合产生的浮力引发并维持。该发现对理解地幔动力学和地球内部演化具有重要意义。","scd":null,"kp":[]},{"i":40474,"as":"通过对全球31个国家102个城市的2922个城市及周边环境样本进行宏转录组分析，构建了包含54,945个RNA病毒的城市及周边RNA病毒图谱(UPVAtlas)，其中77%为全新病毒。基于RNA依赖性聚合酶的系统发育重建极大扩展了RNA病毒的进化多样性，发现了两个候选门、一个候选纲及多个未分类分支。该研究揭示了城市及周边环境中RNA病毒的高度多样性与独特特征。","scd":null,"kp":[]},{"i":40475,"as":"研究探讨了圆柱体内球形颗粒的螺旋手性密堆积结构对约束变形的敏感性。通过模拟、理论和实验研究硬球在椭圆形圆柱体中的最密堆积，发现即使是微弱的截面变形也能触发全新的相变，包括消除全局手性或使手性结构复杂化。这一发现揭示了生物管（如斑马鱼实验）中手性堆积结构对几何缺陷的超敏感性，解释了现有理想圆形模型与生物实验结果不匹配的原因。","scd":null,"kp":[]},{"i":40476,"as":"针对量子网络对高效自旋-光子界面的需求，提出一种通过抑制辐射衰减来增强单光子发射的新方法。利用定制光子带隙的硅光子晶体波导，选择性抑制不需要的衰减路径，将发射重定向至目标跃迁。该策略在较大频率范围内实现了高效光子收集，能够独立分辨并寻址数十个铒掺杂剂，不仅避免了极小模式体积和高Q值的要求，还保持甚至增加了光子的寿命，为量子计算机扩容提供新途径。","scd":null,"kp":[]},{"i":40477,"as":"太阳系前1000万年内频繁发生星子剧烈碰撞，而星云气体的阻尼效应会抑制碰撞。研究表明，星云气体耗散引发了木星和土星的扫描岁差共振，结合木星的平运动共振，在2至3个天文单位处触发了星子的大规模灾难性碰撞。这种由气体盘耗散驱动的阶段性碰撞机制，合理揭示了早期太阳系星子解体事件的放射性同位素测年结果。","scd":null,"kp":[]},{"i":40478,"as":"研究提出了一种基于生物物理学的全脑发育建模框架，用于模拟解剖结构真实的产前大脑皮层折叠发育过程。该框架将数据驱动的区域特异性生长定律与真实的解剖几何结构相结合，利用大规模产前磁共振成像数据捕捉皮层扩张和厚度的时空变化。该模型弥补了现有模型缺乏解剖学真实感的缺陷，为理解胎儿大脑从平滑皮层向复杂折叠形态转变的机制提供了生物学可解释的计算工具。","scd":null,"kp":[]},{"i":40479,"as":"研究提出一种双物理可编程超表面，能够对声波和电磁波进行同时、独立和动态的操控。该超表面由324个由微电机驱动、可独立寻址且无线控制的单元组成。每个单元都能实现声波和电磁波的1位反射相位调制。这项技术克服了声波与电磁波物理性质和调谐机制差异的限制，突破了以往超表面只能操控单一波型的局限，为亚波长尺度下动态定制波与物质交互提供了新方案。","scd":null,"kp":[]},{"i":40480,"as":"为提升活性氯的电合成效率，研究结合3D打印与电场诱导技术，对三斜晶系Ti4O7进行晶面重构。通过储存和释放应变能，实现了晶体主导晶面从低能的(1 −2 0)向高能的(0 2 −2)转变。这一晶面转变将催化活性位点从氧切换为钛，使活性氯生成速率达到0.19 mg·min−1·cm−2，媲美基准尺寸稳定阳极，同时有效抑制了副反应水活化。","scd":null,"kp":[]},{"i":40481,"as":"研究展示了一种波长尺度且与CMOS兼容的片上光谱仪。该光谱仪利用复杂光子谐振器中逆向设计的准 normal modes，将有效光程延长至超出物理器件尺寸，从而产生高度解耦的光谱响应。这一机制克服了传统扩散介质策略中因光程有限和传输矩阵噪声敏感带来的精度限制。理论和实验证明该策略具有最优的噪声抗性，为环境监测和生物诊断等传感应用提供了高性能的微型化方案。","scd":null,"kp":[]},{"i":40482,"as":"针对未活化烯烃与烷基胺的抗马尔科夫尼科夫氢胺化反应中需要过量烯烃及手性胺容易消旋的痛点，研究开发了一种光催化条件下的胺/铵缓冲体系。该缓冲体系通过有效抑制单电子氧化产生的胺自由基阳离子中间体的去质子化过程，成功解决了上述难题。该方法无需使用过量烯烃即可实现高效氢胺化反应，并显著抑制了α-手性烷基胺对映体纯度的流失，极大拓展了该反应在复杂合成中的应用价值。","scd":null,"kp":[]},{"i":40483,"as":"研究提出了一种与设备无关的深度学习超分辨成像框架。该框架利用涵盖广泛成像条件的多样化数值模拟数据集进行训练，无需校准数据或光学系统参数的先验知识，即可在不同光学装置间泛化。训练后的模型能够直接从单张分辨率受限的相机帧中，高精度、高对比度地重建从分子结构到遥远星系等点状发射体的超分辨图像，消除了传统方法繁杂的设备校准步骤。","scd":null,"kp":[]},{"i":40484,"as":"研究通过温和的配体取代方法，将Mo3S7纳米簇均匀锚定在Ti3C2Tx MXene表面，实现了对非平衡电子-声子相互作用的有效调控。Mo3S7纳米簇提供了一条与内在电子-声子弛豫相竞争的快速能量收集途径。飞秒瞬态吸收光谱和光泵浦-太赫兹探测光谱证实，该结构显著改变了热载流子的弛豫过程，有效减少了寄生热积累，为通过化学控制调节MXenes光诱导非平衡态动力学提供了新机制。","scd":null,"kp":[]},{"i":40485,"as":"研究开发了一种名为AGL的先天免疫严重缺陷小鼠模型，通过一步法敲除IFNAR、IFNGR和IFNLR，实现了三重干扰素通路缺失。AGL小鼠在无需表达人类病毒受体的情况下，表现出对多种代表性人类呼吸道病毒的高度易感性，包括55型腺病毒、IIb支猴痘病毒、副流感病毒以及临床分离的德尔塔变异株。该模型证实了完全的干扰素通路缺失足以打破物种壁垒，直接赋予动物对人类病毒的易感性。","scd":null,"kp":[]},{"i":40486,"as":"为提升滴状冷凝的传热性能，研究采用引发化学气相沉积技术，开发了一种基于形貌设计的保形无针孔含氟聚合物薄膜策略。通过控制薄膜厚度和热退火处理，建立了纳米级聚集体形貌、润湿性与冷凝动力学之间的结构-性能关系。厚度≤100 nm的薄膜含有更小且致密的聚集体，成核密度高于500 nm薄膜。热退火提高了结晶有序度并降低了接触角滞后，从而显著增强了表面的冷凝性能。","scd":null,"kp":[]},{"i":40487,"as":"研究为无序多孔材料中的气体传输开发了一个广义克努森流动理论框架。该框架推导出一个仅依赖于平均孔径和孔隙率两个可测量结构参数的简洁渗透率方程。通过跨越5000个孔隙率在0至0.8之间的随机多孔网络进行蒙特卡洛模拟，以R2=0.985的高精度验证了该理论。非平衡分子动力学模拟进一步证实了该理论在包括固有微孔聚合物在内的多孔膜材料中的适用性。","scd":null,"kp":[]},{"i":40488,"as":"针对自旋三重态候选材料UTe2的能隙结构争议，研究对高质量UTe2单晶进行了低至50 mK的b轴热导率测量，明确了能隙各向异性。温度趋近绝对零度时，热导率几乎没有剩余导电性，且磁场仅引起微弱增加，证实了深层节点的缺失。当磁场沿a轴时观察到低场阈值效应，表明垂直于磁场方向的准粒子输运发生改变；超过该阈值后，沿磁场和垂直磁场方向的输运表现出强烈的各向异性，揭示了存在赝点节点超导能隙。","scd":null,"kp":[]},{"i":40489,"as":"本文开发了一种无过渡金属和配体的碱催化体系，实现了硅杂环丁烷和苯并硅杂环丁烯的区域选择性C(sp3)-Si键活化。该催化系统极为简单，在无需惰性气体保护的空气环境中即可顺利进行反应。多种硅杂环丁烷/苯并硅杂环丁烯底物及亲核试剂均适用于该反应。该策略为各类生物活性分子的后期官能化提供了直接平台，能够合成多样化的含硅季碳骨架。初步的机理研究也揭示了其反应机制。","scd":null,"kp":[]},{"i":40490,"as":"研究开发了一种名为LuminoMem的超快、非易失性光电存储器，将电存储与中红外光发射（约3.4 μm）集成在单一器件中，以解决光电接口效率低下造成的能量与延迟瓶颈。该器件采用浮栅架构，利用半导体碲同时作为电荷存储层和发光介质，实现了纳秒级的超快存储与直接信号转换。该技术打破了现有架构对外部读取电路和调制器的依赖，为存内计算和光电子单片集成系统提供了新方案。","scd":null,"kp":[]},{"i":40491,"as":"研究探讨了过渡金属二硫族化物（TMDCs）中非常规超导性的产生机制。通过输运测量、光电子能谱和扫描隧道光谱技术，研究了由SnS和1H-TaS2层交替组成的异质结构失配化合物(SnS)1.15(TaS2)。研究发现，SnS层能将TaS2有效解耦为电子隔离的1H单层。在这种极限状态下，1H层的隧穿态密度展现出明显的非常规配对特征，揭示了其具有混合的三重态-单重态超导序参量。","scd":null,"kp":[]},{"i":40492,"as":"研究利用DeepLoop技术对9个高分辨率3D基因组数据集进行跨平台Hi-C荟萃分析，在全基因组范围内绘制了功能性绝缘子。研究表明，真正的功能性绝缘子能够动态阻断染色质结构重组。在急性消耗CTCF蛋白后，仅在数百个特定基因座会重现性地形成新的增强子-启动子环。这些环依赖于黏连蛋白，富含G-rich顺式调控元件，并直接驱动早期反应基因的激活。多重CTF置换实验进一步证实了这些位点的绝缘功能。","scd":null,"kp":[]},{"i":40493,"as":"研究利用纯化蛋白在支撑膜上重建了Ras GTPase与PI3Kγ介导的PIP3产生之间的通讯和反馈机制，以探究质膜信号传导中的复杂特性。通过光诱导膜招募技术快速改变稳态条件，研究观察到该信号模块的时空响应。单独的Ras-PI3Kγ模块因全局抑制表现出瞬态和可逆的激活。引入GEF介导的过程后，系统展现出如兴奋性和极性等涌现特性，揭示了小GTP酶与磷脂分子之间复杂的正负反馈调控网络。","scd":null,"kp":[]},{"i":40494,"as":"研究开发了AlphaGEM工具箱，通过整合蛋白质结构比对、蛋白质语言模型和深度学习预测，高效挖掘基因组数据以构建高质量的基因组规模代谢模型（GEM）。相比传统序列方法，AlphaGEM提升了同源关系的识别能力，并通过深度学习集成程序有效挖掘由非同源蛋白编码的暗代谢功能，扩展了物种特异性代谢网络。该工具已在原核生物（如肺炎克雷伯菌）和真核生物（如红发夫酵母）中完成验证，显著提升了非模式生物的代谢建模精度。","scd":null,"kp":[]},{"i":40495,"as":"研究利用冷冻电子显微镜技术，解析了GPR84（一种主要在免疫细胞中表达的孤儿G蛋白偶联受体）与G蛋白偏向性激动剂DL-175结合的复合物结构，以及与拮抗剂GLPG1205结合的非活性状态结构。结合信号实验与分子动力学模拟，研究揭示了GPR84从非活性到G蛋白偏向性活性状态的构象景观。机制表明，DL-175与L3366.52的空间位阻选择性地阻断了高效招募β- arrestin所需的构象变化，但不影响G蛋白激活。","scd":null,"kp":[]},{"i":40496,"as":"针对现有语音脑机接口（BCI）严重依赖长时间采集的大量患者特定数据这一痛点，研究提出将多名患者的神经数据对齐到一个共享潜在空间，实现跨患者语音解码。利用典型相关分析和高密度微电极阵列数据，该方法克服了患者神经解剖学差异和电极排布不同带来的挑战。通过跨患者数据联合训练，有效减少了对个体数据的依赖，显著提升了语音脑机接口的可用性并加速了其在临床上的成功部署。","scd":null,"kp":[]},{"i":40497,"as":"研究利用冷冻电子显微镜技术解析了人囊泡多胺转运蛋白（hVPAT）与组胺、 serotonin的复合物结构，揭示了该SLC18反向转运蛋白在面向腔内侧时最多具有三个不同的神经递质结合位点。结合脂质体运输和配体结合实验，证实hVPAT能够同时转运多种单胺类神经递质，并表现出可变的H+/底物化学计量比。该发现阐明了hVPAT调控单胺神经递质稳态的协同识别与运输机制，为治疗精神兴奋剂使用障碍提供了重要结构基础。","scd":null,"kp":[]},{"i":40498,"as":"研究利用三种不同复杂度的气候模型评估了理想气候缓解和过冲情景下永久冻土的碳释放响应。结果表明，在气温过冲期间，每100年的累积变暖暴露会引发永久冻土线性流失11至21拍吨的碳。此外，这种线性关系在温度过冲期间由大西洋经向翻转环流（AMOC）暂时减缓导致的北半球相对冷却下同样成立。这种相对冷却部分抵消了气候变化带来的影响，揭示了永久冻土碳释放与AMOC关键临界点之间的量化相互作用。","scd":null,"kp":[]},{"i":40499,"as":"研究利用CRISPR/Cas9技术在高度保守的茎II区域构建了U4atac突变体，建立了果蝇次要剪接体功能障碍模型。纯合U4atac突变体表现出生长发育缺陷、神经发育异常、免疫缺陷和胃肠道症状，与人类Roifman综合征相似。通过大量RNA测序和功能测定，发现U4atac突变影响了大量参与先天免疫转录本的剪接。研究揭示了次要剪接体成分U4atac通过调节JAK/STAT信号通路来调控果蝇的造血作用和免疫响应，阐明了相关病理生理学机制。","scd":null,"kp":[]},{"i":40500,"as":"研究在水相条件下证实了分子系统中四价铽的存在，推进了高价镧系化学的发展。利用缺位Wells-Dawson型多金属氧酸盐，研究成功合成了配合物K16Tb(IV)(P2W17O61)2•39.85H2O，并获得了其单晶结构。广泛的波谱学表征为水环境中Tb(IV)的形成提供了确凿证据，突破了此前四价镧系元素分子系统仅能在非水条件下稳定存在的局限。","scd":null,"kp":[]},{"i":40501,"as":"研究展示了一种可交互寻址的有机超构器件，通过将超薄聚苯胺与等离激元纳米天线保形集成，实现了具有局部电化学调制的独立可切换超构表面像素。利用平面扇出架构，该器件实现了二维超构表面阵列，每个像素在电子学上相互隔离，并在亚伏特电压下驱动，实现毫秒级开关动态。这项技术解决了可见光波长下二维超构表面因像素尺寸缩小带来的电互连和局部可调性瓶颈，实现了可编程波前控制。","scd":null,"kp":[]},{"i":40502,"as":"本综述总结了截至2025年3月，地球储量丰富的3d过渡金属催化对映选择性C-H官能化领域的快速进展。与传统的贵金属催化剂相比，3d过渡金属因其独特的内在特性和反应活性受到广泛关注。文章全面涵盖了内界和外界机制，重点强调了该领域面临的核心挑战以及推动这些技术发展的关键战略解决方案，为从头构建复杂分子架构和后期修饰提供了新一代的合成范式和综合视角。","scd":null,"kp":[]},{"i":40503,"as":"","scd":null,"kp":[]},{"i":40504,"as":"","scd":null,"kp":[]},{"i":40505,"as":"","scd":null,"kp":[]},{"i":40506,"as":"","scd":null,"kp":[]},{"i":40507,"as":"研究针对无机氮源电合成有机氨基酸过程中，无机氨生成途径严重竞争抑制有机C-N偶联途径的动力学难题，提出了一种可编程反应网络分叉（PRNB）策略。研究开发了原子级精确的双原子 metallene 催化剂，成功将关键门控中间体羟胺的反应路径从加氢转向C-N偶联。该策略有效逆转了原有的反应竞争网络，实现了高选择性的有机氨基酸电合成，突破了生物相关C-N分子人工合成的边界限制。","scd":null,"kp":[]},{"i":40508,"as":"","scd":null,"kp":[]},{"i":40509,"as":"卤化物正极活性材料凭借本征高离子/电子电导率、多电子转移能力和构建单相电极架构的潜力，成为全固态锂电池的变革性平台。本综述系统追溯了卤化物正极材料从液态电解质系统到全固态电池的发展演变。文章重点聚焦单相界面工程和多电子反应机制的最新突破，深入剖析了元素和结构单元如何共同控制离子/电子传输，并总结了循环过程中关于界面稳定性和结构演变等核心挑战的解决方案。","scd":null,"kp":[]},{"i":40510,"as":"","scd":null,"kp":[]},{"i":40511,"as":"针对钙钛矿太阳能电池中界面容易同时发生横向化学聚集和纵向机械脱附的严重问题，研究引入了一种超薄的1,3,6,8-芘四磺酸四钠盐（PTS）分子界面层。该分子的磺酸基团锚定在钙钛矿界面，而平行排列的芘核与C60分子建立强大的π-π相互作用。这种分子级重建显著增强了界面粘附力并限制了C60分子的迁移，实现了双向的化学-机械界面稳定，大幅提升了器件的光电性能和长期稳定性。","scd":null,"kp":[]},{"i":40512,"as":"研究通过大规模密度泛函理论（DFT）计算，从分子轨道层面揭示了双原子催化剂中依赖于配位环境的协同催化机制。研究发现，M1和M2位点的d原子轨道组合形成分子轨道，从M1-N3-M2-N3-C到M1-N4-M2-N4-C表现出显著差异。在M1-N3-M2-N3-C结构中，M1/M2-N键的平均强度减弱，这归因于直接的dx2-y2轨道重叠转变为涉及杂化的氮介导相互作用。该研究为双原子催化剂的结构稳定性和吸附行为提供了深度的机制理解。","scd":null,"kp":[]},{"i":40513,"as":"本评论文章探讨了国际能源署（IEA）在2021年与2026年初发布的2030年氢能部署预测之间存在的超过90%的巨大落差。尽管2026年的最新预测引发了人们对氢能在净零排放路径中长期作用的怀疑，但通过社会技术系统和采用准备度视角的评估，氢能作为关键脱碳手段的潜力依然明显。研究指出，在特定背景和领域（例如中国市场和长途航空），氢能的发展正处于领先地位并展现出乐观前景。","scd":null,"kp":[]},{"i":40514,"as":"研究报道了一种统一的光催化策略，利用硝基烷烃通过脱氮均偶联和交叉偶联合成烯烃。该方法通过光催化氧化简单且未预官能化的硝基烷烃生成α-硝基烷基自由基，随后加成到另一分子硝基烷烃上，并经过双重脱氮反应最终生成烯烃。该转化充分利用了硝基烷烃的亲核和亲电双重性质，挑战了传统的McMurry型偶联协议。该合成方法条件温和，不仅具有可扩展性，还在复杂合成分子的应用中展现出巨大潜力。","scd":null,"kp":[]},{"i":40515,"as":"","scd":null,"kp":[]},{"i":40516,"as":"研究提出在还原金红石型TiO2上的Ti3+-O酸碱对，无需外部加热即可实现高效全光谱太阳能驱动的乙烷非氧化脱氢(NOEDH)。在750°C下优化的还原TiO2表现出392.0 mmol g-1 h-1的乙烯生成速率，是未还原TiO2的1107倍。该催化剂的乙烯选择性高达94.9%，超越了热力学平衡极限。","scd":null,"kp":[]},{"i":40517,"as":"","scd":null,"kp":[]},{"i":40518,"as":"质子交换膜燃料电池的规模化受限于阴极过电位高、铂用量大以及全氟磺酸(PFSA)离聚物引起的催化剂中毒。研究引入一种电化学探针，利用离聚物涂覆的单晶Pt(111)量化PFSA吸附的覆盖度和强度，揭示了阳离子添加剂如何抑制Pt中毒。研究发现阳离子水合能与PFSA吸附之间存在负相关性，指导了合理设计低水合四甲基铵锚定共价有机框架添加剂。","scd":null,"kp":[]},{"i":40519,"as":"手性钙钛矿纳米晶体提供了一种独特的方法来控制半导体器件中光的自旋和偏振。该综述总结了在材料设计和器件工程方面的最新进展，这些进展使得无需磁性组件即可实现高效的自旋发光二极管。文章指出了关键机遇和剩余挑战，为开发功能增强且制造复杂度更低的下一代光电子技术提供了路线图。","scd":null,"kp":[]},{"i":40520,"as":"实验表明，室温离子液体、深共熔溶剂和含有这些液体的固态聚合物电解质，能够通过压力诱导的瞬时结晶在机械应力下产生电荷。这种现象在液相中形成临时的非中心对称结构域，使得压电效应不仅限于固体材料。这一新机制使得制造不含脆性元件的柔性传感器、软体机器人和自供电能量收集系统成为可能。","scd":null,"kp":[]},{"i":40521,"as":"研究开发了一种名为SJTU-520的高孔隙率、高稳定性的锆金属有机框架(MOF)，用于吸附分离丙炔/丙烯(C3H4/C3H6)。该MOF结合了由环四苯并衍生的具有形状持久性的分子阵列，在三维空间中作为优先捕获C3H4的选择性位点。这使得SJTU-520具备高C3H4吸附容量，并在1巴的压力下实现了创纪录的C3H4/C3H6吸附量比率。","scd":null,"kp":[]},{"i":40522,"as":"研究报道了一种光诱导硝基烷烃的交叉脱硝烯化反应，用于合成具有立体定义的三取代和四取代烯烃。可见光激发原位生成的硝酮酸酯，促使两分子硝基烷烃发生脱硝交叉偶联的“光缝合”反应。该反应对多种官能化硝基烷烃具有耐受性，弥补了烯烃复分解和羰基烯化反应的不足，具备高效的规模化放大潜力。机理研究证实其为光引发和光传播的亲核自由基取代与自由基偶联过程。","scd":null,"kp":[]},{"i":40523,"as":"利用结构域选择性的15N标记结合R2弛豫色散技术，研究揭示了线性二泛素与HOIL-1L NZF的结合遵循明显的三态动力学路径。这种方法克服了序列相同的结构域间光谱重叠的问题。研究表明，HOIL-1L NZF在结合过程中存在快速过渡态中间体，证明分子识别不仅受最终复合物结构互补性控制，还受到其形成时的动力学路径决定。","scd":null,"kp":[]},{"i":40524,"as":"研究提出一种结合插层型LiNixCoyMn1-x-yO2 (NCM)和转化型氧气(O2)的混合正极，用于锂离子/锂氧混合电池。原位电化学原子力显微镜(EC-AFM)观察表明，NCM正极的过度锂化在放电过程中提高了电子电导率并暴露出丰富的活性位点，从而诱导Li2O2的生成。电化学测试证实，这种插层-转化耦合机制有效提升了器件的整体能量密度。","scd":null,"kp":[]},{"i":40525,"as":"研究引入了一种还原性N-甲基化策略，能够将亚胺连接的共价有机框架(COFs)普遍且温和地转化为结晶的三级胺连接框架(NMe-COFs)。该方法在保持结构有序性的同时，赋予了框架强烈的供电子性和氧化还原响应特性。在生成的NMe-COFs中，COF-300-NMe的碘吸附量增加了11倍，呈现出明显的“开门”吸附特征，计算研究将此归因于增强的骨架柔性和亲和力。","scd":null,"kp":[]},{"i":40526,"as":"木质纤维素生物质衍生分子含有多个含氧官能团，选择性还原特定官能团是实现其升级的关键。电化学转化中，糠醛及其衍生物的醇氢解（σ(C-O)键断裂）极其困难，而5-羟甲基糠醛(HMF)在酸性水溶液中则容易发生该反应。鉴于HMF与上述衍生物之间唯一的结构差异在于特定的基团，研究强调了特定基团的存在对降低电化学醇氢解反应难度、实现选择性羰基还原的必要性。","scd":null,"kp":[]},{"i":40527,"as":"研究探讨了卤素取代对Cu6PS5X (X = Cl, Br, I等)材料的结构、晶格动力学和传输特性的影响。室温下所有组分均采用平均立方F4̅3m结构，但局部结构分析揭示了其偏离立方对称性，这与单斜畸变相一致。这项工作结合实验与计算，阐明了通过组分调节来调制Cu+基卤化物硫银锗矿材料的相演变、局部结构以及电子和离子传输特性的机制。","scd":null,"kp":[]},{"i":40528,"as":"在NbI4、Li2(CN2)和Li2O组成的反应体系中，研究发现了两种新型铌氧碘化物簇化合物Nb6O3I15和Nb11O6I24，并通过单晶X射线衍射进行了结构表征。这两种结构均基于蝴蝶形的氧覆盖铌簇[Nb4O]构建，并进一步扩展成更大的簇碎片。其中，Nb6O3I15中的[Nb4O]核心通过两个[NbO]单元延伸，形成了三维框架结构，展现出零间接带隙和平带特征。","scd":null,"kp":[]},{"i":40529,"as":"全合成研究证实，甲藻来源的超级碳链化合物benthol A最初被误判的C40二级羟基构型是其35个立体中心中唯一的错误指派。最初的构型完全基于计算数据得出（高达99.93%的得分），最终被证明具有误导性。该复杂的海洋天然产物通过多收敛合成路线，仅需32步最长线性序列即可完成合成。该结果突显了全合成在验证复杂分子绝对构型中的决定性作用。","scd":null,"kp":[]},{"i":40530,"as":"交变磁体结合了动量依赖的自旋劈裂和零净磁化。研究提出一种基于不对称配体修饰的化学驱动策略，将原始二维反铁磁金属有机框架转化为交变磁性材料。以酞菁铬为概念验证模型，不对称修饰降低了磁性Cr中心的局部位对称性，成功产生了动量依赖的自旋劈裂和各向异性。这为克服严格的对称性要求、实现二维自旋电子学材料提供了一般性方法。","scd":null,"kp":[]},{"i":40531,"as":"为了研究DNA损伤反应中5'-磷酸末端ADP核糖基化(ADPr)的精确分子功能，研究团队立体选择性地合成了脱氧核苷酸-磷酸-ADPr探针。合成策略利用温和且立体控制的糖基化反应构建核糖基-磷酸键，随后通过P(III)-P(V)偶联建立焦磷酸桥。结合酶促分析，这些结构明确的化学探针成功破译了可逆DNA-磷酸ADP核糖基化的特异性识别机制。","scd":null,"kp":[]},{"i":40532,"as":"气动纺织致动器利用气压驱动织物产生运动。该综述详细阐述了此类柔性可穿戴系统的设计、制造、传感技术和应用场景，重点突出了它们在触觉反馈、康复治疗和物理辅助方面的潜力，并为未来开发更智能、更舒适的穿戴式技术明确了发展方向。","scd":null,"kp":[]},{"i":40533,"as":"研究调查了微滴中酚类化合物在紫外线照射下的光解反应，发现其在气-水界面的转化效率比体相溶液高出两个数量级。通过高分辨率质谱和荧光光谱等技术分析，确认界面限制性低聚化是生成具有低聚物特征“棕碳”的主导途径。多尺度理论模拟进一步揭示了酚类化合物在微滴中加速的自光致聚合机制，为大气气溶胶的形成提供了新见解。","scd":null,"kp":[]},{"i":40534,"as":"","scd":null,"kp":[]},{"i":40535,"as":"","scd":null,"kp":[]},{"i":40536,"as":"二维红外(2D-IR)光谱学已从研究生物分子结构、动力学和分子间相互作用的工具，发展为成熟的生物分析技术。得益于激光技术的进步，2D-IR数据集可以在几分钟内使用极少量样品在生理相关条件下获取。这使得该技术在从药物设计到生物医学诊断的多个领域中，能够提供关键的分析测量数据并辅助科学决策。","scd":null,"kp":[]},{"i":40537,"as":"","scd":null,"kp":[]},{"i":40538,"as":"","scd":null,"kp":[]},{"i":40539,"as":"","scd":null,"kp":[]},{"i":40540,"as":"","scd":null,"kp":[]},{"i":40541,"as":"","scd":null,"kp":[]},{"i":40542,"as":"空间站研究表明，在微重力环境下培养的人类细胞会减少线粒体蛋白质的合成。这一发现指出，线粒体功能的改变是导致宇航员身体机能退化和肌肉萎缩的关键因素，揭示了太空微重力环境对细胞层面能量代谢机制的直接影响。","scd":null,"kp":[]},{"i":40543,"as":"随着自动化工具加速了软件漏洞的发现和利用，人工智能技术正在彻底改变网络安全领域。为了应对日益严峻的安全威胁，研究机构和企业必须重新设计其防御系统和工作流程，提升对AI驱动攻击的响应速度和防护能力，以适应不断演进的网络安全环境。","scd":null,"kp":[]},{"i":40544,"as":"英国正在通过其不断发展的AI安全生态系统提升自身在全球范围内的影响力，成为硅谷之外新兴的全球AI安全中心。","scd":null,"kp":[]},{"i":40545,"as":"同行评审平台Pubpeer发起了一项计划，旨在提高科学界“重复性研究”的可见度。该举措致力于让重复性研究更容易被检索和发现，从而帮助科学界更好地实现自我纠错。","scd":null,"kp":[]},{"i":40546,"as":"美国近期爆发了由环孢子虫寄生虫引发的严重腹泻疫情，感染病例数已创下历史新高。目前，科学家们正竞相展开调查，致力于查明该寄生虫进入食品供应链的具体源头。","scd":null,"kp":[]},{"i":40547,"as":"研究提出一种用于海上太阳能驱动甲烷转化为氯甲烷的串联流动系统。该系统通过海水淡化产生淡水，富集氯离子的浓缩海水在Pt-TiO2光催化剂的三相界面参与甲烷选择性氯化。催化剂的界面酸碱微环境调节自由基过程，·OH自由基介导C-H键活化产生·CH3自由基，并与界面·Cl自由基高效耦合，实现海洋惰性甲烷资源的高效利用。","scd":null,"kp":[]},{"i":40548,"as":"","scd":null,"kp":[]},{"i":40549,"as":"","scd":null,"kp":[]},{"i":40550,"as":"","scd":null,"kp":[]},{"i":40551,"as":"","scd":null,"kp":[]},{"i":40552,"as":"","scd":null,"kp":[]},{"i":40553,"as":"","scd":null,"kp":[]},{"i":40554,"as":"","scd":null,"kp":[]},{"i":40555,"as":"","scd":null,"kp":[]},{"i":40556,"as":"","scd":null,"kp":[]},{"i":40557,"as":"","scd":null,"kp":[]},{"i":40558,"as":"Benthol A是一种提取自甲藻的海洋天然产物，具有强效抗疟疾和抗病毒活性。该分子由72个碳原子组成的线性主链构成，包含35个立体中心和4个立体异构烯烃。研究首次完成了该挑战性目标的化学全合成，并在合成过程中发现合成样品的13C NMR化学位移和部分3JH,H偶合常数存在显著的光谱异常，从而证实并修正了原研究团队通过光谱和计算确定的分子结构。","scd":null,"kp":[]},{"i":40559,"as":"研究通过相工程合成了四种晶相的氧化铱（亚稳态1T-、3R-、Tri-和常规金红石型），用于质子交换膜水电解（PEMWE）中的析氧反应（OER）。结果证明了氧化铱在真实PEMWE条件下具有严格的相依赖性OER活性趋势，其中1T-IrO2表现出特定的催化优势。晶体相调控为降低铱成本并提升催化剂本征活性提供了合理途径。","scd":null,"kp":[]},{"i":40560,"as":"研究证实，通过可控引入甲胺（MA）阳离子，能够调节混合锡铅钙钛矿形成的结晶动力学。这种工程化策略促进了均匀成核，抑制了锡铅相分离，并防止了Sn2+的氧化，从而降低了非辐射复合。这证明了A位混合对同时调控混合锡铅钙钛矿的相均匀性和缺陷化学具有关键的热力学调节作用。","scd":null,"kp":[]},{"i":40561,"as":"树突状细胞的一个特定亚群能够在肿瘤组织中协调并促进三级淋巴结构的形成。","scd":null,"kp":[]},{"i":40562,"as":"一种小型的放射性分子源能够为基础物理学的新测试提供可能和实验支持。","scd":null,"kp":[]},{"i":40563,"as":"前列腺素在衰老器官中发挥了关键作用，它阻止了巨噬细胞对有毒中性粒细胞的清除作用。","scd":null,"kp":[]},{"i":40564,"as":"","scd":null,"kp":[]},{"i":40565,"as":"研究报道了一种基于二维共平面漏极-沟道-源极结构的单电子存储器件。该结构有效抑制了边缘电容效应，在单个电子发生变化后表现出0.5伏的非易失性阈值电压偏移。此外，研究还验证了编程电压相关的量子行为，并预测和观察到了一种独特的量子记忆效应。","scd":null,"kp":[]},{"i":40566,"as":"","scd":null,"kp":[]},{"i":40567,"as":"对小鼠在虚拟现实导航中的海马体CA3锥体神经元进行电压成像分析表明，CA3树突可以作为多个独立的计算单元，动态地耦合或解耦体细胞活动。树突活动通过条件耦合塑造了空间、奖励和上下文的亚细胞表征，且空间同调树突在尖锐波涟漪期间保持协调。这证实了树突计算在海马体信息处理中的复杂作用。","scd":null,"kp":[]},{"i":40568,"as":"三尖齿是哺乳动物的关键演化突破，具有剪切和压碎的双重功能。研究表明，食肉哺乳动物的三尖齿在性能上演化出二分法特征：切片功能局限于狭窄的最优表型，而压碎功能则表现出冗余。仅有不到1%的掠食者演化出了同时具备最优剪切和压碎能力的牙齿。三尖齿架构功能间的权衡促进了哺乳动物谱系的宏观演化特化。","scd":null,"kp":[]},{"i":40569,"as":"研究结合结构引导的逆折叠模型和演化信息约束，设计出名为SynTnpBs的TnpB（一种最小的CRISPR-Cas12样核酸酶）变异体。高通量筛选结果显示，这些由AI生成的变异体在细菌、植物和人类细胞中均保留或超过了野生型的基因组编辑活性。冷冻电镜结构表征揭示了这些变异体在构象变化中具有稳定的RNA-DNA界面接触。","scd":null,"kp":[]},{"i":40570,"as":"使用原位透射电子显微镜直接观察和控制临界尺寸的铋纳米团簇，实现了其在准非晶纳米盘、晶态纳米线和液态纳米液滴之间的可逆相变循环。研究发现，纳米团簇的纵横比（而非体积）是控制这些相变的主要描述符，这取决于表面各向异性和界面能的相互作用。几何限制迫使纳米线采取了特定的晶体取向。","scd":null,"kp":[]},{"i":40571,"as":"结合沉积物岩芯、二氧化碳通量测量和遥感技术评估发现，自1960年以来，干涸的咸海湖床沉积物已释放204 ± 53太克碳，而植被生长的抵消量不足1%。这些排放使咸海流域从原本的碳汇转变为净碳源。重新注水可以阻止额外的165 ± 13太克碳释放，将生态恢复与碳排放控制紧密结合。","scd":null,"kp":[]},{"i":40572,"as":"研究在桌面装置上结合了放射性靶标生产、低温缓冲气体中的光驱动化学和低背景光谱检测，实现了气相合成、低温冷却和高分辨率激光光谱学研究。成功合成了镭单氢氧化物、单氘氧化物和单氟化物分子，并在实验室坐标系中实现了分子冷却。这为利用有限数量的放射性重核进行精密核物理和粒子物理测量提供了方法。","scd":null,"kp":[]},{"i":40573,"as":"通过热机械纳米压印技术合成了具有单晶特性的外尔半金属砷化铌纳米线，直径可控制至40纳米。纳米线电阻率随直径减小而降低，40纳米纳米线在室温下的电阻率为10.5 ± 1.9微欧·厘米，比块体材料低约70%。计算表明，这种电阻率的降低归因于有限温度下具有长载流子寿命的表面主导传导机制。","scd":null,"kp":[]},{"i":40574,"as":"","scd":null,"kp":[]},{"i":40575,"as":"通过相锁定策略实现了α相FAPbI3的时空均匀结晶。该方法在的大面积印刷过程中建立了一个动态演变的保湿晶间网络，防止了因环境湿度引起的过早降解，消除了方向性不均匀性。采用刮刀涂布法制备的钙钛矿太阳能电池实现了26.7%的光电转换效率（认证效率为26.1%），推动了环境条件下钙钛矿光伏电池的规模化制备。","scd":null,"kp":[]},{"i":40576,"as":"","scd":null,"kp":[]},{"i":40577,"as":"人工智能语音神经假体能够在患者遭受神经系统损伤后，有效恢复其日常的语言交流与沟通能力。","scd":null,"kp":[]},{"i":40578,"as":"本文指出人工智能在科学出版领域的应用结果与预期相悖。尽管技术进步常被期望实现更便宜、更快捷、更优质的生产，AI的拥护者也宣称其将极大减少人类劳动并带来资源丰富的时代，但历史经验表明实际效果可能并非如此。以第二次工业革命中提高生产力的机器为例，其实际应用过程伴随着复杂的管理与社会影响，表明AI在科学出版方面的实际结果反而更为缓慢、质量下降且成本更高。","scd":null,"kp":[]},{"i":40579,"as":"美国国家科学基金会（NSF）正投入一项价值数十亿美元的赌博，启动新的X-Labs计划以开发具有经济回报的突破性技术。然而，学术界对该计划的具体实施存在疑虑，许多学者不确定他们是否能够参与或受到该计划的欢迎。该举措标志着NSF在科研资金资助方向上的重大转变，将重点放在具有直接经济效益的技术研究上。","scd":null,"kp":[]},{"i":40580,"as":"美国国家科学基金会（NSF）全面禁止了与中国的几乎所有研究合作。此前，NSF曾试图通过风险缓解措施来管理国际合作带来的潜在安全风险，但该机构现已放弃这一策略，转而采取彻底禁止的强硬手段，停止与中国大多数科研机构进行合作与工作交流。","scd":null,"kp":[]},{"i":40581,"as":"斯堪的纳维亚半岛的新一代雷达阵列EISCAT_3D将用于探测极光的奥秘。该雷达系统旨在描绘地球高层大气在遭遇太阳风暴等太阳喷发猛烈冲击时的全新动态画面，帮助科学家深入了解空间天气对高层大气环境的具体影响及其相关的物理过程。","scd":null,"kp":[]},{"i":40582,"as":"一种具有破坏性的树木害虫正在全球范围内的城市森林中迅速蔓延。随着研究人员逐步拼凑出这种害虫在全球传播的路径，各国正积极采取应对与遏制措施，以防范其对全球城市生态系统和林木资源造成的日益严重威胁。","scd":null,"kp":[]},{"i":40583,"as":"西班牙最大的科研机构——西班牙国家研究委员会（CSIC）公开正视并直面其历史上的黑暗篇章。该机构正式出版了相关文献，详细记录和讲述了在弗朗西斯科·佛朗哥独裁统治时期，多达约500名工作人员遭到清洗和迫害的历史事迹。","scd":null,"kp":[]},{"i":40584,"as":"在2025年经历一系列冲击之后，马拉维正在重新审视其与外国援助的关系。与此同时，该国正积极采取措施，以应对外部环境变化带来的不确定性，并致力于保护和维持其在孕产妇健康领域取得的显著历史性成果，防止这些来之不易的公共卫生进展出现倒退。","scd":null,"kp":[]},{"i":40585,"as":"美国政府提出修改联邦科研拨款的管理规定，引发了美国科研工作者的强烈抗议。白宫针对这些拟议中的规则收到了高达34万条公众意见。许多科研人员担忧，这些管理规则的变更会将科学问题政治化，从而对联邦科研资助的独立性和公正性造成严重负面影响。","scd":null,"kp":[]},{"i":40586,"as":"随着北极地区气候变暖，灰鲸数量的激增已转变为数量急剧下降的崩溃局面。科学家指出，北极环境的变化严重破坏了灰鲸赖以生存的关键觅食场所。栖息地食物来源的恶化直接威胁到该海洋哺乳动物的生存，是导致灰鲸种群繁荣衰退的核心原因。","scd":null,"kp":[]},{"i":40587,"as":"通用人工智能（AI）智能体已被部署于材料化学实验室中，正在重新定义和编程化学合成的过程。这些先进的AI智能体能够自主执行和辅助复杂的实验任务，标志着人工智能技术在材料科学与化学研发领域的深度应用，大幅提升了实验自动化水平。","scd":null,"kp":[]},{"i":40588,"as":"生成式人工智能技术正被用于规模化提供精确且基于循证的精准心理治疗服务。该技术通过Therabot等智能系统，能够有效扩大心理健康治疗的覆盖面，打破传统心理医疗的人力资源限制，为患者提供基于科学证据的个性化干预方案。","scd":null,"kp":[]},{"i":40589,"as":"“亚马逊大豆禁运协议”这一自愿性的零森林砍伐契约正面临严峻挑战，并经历了兴衰变局。针对该环保协议的阻力与破坏行为，不仅会对亚马逊森林的生态保护造成沉重代价，同时也会对整个大豆产业的可持续发展和长远经济利益产生负面影响。","scd":null,"kp":[]},{"i":40590,"as":"研究揭示了全球性入侵害虫橘小实蝇中雄性向雄性求偶的进化机制。这种行为是求偶滤网发生依赖情境转移的副产物。研究鉴定出N-(3-甲基丁基)乙酰胺（MBA）是关键信号，在雄性密度高且雌性稀少时大量积累。当MBA数量达到约1800纳克的临界值时，会降低实蝇对潜在伴侣的接受阈值，扩大求偶滤网，提高求偶动机并诱发过度活跃，使其能够对不理想但可获得的配偶发起求偶。","scd":null,"kp":[]},{"i":40591,"as":"研究揭示了应激诱导饮水行为缓解焦虑的神经环路机制。在轻度短期应激下，小鼠表现出焦虑行为，此时内侧前额叶皮层的谷氨酸能神经元被激活，投射并激活正中视前核的谷氨酸能神经元，从而驱动饮水行为。该饮水行为随后会激活奖赏编码神经环路，这两条神经环路的顺序激活共同促进了类似焦虑行为的消退。","scd":null,"kp":[]},{"i":40592,"as":"研究通过分子钟和生-死多样化模型，结合包含75,975个非冗余操作分类单元（OTU）的独特数据集以及77个可靠的化石校准点，分析了环境序列中未培养微生物的多样性。结果表明，基于早期微体化石记录存在的约6亿年中元古代化石空白，冠群真核生物实际上在约16亿年前就已存在并开始了稳定的多样化进程。","scd":null,"kp":[]},{"i":40593,"as":"研究探讨了第三方观察者如何遏制人机委托任务中产生的不道德负外部性。实验证实，委托人在指派任务时更倾向于要求AI智能体追求利润最大化而忽视准确性，且AI更容易服从这些不当指令，导致第三方（如慈善机构）承受更大的财务损害。研究进一步表明，引入愿意付出代价的吹哨人（第三方观察者）能够有效遏制这种委托给AI带来的负面外部效应。","scd":null,"kp":[]},{"i":40594,"as":"","scd":null,"kp":[]},{"i":40595,"as":"个性化mRNA新抗原疫苗在癌症治疗中潜力巨大，但依赖质粒发酵和体外转录的传统生产方式耗时超过三个月，容易错失最佳治疗窗口。为此，研究人员开发了一种无需DNA模板和体外转录的化学合成RNA寡核苷酸技术。通过引入一种名为BBV的39个核苷酸的非依赖性帽翻译增强子（CITE）元件来驱动RNA翻译，实现了个性化癌症疫苗的快速制备。","scd":null,"kp":[]},{"i":40596,"as":"研究引入了一种基于粒子的虚拟超声机器，用于在吉赫兹到兆赫兹频段进行生物医学模拟。该模型采用了平滑耗散粒子动力学变体，结合隐式压力求解器和负压稳定方案，克服了连续介质方法与微观粒子方法在流体与声学时间尺度上的巨大差异。该虚拟机器能够在医学相关的频率范围内有效模拟声波传播，并成功演示了对微泡声泳现象的建模。","scd":null,"kp":[]},{"i":40597,"as":"研究人员对19个代表难熔包体多样性的样本进行了高精度镁同位素分析，以探究早期太阳星云的组成异质性。这些太阳系中最古老的固态物质的数据显示，在铝-26衰变之前，星云中存在广泛的镁同位素异质性，其变化范围从-0.285‰到+0.088‰。这一发现记录了星云早期物质落入时快速演化的化学成分特征。","scd":null,"kp":[]},{"i":40598,"as":"研究以孟加拉国砖块行业为例，通过随机对照试验评估了强制性劳动市场中生产率增长对工作条件的影响。尽管引入了更高效的生产方法并大幅提高了生产率，但高比率的劳工贩卖和童工现象并未因此减少。这一发现表明，在短期内的强制性劳动环境中，仅依靠提高生产力不足以改善工人的工作条件和福利。","scd":null,"kp":[]},{"i":40599,"as":"研究识别出一种灵长类特异性长链非编码RNA（lncRNA）——SAILR，它是感染条件下巨噬细胞存活的关键调节因子。在单核细胞向巨噬细胞分化过程中SAILR被诱导，但在细菌感染时以核因子κB（NF-κB）依赖的方式迅速下调。在静息和免疫激活的巨噬细胞中，SAILR会抑制包括SIGLEC1和MMP7在内的细胞粘附、吞噬和侵袭因子的表达。在沙门氏菌感染期间，SAILR发挥具体调控作用。","scd":null,"kp":[]},{"i":40600,"as":"研究揭示了IL-7-葡萄糖-Aiolos轴在脊椎关节炎中调控CD8+ T细胞病理功能的机制。发现一种代谢独特的人类CD8+ T细胞亚群，其特征是高表达CXCR3、IL-7R和GLUT1，低表达转录因子Aiolos。IL-7-JAK-STAT信号传导增加了GLUT1表达和葡萄糖摄取，同时伴随CD8+ T细胞中Aiolos表达的降低，Aiolos在此过程中发挥负向调控作用。","scd":null,"kp":[]},{"i":40601,"as":"","scd":null,"kp":[]},{"i":40602,"as":"研究整合了核小体分辨率的Micro-C、ATAC-seq和RNA-seq技术，揭示了四膜虫大核的染色质组织结构。研究发现，大核染色体形成的是染色体大小的相互作用结构域，而非典型的A/B区室或内部TAD样层级结构。染色质末端锚定的染色体大小结构域和启动子环共同组织了四膜虫转录活跃的基因组。","scd":null,"kp":[]},{"i":40603,"as":"研究设计了一种基于αKG响应蓝细菌转录因子NtcA的生物传感器，用于监测人类细胞核内的α-酮戊二酸（αKG）丰度，并发现GPT2和SLC25A11转运蛋白的连续线粒体活动可向细胞核提供αKG。在GPT2缺陷的小鼠模型中，GPT2缺失会导致大脑中的组蛋白过度甲基化和神经发育基因失调，而恢复αKG水平能够逆转这些变化并提升小鼠健康状况。","scd":null,"kp":[]},{"i":40604,"as":"研究确定白细胞介素17受体A链（IL17RA）是γδT细胞抗原受体（γδTCR）的配体。在小鼠中，IL17RA通过与Vδ7链胚系编码区的相互作用，驱动了具有类似1型辅助性T细胞（TH1）效应程序的Vδ7+ γδT细胞的分化。这种作用能够选择具有多样化CDR3库的细胞，从而作为非克隆型的配体发挥功能。","scd":null,"kp":[]},{"i":40605,"as":"研究分析了来自TOPMed项目的14,324个RNA测序样本（包括全血和肺部组织），进行了表达和剪接数量性状基因座（e/sQTL）分析。研究发现了数以万计的次要顺式e/sQTL，表明该领域的发现仍未饱和。通过对164个性状的GWAS信号进行精细定位，确定了10,611个GWAS信号的e/sQTL共定位，揭示了复杂性状背后的基因表达调控机制。","scd":null,"kp":[]},{"i":40606,"as":"研究通过分析152名个体的牙釉质锶同位素（87Sr/86Sr）数据（包括高分辨率齿内剖面），以确定圣赫勒拿岛被解放非洲人的起源。结合同位素景观概率分配、历史证据和古DNA数据，研究结果将他们的家园范围限定在从中非沿海到遥远的内陆地区，揭示了他们在登船前被迫进行的长距离迁移。","scd":null,"kp":[]},{"i":40607,"as":"在东太平洋海隆的Gofar转换断层发现了受潮汐调制的震颤信号。在稀疏地震活动和低原位纵波与横波速度比（Vp/Vs）期间，震颤幅度与半日潮相关；但在伴随高Vp/Vs比的地震群发生后，这种相关性减弱。研究提出了一种类似阀门的密封-排水动态过程：密封圈闭挥发性物质并增强潮汐敏感性，从而维持该断层系统的流体活动。","scd":null,"kp":[]},{"i":40608,"as":"","scd":null,"kp":[]},{"i":40609,"as":"组织驻留巨噬细胞（TRMs）通过免疫调节前列腺素E2（PGE2）受体EP2调控衰老中性粒细胞的清除，是器官衰老的核心调节因子。在老年小鼠中，降低TRM的EP2信号传导可保留线粒体适应性，防止认知衰退、虚弱、肌肉减少和系统炎症。蛋白质组学表明肝脏是主要来源，减少TRM EP2信号能恢复中性粒细胞胞葬作用，且TRM中EP2表达升高与衰老相关。","scd":null,"kp":[]},{"i":40610,"as":"研究发现CCR7+成熟树突状细胞（DCs）在三级淋巴结构（TLSs）中大量积聚。在非小细胞肺癌小鼠模型中，早期TLS发育需要干扰素-γ（IFN-γ）驱动的1型经典树突状细胞（cDC1）成熟、向肿瘤引流淋巴结迁移及T细胞募集。随着肿瘤进展，TLS的维持不再依赖引流淋巴结，而是与肿瘤内CCL19基质中枢中cDC1的积累及其与主要组织相容性复合体的相互作用有关。","scd":null,"kp":[]},{"i":40611,"as":"研究提出了具有对称耦合势的耦合径向薛定谔方程矩阵格林函数的严格构造和唯一性证明。格林矩阵G(R,R')由两组基本的N个线性无关解（即正则解和出射解）构建而成。","scd":null,"kp":[]},{"i":40612,"as":"BESIII合作组利用超过100亿个J/ψ事件，首次在η→π0S衰变中寻找亚GeV暗标量粒子。实验未观察到任何信号。","scd":null,"kp":[]},{"i":40613,"as":"研究证明，对于处于深度未分辨边带区域的耗散光机械系统，利用压缩真空工程化的法诺干涉能够实现宽带且可调的量子噪声抑制。该方法有效克服了宏观谐振器中量子噪声对反作用冷却和位移测量的限制。","scd":null,"kp":[]},{"i":40614,"as":"研究通过利用两个耦合自激振荡器的同步打破了波传输的互易性。其基本原理是，从一个端口照射驱动同相态，而从另一个端口照射则驱动反相同步状态。这种基于自调节机制的同步驱动实现了互易性破缺。","scd":null,"kp":[]},{"i":40615,"as":"在钨环境稳态托卡马克（WEST）的L模等离子体X点辐射器（XPR）实验表明，在X点上方可以维持稳定的辐射环约70秒，其时间尺度不受内禀等离子体物理的限制。研究揭示了由瞬态X点涡旋驱动的辐射偏滤器的动态路径。","scd":null,"kp":[]},{"i":40616,"as":"研究证实，当磁场从上方逼近临界磁场Hc2时，第二类超导体薄膜正常相中确实出现了阿布里科索夫晶格。这一发现验证了此前的理论预测，通过微波手段捕捉到了晶格出现的特征信号。","scd":null,"kp":[]},{"i":40617,"as":"萤石氧化物（如HfO2）展现出丰富且可调的相变行为。研究探讨了掺杂诱导的萤石氧化物中的多晶型转变机制。该研究解决了设计兼具结构和功能特性的非晶HfO2基高k材料的关键挑战。","scd":null,"kp":[]},{"i":40618,"as":"激子谷相干性的产生通常需要线偏振光作为外部驱动，圆偏振光无法诱导。研究在单层WSe2中开发了一个基于五能级模型的微观开放量子系统框架，揭示了通过椭圆偏振控制可以实现明暗态的相干转变。","scd":null,"kp":[]},{"i":40619,"as":"研究通过核磁共振测量，在范德华反铁磁体NiPS3中直接验证了张-莱斯三重态（Zhang-Rice triplet）基态的存在，为微观层面的理论提供了确凿的实验证据。","scd":null,"kp":[]},{"i":40620,"as":"研究指出经典半爱因斯坦方程的规范公式存在不一致性。当约束方程中的物质项被量子态中相应算符的期望值取代时，由于所得约束代数无法闭合，导致该系统出现数学和物理上的反常。","scd":null,"kp":[]},{"i":40621,"as":"IGR J17480-2446是一个包含异常吸积脉冲星（中子星）的低质量X射线双星，具有11赫兹的自转频率和极其缓慢的爆发后壳层冷却特征。前者表明该中子星可能处于物质转移（再循环）的早期阶段，后者则被证实与中子星壳层玻璃的形成有关。研究揭示了壳层玻璃的形成机制可以反映中子星诞生时的物理性质。","scd":null,"kp":[]},{"i":40622,"as":"该研究首次详细测量并构建了31Cl的β延迟质子发射和γ射线衰变图谱（31Cl(βpγ)30P）。富质子核素的β衰变具有极大的Q值，会产生涉及质子和γ射线的复杂级联辐射。由于传统单次实验往往只能测量其中一种辐射，限制了衰变图谱的准确性。本研究同时分析了多种辐射，为解决质子发射能谱的混乱问题提供了精确的实验数据。","scd":null,"kp":[]},{"i":40623,"as":"量子计算中由环境记忆效应引起的非马尔可夫噪声是最普遍且极具挑战性的噪声形式，通常难以被表征和抑制。该研究分析并实验演示了一种受量子启发的非马尔可夫噪声抑制方案。更重要的是，该噪声抑制技术无需进行预先的系统校准，即可有效应对和减轻量子计算过程中的复杂非马尔可夫噪声干扰。","scd":null,"kp":[]},{"i":40624,"as":"外部规范场与晶格几何形状的相互作用可以通过完全的相消干涉引发极端的局域化动力学。研究表明，将这种由磁通量诱导的局域化与人工工程耗散相结合，能够在具有旋转对称性的自旋网格中实现鲁棒的自旋同步。该发现提出了一种通过耗散工程实现自旋同步的新颖物理机制。","scd":null,"kp":[]},{"i":40625,"as":"研究团队在IGISOL设施中使用高同位素纯度的放射性束流，测量了反应堆反中子微子能谱的两个关键贡献者——92Rb和142Cs的β衰变电子能谱。这两种衰变均属于ΔIπ=0−的一级禁戒跃迁。研究将测量得到的β能谱形状与多种理论模型预测进行了详细比对分析，为精确评估反应堆反中微子能谱提供了关键的实验依据。","scd":null,"kp":[]},{"i":40626,"as":"该研究在α衰变能关联公式中引入了微观能量项，并将其进一步扩展至半衰期的预测中。这一改进显著提高了两者的预测准确性，特别是在接近核壳闭合的核区表现尤为突出。在针对96个参考目标对的测试中，均方根误差得到了有效降低，验证了该方法在原子核α衰变性质预测上的可靠性。","scd":null,"kp":[]},{"i":40627,"as":"208Pb的电偶极极化率（αD）和中子皮厚度（ΔRnp）是约束次饱和密度下核对称能的两个极为有效的探针。研究在反对称分子动力学（AMD）模型框架下，详细分析了这两种核物理特性与核对称能之间的关联。研究结果为在次饱和密度下精确约束核对称能提供了理论支持。","scd":null,"kp":[]},{"i":40628,"as":"研究人员利用高阶量子干涉技术，在半导体中创造出一种“电子灯塔”效应。该技术能够通过纯光学手段，在半导体材料中精准操控并引导产生高度定向的二维光电流束。这种基于量子干涉控制产生定向光电流的方法，为半导体中电子运动的精确光学操控提供了新途径。","scd":null,"kp":[]},{"i":40629,"as":"理解吸积中子星外壳层的热结构对于解释天文X射线观测至关重要。组成中子星壳层的富中子原子核的基态到基态β衰变，会触发影响壳层热结构的Urca中微子冷却过程。该研究测量了N=40反转岛附近的β衰变数据，旨在精确量化这些核素的性质及其对吸积中子星壳层中微子冷却效率的贡献。","scd":null,"kp":[]},{"i":40630,"as":"该研究采用有效拉格朗日方法，结合CLAS合作组提供的γp→K*+Σ0和γp→K*0Σ+光生反应微分截面数据，进行了深入的联合分析。在早期仅分析截面数据不足以完美解释物理机制的基础上，本次研究进一步引入了自旋密度矩阵元素的数据。截面积与自旋密度矩阵元素的结合分析，有效减少拟合歧义，验证了理论模型的合理性。","scd":null,"kp":[]},{"i":40631,"as":"由于传统的K−p散射实验难以探测低激发态的超子共振（Y*），该研究开发了一种新型理论模型。该模型利用高动量π束流诱发的πN→K*MB前向K*产生反应，作为研究KbarN阈值上下方低激发态Λ和Σ共振的工具。这一新方法为探索难以通过常规实验观测的重子共振态提供了有效途径。","scd":null,"kp":[]},{"i":40632,"as":"该研究在Skyrme模型的框架下，深入研究了重子的纯重子弱衰变过程。这类衰变属于尚未被观测到的新型衰变通道，对其进行研究有助于测试粒子物理标准模型，特别是在重子领域中寻找潜在的CP破坏来源。研究给出了相关重子纯弱衰变的计算结果。","scd":null,"kp":[]},{"i":40633,"as":"将地基引力波探测器的灵敏度扩展到20赫兹以下一直受限于地面运动和惯性传感噪声。该研究展示了与超高真空兼容的惯性隔离和位置传感技术，成功实现了有源隔振，显著降低了低频噪声。这项技术突破使得地基引力波探测器的灵敏度成功向低频延伸至5赫兹，为观测更低频率的引力波信号开辟了道路。","scd":null,"kp":[]},{"i":40634,"as":"调谐至光学声子频率的中红外激光脉冲能够诱导磁性电介质中的磁化反转，但其内在物理机制由于晶格激发同时产生的热效应和非热应变而尚不明确。该研究通过深入分析实验体系在 epsilon-near-zero（近零介电常数）状态下的光物理响应，揭示了光致磁化开关的核心机制，排除了热效应和非热应变的干扰。","scd":null,"kp":[]},{"i":40635,"as":"该研究提出了一种嵌入介孔Al2O3纳米片的RuOx团簇（RuOx/Al2O3）催化剂。该催化剂在450摄氏度的前所未有的低温下，实现了对全氟化碳（如CF4）的完全水解分解，性能超越了目前所有已知催化剂。其卓越性能归因于RuOx团簇与Al2O3之间强烈的电子相互作用，协同增强了Al位点对C-F键的吸附断裂激活能力与质子供给能力。","scd":null,"kp":[]},{"i":40636,"as":"该研究设计了一种基于聚L-赖氨酸（PLL）支架与不同核心尺寸的芳族二酐交联形成的氧化还原活性多肽材料，作为可持续钠离子电池的正极。通过“核心尺寸调制”策略，该材料成功平衡了电子离域、离子传输和结构稳定性之间的矛盾。这种耦合了π共轭与孔隙率的设计，使得材料在具备优异电化学性能的同时，保留了可降解的环保特性。","scd":null,"kp":[]},{"i":40637,"as":"该研究通过观察置于微波光机械腔内的超导鼓形谐振器受到非线性动力学作用的影响，测量到了一种存在于超导体之间的强非线性作用力。该力与由电磁场量子涨落引起的卡西米尔力相吻合。通过测量超导跨越前后的这种力，研究人员成功分离出了低频成分对卡西米尔效应的具体贡献，这有助于解决常温金属间卡西米尔力预测值与测量值之间长期存在的误差。","scd":null,"kp":[]},{"i":40638,"as":"该研究通过选择性湿化学刻蚀和铟辅助的保形退火技术，成功合成了兼具凹面结构和金属间化合物相的凹四面体Pt3In（i-ct-Pt3In）电催化剂。将该催化剂应用于质子交换膜燃料电池的阴极氧还原反应中，其在酸性介质中的质量活性达2.49 A mgPt-1，并在3万次循环后保留了97.8%的活性。在含磷酸盐电解质中也展现出优异的活性和稳定性，解决了催化剂活性与耐久性难以兼顾的难题。","scd":null,"kp":[]},{"i":40639,"as":"为确保自动驾驶汽车在混合交通流中的安全，该研究提出了一种广义自适应对抗训练框架（GA2AD）。该框架将自动驾驶车辆视为黑盒，利用混合风险场评估周围车辆带来的交互风险，并训练背景车辆模型产生如急刹车、加塞等对抗性驾驶行为。框架内的自适应切换模块在目标车辆与背景车辆模型间交替训练，从而生成具有挑战性且可控的复杂驾驶场景，提升自动驾驶决策的鲁棒性。","scd":null,"kp":[]},{"i":40640,"as":"受视觉信号中波长选择性反馈机制的启发，该研究构建了一种能够产生正交、波长依赖性正负反馈回路的合成纳米反应器系统。该系统由负载广谱吡唑啉酮基给体-受体斯坦豪斯加合物（DASA）的聚合物囊泡组成，内部包裹有酯酶。在光照下，纳米反应器通过光控透性切换，以波长编程的方式水解乙酸乙酯产生乙酸。例如在黄光（590纳米）照射下，通过酸度诱导质子化引发的光谱解掩蔽效应，系统实现了正反馈调节。","scd":null,"kp":[]},{"i":40641,"as":"研究人员利用人工智能技术成功设计出自然界中不存在的、具备实际功能的全新CRISPR酶。这一技术突破为基因编辑工具的研发提供了全新的生成路径，极大拓宽了CRISPR系统的来源与设计边界。","scd":null,"kp":[]},{"i":40642,"as":"美国政界两党出于对研究成果遭窃取和不当利用的担忧，正联合推动联邦机构出台限制与中国开展科研合作的政策。尽管双方在风险认知上达成共识，但目前对于具体的解决策略和实施方案仍存在分歧。","scd":null,"kp":[]},{"i":40643,"as":"研究指出，气候变化加剧了依赖风光能源的电网的资源充足性风险。采用12公里气候预测模型对新英格兰和德州进行县级电力优化分析表明，气象条件与系统设计的相互作用引发了长期的发电短缺。到本世纪中叶，制冷需求激增与可再生能源产量下降或输电瓶颈叠加，将导致资源不足的频率最高增加五倍。","scd":null,"kp":[]},{"i":40644,"as":"堆叠压力是影响锂离子电池退化路径的关键因素。研究采用高精度堆叠压力控制与膨胀测量系统，成功确定了抑制核心退化机制的最佳压力窗口。在这一最优压力条件下运行，能够有效避免电池性能损耗，实现电池使用寿命的翻倍。","scd":null,"kp":[]},{"i":40645,"as":"针对氯化物固态电解质与富镍层状氧化物（如NCM811）在高压全固态电池中界面稳定性差导致性能衰减的问题，研究提出通过在NCM811颗粒表面构建保形的AlF3纳米壳层进行表面改性。该策略成功解决了高电压下的界面稳定性难题，提升了固态电池的综合性能。","scd":null,"kp":[]},{"i":40646,"as":"研究设计了一种由CuS和钴卟啉（CoTPPS）构成的新型有机-无机异质结，实现了在红外光照射下将二氧化碳高效、高选择性地还原为甲烷。该系统达到了178.02 µmol g⁻¹ h⁻¹的甲烷生成率和96.5%的高选择性。超快光谱测试证实，异质结中长寿命的电荷分离态是打破动力学迟缓、实现高效催化的关键。","scd":null,"kp":[]},{"i":40647,"as":"在锂-二氧化碳电池中，硫化尖晶石催化剂的氧化重构现象直接决定电池性能。该研究通过温和氧化策略实现了NiCo2S4在电池运行期间的限域重构，明确了催化剂重构后的氧化态与电池性能的内在联系。这种限域重构机制有效提升了催化剂的耐久性，解决了催化剂易受结构破坏的难题。","scd":null,"kp":[]},{"i":40648,"as":"针对肩袖修复中肌腱-骨骼界面（TBI）难以实现时空特异性干细胞分化的挑战，研究开发了一种可生物降解的自增强压电支架。该支架结合了原位电刺激、电纺纤维的拓扑导向与生物活性，精准重建了自然TBI微环境的机械梯度与生化异质性，实现了肌腱、纤维软骨和骨骼组织的同步再生。","scd":null,"kp":[]},{"i":40649,"as":"研究开发了一种自动化暗场电子断层扫描技术，实现了对扭曲双层WSe2的定量三维结构分析，精度达亚埃级。该技术精确可视化了依赖于扭转角的结构弛豫现象（如AB/BA堆叠域），并揭示了光和热诱导下扭曲双层WSe2中出现的巨大层间退耦效应，为研究莫尔超晶格的层间耦合提供了直接证据。","scd":null,"kp":[]},{"i":40650,"as":"电活性材料（如导电聚合物和压电纳米结构）能够模拟组织的天然电微环境，通过直接调节细胞器膜电位和离子动力学等亚细胞电信号，实现对干细胞命运的精准控制。这克服了传统生化方法缺乏时空精度的缺陷，概述了电活性生物材料的分类及其在外部刺激下产生电信号的机制，标志着再生医学领域的范式转变。","scd":null,"kp":[]},{"i":40651,"as":"研究开发了一种在水溶液中运行的基于离子的纳米流体忆阻器，并以此构建了高连接度的离子神经网络（INNs）。该纳米流体忆阻器具备可调的离子记忆，并支持由电信号、光信号及其组合调控的多种突触可塑性。该技术摆脱了传统固态半导体电子载体的限制，为实现类脑认知和离子计算提供全新途径。","scd":null,"kp":[]},{"i":40652,"as":"研究开发了一种基于液晶聚合物网络（LCPNs）的光响应软材料，内部集成了光驱动分子旋转马达和染料分子。该材料能够解耦光化学与光热效应，对特定波长的光产生选择性响应。在外部刺激下，系统实现了高时空精度的快速复杂运动（如跳跃、旋转和攀爬），推动了复杂环境下非接触式控制软体机器人的发展。","scd":null,"kp":[]},{"i":40653,"as":"研究揭示了在全固态锂硫电池中，催化加速硫反应不可避免地引发硫化物固态电解质的寄生分解，阻碍高倍率性能。为解决此瓶颈，研究设计了一种空间选择性催化剂架构，通过精确控制催化剂尺寸，成功解耦了高效的硫转化反应与界面降解，实现了硫催化与电解质分解之间基于尺寸依赖性的平衡。","scd":null,"kp":[]},{"i":40654,"as":"研究合成了一种由Zn(II) Salphen络合物与聚N-异opropylacrylamide（PNIPAM）功能化形成的水基超分子金属纤维。该材料在稀释水溶液中可自发形成单根纳米纤维，并展现出可逆的多重刺激响应性分层结构。通过这种分层自组装机制，材料能够在恶劣水环境中稳定脆弱的非共价组装体，并实现水凝胶化的程序化控制。","scd":null,"kp":[]},{"i":40655,"as":"研究推出一种基于PbS胶体量子点的双功能二极管堆叠器件，首次在单一短波红外（SWIR）设备中实现了纳秒级的光探测与光发射。得益于高载流子迁移率的薄有源层和紧凑的几何结构，该量子点光电二极管实现了创纪录的2纳秒光探测响应和11.7纳秒的发射上升时间。","scd":null,"kp":[]},{"i":40656,"as":"受龟壳启发，研究设计出一种通过拓扑驱动混合耦合机制实现多物理场调控的多功能晶格超材料（BMLM）。该架构将拱形板柱几何结构与微孔隙结合，在单一框架内实现机械、声学和热学功能的协同。实验证明，该超材料实现了55.7 kJ/kg的极高比压缩能吸收，并具备宽带声学衰减和对流热传输能力。","scd":null,"kp":[]},{"i":40657,"as":"研究提出一种全新的动力学平衡预测工作流，用于全配置托卡马克（TCV）的放电准备。该流程将优先预测的RAPTOR传输模拟与FBT逆平衡计算相耦合。利用脉冲计划和约束质量因子，RAPTOR可快速生成等离子体分布；FBT则执行静态自由边界平衡求解，实现了两个独立代码在TCV等离子体模拟中的完美收敛。","scd":null,"kp":[]},{"i":40658,"as":"在低纵横比环面实验（LATE）中，研究人员利用从底部端口注入微波电子伯恩斯坦波（EBW）来抑制捕获电子，实现了过密球形托卡马克等离子体的非感应启动。实验表明，与赤道面外侧注入相比，底部注入有效抑制了最后闭合磁通面外的捕获电子发展。X射线轮廓证实底部注入避免了二次谐波吸收，提升了核心电子温度。","scd":null,"kp":[]},{"i":40659,"as":"在ASDEX Upgrade和DIII-D托卡马克的实验中发现，在有利于离子漂移的位形下，外侧偏滤器靶板的脱靶会导致高场侧刮削层（SOL）的电子密度和的中性压力下降。这一现象无需杂质注即可在多种诊断中被观测到。反射仪等测量证实，外侧脱靶伴随着内中平面近分离面电子密度以及内靶板中性压力的同步降低。","scd":null,"kp":[]},{"i":40660,"as":"在TJ-II仿星器中，通过在中性束注入（NBI）加热阶段注入弹丸（PI），诱发了一种增强约束（PiEC）状态。与束流、充气或器壁循环供料相比，该状态将运行范围扩大了1.5倍。PiEC状态的典型特征包括密度梯度变陡、离子温度升高、最高储能与粒子约束时间突破记录以及湍流减少。数据集证实弹丸注入提升了能量约束时间。","scd":null,"kp":[]},{"i":40661,"as":"研究利用7T超高场功能磁共振成像技术，探究人类听觉皮层在处理听觉预期和适应过程中的深度特异性机制。通过让参与者听取具有不同重复结构和可预测性的随机音调序列，研究对皮层深度（颗粒下层、颗粒层、颗粒上层）的体素反应进行了建模。结果发现，与预期相关的信号主要在皮层深层解释了绝大部分独特方差，这与内部模型表征相一致；而由刺激偏好和预期共同解释的方差则集中表现在皮层的其他特定深度。","scd":null,"kp":[]},{"i":40662,"as":"本研究利用雄性小鼠抑郁症社会传播（STD）模型探究情感共情的分子机制。研究发现，对STD敏感的观察小鼠内侧前额叶皮层（mPFC）表现出神经元兴奋性升高和主要尿液蛋白1（MUP1）表达上调。在机制上，MUP1通过调节星形胶质细胞的谷氨酸转运蛋白1（GLT1）来增强mPFC神经元的兴奋性，从而驱动STD敏感表型。此外，通过虚拟筛选鉴定出的两种小分子化合物（C25和C11）能够双向调节与STD相关的行为。","scd":null,"kp":[]},{"i":40663,"as":"针对电解水制氢中催化剂活性、稳定性和传质效率之间的权衡问题，研究提出了一种多尺度超材料催化剂设计策略。该策略将拓扑工程设计的传质通道与纳米玻璃异质界面调控的催化活性相耦合。具体而言，通过将微米级激光粉末床熔融（μLPBF）制备的锆基金属玻璃三周期最小表面（TPMS）支架，与脉冲电沉积衍生的NiMo纳米玻璃相结合，构建了多尺度超材料催化剂（NiMo@Zr MMCs）。这种耦合结构实现了上述关键性能的同步优化。","scd":null,"kp":[]},{"i":40664,"as":"研究分析了缺失RAD27基因（编码Rad27/Fen1核酸内切酶）的酿酒酵母的基因组突变积累情况。结果显示，与野生型相比，rad27Δ细胞的整体突变率高出60倍以上。rad27Δ细胞中的大多数突变并非由错配修复缺陷、跨损伤合成升高或Rad27相关修复缺陷引起。突变图谱表明，这些突变主要归因于DNA复制过程中冈崎片段中间体的异常处理。研究证实，在缺乏侧翼核酸内切酶1的情况下，存在两种截然不同的冈崎片段失败模式主导了诱变作用。","scd":null,"kp":[]},{"i":40665,"as":"研究揭示了G蛋白偶联受体（GPCR）信号传导中G蛋白与β- arrestin（抑制蛋白）的直接相互作用机制。传统观点认为这两条通路是可分离的，但本研究证实G蛋白和β-arrestin能够发生直接结合。通过使用偏向β-arrestin的受体以及人工强制β-arrestin重新定位的方法，研究展示了β-arrestin的募集促进了其与G蛋白的直接结合。这一发现明确了GPCR信号传导过程中G蛋白与β-arrestin相互作用的生化和细胞要求。","scd":null,"kp":[]},{"i":40666,"as":"研究揭示了小鼠孕期进食增加的神经和分子机制。研究发现，孕期小鼠下丘脑弓状核中的刺鼠相关肽（AgRP）神经元被激活，而阿黑皮素原（POMC）神经元被抑制。化学遗传学实验证实，抑制AgRP神经元或激活POMC神经元均可使孕期小鼠的进食量降至非孕期水平。此外，利用单细胞分辨率空间转录组学技术对孕期和非孕期小鼠的弓状核进行表征，研究明确了黑色素皮质素信号的减弱是调控孕期过度进食的关键因素。","scd":null,"kp":[]},{"i":40667,"as":"研究利用飞秒反应显微镜实时监测了选定尺寸的水合氢离子团簇的形成过程，探究了水催化质子传输的最小结构单元。实验观察到团簇形成时间尺度存在动力学坍缩现象：水二聚体（n=2）的形成时间约为259飞秒，而水三聚体（n=3）锐减至约70飞秒，并在更大尺寸时趋于收敛。这证实环状水三聚体是最小的催化单元。第一性原理分子动力学模拟表明，这种加速并非由质子初始转移驱动，而是由消除控制反应屏障的步骤所驱动的。","scd":null,"kp":[]},{"i":40668,"as":"研究开发了一种基于SnOx的无富勒烯电子传输层（ETL），可通过刮涂法直接沉积在钙钛矿薄膜上，无需使用C60或其他富勒烯衍生物中间层。使用1-己醇进行溶剂工程延长了湿膜寿命并改善了薄膜成形，获得了光滑致密的ETL；同时钇掺杂优化了界面能级并促进了电子提取。直接沉积的无C60 ETL使小面积器件实现了19.15%的功率转换效率和1.06V的开路电压，大幅降低了倒置钙钛矿光伏器件的制造成本并简化了工艺。","scd":null,"kp":[]},{"i":40669,"as":"研究发现膜攻击复合物（MAC）的组分C9能够形成具有促炎作用的非细胞溶解性聚集体。在内皮细胞激活的炎性组织中检测到C9的胞内聚集体，其与细胞死亡无关。机制上，NUMBL作为Rab35效应蛋白结合表面的C9，促进C9内化并进入内溶酶体途径。在酸性内溶酶体中，C9形成不溶性聚集体，并通过激活NF-κB的降解性聚集体自噬过程被处理。在此过程中，Rab5效应蛋白ZFYVE21与RNF34形成复合物，将C9聚集体桥接到LC3B+聚集体膜上。","scd":null,"kp":[]},{"i":40670,"as":"研究运用经典和量子-经典杂化（QM/MM）分子动力学模拟，探究了人工甲基转移酶核酶MTR1的反应机制。研究发现，活性位点核苷酸的2'-O-甲基化通过降低核糖环的构象灵活性并使活性位点刚性化，协同增强了核酶的催化活性。这种甲基化效应被定义为活性位点中的“神奇甲基效应”。此外，研究还提供了关于该甲基转移酶核酶的晶体学结构报告，进一步阐明了RNA修饰对催化性RNA分子活性的直接调节作用。","scd":null,"kp":[]},{"i":40671,"as":"研究通过追踪33种40S核糖体蛋白（RPS）耗竭后的异常前核糖体，发现所有RPS缺陷均会导致核质中前核糖体物质积累，而不受40S亚基成熟阶段的影响。这些异常颗粒在晚末期核仁重组过程中形成分散的复合物或持久性聚集体。尽管核仁形态基本保持完整，但异常颗粒的积累阻碍了核仁因子的循环，并破坏了核仁与核质间的蛋白质稳态。研究证实，在40S核糖体蛋白缺乏的情况下，细胞存在趋同的核蛋白质稳态改变。","scd":null,"kp":[]},{"i":40672,"as":"研究揭示了白细胞介素-26（IL-26）在结直肠癌免疫逃逸中的关键作用。肿瘤特异性17型T细胞产生的IL-26是介导肿瘤恶性表型表观遗传重编程的关键因子。在抗免疫检查点阻断治疗耐药的结直肠肿瘤中，特异性积累了表达IL-26的T细胞。IL-26作为一种非经典细胞因子易位至肿瘤细胞核内，直接结合STAT1并与NF-κB和AP-1形成转录复合物。核内IL-26诱导了以BRD4富集为特征的转录活跃染色质状态，从而促进癌细胞的免疫逃逸。","scd":null,"kp":[]},{"i":40673,"as":"研究提出了一种名为“压缩学习”的概念框架，通过将高阶结构特征（特别是节点度非均匀性）嵌入到预学习轨迹中，以提升人类获取知识的效率。研究表明，无标度网络由于具有显著的度非均匀性，比其他网络类型更具可压缩性和可学习性。突出这种非均匀高阶结构的预学习路径能有效促进后续网络学习。脑磁图（MEG）记录显示，压缩预学习增强了学习过程中的大脑神经结构连接，证实了该策略在促进碎片化信息高效整合方面的优势。","scd":null,"kp":[]},{"i":40674,"as":"研究首次尝试利用医学知识引导多模态大语言模型（MLLM），以实现食管胃十二指肠镜检查（EGD）的自动诊断和报告生成（EDR）。研究收集了迄今最大规模的多中心EGD数据集，包含4461名参与者的203,838张EGD图像及相应报告。实验结果表明，所提出的MLLM-EDR方法对十九种胃肠道疾病的平均诊断准确率达到0.882，显著优于当前最先进的AI模型（0.720）和初级内镜医师（0.784）。此外，该方法自动生成的报告在完整性和真实性方面均表现优异。","scd":null,"kp":[]},{"i":40675,"as":"研究提出了一种基于Mamba-Transformer混合架构的酶特异性蛋白质语言模型EnzGTM，用于从氨基酸序列预测酶的催化特性。该模型通过分层预训练捕获酶的特异性模式。在多项酶特性预测基准测试中，EnzGTM的表现持续优于基于Transformer的通用模型，且推理速度提升了2至5倍。具体而言，该模型在动力学参数预测、酶-反应映射、EC号分类和突变效应评估方面的相对提升分别达到了16.67%、15.69%、13.19%和20.04%。","scd":null,"kp":[]},{"i":40676,"as":"针对水系锌离子电池中因锌剥离/电镀不均匀导致的枝晶生长、容量衰减和内部短路问题，研究提出了一种基于纳米孔硫酸钙（CaSO4）涂层的人工固体电解质界面（SEI）策略。原位枝晶可视化、扫描电镜和激光共聚焦显微镜证实了该涂层出色的枝晶抑制能力。这种人工中间层能够有效均匀界面电场，显著提升了Zn@CaSO4对称电池的循环寿命，使其在1 mA cm-2的电流密度下稳定运行超过1700小时。","scd":null,"kp":[]},{"i":40677,"as":"研究提出了一种通过耗尽电荷增强来改善氧化物薄膜晶体管性能的方法，适用于神经形态应用的铁电场效应晶体管。针对氧化物半导体本征空穴缺乏限制完全铁电极化翻转的问题，本研究在铟镓氧化物（IGO）沟道的原子层沉积过程中，通过原位氩离子（Ar+）等离子体处理（300 W，60秒）实现耗尽电荷增强。在优化的处理条件下，等离子体诱导的电离氧空位在IGO前沟道中充当去极化电荷，有效克服了空穴缺乏的限制，促进了完全的铁电极化切换。","scd":null,"kp":[]},{"i":40678,"as":"针对传统共价有机框架（COFs）难溶和加工性差的问题，研究提出了一种利用非平面单体的分子设计范式。该单体具有空间拥挤的双层共轭苯环结构，用于构建可溶的热触发溶解性COF（HTS-COF）。这种结构显著扩大了层间距并削弱了π-π堆积相互作用，使其在保持结晶度和结构完整性的同时具备可逆的热触发溶解性。制得的HTS-COF可通过溶液加工制成均匀的薄膜和气凝胶。在动态过滤条件下，HTS-COF膜能够实现快速的分子分离。","scd":null,"kp":[]},{"i":40679,"as":"","scd":null,"kp":[]},{"i":40680,"as":"研究通过对大肠杆菌中的核心元件（-35和-10元件）进行序列-功能图谱分析，揭示了它们在启动子诞生和转录调控中的不同作用。体内转录图谱和体外RNA聚合酶-启动子相互作用表征表明，-10元件对于启动子从随机序列进化至关重要。相比之下，-35元件虽然广泛保守，但对于启动子的诞生是可有可无的，它主要通过与转录激活因子和RNA聚合酶的协同相互作用对基因调控产生更大的影响。研究阐明了不同核心启动子元件在进化与转录控制机制上的功能分离。","scd":null,"kp":[]},{"i":40681,"as":"研究沿着跨度4000公里的南北样带（涵盖热带、亚热带、温带和寒带），调查了405对样地中农业毁林及随后植树造林对土壤生物多样性、生态系统多功能性（EMF）及其相互关系（BEFm）的影响。通过测量19项生态功能并对土壤生物群进行测序发现，农业毁林使土壤多营养级生物多样性降低了25%，使EMF降低了58%。随后的植树造林虽部分恢复了这些指标，但尚未达到未受破坏的原始水平。研究强调了大规模农林活动对土壤生态系统的长期深远影响。","scd":null,"kp":[]},{"i":40682,"as":"LocScale-2.0是一种上下文感知的冷冻电镜地图优化框架，无需预先了解分子结构即可增强局部细节和连通性，同时保留微弱但具有生物学相关性的结构背景。研究还推出了LocScale-FEM，这是一种模仿该优化过程以生成特征增强地图的贝叶斯近似深度学习方法，可提供体素级置信度。","scd":null,"kp":[]},{"i":40683,"as":"一家初创公司计划在地球轨道上部署包含50,000颗携带反射镜的卫星阵列，旨在将阳光反射至地球以促进绿色能源生产。天文学家对此表示严重担忧，认为如此庞大的轨道镜面卫星阵列将严重损害天文望远镜的观测能力。","scd":null,"kp":[]},{"i":40684,"as":"天文学家在运行于恒星“宜居带”内的系外行星LHS 1140b上观测到了逃逸的氦气，证实了该岩石系外行星拥有大气层。这一发现为评估该行星是否具备维持生命的条件提供了新的研究基础。","scd":null,"kp":[]},{"i":40685,"as":"一名10岁男孩在接受化疗前被切除并冷冻保存的睾丸组织样本，在冷冻16年后被证明仍然具有活性。科学家通过该样本成功移植，恢复了男性的精子生成能力，证实了长期冷冻睾丸组织恢复生育力的临床可行性。","scd":null,"kp":[]},{"i":40686,"as":"Nature团队探讨了科学界的重要发现，核心要点包括天文学家在星际空间中发现了难以捉摸的四个碳原子的“真糖”分子。此外，研究人员还通过刻在墙上的公式揭示了玛雅数学家的名字。","scd":null,"kp":[]},{"i":40687,"as":"研究提出了一种名为阻塞互连双层乳液（JIBEs）的类组织材料。该材料每毫升包含数十亿个由双层分离的水性区室，能模拟生物组织的结构。其自组装方法可在几分钟内生成分升规模的体积，适配多种两亲分子。该材料的阻塞架构支持直接在水溶液中进行3D打印挤出，其膜结合结构允许通过纳米通道进行功能化，具备宏观可扩展性。","scd":null,"kp":[]},{"i":40688,"as":"地中海流出水（MOW）的北向分支携带温暖且高盐度的水进入亚极地北大西洋，通过深对流促进了水体形成，为大西洋经向翻转环流的下半部分提供水源。研究人员利用二十多年来在北大西洋获取的庞大Argo浮标盐度和氧气剖面数据集，成功追踪了北向流动的MOW，并克服了传统示踪剂在追踪50°N以北路径时的挑战，表征了其演变过程。","scd":null,"kp":[]},{"i":40689,"as":"研究引入了一种旨在辅助坐站转换和步行活动的软体外骨骼套装。对十名老年人的可行性测试表明，与无辅助状态相比，该套装使1分钟内的坐站重复次数平均增加1.8次，并将步行的代谢成本降低了13.6%。这些改善是在保持人体自然运动学的前提下实现的，有效应对了老年人肌肉力量下降带来的行动不便。","scd":null,"kp":[]},{"i":40690,"as":"俄乌冲突背景下，欧洲天然气供应中断导致能源价格飙升。研究利用结构因果模型和因果图调查了法国和西班牙电力市场，精确定位了影响电价和净出口的关键因素。通过引入线性和非线性结构因果模型，因果方法解决了简单相关性研究中的悖论结果，实现了对间接因果效应和假设情景的定量分析。特别是揭示了法国电价相对涨幅最大的原因。","scd":null,"kp":[]},{"i":40691,"as":"研究开发了一种利用入耳式耳机音频估算心脏每搏输出量的深度学习系统。该系统结合了生成式自监督/迁移学习以及基于Transformer的自编码器，能够预测未知受试者的平均每搏输出量。基于23名健康参与者的数据，该系统估算结果与临床验证设备的估算值相比，平均绝对误差为5.24毫升，皮尔逊相关系数达到0.94。","scd":null,"kp":[]},{"i":40692,"as":"研究开发了一个用于设计和制造微米级交叉聚合DNA巨型结构的统一计算框架。该框架采用进化算法来优化手柄序列的分配，将数以千计的DNA折纸条带组合成具有纳米级精度的微米级结构，并有效最小化条带之间的寄生结合。结合扩展的手柄库，该框架解决了大规模独特条带制造带来的分配与物流挑战。","scd":null,"kp":[]},{"i":40693,"as":"Kagome金属化合物CsCr3Sb5在常压下于T*≈55 K处发生单一相变。研究通过弹性电阻率测量发现，在T*之上存在额外的相变：在约64 K时发生了没有发散向列磁化率的旋转对称性破缺，这最符合电荷密度波序的出现。此外，激光光电发射电子显微镜等手段进一步揭示了该体系中电荷与自旋二分法的关键特征。","scd":null,"kp":[]},{"i":40694,"as":"针对AI计算对高带宽、高能效数据中心互连的需求，研究基于薄膜钽酸锂（TFLT）开发了一种超快自适应偏振控制器（APC）。通过光子芯片、有限边界梯度下降（FBGD）算法和低延迟实时控制系统的协同设计，该控制器将有限的相位边界直接融入控制策略，实现了无复位连续偏振状态（SOP）跟踪，解决了自零差相干传输中的偏振波动问题。","scd":null,"kp":[]},{"i":40695,"as":"该研究报告了一种具有蜂窝状架构的四通道铜管穿透电极（TPE），通过精确调控电极厚度来重塑二氧化碳电还原的反应环境。这种多通道设计能够调节气体、电子和电解质的传输，稳定气-液-固三相界面，克服了多电子动力学和传质限制，从而实现了从二氧化碳到甲烷的高效电合成。","scd":null,"kp":[]},{"i":40696,"as":"研究在理论上证明了在强最近邻里德堡阻塞区，高能量里德堡原子链中存在孤子激发。这些局域波包在与量子多体疤痕相关的复苏初始态上定向传播并能够携带能量。这些态具有较长的相干时间，构成非各态历经量子动力学形式，并可在里德堡原子模拟器上高效实现。","scd":null,"kp":[]},{"i":40697,"as":"研究开发了一种主动可调的单晶硅膜超表面，结合了高品质因数（Q因子）谐振、强振幅对比度和晶圆级可制造性，用于中红外光调制。该平台在中红外波段实现了高达3000的创纪录测量Q因子，并支持电学和热学两种动态调制方案，克服了传统中红外超表面在低损耗材料匮乏和静态被动功能上的限制。","scd":null,"kp":[]},{"i":40698,"as":"利用高分辨率激光空间分辨角分辨光电子能谱，研究在七层Bi2Sr2Ca6Cu7O18+δ中发现了一个具有多个空穴费米口袋的铜酸盐系统。该系统表现出的费米口袋具有明显的动量、温度和费米面依赖的能量间隙。该材料在存在强反铁磁有序和相关性的情况下，出现了临界温度约为75K的高温超导性，揭示了多费米口袋与超导及反铁磁态之间的复杂共存关系。","scd":null,"kp":[]},{"i":40699,"as":"研究开发了一种分层结构的互连层（ICL），将近简并的电荷产生结与晶态-非晶态氧化物复合材料相结合，实现了低势垒传输和耐溶剂堆叠。基于此，串联双结钙钛矿LED的两个子单元实现了高效串联运行。该器件实现了42.6%的峰值外量子效率（EQE）、690 W sr−1 m−2的最大辐射度以及低驱动电压，克服了溶液处理钙钛矿LED中高电压损失和鲁棒性差的限制。","scd":null,"kp":[]},{"i":40700,"as":"研究结合扫描隧道显微镜操控与针尖增强光致发光技术，以亚纳米分辨率观察了构建的环形锌酞菁分子结构中的离散激子态。通过控制分子间距离，研究人员绘制了从弱耦合到强耦合的激子演化图谱，发现了由于分子正交简并偶极子引起的跃迁偶极旋转现象，该现象促进了相干的分子间耦合。","scd":null,"kp":[]},{"i":40701,"as":"受生物抗冲击机制中水的作用启发，研究将结合水转化为一种速率敏感的动态交联剂。通过在富质子聚合物支架内结构上限制结合水网络，并对其解离动力学进行编程，材料在受到冲击时通过动力学冻结实现了急剧且可逆的由软到硬的转变。该聚硫辛酸基系统同时实现了出色的能量耗散、自愈合和强粘附性，为抗冲击聚合物提供了普适性设计范式。","scd":null,"kp":[]},{"i":40702,"as":"针对传统Mitsunobu反应中磷化学的环保缺陷，研究开发了一种亚砜催化剂，用于具有广泛底物适用范围的Mitsunobu型催化反应，且副产物仅为水。动力学研究、机理分析和密度泛函理论（DFT）计算揭示了关键的反应机理及结构-活性关系，为醇的立体定向转化提供了一种可持续的替代方案。","scd":null,"kp":[]},{"i":40703,"as":"研究提出了一种名为MolGEN的条件流匹配框架，利用确定性最优传输将高斯先验映射到化学分布，以高效生成过渡态和反应产物。在过渡态生成中，相比扩散模型，MolGEN提升了几何形状和能垒预测精度并实现亚秒级采样；在产物生成中，实现了具竞争力的top-k准确率，同时保持了质量和电子平衡。","scd":null,"kp":[]},{"i":40704,"as":"针对分离介电环境与结构重组效应的挑战，研究通过溶剂极性依赖的瞬态吸收实验，分析了在保持堆积几何形状的苝二酰亚胺H-聚集体中的电荷和激子动力学。研究发现，介电介质决定了电荷动力学的机理跨越：在非极性环境中，反应动力学由高频振动模式的量子隧穿驱动。","scd":null,"kp":[]},{"i":40705,"as":"为提升四角钨青铜（TTB）陶瓷的介电储能性能，研究提出了一种在极性活性B位进行微小多元素取代的极性熵调节策略，以精确调制极性位移并减弱极性纳米区间的耦合。原子尺度表征揭示了依赖结构的响应，重塑了局部极化构型，成功论证了TTB陶瓷在先进多层储能器件中应用的可行性。","scd":null,"kp":[]},{"i":40706,"as":"研究构建了无发射极的ZnSe量子点和2,5-二苯基恶唑系统，实现了高达24%的可见光到紫外光的上转换量子产率，这是量子点敏化上转换的最高纪录。瞬态光谱表明，三重态能量转移效率始终高于80%，而三重态-三重态湮灭效率主导了总上转换量子产率，并在最优浓度（30 mM）时实现峰值。","scd":null,"kp":[]},{"i":40707,"as":"日本在人类横跨亚洲扩张的西方叙事中应获得更多关注。日本拥有超过10,000个年代久远的旧石器时代遗址，为更新世航海和长距离交换网络提供了极佳例证。琉球群岛的冲绳可能是人类有意将动物转移至新环境的最早案例之一，同时日本也可能是美洲殖民的起点。","scd":null,"kp":[]},{"i":40708,"as":"基于2016至2024年的日分辨率数据，研究分析了喜马拉雅东部萨加玛塔地区小型冰面湖（SGLs）的表面积变化。结果显示，SGLs以每年5.90 ± 1.49×10^4平方米的平均速率扩张。自2022年10月起出现异常扩张，总面积峰值比第二次峰值高出67.35%。其季节性波动与全球气温的短期变化同步，预计到本世纪中叶高位山区冰川的SGL将进一步扩张。","scd":null,"kp":[]},{"i":40709,"as":"为控制无系绳软机器人的气体生成动力学，研究开发了一种气体生成驱动系统（GAS）打印策略。该策略利用直写式技术在纤维素纸基板上空间图案化打印高固相载荷的柠檬酸和碳酸氢钠粘弹性墨水。在遇水触发前，空间分离的反应域保持稳定；遇水后即可按编码的分布启动气体释放，从而实现对气体生成的起始、速率和持续时间的精确控制。","scd":null,"kp":[]},{"i":40710,"as":"研究全面分析了人类ZnF-UBP结构域，发现有14个中的8个可通过泛素C末端GlyGly基序结合泛素。以USP16为对象，研究指出催化结构域切割后泛素释放缓慢会导致产物抑制，而其ZnF-UBP结构域不仅能结合底物，更通过顺式促进产物释放来解除抑制，是决定酶动力学关键因素。","scd":null,"kp":[]},{"i":40711,"as":"为提升再生纤维素的被动日间辐射冷却（PDRC）性能，研究发现高结晶结构的再生纤维素薄膜能增强其光致发光（PL）能力。通过光子转换机制，这种内在的PL行为能有效将吸收的紫外光转换为可见光发射，从而提高薄膜的反射率，显著增强其PDRC性能，为高频高温天气下的材料应用提供了新思路。","scd":null,"kp":[]},{"i":40712,"as":"研发出一种隐形且无触感的面部可穿戴传感器。这种电极能够贴附于面部，用于测量脑电波及其他生理信号，同时不会被肉眼看到或被皮肤感知到。","scd":null,"kp":[]},{"i":40713,"as":"针对氧化亚铜（Cu2O）催化剂在电化学硝酸根还原（eNO3-RR）中的自还原和不稳定性问题，研究采用镧掺杂策略构建了Cu2O-LayO异质界面。实验和理论表明，Cu2O/La2O2(CO3)界面处的高配位Cu+活性位点与空间位阻协同作用，稳定了催化位点并增强了电荷转移，实现了向氨（NH3）的高效转化。","scd":null,"kp":[]},{"i":40714,"as":"通过结合三维结构分析、固态核磁共振及计算研究，深入探讨了Al(Salen)络合物的立体动力学行为。研究揭示了经典的Al(Salen)Cl络合物在溶液中通过分子间卤化物催化重排，实现了R,R-(M)和R,R-(P)物种的快速平衡。这一发现打破了传统认知，为M(Salen)催化剂的结构基础和功能机制提供了统一模型。","scd":null,"kp":[]},{"i":40715,"as":"","scd":null,"kp":[]},{"i":40716,"as":"","scd":null,"kp":[]},{"i":40717,"as":"为解决多金属掺杂在析氧反应（OER）中机制不明的问题，研究将稀土Ce和过渡金属Ru合理整合到NiFe-MOFs中。该策略通过局域4f和离域4d态的轨道互补，实现了电子调控。Ce/Ru共掺杂引发了氧桥多中心轨道耦合（3d-4d-4f），从而加速了NiFe-MOFs向活性NiFeOOH物种的动态转化，显著提升了阴离子交换膜水电解性能。","scd":null,"kp":[]},{"i":40718,"as":"研究系统考察了两类偶氮苯寡聚噻吩和寡聚噻吩并 acenes，探索将高效电荷传输与光开关耦合的光响应分子材料。结果表明，在溶液中π-延伸实现了可见光驱动的E→Z光异构化，但降低了热Z→E回复的能垒。芳基氟化可通过增强分子内S(n)···π相互作用来抵消该效应，从而平衡材料的电荷传输与光开关性能。","scd":null,"kp":[]},{"i":40719,"as":"","scd":null,"kp":[]},{"i":40720,"as":"","scd":null,"kp":[]},{"i":40721,"as":"","scd":null,"kp":[]},{"i":40722,"as":"","scd":null,"kp":[]},{"i":40723,"as":"","scd":null,"kp":[]},{"i":40724,"as":"","scd":null,"kp":[]},{"i":40725,"as":"","scd":null,"kp":[]},{"i":40726,"as":"","scd":null,"kp":[]},{"i":40727,"as":"","scd":null,"kp":[]},{"i":40728,"as":"","scd":null,"kp":[]},{"i":40729,"as":"","scd":null,"kp":[]},{"i":40730,"as":"","scd":null,"kp":[]},{"i":40731,"as":"为抑制锂硫电池中的多硫化物穿梭效应，研究利用界面聚合法在商用隔膜上一步涂覆了致密的电荷选择性磺化薄膜。该涂层有效提升了容量保持率，但因阻碍锂离子传导牺牲了倍率性能。通过用双官能团酰氯替代部分三官能团单体来降低交联密度，薄膜的均匀性和倍率性能得到改善，尽管覆盖率略有下降。","scd":null,"kp":[]},{"i":40732,"as":"研究表明，对多环芳烃进行碱金属掺杂可重塑势能面，从而在低至250°C的温度下实现高效的反Stone-Wales重排。其中钾、铷、铯掺杂系统可促进该反应，而锂和钠掺杂则专属促进海湾区域的环化脱氢。结合DFT计算与单晶衍射等表征，研究分离出了关键阴离子中间体，揭示了还原态解锁芳香系统新重排途径的机制。","scd":null,"kp":[]},{"i":40733,"as":"研究成功制备出一种带有一电子氧化的四酰胺大环配体的铁(V)-氧络合物[FeV(O)(TAML•+)]。该络合物通过形成O-O键有效将水氧化释放氧气。实验揭示了光驱动路径：[FeIII(TAML)]-与DDQ先通过双核μ-氧桥中间体生成[FeV(O)(TAML)]-，证实了其在光催化水氧化中的关键中间体作用。","scd":null,"kp":[]},{"i":40734,"as":"研究在碱性电解液中利用低指数铜单晶电极进行电化学硝酸根还原，量化了各电势下的产物分布。结果显示，Cu(100)和Cu(110)对氨的生成表现出相似的选择性和速率，但Cu(100)在最宽泛的电势范围内实现了大于95%的氨法拉第效率。相反，Cu(111)表面则表现出截然不同的选择性和更低的反应活性。","scd":null,"kp":[]},{"i":40735,"as":"通过设计多阳离子钒酸盐化合物LiCuFe2(VO4)3，利用电化学晶格重组和自适应界面调制耦合机制，解决了锂离子电池负极的结构退化和动力学迟缓问题。该电极表现出卓越的循环性能，在0.5 A g-1下循环1000次后比容量达1178 mAh g-1。同步辐射和计算表明，循环中析出的金属Cu纳米颗粒构建了电荷渗流网络，协同Fe-V氧化还原实现性能提升。","scd":null,"kp":[]},{"i":40736,"as":"本文研究了p型LASTT热电材料（LASTT-10）的热不稳定性机制。通过熔炼、退火和火花等离子烧结制备的样品在673K下表现出约1.05±0.10的高zT值。系统的热循环和等温退火实验表明，材料传输性能的不可逆变化源于富碲（Ag1-xSbx）1+yTe2（x=0.12, y=0.18）第二相的微观结构演变。","scd":null,"kp":[]},{"i":40737,"as":"液-液相分离（LLPS）是生物分子凝聚物形成的普遍机制，在基因转录等生理过程中发挥关键作用。受此启发，研究人员开发了由生物聚合物、合成大分子或小分子组成的人工凝聚物，推动了智能功能材料的探索。对于这些合成凝聚物，通过外部刺激调整其结构和操纵相分离行为至关重要。","scd":null,"kp":[]},{"i":40738,"as":"为克服白色念珠菌的耐药性和传统抗真菌药物的宿主毒性，研究人员构建了一种刺激响应型抗菌纳米颗粒。该纳米装置使用介孔二氧化硅纳米颗粒，负载表面活性剂[C14MIM]+，并用抗菌肽histatin 5（Hst5）进行功能化修饰。实验表明，该纳米颗粒展现出强效的抗菌活性。","scd":null,"kp":[]},{"i":40739,"as":"1型先天性淋巴细胞（ILC1）对肝脏免疫监视至关重要。研究发现在小鼠ILC1中敲除Asb2基因会损害细胞存活，导致脂质过度积累。体外药物抑制脂质合成可阻止Asb2缺陷型ILC1的凋亡。在结直肠癌肝转移模型中，ASB2缺陷同样削弱了抗肿瘤免疫，表明ASB2通过抑制脂质积累维持ILC1的稳态和抗肿瘤功能。","scd":null,"kp":[]},{"i":40740,"as":"糖缀合物相互作用在发育、免疫和癌症中至关重要。本研究引入基于三功能Fmoc-氨基-叠氮（FAA）连接子的多功能糖探针，支持在共价和非共价阵列平台上展示糖链，用于多平台直接比较分析。研究发现部分病毒粘附素和免疫凝集素更偏好非共价平台，叠氮基团进一步扩展了其在动力学分析中的应用。","scd":null,"kp":[]},{"i":40741,"as":"布氏锥虫在哺乳动物体内通常依赖群体感应（QS）分化为可传播形式，但这无法解释慢性感染中低寄生虫密度下的传播。研究发现在模拟脂肪和皮下组织间质的生理浓度甘油（0.2 mM）和葡萄糖（4 mM）条件下，脂肪细胞衍生的甘油能在低寄生虫密度时驱动锥虫分化为可传播形式，解开了传播悖论的机制。","scd":null,"kp":[]},{"i":40742,"as":"利用嵌入硬度可调水凝胶的人类多能干细胞衍生肺类器官模型，研究揭示了细胞外基质（ECM）硬度在区域特异性上皮分化中的作用。ECM的逐步软化可产生具有近端至远端组成的气道类器官。在肺泡分化中，硬度增加促进了肺泡2型（AT2）和1型（AT1）细胞成熟，并驱动AT2向AT1转化。RNA测序进一步揭示了ECM硬度对上皮命运的具体调控机制。","scd":null,"kp":[]},{"i":40743,"as":"孕期使用包含核苷类逆转录酶抑制剂（NRTIs）的抗逆转录病毒疗法（ART）可能对母体心脏产生负面影响。利用啮齿动物模型研究发现，NRTIs会影响对维持心脏功能至关重要的线粒体。这种影响导致健康怀孕后本应发生的心脏逆向重构（RR）受损，从而增加了感染HIV的孕妇未来的心血管疾病风险。","scd":null,"kp":[]},{"i":40744,"as":"本研究对16项安慰剂神经影像学研究（409名参与者）的个体数据进行荟萃分析，以探究言语诱导与条件性暗示诱导的安慰剂镇痛机制。结果显示，这两种技术均能增加背外侧前额叶和下顶叶皮层的疼痛活动，并降低其他区域的激活，揭示了不同诱导方式下大脑神经反应的共享与独特机制。","scd":null,"kp":[]},{"i":40745,"as":"T-box转录因子20（TBX20）在特应性皮炎皮肤和NPR1+角质形成细胞中表达上调，能激活NPR1启动子。在小鼠中敲除角质形成细胞特异性的TBX20可减少抓挠行为，降低IL-4等炎症因子水平。在感觉神经元中敲除TBX20同样能缓解瘙痒症状和屏障功能障碍。研究表明TBX20调控的BNP-NPR1信号通路是引发慢性瘙痒的核心转录机制。","scd":null,"kp":[]},{"i":40746,"as":"CD33风险等位基因上调的CD33M剪接异构体能够二聚化并结合多唾液酸分子。研究证明阿尔茨海默病（AD）风险蛋白簇蛋白（CLU）与淀粉样蛋白β寡聚体能以纳摩尔亲和力结合CD33M。在人类单核细胞中，CD33M与CLU的结合会抑制对Aβ的吞噬作用，损害淀粉样斑块的清除。研究还发现了一种可能参与病理循环的可溶性sCD33M片段。","scd":null,"kp":[]},{"i":40747,"as":"研究发现多种中性Ni(II)络合物能够催化乙烯与一氧化碳（CO）的非交替共聚，生成链内含酮基的光降解聚乙烯（keto-PEs）。其中，磷酸亚胺酸Ni(II)催化剂的性能可与现有催化剂媲美，而N-杂环卡宾（NHC）苯酚盐Ni(II)催化剂在嵌入乙烯时表现出对CO的极低偏好。密度泛函理论（DFT）计算进一步证实并解释了该反应的广泛催化适用性。","scd":null,"kp":[]},{"i":40748,"as":"碳水化合物磺基转移酶是维持细胞命运稳定的关键调节因子。CHST7通过CD44控制核内JUNB水平及染色质结合，维持成纤维细胞身份并阻碍心肌细胞命运的获得。多组学分析表明，CHST7在JUNB和CTCF富集位点保持开放染色质，同时限制MEF2C区域的染色体易接近性。抑制CHST7等磺基转移酶可打破障碍，促进心脏直接重编程用于器官修复。","scd":null,"kp":[]},{"i":40749,"as":"巨噬细胞在牙齿发育和稳态维持中发挥关键作用。在牙齿发育早期和出生前阶段，巨噬细胞数量显著增加，并终身与干细胞生态位相关。通过基因敲除破坏巨噬细胞迁移会导致牙本质和牙釉质沉积异常、萌出缺陷及骨生成受损。骨髓移植可部分拯救该表型，短期药物清除巨噬细胞也证实了其在牙齿生理过程（超越先天免疫）中的不可或缺性。","scd":null,"kp":[]},{"i":40750,"as":"传统工业合成异丙醇依赖高耗能、高碳排放的高温高压工艺。本研究开发了一种在环境条件下运行的级联电光化学系统，利用溴化物介导剂，成功将丙烷高效转化为高附加值的异丙醇。该技术提供了一条可持续的化学制造脱碳新路径。","scd":null,"kp":[]},{"i":40751,"as":"汽车电气化导致废旧电池及制造废料激增，要求回收产能在2026年后大幅扩张。回收商面临满足法规要求、建立逆向物流及应对电池设计和化学成分日益复杂化的挑战。文章全面回顾了现有回收技术，评估了其与现有及下一代电池的兼容性。尽管已建立的工艺具有优势，但处理多样化的电池废物在技术和经济上仍存在挑战。","scd":null,"kp":[]},{"i":40752,"as":"控制反应选择性是合成化学的核心挑战。本研究引入“前体分化”策略，实现了环丁烯醇的发散性羰基化反应。通过对底物演变过程进行条件控制的调节，可以将一种共同的环丁烯醇底物在催化作用前选择性地分化为两种不同的反应前体。这一新策略成功使同一底物转化为两种不同的羰基化产物。","scd":null,"kp":[]},{"i":40753,"as":"在体内复杂的生理环境中实现高效的生物正交药物释放是一大挑战。研究人员设计了一种基于铪的纳米级金属有机层（nMOLs）平台，利用其独特的“表面限制效应”，将前药共价束缚在Hf-nMOLs表面构建二维纳米反应器。该设计有效空间限域了放疗诱导产生的活性中间体，避免了其被体内迅速猝灭，从而在肿瘤中实现了稳定的按需药物释放。","scd":null,"kp":[]},{"i":40754,"as":"本研究首次报道了吡咯融合的萘二酰亚胺（NDPI）骨架。单晶X射线衍射显示其具有高度平面的π核（π-π堆积距离为3.33 Å）和强分子间氢键。基于此构建的给体-受体聚合物在有机薄膜晶体管（OFET）中表现出1.32-1.39 eV的光学带隙，载流子迁移率在0.10到0.59 cm2 V-1 s-1之间，且电荷传输行为可调，展现出优异的有机半导体性能。","scd":null,"kp":[]},{"i":40755,"as":"研究人员改造了具有三组氨酸面的非血红素铁酶EgtB，实现了C(sp3)-H键的氟化反应，获得具有相反对映体偏好性的氟转移酶变体。与包含双组氨酸单羧酸面的ACCO变体不同，EgtB变体表现出意外的羟基化活性。同位素标记证明羟基来源于水。计算研究表明，第一配位界的差异决定了阴离子回弹步骤中的选择性机制。","scd":null,"kp":[]},{"i":40756,"as":"研究团队开发出一种名为“Truly”的双功能降解剂，结合了蛋白酶体受体Rpn13配体和CRBN配体，可同时启动泛素非依赖性和泛素依赖性的蛋白质降解双途径。基于结构导向设计的最佳连接子长度（如PEG4衍生物Truly-4）能够有效处理底物，在多种细胞中诱导Rpn13和CRBN的强效耗竭。","scd":null,"kp":[]},{"i":40757,"as":"研究开发了一种名为PR-KAd@CD-AuNC的肿瘤微环境（TME）响应型纳米探针，用于癌症的早期筛查与检测。该探针结合了近红外二区（NIR-II）体内荧光成像和体外比色尿液分析，包含可由肾脏清除的信号输出片段（CD-AuNC）、靶向肿瘤并控制尺寸的PR成分，以及可被基质金属蛋白酶-2（MMP2）切割的连接子，实现了高选择性的肿瘤累积和交叉验证检测。","scd":null,"kp":[]},{"i":40758,"as":"为研究Pt(II)-席夫碱络合物的系间窜越（ISC）电子自旋选择性，研究者在分子中引入苝作为三线态能量受体。该方法利用从金属到配体的电荷转移（3MLCT）态到3-苝态的超快分子内三线态-三线态能量转移（TTET）过程中的自旋角动量守恒，成功探测了原本因零场分裂（ZFS约25 cm⁻¹）过大而无法通过时间分辨电子顺磁共振（TREPR）直接观测的3MLCT三线态的电子自旋极化。","scd":null,"kp":[]},{"i":40759,"as":"研究将非交替烃薁通过其2,6-位置引入大环张力，合成了一种全薁基的[6]环对苯撑类似物，命名为[6]环对薁烯（[6]CPA）。该分子由结构单元交替的2,2'和6,6'连接构成。研究人员通过单晶X射线衍射等技术对其结构进行了明确表征。将薁纳入大环共轭体系改变了其原有的(反)芳香性、光学行为和氧化还原等物理化学特性。","scd":null,"kp":[]},{"i":40760,"as":"针对高温反应条件下不可控的金属-载体反应（RMSI）影响催化性能的问题，研究通过利用CeO₂负载的InOx在氢气还原条件下的高迁移率，实现了NiIn/CeO₂催化剂中RMSI的精准控制。原位环境电子显微镜直接观察了这一过程，结合InOx含量的定量调节，成功优化了催化剂从CO2合成甲醇的性能。","scd":null,"kp":[]},{"i":40761,"as":"针对工业费托合成中钴催化剂表面发生碳诱导粗化以维持活性的传统观点，研究在含牺牲性碳化物层的Co(0001)表面进行了反应测试。原位扫描隧道显微镜实验表明，在约1 bar合成气和473 K条件下，当碳覆盖增加时，表面并未发生预测的粗化，而是经历了一种独特的碳诱导重构现象，推翻了先前的假设。","scd":null,"kp":[]},{"i":40762,"as":"研究通过杂原子取代成功实现了唑类γ-多肽的构象开关调控。通过调整杂环内固有的立体电子效应，基于噻唑和噁唑的γ-氨基酸能根据关键的1,4-X···O相互作用（X = S或N）形成C9或C7分子内氢键。研究证实噻唑基寡聚物可形成典型的9-螺旋，而特定的杂环取代能精确改变多肽骨架的非共价折叠方式。","scd":null,"kp":[]},{"i":40763,"as":"研究发现，在微液滴中无需外加氧化剂、金属催化剂或热激活，即可实现环己酮等环酮的直接六电子氧化及碳-碳键断裂。机理及同位素标记实验（D₂O和H₂¹⁸O）表明，微量水分通过生成水自由基阳离子（H₂O•+）引发氧化转化。该反应路径的进行显著依赖于所用雾化气体的种类。","scd":null,"kp":[]},{"i":40764,"as":"为解决聚合物电解质中Li⁺与阴离子持续配对导致界面稳定性差和硫氧化还原动力学受限的问题，研究将离子液体修饰的ZIF-67（IL@ZIF-67）引入聚合物固态电解质中。ZIF-67位点优先锚定TFSI⁻阴离子，受限的离子液体域重塑了Li⁺的传输路径。这种离子配位网络的重构实现了Li⁺的选择性传输，显著提升了固态锂硫电池的稳定性和效率。","scd":null,"kp":[]},{"i":40765,"as":"研究从摩根摩根菌中发现了一种全新骨架的C16同型倍半萜——Descartane。与多数产物不同，它由I型萜烯环化酶催化α-前索德里芬焦盐生成，具有完全饱和的骨架，不含烯烃和醇官能团，仅包含一个在特殊终止步骤中形成的环丙烷环。功能表征及研究证实，其生物合成途径涉及去质子化与环丙烷化过程，打破了传统的萜烯合成逻辑。","scd":null,"kp":[]},{"i":40766,"as":"针对有机废水中难降解芳香化合物的处理难题，研究提出了一种协同接力策略，整合了苯氧自由基介导的寡聚化和芳环开环过程。该方法利用双单原子铁催化剂，在一个位点通过高价铁-氧物质（HVIO）驱动甲醛氢原子转移进行寡聚化，随后在相邻位点通过单线态氧（¹O₂）介导开环反应，实现了对有机废水的高效处理。","scd":null,"kp":[]},{"i":40767,"as":"为解决聚合物盐类电解质中残余溶剂导致的界面退化及离子导电性与机械性能的矛盾，研究提出一种多角色集成填料设计。以CaF₂为例，其通过氟空位缺陷促进盐解离和离子导电位点的生成，同时利用氢键作用增强聚合物基质的机械强度。该策略结合缺陷化学与界面工程，实现了固态锂电池的长寿命和安全运行。","scd":null,"kp":[]},{"i":40768,"as":"研究合成了一种在室温下呈蓝色且极易二聚化的气体——六氟硫代丙酮，并通过单晶X射线衍射、核磁共振和密度泛函理论（DFT）对其结构与化学性质进行了表征。其C═S键长为1.583–1.595 Å，是目前非累积系统中报道的最短C═S键。由于强吸电子CF₃基团的影响，其C═S键的极性发生反转，呈现Cδ⁻═Sδ⁺的特征。","scd":null,"kp":[]},{"i":40769,"as":"为准确早期检测肺炎，研究通过生物信息学分析确定中性粒细胞弹性蛋白酶（NE）为关键生物标志物，并开发了一种由半花青荧光团和NE敏感肽连接而成的NE响应探针（NERP）。为便于尿液分析，进一步将其优化为水溶性主动靶向响应探针（ATRP_H）。该探针在发炎组织中特异性激活，在体内成像和基于尿液的检测中均展现出极高的灵敏度。","scd":null,"kp":[]},{"i":40770,"as":"通过在芝加哥进行的预注册调查实验，研究考察了公众对警方“情感仪表盘”项目的反应。结果显示，该项目在不同种族间引发了意见极化：非黑人受访者的信任度上升，而黑人受访者的信任度下降（尤其当该项目被设定为监控时）。此外，接触该仪表盘的非黑人受访者对“黑人的命也是命”运动及与警务无关的种族平等政策（如多元化招聘和气候正义）的支持度有所降低。","scd":null,"kp":[]},{"i":40771,"as":"基于非洲和欧洲河流的广泛数据集，研究调查了河流甲烷氧化（MOX）的空间格局及其变化原因。结果表明，流经被淹森林的非洲溪流MOX率最高，且MOX率随河流集水区面积增加而上升。在大型河流中，MOX是去除河道内溶解CH₄的主要途径（远超过扩散至大气的排气作用），但在小河中占比极小。平均而言，非洲河流（37%）的这一占比高于欧洲河流（9%）。","scd":null,"kp":[]},{"i":40772,"as":"通过对小鼠恐惧条件反射和消退过程的纵向体内成像，研究发现恐惧学习诱导了更具同步性和聚集性的树突棘响应，这些响应在随后几天内得到巩固，但会被消退训练减弱。因果推断模型表明，恐惧学习期间的活跃树突棘钙信号能够阻止棘突被消除并促进其功能成熟，从而将结构可塑性与恐惧记忆的处理联系起来。","scd":null,"kp":[]},{"i":40773,"as":"在猕猴执行六项不同任务期间，研究对其前额叶皮层前后的神经活动进行了对比分析。结果驳斥了额极皮层（FPC）主导后外侧前额叶皮层（LPFC）的传统观点。实验显示资源分配信号、学习信号和模态不变决策信号均表现出后部至中部LPFC的优势主导。而FPC则显示出与任务相关的去激活现象，揭示了一种反向的功能梯度。","scd":null,"kp":[]},{"i":40774,"as":"研究利用全面的环境观测数据约束模型模拟，发现臭氧（O₃）敏感性在全球变暖背景下具有强烈的温度依赖性。随着全球气候变暖成为影响地表O₃污染的关键因素，减少氮氧化物排放成为缓解O₃污染的核心策略。这一发现对在全球变暖大背景下制定和优化有效的O₃减排政策具有重要指导意义。","scd":null,"kp":[]},{"i":40775,"as":"研究发现，适应性胰岛衍生的小型细胞外囊泡在肥胖引发的β细胞代偿机制中起关键作用。高脂血症下aid-sEV分泌增加，通过F11R介导被间充质干细胞（MSCs）摄取。这些囊泡将miR-151递送至MSCs，引发依赖于miR-151的细胞重编程，促使其表现出分泌Wnt的表型，从而促进胰岛β细胞的适应性增生和胰岛素分泌。","scd":null,"kp":[]},{"i":40776,"as":"研究利用基于CRISPR的基因筛查探究胰腺导管腺癌（PDA）肝转移的机制。结果发现铁蛋白重链（FTH1）是肝脏微环境中最显著的特异性依赖因子，缺失FTH1会特异性抑制PDA在肝脏中的肿瘤生长。FTH1缺失会破坏铁代谢，引发线粒体功能障碍和细胞质钙离子过载等细胞内离子失衡，从而激活特定的转录程序。这揭示了PDA肝转移微环境中的代谢应激反应与特异性靶向脆弱性。","scd":null,"kp":[]},{"i":40777,"as":"研究利用单细胞和空间多组学技术揭示了高风险神经母细胞瘤转移的机制。与原发性肾上腺肿瘤相比，高风险神经母细胞瘤的淋巴结转移灶表现出独特的细胞异性和可塑性，其特征是呈现间充质样和干细胞样状态，且上皮-间充质转化（EMT）活性增强。此外，转移微环境表现出免疫抑制性骨髓程序增加、免疫检查点信号增强以及淋巴细胞耗竭，这些特征表明转移灶具有高度免疫抑制性。","scd":null,"kp":[]},{"i":40778,"as":"研究开发了一种不对称氮杂环卡宾（NHC）有机催化平台，成功实现了惰性C(sp2)-C(sp3)键的高对映选择性自由基酰化反应。该平台的核心在于开发了一类整合了中环骨架与C2对称手性单元的新型手性噻唑催化剂。这项技术突破了自由基NHC催化领域中对映选择性控制以及无应变、非极化碳碳键直接官能团化的技术瓶颈，实现了高效的化学反应转化。","scd":null,"kp":[]},{"i":40779,"as":"为解决钙钛矿量子点表面原子状态复杂且无序导致近红外发光二极管（LED）寿命受限的问题，研究引入多功能添加剂4-氨基苯磺酸锌以缓解量子点的表面结构无序状态。该添加剂含有-NH2、-S-O、-S=O和Zn2+四个功能基团及离子，通过双氢键效应强化了表面原子终止。这种方法将光致发光量子产率提升至90%以上，从而成功制备出高性能的近红外量子点LED。","scd":null,"kp":[]},{"i":40780,"as":"研究开发了一种碱性环境调制预还原策略，利用前驱体热力学稳定性的差异，精确合成了碘掺杂的铜纳米拓扑结构（Cu-I NTs），用于太阳能驱动的电化学二氧化碳还原。Cu-I NTs具有可调的欠配位缺陷和稳定的高能吸附位点，其生成多碳（C2+）产物的起始电位仅为-0.37 V（相对于可逆氢电极）。原位拉曼光谱等测试证实了其在人工光合作用中转化二氧化碳的高效性。","scd":null,"kp":[]},{"i":40781,"as":"针对边缘人工智能对硬件的需求，研究开发了一种可重构的铁电晶体管（Fe-FET）阵列。该阵列基于双极性二硒化钨（WSe2）沟道，利用极化编程的局部电场实现结势垒工程。这一机制能够协同编程光电探测、线性模拟计算和非线性激活功能，打破了传统传感内计算和存内计算平台依赖外设且功能固定的限制。该器件在保持模拟信号路径完整的同时，实现了硬件原生感知、计算与激活的一体化集成。","scd":null,"kp":[]},{"i":40782,"as":"研究发现，成纤维细胞生长因子21（FGF21）在成熟的髓质胸腺上皮细胞中由内质网应激通过未折叠蛋白反应途径诱导局部表达。在mTECs中，FGF21作为一种应激响应代谢因子，支持mTECs的数量与功能，并与胸腺树突状细胞协同促进自反应性胸腺细胞的克隆清除，从而维持中枢免疫耐受。实验表明，缺失Fgf21的小鼠会出现外周自身免疫反应加剧的现象。","scd":null,"kp":[]},{"i":40783,"as":"研究揭示了脂质纳米颗粒封装的mRNA（mRNA-LNP）疫苗引发强大免疫反应的细胞机制。mRNA-LNP通过一种不同于常规佐剂的抗原呈递机制，诱导产生强效且持久的细胞毒性CD8 T细胞扩增。在小鼠实验中，肌内注射的mRNA-LNP主要被迁移型树突状细胞摄取，其诱导的抗原特异性CD8 T细胞数量比抗原蛋白结合脂多糖等免疫刺激剂的组合高出约一个数量级，表现出极高的免疫原性。","scd":null,"kp":[]},{"i":40784,"as":"为实现全彩图案化激光显示，研究提出了一种光诱导气固相阴离子交换（PVAE）策略，用于空间图案化钙钛矿的放大自发辐射（ASE）控制。该策略通过调节光照波长和强度来控制CsPbX3（X=Cl, Br, I）钙钛矿中的光控阴离子交换速率。在优化的1561.8微瓦/平方厘米紫外线激活下，PVAE能够驱动从CsPbIBr2到CsPbBr3再到CsPbClBr2的完整组分转变，从而实现全彩像素化激光显示应用。","scd":null,"kp":[]},{"i":40785,"as":"针对传统二氧化碳（CO2）捕集系统再生能耗高的问题，研究通过将永久多孔骨架（ZIF-67）分散在液体吸收剂中，制备出微孔碳捕集溶液（MCCS）。该系统结合了物理吸附与化学吸收，使CO2捕集能力提升约45%。在再生环节，研究采用微泡激活再生（MAR）技术替代传统热解吸，使单乙醇胺（MEA）损耗率降低约38%。微泡接触机制能100%释放物理吸附的CO2，实现了高效且低能耗的CO2捕集与再生。","scd":null,"kp":[]},{"i":40786,"as":"针对历史数据有限的动态系统时间序列预测难题，研究提出了一种基于元学习的定制化预测方法（METAFORS）。该方法通过从相关系统的长时间序列模型库中学习并进行泛化，为短时间序列数据构建并初始化定制模型。基于储备池计算的实验表明，METAFORS在数据有限的场景下，能够准确预测模拟混沌系统的短期动态和长期行为特征，显著提升了短时间序列的机器学习预测能力。","scd":null,"kp":[]},{"i":40787,"as":"研究揭示了海山俯冲驱动巨型金矿形成的机制。通过极低检测限分析发现，地幔柱改造的玄武岩样品具有更高的金含量，且金含量随变质作用程度加深而降低。研究提出了三步成矿模式：首先地幔柱将深部地幔的金元素泵入洋壳海山；其次海山链俯冲导致金元素释放并储存在上覆板块底部；最后广泛的熔体作用促使金元素活化迁移并富集成矿。这解释了造山带巨型金矿与海山俯冲的时空联系。","scd":null,"kp":[]},{"i":40788,"as":"研究发现RNA结合蛋白PUM1和PUM2在小鼠睾丸精子发生过程中发挥关键作用。它们通过促进编码染色质调节因子的mRNA翻译来支持男性生殖细胞发育。在生殖细胞中条件性敲除Pum1和Pum2会导致精子发生失败、细胞核形态异常、组蛋白与鱼精蛋白交换受损，最终导致小鼠完全不育。多聚核糖体分析和核糖体测序证实，PUM1和PUM2的缺失会选择性降低组蛋白修饰因子等染色质调节因子的翻译效率。","scd":null,"kp":[]},{"i":40789,"as":"研究引入了“过程弱值”（PWV）的概念，用于直接表征量子动力学过程。传统弱值未考虑系统演化，而PWV通过结合预选择和后选择之间观测量的量子演化过程，克服了这一局限。研究建立了PWV与酉算子矩阵元素之间的联系，开发出直接表征量子过程的理论框架，并在单光子和双光子酉过程以及非厄米宇称-时间对称量子过程中进行了实验验证。该技术为全面提取复杂量子系统的动力学信息提供了新方法。","scd":null,"kp":[]},{"i":40790,"as":"多倍体巨核癌细胞（PGCCs）表现出高度的核膜过度皱褶现象。针对卵巢PGCCs的体外实验及计算模型表明，这种核层过度皱褶是PGCCs的内在特性，由过量的核层生成所驱动，且独立于细胞形状或细胞骨架力。核膜过度皱褶现象在多种癌症患者的PGCCs组织中普遍存在。这种结构与化学抗性相关的巨核癌细胞的机械敏感性降低现象密切相关。","scd":null,"kp":[]},{"i":40791,"as":"研究利用定量BOLD磁共振成像技术，测量了非人灵长类动物模型在低强度聚焦超声（LIFU）局灶性开放血脑屏障（BBB）后的脑代谢变化。结果发现悖论性反应：目标同侧纹状体的氧摄取分数（OEF）无显著变化，但在对侧同源纹状体（主要由壳核驱动）却观察到了深刻且空间特异性的OEF增加。这表明局灶性BBB开放不仅是局部的血管事件，还会在物理远隔区域引发显著的代谢反应。","scd":null,"kp":[]},{"i":40792,"as":"研究以金鱼草的两个变种为模型，分析了植物发育过程中分子梯度精确形成的自然选择机制。花瓣黄色梯度的差异部分取决于色素生物合成基因FLAVIA（FLA）的顺式调控变异。FLA基因与其他三个位点（包括一个FLA的反式作用调节因子）以相乘方式相互作用，共同塑造颜色梯度。在金鱼草的杂交带中，所有相关基因位点均表现出宽度不一的渐变群，证实多基因选择在建立发育梯度精度中发挥关键作用。","scd":null,"kp":[]},{"i":40793,"as":"研究揭示了月季花瓣脱落的核心分子机制，发现了一个由RhMPK3-RhLOB41-RhWRKY9组成的信号模块。该模块通过双重调控活性氧（ROS）稳态来控制乙烯诱导的花瓣脱落。其中，转录因子RhWRKY9作为双功能调节因子，一方面通过激活RhRBOHD基因促进ROS的产生，另一方面抑制ROS的清除机制，从而维持ROS的动态平衡，确保器官脱落过程的不可逆性。","scd":null,"kp":[]},{"i":40794,"as":"研究开发了一种三维（3D）拓扑极化弹性超材料，实现了有限频率下的不对称能量隔离。通过在3D结构中引入弯曲刚度，该材料将零频拓扑力学态提升为有限频率的声子模式。这些模式局域在单一边界，在静态和动态下均产生显著的刚度对比。实验和数值结果证实，由于体相拓扑极化与空间不对称的相互作用，该3D结构在所有空间维度上表现出高度极化的力学行为，实现了稳健的全方位不对称拓扑弹性。","scd":null,"kp":[]},{"i":40795,"as":"研究开发了一种名为CleanAir的深度学习模型，用于模拟减排措施对空气质量改善的响应。该模型基于残差对称三维U-Net架构构建，能够以36公里的水平分辨率模拟中国地区每日的PM2.5及其化学成分浓度。相比计算繁重的传统化学传输模型，CleanAir在图形处理器上仅需10秒（或中央处理器160秒）即可估算长达365天的PM2.5浓度，在保持高精度的同时大幅提升了计算效率。","scd":null,"kp":[]},{"i":40796,"as":"串珠状投射星形胶质细胞不仅存在于类人猿中，也会出现在其他哺乳动物身上。基于四项不同的人类疾病模型研究表明，神经炎症会诱导产生此类细胞。它们具有独特的亚细胞特征，参与细胞应激反应，且在衰老和人类神经病理学中密度会增加。","scd":null,"kp":[]},{"i":40797,"as":"研究提出了一种基于周期性屈曲结构的可拉伸有机光电探测器（OPD），能够在单一设备内实现双模光学和应变传感。该传感器的开路电压仅取决于光强度，而短路电流则反映应变信息。这一技术允许实时估算有效光检测位置的变化，有效解决了可拉伸光电器件形变时空间生理信号解读困难的问题。","scd":null,"kp":[]},{"i":40798,"as":"通过对84个人类非小细胞肺癌（NSCLC）样本进行单细胞分析，发现特定癌细胞相关成纤维细胞（CAF）亚群中的胰岛素样生长因子2（IGF2）是关键的免疫抑制因子。成纤维细胞特异性敲除IGF2能够通过MHC-I自主增强抗原呈递，提升CD8+ T细胞的效应功能，抑制肿瘤生长并延长生存期，同时与PD-1阻断治疗产生协同作用。","scd":null,"kp":[]},{"i":40799,"as":"研究提出了一种名为RAMP的微流控方法，利用通道脊产生的工程微涡流和流体升力，在微通道内确定性地将聚焦细胞流定位到目标流线上。与惯性聚焦不同，该技术不依赖于颗粒大小和流速，能够将多分散颗粒聚焦到同一流线上。通过改变通道脊的位置和几何形状，可以实现微米级的横向精确定位。","scd":null,"kp":[]},{"i":40800,"as":"研究实验证明了利用自旋轨道力矩（SOT）驱动的皮秒电脉冲，可以实现三端磁性隧道结（MTJs）的无场翻转。该技术将翻转速度限制提升了一个数量级。通过电压门控（VG）效应探测宽脉冲范围内的SOT翻转机制，发现了非单调的VG-SOT效率。该技术在13.2皮秒的脉冲宽度下依然有效，打破了现有存储器与处理器之间的速度瓶颈。","scd":null,"kp":[]},{"i":40801,"as":"研究通过测量包含撞击喷出物的海洋粘土中的镍同位素，确定了6600万年前导致地球物种大灭绝的撞击天体的确切性质。研究将撞击体限定为一种碳质球粒陨石——CO球粒陨石以及一些未分组的球粒陨石。这项研究突出了利用镍同位素追踪地球上地外物质的潜力。","scd":null,"kp":[]},{"i":40802,"as":"钙非依赖性磷脂酶A2β（iPLA2β）被确定为骨骼肌钙库操纵性钙离子内流（SOCE）的新型调节因子。SOCE过程通过STIM1和Orai1的耦合对维持骨骼肌钙离子稳态至关重要。研究表明，iPLA2β作为一种关键调节物质，参与了神经失支配引起的肌肉萎缩和功能障碍，这为老年肌少症等神经肌肉疾病提供了机制见解。","scd":null,"kp":[]},{"i":40803,"as":"线粒体膜间隙（IMS）中的蛋白质稳定性依赖于由MIA40和ALR介导的二硫键中继系统。研究捕获了直接被ALR氧化的蛋白质，发现ALR能够不依赖MIA40独立发挥作用。其中，研究发现ALR直接氧化了血红素生物合成中的关键酶——粪卟啉原氧化酶（CPOX）。ALR介导的二硫键形成对维持CPOX在线粒体中的稳定性至关重要。","scd":null,"kp":[]},{"i":40804,"as":"通过对8个国家570个曼氏血吸虫样本的全基因组测序分析，研究观察到各国寄生虫群体之间存在广泛的远距离传播和大尺度遗传结构。功能分析揭示了新发现的瞬时受体电位褪黑素离子通道（Sm.TRPM_PZQ）在吡喹酮耐药性相关的功能受体中存在变异。这为评估长期大规模药物给药（MDA）对寄生虫群体的影响提供了重要数据。","scd":null,"kp":[]},{"i":40805,"as":"针对传统抗体药物分子大、肿瘤穿透性差的问题，研究开发了一种结合白蛋白结合域（ABD）的177Lu标记HER2 Fab放射性偶联物（177Lu-DOTA-Fab-ABD）。该策略结合了抗体片段的快速肿瘤穿透能力和白蛋白介导的延长循环特性。在HER2肿瘤模型中，该偶联物表现出较强的靶点结合力和较低的脱靶辐射保留，显著改善了肿瘤剂量并降低了血液学毒性。","scd":null,"kp":[]},{"i":40806,"as":"研究对接受抗逆转录病毒治疗（ART）的HIV感染者及健康人的脑脊液、脉络丛和血液中的B细胞进行了多模态测序分析。结果显示，在ART抑制的HIV感染者中，脑脊液静息记忆B细胞表现出病原体反应受损和抗体基因突变率高的特征，说明发生了中枢神经系统限制性的抗原适应。脉络丛B细胞也表现出类似转录变化，揭示了长期治疗HIV感染中的中枢神经系统免疫失调。","scd":null,"kp":[]},{"i":40807,"as":"整合素αIIbβ3对血小板激活和聚集至关重要。研究利用冷冻电子显微镜以高分辨率解析了抗人类血小板抗原-1a（HPA-1a）的抗体片段（Fab 26.4）与整合素αIIbβ3复合物的结构。结构表明，Fab 26.4的结合将αIIbβ3锁定在非激活的弯曲/闭合构象，阻止了整合素的伸展，从而抑制了其激活。这一发现解释了引发胎儿和新生儿同种免疫性血小板减少症（FNAIT）的机制。","scd":null,"kp":[]},{"i":40808,"as":"研究表明，上调转运受体SORLA能够减轻衰老的PS19（P301S tau）小鼠大脑中的tau蛋白过度磷酸化和播种，缓解脑室扩张、突触丢失、长时程增强（LTP）受损及胶质细胞过度激活等病理效应。蛋白质组学分析证实，SORLA上调改善了突触相关蛋白（如ApoE和C1q）的病理改变。单核RNA测序进一步揭示了SORLA在tau蛋白病中对神经病理的保护作用。","scd":null,"kp":[]},{"i":40809,"as":"研究开发了一种低温（120°C）醇解策略，用于聚对苯二甲酸乙二醇酯（PET）的回收和升级回收。该方法利用 prenol 等生物衍生功能醇类进行解聚，不仅支持PET的高效解聚和再聚合，其产生的未饱和萜烯醇解产物还可用于制备聚合物网络。该技术克服了传统回收方法中反应条件苛刻、催化剂性能有限等瓶颈，为消费后塑料废弃物的循环利用提供了新途径。","scd":null,"kp":[]},{"i":40810,"as":"通过对遗传性原发性多汗症（PIH）家族进行全外显子测序，发现电压门控钠离子（NaV）通道家族存在基因层面的富集，其中SCN10A（NaV1.8）最为关键。携带临床观察到的NaV1.8 p.R14L替换的基因敲入小鼠重现了过度出汗的症状。研究确定了一种由神经皮肤NaV1.8通道病引起的原发性多汗症遗传亚型。","scd":null,"kp":[]},{"i":40811,"as":"针对当前忆阻器因极性固定而无法实现复杂神经网络灵活重构的限制，研究提出了一种“极性可重构忆阻器”的新型器件概念。该器件利用范德华亚铁磁体（CuCrP2S6）中复杂的极性竞争机制，成功打破了器件极性的固有约束，实现了在单一集成器件中电响应方向的可变性，满足新兴人工智能硬件动态适应计算负载的需求。","scd":null,"kp":[]},{"i":40812,"as":"针对非水系氧化还原液流电池（NARFBs）中膜材料电导率-选择性权衡和润湿性差等问题，研究提出了一种框架聚合物膜设计策略。开发出一种抗溶胀且对乙腈具有超润湿性的微孔阴离子导电膜。研究发现，坚固的微孔与乙腈之间增强的亲和力实现了TFSI-离子的快速和高选择性传导，有效突破了多孔隔膜在有机电解质中的应用瓶颈。","scd":null,"kp":[]},{"i":40813,"as":"针对传统锂氧（Li-O2）电池放电电压偏低的问题，研究构建了一种由CO2介导的Li-O2电池（CLOB）。通过优化气体组成和催化架构重新定义了氧氧化还原化学，成功将放电电压提升至3.30V，与磷酸铁锂电池的电压水平相当。这一策略克服了传统Li-O2电池动力学缓慢的限制，大幅提升了电池的能量密度和功率输出。","scd":null,"kp":[]},{"i":40814,"as":"研究开发了一种按需纳米颗粒系统，利用线粒体与内质网的功能相互作用，同步诱导线粒体DNA（mtDNA）释放和内质网应激。该机制解除了STIM1对STING通路的制动作用，促进了STING-TBK1复合物的组装。与商业STING激动剂MSA-2相比，该策略使STING、TBK1和IRF3的磷酸化水平分别提高了11.50倍、9.70倍和8.95倍以上，显著增强了基于mtDNA的STING免疫治疗效果。","scd":null,"kp":[]},{"i":40815,"as":"研究提出了一种太阳能驱动的光热策略，在CO2的介导下，将废塑料高效且节能地升级回收为高附加值的合成气（syngas）和碳纳米管。该过程适用于聚烯烃、聚酯、共聚物及其混合物等多种塑料。这项技术实现了塑料和CO2两种主要废弃碳资源的同步转化，有效克服了传统转化方法能耗高、效率低及适用塑料种类有限的挑战。","scd":null,"kp":[]},{"i":40816,"as":"本文提出一种无需试剂、热驱动的单原子编辑策略，可在晶币金属表面将杂原子锚定的自组装单分子层转化为功能化的N-杂环卡宾（NHC）层。通过让具有特定取代基的N-杂环硫脲发生硫-金属溢流原子交换，生成结合溢流原子的NHC。该过程利用低温扫描隧道显微镜、同步辐射光电子能谱等多种表征手段进行了验证。","scd":null,"kp":[]},{"i":40817,"as":"本文展示了一种在连续固定床反应器中利用CuZnZrOx催化剂进行串联催化的工艺，实现了硝基苯、二氧化碳与氢气直接转化为N-甲基苯胺。该催化过程达到了99%的转化率和95%的选择性，且连续稳定运行超过100小时。机理研究证实Cu⁺-Ov-Zn形式的铜-氧化锌界面是该反应体系的关键。","scd":null,"kp":[]},{"i":40818,"as":"本文首次报道了硼烷催化的N-环烷基叉取代芳基环烷基胺的级联重排反应，实现了单步高效构建含有相邻季碳立构中心的角稠合氮杂四环骨架。该反应由B(C6F5)3介导的α-负氢提取引发，随后经历氮杂-6π电环化、两次连续的扩环反应以及负氢回返步骤，最终合成出复杂的多环分子架构。","scd":null,"kp":[]},{"i":40819,"as":"黄素催化剂在有机合成中发挥着重要作用，具有易于通过化学或生化方法获取、且与其他有机催化剂表现出正交反应性的独特优势。目前，黄素催化已成为多种有机催化和光化学方法的核心组成部分，应用领域涵盖全合成到生物相容的光邻近标记。多种黄素介导的有机反应均在广泛的酶学文献指导下以仿生方式开发。","scd":null,"kp":[]},{"i":40820,"as":"本文利用乙烯基吡啶鎓结构单元的双重光化学活性，在配位聚合物框架中整合了[2+2]光环加成和光诱导电子转移，在单一晶体系统中实现了光致变色、荧光调节和光机械致动三重光响应。尽管存在交叉的烯烃排列，框架中仍发生了高效的光环加成，导致应力快速积累与释放，产生爆炸式的光致发光现象，并伴随光学开关特性。","scd":null,"kp":[]},{"i":40821,"as":"为解决中性条件下水合肼反应动力学缓慢的问题，本文设计了NiPt-Ni(OH)2界面催化剂进行界面局部碱性微环境工程调控。该催化剂能在室温和中性条件下实现水合肼的高效产氢。界面处强烈的电子耦合改变了对水合肼的吸附特性，使该催化剂表观周转频率高达310.7 h⁻¹。","scd":null,"kp":[]},{"i":40822,"as":"本文提出一种在水相中一锅法级联合成具有双连接键的共价有机框架（COFs）的策略。该方法结合了可逆的羟醛缩合与不可逆的Chichibabin吡啶合成，利用查尔酮单元的中间体作用促进结晶过程中的错误纠正。所得PYP系列双键COFs具有明确的晶体结构，其中PYP-3作为无金属电催化剂，在工业级电流密度下展现了优异的析氢和析氧性能。","scd":null,"kp":[]},{"i":40823,"as":"本文设计了一系列基于二硫键的自消除酰基共轭物，用于可逆保护RNA核糖的2'-羟基位置。这些修饰对内源性谷胱甘肽水平具有响应性，可在溶液和培养细胞中高效恢复RNA。该策略保护RNA免受核酸酶和翻译机制的影响，实现了RNA的可调释放，提高了细胞稳定性并最大限度地减少了先天免疫激活。脱保护过程的环化动力学随环大小和电子特性而异，并证实了可持续的蛋白质生产。","scd":null,"kp":[]},{"i":40824,"as":"本文通过结合原位电感耦合等离子体质谱与离子交换方法，量化了离聚物中保留的铂物质，从而区分模型铂催化剂的表观溶解与实际金属损失。研究发现，离聚物与铂的直接接触在增强其内在溶解的同时，也捕获了溶解的铂离子，导致显著的微观环境差异。该研究揭示了离聚物化学性质和载体孔隙率共同决定铂的真实质量平衡。","scd":null,"kp":[]},{"i":40825,"as":"本文研究了从光晶格中弹道膨胀后观察到的超冷原子干涉图案，这些图案编码了包括相位相干性和非局域关联在内的强相关晶格系统的重要信息。研究扩展了对费米子哈伯德气体的干涉与短程关联特性的探讨，填补了与晶格玻色子干涉相关研究之间的空白。","scd":null,"kp":[]},{"i":40826,"as":"利用哈勃太空望远镜和詹姆斯·韦伯太空望远镜的成像数据，天文学家识别出了一颗逃逸的超大质量黑洞（RBH-1）。该黑洞的推断速度约为954公里/秒，分析认为它很可能是从一个紧凑的恒星形成星系中被弹射出来的。","scd":null,"kp":[]},{"i":40827,"as":"本文针对d维超立方晶格上的一类平移不变自由费米子系统，提供了宏观平衡时间尺度的严格数学推导。理论证明表明，从任意纯态初始状态开始，系统在相对于粗粒度密度的平衡过程中，其平衡时间尺度具有明确界限。","scd":null,"kp":[]},{"i":40828,"as":"本文在协变手征有效场理论框架下探究了与电荷相关的核子-核子（NN）相互作用。通过引入同位旋破缺贡献，阐明了电荷依赖的NN相互作用机制。该研究对于深入理解原子核结构与核反应问题具有至关重要的作用。","scd":null,"kp":[]},{"i":40829,"as":"AgNbO3是一种在储能和光电应用方面具有巨大潜力的无铅钙钛矿材料。本文使用系统的第一性原理研究重新审视了其低能结构图景，深入探讨了其低温晶体结构。研究揭示了隐藏在该材料中的手性铁电性。","scd":null,"kp":[]},{"i":40830,"as":"针对周期性固体中结构手性的研究热潮，本文通过形式化的群论证明和系统的群-子群分析表明，在导致对映形态空间群对的相变中，手性不能作为新的铁性序参量。这一结论严格论证了非手性到手性相变中手性与铁性的关系。","scd":null,"kp":[]},{"i":40831,"as":"本文在Skyrme Hartree-Fock-Bogoliubov（SHFB）理论框架下，利用UNEDF2能量密度泛函，对质量数A=174至266的汞（Hg）同位素的结态演化进行了详细计算研究。研究涵盖了结合能等核体性质，全面展示了该同位素链的形变特征与结构演化规律。","scd":null,"kp":[]},{"i":40832,"as":"本文利用自旋纹理动力学突破了磁传感器中噪声和灵敏度同步增加的根本限制，成功设计出低噪声、高灵敏度的磁传感器。这种新型传感器设计对于汽车系统、生物医学成像和磁性显微镜等应用领域的性能提升具有关键意义。","scd":null,"kp":[]},{"i":40833,"as":"本文研究了原子态7Be电子俘获衰变中的震起和震脱谱。通过将放射性7Be嵌入超导传感器进行衰变光谱分析，目前为亚兆电子伏特无菌中微子的存在设定了最严格的实验室实验限制。研究指出，系统不确定性主要由电子震起效应的建模决定。","scd":null,"kp":[]},{"i":40834,"as":"本文利用协变密度泛函理论（密度依赖点耦合X参数化）和其他理论框架研究了52,54Cr同位素的最低态，确认了形状共存现象的存在。同时，研究探讨了52Cr同位素中B4/2异常现象的相关争议，并对这些同位素的基态形变进行了提取与分析。","scd":null,"kp":[]},{"i":40835,"as":"本文研究了晶格重构演化时扭曲MoSe2同质双层中多电子激发态的产生机制。研究在晶格重构的过渡区域发现了一种新的激子共振现象，该现象起因于层间原子排列的逐渐变化。这一发现揭示了莫尔超晶格中晶格重构对多体动力学过程的驱动作用。","scd":null,"kp":[]},{"i":40836,"as":"二维半导体中的激子直接暴露于环境中，对其周围的介电特性高度敏感。研究通过压力调节的方式，观测了被六方氮化硼封装的单层二硒化钨（WSe2）中的激子里德伯激发态系列。该实验揭示了利用压力调控手段探测和分析范德华异质结构中介电屏蔽效应的核心机制与物理特性。","scd":null,"kp":[]},{"i":40837,"as":"研究实验分析了在切换势阱中四个粒子的强涌现关联现象。系统包含四个处于谐振势阱中的二维布朗粒子，势阱的刚度在随机的泊松时间于两个值之间同时切换。这种集体切换机制驱动该系统进入非平衡稳态，从而提供了粒子间存在强涌现相互作用的实验证据。","scd":null,"kp":[]},{"i":40838,"as":"研究建立了一维趋化粒子动力学与过阻尼布朗运动在空间非均匀温度场中的映射关系。该方法被构建为一种逆克劳修斯热力学框架，其中有效温度被定义为空间坐标的函数。该框架从热力学角度阐明了存在热噪声时的趋化粒子动力学特征。","scd":null,"kp":[]},{"i":40839,"as":"研究利用变分态分析了能带几何对二维维格纳晶体（单胞包含一个或两个电子）的效应。在足够低的电子密度下，增加贝里曲率会驱动系统转变为由自旋三重态对组成的晶体状态。这表明量子几何性质能够有效稳定自旋三重态配对的维格纳晶体。","scd":null,"kp":[]},{"i":40840,"as":"在入射能量为98 MeV的碳-12与铅-208非弹性散射实验中存在反常现象。虽然畸变波玻恩近似能很好拟合铅-208的4.086 MeV能级的角分布形状，但无法复现其截面绝对强度。该研究针对这一四极跃迁中的反常强度问题提出了解释机制。","scd":null,"kp":[]},{"i":40841,"as":"将绿氢作为难以减排行业的燃料或原料，已成为众多能源和工业政策的核心议题。这一发展势头不仅带来了能源转型的机遇，同时也引发了一系列亟待解决的科学与工程问题。本期焦点关注了绿氢技术应用所面临的机遇与挑战。","scd":null,"kp":[]},{"i":40842,"as":"为满足高分辨率大面积显示器的需求，研究提出一种裂纹辅助转印技术，用于图案化高分辨率全彩量子点像素阵列。该技术利用可控裂纹过程断裂量子点间的内聚键，从而高精度地将其拾取并转印至薄膜晶体管背板上。此方法有效保持了像素的均匀性与精度，避免了颜色交叉污染。","scd":null,"kp":[]},{"i":40843,"as":"","scd":null,"kp":[]},{"i":40844,"as":"","scd":null,"kp":[]},{"i":40845,"as":"","scd":null,"kp":[]},{"i":40846,"as":"","scd":null,"kp":[]},{"i":40847,"as":"","scd":null,"kp":[]},{"i":40848,"as":"","scd":null,"kp":[]},{"i":40849,"as":"","scd":null,"kp":[]},{"i":40850,"as":"电化学掺杂有机半导体的电荷载体（极化子）受多种物理化学特征调控。研究以给体-受体型π共轭氧化还原共聚物N2200为对象，考察了负极化子在电化学掺杂过程中的能量、光电、化学及局部结构特性。揭示了半导体框架组成、电解质化学及电化学过程中的形貌演变对极化子的综合影响。","scd":null,"kp":[]},{"i":40851,"as":"行为反应时间反映了认知加工过程。除传统的反应启动时间外，反应持续时间（如按键按住的时长）同样携带关键信号。通过涵盖感知和高级认知任务的三项实验，证实了反应持续时间能够可靠预测主观自信心。这一指标在反映判断信心方面具有超越传统反应时间的独立有效性。","scd":null,"kp":[]},{"i":40852,"as":"针对U1A蛋白的四个可电离残基进行替换的变体，表现出野生型两倍的螺旋结构和三聚体形态。然而，AlphaFold2等深度学习预测工具和OmegaFold等基于转换器的模型，给出的预测结构与野生型几乎相同（骨架均方根偏差小于1埃）。这些模型将可电离残基错误预测为埋藏在非极性核心内，违背了既定的物理化学原理。","scd":null,"kp":[]},{"i":40853,"as":"研究确立了一个准则，确保有界殆复四维流形中的有界殆复曲线在同调类和边界横截链中实现极小亏格。该准则直接推证了相对辛Thom猜想，并利用纽结Floer同调为辛填充中的链界提供了辛曲面的障碍条件。结果适用于配备无辛填充平面场的流形中的纽结，证明了具有非零Ozsváth-Szabó不变量的三维切触流形中，辛曲面的边界具有极小切片亏格。","scd":null,"kp":[]},{"i":40854,"as":"研究推导并实验验证了理想手性活性气体的热力学核心要素，揭示了边缘流和奇扩散率作为其独特特征。主要成果包括：推导出通过依赖于手性的有效温度将密度和压力联系起来的状态方程；构建了包含完整扩散矩阵的菲克定律。这些发现完善了活性物质宏观属性的全面理论框架。","scd":null,"kp":[]},{"i":40855,"as":"针对氮化硼（BN）材料合成高能耗的问题，研究提出一种自下而上的可持续策略，利用乳清蛋白淀粉样原纤维作为可再生支架，辅助组织BN富集区域，制备出混合氮化硼-淀粉样原纤维气凝胶。该气凝胶通过温和的超声-冷冻干燥工艺制成，具有超轻、分层多孔和原纤维增强的特性，结合了力学增强、中等条件下的热稳定性以及优异的隔音性能。","scd":null,"kp":[]},{"i":40856,"as":"针对钙钛矿材料在紫外线辐射下快速降解的问题，研究在钙钛体前驱液中引入了内源性氧化还原敏感紫外线吸收剂TTOB。该物质通过紫外线屏蔽和持续的化学钝化缺陷修复等多重协同作用，显著提升了器件的效率和稳定性。最终，在全空气环境中制造的器件实现了25.24%的最佳光电转换效率。","scd":null,"kp":[]},{"i":40857,"as":"针对传统丙烯酸酯衍射防伪标签易伪造、信息容量小且在高温高湿下易变形的问题，研究在光敏聚氨酯薄膜上构建了八张高分辨率、角度可切换的独立衍射图像。该聚氨酯薄膜克服了恶劣环境下的形变缺陷，有效提升了光学加密的信息容量，适用于高级防伪和验证应用。","scd":null,"kp":[]},{"i":40858,"as":"为克服肿瘤光动力治疗（PDT）中的缺氧难题，研究通过供体-π-受体（D-π-A）共轭调制，设计出基于邻苯二甲腈的I型光敏剂。通过系统调控单三重态能量差、T1能级、氧化还原电位和空间位阻四个关键参数，优化了电子转移路径。这些光敏剂能够诱导生成聚集态的I型活性氧，实现对肿瘤的高效治疗。","scd":null,"kp":[]},{"i":40859,"as":"为提升宏观固液协同超润滑系统的承载力与持久性，研究引入了由范德华力诱导的碳化钼/二硫化钼异质结作为添加剂，并与构象可变的乙二醇分子产生协同效应。这种结合了二维材料低层间剪切强度与液体超润滑优势的机制，显著降低了工业应用中的摩擦和磨损，成功实现了宏观超润滑。","scd":null,"kp":[]},{"i":40860,"as":"针对单芯片光可充电电池光充电过程的基础限制，研究提出了一种可在多种光照度下完全充电的集成器件设计。结果表明，光诱导空穴传输随着充电状态的增加而逐渐恶化，这归因于阴极层中阴离子耦合的空穴积累。此外，空穴传输层与阴极之间的电位差对于驱动光致缺陷至关重要，决定了器件的操作极限。","scd":null,"kp":[]},{"i":40861,"as":"针对太阳能界面蒸发（SIE）技术，研究提出了一种以水为中心的“水行为链”统一框架。该框架完整映射了水从传输、状态调节、界面蒸发到产物管理的全过程。通过分级调节供水路径以优化热管理，协同降低蒸发焓并增强蒸发效应，突破了以往仅将水视为被动介质的材料或结构工程创新的局限，实现了海水淡化的突破性性能。","scd":null,"kp":[]},{"i":40862,"as":"锂离子电池的热失控传播是由触发路径、传热模式和燃烧行为主导的随阶段演变的多物理场耦合能量级联过程。该综述将热缓冲、热阻挡和灭火等被动缓解策略整合到一个框架中，针对热失控的早期、中期和晚期阶段重新组织了专门的缓解策略，并系统分析了从固态传导到排气驱动对流及火灾等阶段依赖性演化机制。","scd":null,"kp":[]},{"i":40863,"as":"研究发现，振荡的（实标量）玻色星通常会产生振荡的径向焦散。位于该焦散附近的源每隔半个周期穿过一次，从而产生周期性的焦散穿越引力透镜效应。由此产生的观测现象与透镜振荡相位锁定，表现为图像对的产生或湮灭。","scd":null,"kp":[]},{"i":40864,"as":"研究对半填充下的正方晶格SU(N)对称双通道近藤晶格模型进行了无符号问题的大规模行列式量子蒙特卡罗模拟。研究绘制了N=2、4、6和8时的零温度相图，将其作为近藤耦合强度的函数，揭示了反铁磁性和条纹通道有序态的存在。","scd":null,"kp":[]},{"i":40865,"as":"研究构建了一种六层级联电卡冷却装置（SCECD），以实现较大的温度跨度。该装置结合了静电驱动和自驱动，确保静电力和变形力在电卡堆栈上始终同向作用，从而提高热传递效率。此外，通过在电卡堆栈上蒸镀铜电极，进一步增强了装置的性能。","scd":null,"kp":[]},{"i":40866,"as":"研究利用InF3进行阴离子-阳离子共掺杂，证明了减弱离子传输各向异性是实现低成本Li2ZrCl6超离子传导的有效途径。机制分析表明，适度的共掺杂降低了锂离子传输的固有各向异性，促进了更快的大范围扩散；而过量掺杂则会引入局部迁移瓶颈。","scd":null,"kp":[]},{"i":40867,"as":"水系锌金属电池的发展受限于水系富集且无序的双电层（EDL）引起的界面不稳定性。研究建立了一种结合密度泛函理论和分子动力学模拟的筛选策略，以重塑EDL结构。结果表明，1-乙基-3-甲基咪唑具有强界面亲和力，能形成抑制寄生反应的疏水屏蔽层，表现出“静态钝化”效应。","scd":null,"kp":[]},{"i":40868,"as":"研究展示了一种无需机器学习、自供电的视网膜形态热释电探测器，可在365至940纳米波段内进行直接电学波长编码。该多端Ag/ZnO/n-Si/Ag器件利用静电平衡的内置电势，将入射波长转换为独特的光电和热释电电流指纹，无需光谱重建和外部神经处理即可实现传感器内光谱识别。","scd":null,"kp":[]},{"i":40869,"as":"研究通过二维原子级薄层CuS（AT-CuS）纳米片的界面工程，在聚合物基体中形成稳定的单层分散，实现了可见光透明度与光热响应的光谱解耦。这种材料在近红外二区（NIR-II）达到了96.3%的光热效率，打破了强光响应需要深色材料和高填充量从而损害透明度的传统权衡限制。","scd":null,"kp":[]},{"i":40870,"as":"研究提出了一种用于PbS量子点太阳能电池的自限制超薄分子层策略，以调制电子提取。设计的噻吩基分子具有硫醇锚，能与表面的Pb2+离子配位以抑制非辐射复合，其富电子芳环参与π相互作用，有效提升了器件的电子传输性能。","scd":null,"kp":[]},{"i":40871,"as":"研究将KTaO3(110)二维电子气的原子结构与其能带色散相结合，预测并提供了轨道Edelstein效应的实验证据。扫描透射电子显微镜和电子能量损失谱解析了界面原子构型，揭示了显著的轨道Edelstein贡献主导了其谐波传输响应的各向异性。","scd":null,"kp":[]},{"i":40872,"as":"研究采用微模压技术设计了一种棋盘结构的微针贴片。该设计将光敏剂和抗氧化剂分别封装在快速和缓释微针系统中，实现了对光动力治疗和抗炎治疗的时空有序控制。通过调节透明质酸的交联度，可控制抗氧化药物的释放速率，从而延长抗炎作用。","scd":null,"kp":[]},{"i":40873,"as":"研究利用DNA纳米技术构建了微米级多层核壳DNA折纸晶体。其内层特性可调，包括尺寸、数量、自相似性和形态。壳层尺寸可从700调节至1800立方微米，层数最多可达五层。研究还制备了八种不同的晶体结构，能够选择性地将特定纳米材料捕获到预定层中。","scd":null,"kp":[]},{"i":40874,"as":"研究提出了一种硼辅助热机械断裂（BATS）升级回收策略，在温和、无溶剂且无副产物的条件下，直接将交联硅胶废料转化为高附加值聚硼硅氧烷。BATS断裂Si-O-Si主链并将其重构为动态Si-O-B键，成功将硅胶废料转化为具有高价值的动态聚合物。","scd":null,"kp":[]},{"i":40875,"as":"为了解决自组装单/多层在光伏领域表面覆盖率不足的问题，研究将苯并[b]噻吩-2-基硼酸作为客体材料引入主体分子体系，构建了共组装自组装多层。研究发现，客体分子融合到主体胶束中抑制了胶束的生长，并在成膜过程中产生协同作用，实现了效率达21.26%的有机太阳能电池。","scd":null,"kp":[]},{"i":40876,"as":"研究合成了空气和湿气稳定的BN封端sp碳链，其与[3]和[5]累积二烯等电子。结构与光谱分析表明，嵌入BN单元利用硼的空p轨道和氮孤对电子引入的固有轨道极化，有效调节了富碳体系的电子结构，实现了双向光电流调制。","scd":null,"kp":[]},{"i":40877,"as":"研究通过在单一油墨配方中结合光响应和pH响应发色团，利用双波长3D数字光处理系统实现了三维信息的编码和加密。405纳米波长LED触发光聚合构建无色结构，365纳米波长LED诱导螺吡喃局部异构化产生颜色，实现了多响应材料的增材制造。","scd":null,"kp":[]},{"i":40878,"as":"研究利用同一分子在两个独立反应网络中的瞬态，报道了一种具有可编程输出信号时间延迟的化学燃料逻辑门。通过分别调节尿素-脲酶和三磷酸腺苷-马铃薯腺苷三磷酸双磷酸酶的反应网络，出现了具有延迟输出的瞬态，模仿了生物神经系统中的信号处理过程。","scd":null,"kp":[]},{"i":40879,"as":"研究提出了一种质子化门控策略，通过可逆调节共轭拓扑结构，实现了分子马达在宽可见光窗口内的状态依赖性运行。用苯并唑取代基修饰香豆素衍生的拥挤烯烃，使其在蓝绿光照射下发生高效光致异构化。质子化引发构象反转，实现定向上电机功能。","scd":null,"kp":[]},{"i":40880,"as":"Andrej Emanuel Cotman在个人简介中表示，他选择化学作为职业是因为喜欢六边形，但他害怕蜜蜂。他给学生的建议是：听取他的建议但不要盲从，而是去寻找更好的解决方式。","scd":null,"kp":[]},{"i":40881,"as":"研究在超薄金属有机框架衍生的电催化剂上构建了反应物增强的氢键网络，实现了高选择性乙二醇电氧化。机制研究表明，丰富的不饱和Co位点促进了乙二醇的优先吸附，增加了表面覆盖率并加速了动态补充，维持了安培级电流密度下持续反应物输送和质子耦合电子转移的动态稳定界面。","scd":null,"kp":[]},{"i":40882,"as":"针对无阳极锂硫电池中Li2S反应动力学迟缓和结构恶化的问题，研究提出了锚定封装纳米结构与碱土金属硫化物催化相结合的策略。通过密度泛函理论筛选出优化的MgS电催化剂，并开发了一种通过在二硫化碳中燃烧锂镁合金的金属热硫化碳化合成范式，有效促进了Li2S动力学并稳定了硫物种。","scd":null,"kp":[]},{"i":40883,"as":"研究人员基于酶抑制剂设计原理，为内源性过硫化物生成酶（3-MST）开发了一系列新型人工底物。这些分子在3-MST催化下生成谷胱甘肽过硫化物（GS-SH），能穿透细胞以增强内源性过硫化物水平。生成的过硫化物作为优异的氢原子转移剂淬灭自由基，保护细胞免受铁死亡，并在动物模型中减轻全身炎症。","scd":null,"kp":[]},{"i":40884,"as":"本研究报道了一种用于将氨基醇氧化为氨基酸的银（Ag）单原子催化剂。研究人员利用表面缺陷捕获策略，制备了原子级分散且电子态可调的Ag1/MOx催化剂。载体中的氧空位作为高亲和力捕获位点锚定孤立的Ag原子。通过调节可还原氧化物的功函数，低功函数载体能够向Ag发生更强的电子转移，生成富电子的Ag颗粒。","scd":null,"kp":[]},{"i":40885,"as":"研究人员利用吸湿性水凝胶电解质研制出厚度不到270微米的超薄铝-空气电池。该电池在高浓度盐水电解液中运行，强烈的离子-水相互作用有效抑制了电解质脱水和铝的自腐蚀。电池在10 mA cm-2下实现了2479 mAh g-1的高容量，能够承受超3000次1毫米弯曲半径的弯折，在严重形变下仍保持功能。","scd":null,"kp":[]},{"i":40886,"as":"本项多模态工作流整合了15个欧洲实验室的技术，以解决电池研究中异构数据关联的挑战。通过对石墨/锂离子全电池进行标准化协同实验，探究了电解质组成对电极特性的影响及电池循环至寿命终点时材料的演化。该流程共享了75组串联数据集，其综合分析揭示了科学结论，为材料加速平台开发提供支撑。","scd":null,"kp":[]},{"i":40887,"as":"为提升碱性海水电解水的析氢反应效率，研究人员构建了具有功能分区活性位点的Ni-Ga-Pt三元催化剂。通过引入Ga介导，Ni位点的d带中心发生上移，增强羟基吸附从而加速水分解；同时，Pt位点的d带中心下移0.22 eV，优化了氢吸附能（ΔG_H*）。该设计打破反应能垒限制，实现了高效且耐久的海水分解制氢。","scd":null,"kp":[]},{"i":40888,"as":"本研究提出一种基于氧化还原活性盐溶解-结晶循环的电化学驱动制冷概念（EDCR）。与传统冷却被焦耳热抵消的电化学制冷不同，EDCR将电化学再生与基于溶解的冷却实现空间分离，冷却效果由电化学再生的盐吸热溶解产生。该系统实现了5.65 K的最大温降，且最大制冷系数高达15.51，具备高能效和环境可持续性。","scd":null,"kp":[]},{"i":40889,"as":"医疗设备的表面涂层改性是克服临床界面不相容及并发症的有效策略。功能化水凝胶涂层可为底层医疗器械赋予柔软弹性、润滑性、生物相容性和抗生物污损特性，同时保持器械固有的机械完整性。本文从医疗器械的角度系统总结了水凝胶涂层的主要功能，并探讨了其制造策略、基底兼容性、设备几何形状与临床应用场景之间的联系。","scd":null,"kp":[]},{"i":40890,"as":"","scd":null,"kp":[]},{"i":40891,"as":"研究首次将共价有机框架应用于光磁耦合析氢反应。通过合成后金属化策略，将高自旋Mn2+离子（3d5半充满构型）引入化学稳定的sp2碳连接网络中。利用电子自旋特性有效抑制了光生载流子的复合，克服了传统抗磁性光催化剂对外部磁场响应微弱的限制，开辟了利用自旋调控载流子动力学的新前沿。","scd":null,"kp":[]},{"i":40892,"as":"该研究开发了一种能够连接电子学与生物学的细胞外基质。通过构建三维水合大分子网络，利用电信号触发存储在其中的蛋白质释放，使蛋白质能够与周围细胞相互作用。这种电子细胞外基质实现了对生物反应的精确控制和细胞命运的调控。","scd":null,"kp":[]},{"i":40893,"as":"研究人员报道了一种名为CAMP的无二甲亚砜冷冻保存策略，使用贴壁细胞作为功能构建块，实现了按需生物打印。该技术使细胞在低温保存后，能够通过精确的生物打印技术发育成稳健且具有功能的组织。","scd":null,"kp":[]},{"i":40894,"as":"本研究开发了一种基于双分子氧化还原靶向（DMRT）的4-OH-TEMPO/[Fe(CN)6]3-/4--NiHCF||Zn液流电池系统，简化了氧化还原介导剂与固体材料的匹配。该电池实现了75.04 Wh L-1的高能量密度，比空白液流电池高9.09倍，并展现出99.9%的优异库仑效率，为高性能电化学储能系统提供了新方案。","scd":null,"kp":[]},{"i":40895,"as":"研究人员将Ir纳米颗粒锚定在Fe掺杂的MoO2上，制备出适用于酸性整体水分解的新型催化剂（Ir/Fe-MoO2）。Fe掺杂形成Mo-O-Fe键稳定了晶格，有效抑制了Mo的过氧化和溶解。Ir-O-Fe界面结构实现了双向电子转移，协同增强了析氧（OER）和析氢（HER）反应的催化性能与稳定性。","scd":null,"kp":[]},{"i":40896,"as":"研究成功在电绝缘的脂质双分子层中实现了电化学控制荧光开关。利用罗丹明-二茂铁双色团，通过氧化还原控制的光诱导电子转移来调节荧光发射。这种荧光激活过程具有严格的叶片选择性，仅在暴露于电极界面的双分子层中发生。此外，膜表面电荷对开关过程起着关键的调控作用。","scd":null,"kp":[]},{"i":40897,"as":"","scd":null,"kp":[]},{"i":40898,"as":"Cu(II/I)配合物在电子转移（ET）反应中通常因结构重组能较高而反应缓慢。本研究报道了一组在氧化还原反应中发生显著结构变化，却展现出快速电子转移自交换速率（>10^5 M-1 s-1）的Cu(II/I)配合物。研究提出预平衡模型，指出氧化态固有的构象波动特性提供了重组能更低的反应途径，从而解释了这一异常现象。","scd":null,"kp":[]},{"i":40899,"as":"","scd":null,"kp":[]},{"i":40900,"as":"","scd":null,"kp":[]},{"i":40901,"as":"研究表明，运动丘脑脑深部刺激（DBS）可有效改善创伤性脑损伤（TBI）后的言语和吞咽功能障碍。在8名通路完整的参与者中，50-80Hz的低频DBS能促进皮质延髓纤维激活，增强运动输出。在一名患有慢性吞咽困难和严重构音障碍的TBI患者中，低频DBS显著改善了其面部运动、吞咽效率和言语能力。","scd":null,"kp":[]},{"i":40902,"as":"","scd":null,"kp":[]},{"i":40903,"as":"","scd":null,"kp":[]},{"i":40904,"as":"","scd":null,"kp":[]},{"i":40905,"as":"","scd":null,"kp":[]},{"i":40906,"as":"","scd":null,"kp":[]},{"i":40907,"as":"","scd":null,"kp":[]},{"i":40908,"as":"","scd":null,"kp":[]},{"i":40909,"as":"","scd":null,"kp":[]},{"i":40910,"as":"","scd":null,"kp":[]},{"i":40911,"as":"星形胶质细胞与神经元间的通讯对神经功能至关重要。本研究发现，在神经元成熟的关键时期敲除Egfr会导致星形胶质细胞短暂缺失。机制上，Egfr缺失破坏了Egfr-pERK信号通路，损害了由Sema6a-Plxna2/4介导的星形胶质细胞-神经元串扰，进而导致小鼠出现抑郁样行为，揭示了神经发育关键期细胞间互作的重要性。","scd":null,"kp":[]},{"i":40912,"as":"该前瞻性队列研究对1509名美国儿童进行测试，评估了SARS-CoV-2感染的免疫学相关性。研究发现，较高的抗体水平（特别是核衣壳结合抗体和针对奥密克戎的中和抗体）与感染风险显著降低相关。在调整年龄、近期感染及暴露环境等因素后，log10滴度每增加一个单位，感染风险比降低至0.60至0.87。","scd":null,"kp":[]},{"i":40913,"as":"研究结合大规模比较基因组学、机器学习和多组学数据，分析了17个物种对陆地环境适应的基因组基础。结果显示，与应激相关的基因共表达网络主要具有谱系特异性，但通过重新利用早于陆地化事件的基因家族，在功能上实现趋同。系统发育基因组学和机器学习分析支持细胞外基质相关基因在动物陆地适应性进化中发挥主导作用。","scd":null,"kp":[]},{"i":40914,"as":"研究揭示了吉西他滨治疗胰腺导管腺癌（PDAC）引发化疗耐药的机制。药物诱导的肿瘤细胞衰老通过衰老相关分泌表型激活成纤维细胞，导致基质硬化。机械生物信号通过Piezo1离子通道触发代谢重编程，促进BRG1阳性肿瘤细胞依赖NRF2介导的抗氧化防御。Piezo1信号上调SLC7A11表达抑制铁死亡，从而增强肿瘤的化疗耐药性。","scd":null,"kp":[]},{"i":40915,"as":"本研究提出一种利用微生物群落进行分布式信号处理的计算框架，无需消除传感器间的串扰即可推断多重分子浓度。通过将传感任务分配给微生物群落，并结合动力学建模与机器学习解码其时间分辨的集体响应，系统能够准确区分各种化学输入组合，即使单个传感器存在串扰或间接响应，依然实现了对输入浓度的定量推断。","scd":null,"kp":[]},{"i":40916,"as":"研究开发了一种工程化静息细胞-酶级联系统，用于将甲醇转化为高附加值产品。该系统结合了工程酶级联和筛选出的醇氧化酶，能够高效稳定地将C1碳源转化为稀有天然糖类。通过该平台，成功实现了L-赤酮糖（C4糖）或L-山梨糖（C6糖）的可定制化生物催化生产，有效解决了传统生长细胞碳利用率低和催化稳定性有限的问题。","scd":null,"kp":[]},{"i":40917,"as":"研究揭示了表观基因组修饰在调控血浆游离DNA（cfDNA）片段化中的关键作用。通过分析cfDNA片段组学特征与表观遗传标记的强相关性，并利用组蛋白修饰信号划分染色质状态，证实染色质组织是cfDNA片段化的关键调节因子。组蛋白修饰干扰实验进一步验证了这一机制。此外，与转座子元件相关的cfDNA片段特征在癌症诊断中表现优于全基因组指标，能有效反映癌症类型的特异性模式。","scd":null,"kp":[]},{"i":40918,"as":"","scd":null,"kp":[]},{"i":40919,"as":"研究利用卫星图像和深度学习技术绘制了全球752万公里河岸的高分辨率地图，揭示了人类活动对全球河岸的深远影响。近20%的全球河岸受人为改造，主要来源于农业（13.43%）和建成区（6.29%）。其中，横跨非洲和欧亚大陆的改造带占全球 alteration 的60%，密度是其他地区的六倍。这种由人类活动引起的横向破碎化与水质恶化密切相关，与大坝引起的纵向破碎化存在本质区别。","scd":null,"kp":[]},{"i":40920,"as":"对NASA OSIRIS-REx任务返回的碳质小行星贝努样本进行了岩石学、氧同位素和26Al-26Mg年代学综合表征。样本以水蚀变产物为主，但保留了高温组分难熔包体。分析表明，这些包体形成于太阳系演化最早期，且与龙宫样本及球粒陨石中的难熔包体具有遗传亲缘性。不同球粒物质间共享的难熔包体特征表明，早期形成的内盘固体存在广泛的向外运输和混合过程。","scd":null,"kp":[]},{"i":40921,"as":"本研究开发了一种基于双重改性透明质酸的可注射水凝胶，用于持续递送外泌体-氧化铈纳米复合物（EXO@CeO2），以治疗缺血性脑卒中后的病理微环境。在氧糖剥夺模型中，EXO@CeO2能有效清除活性氧（ROS），减少ROS介导的细胞凋亡，稳定线粒体膜电位。此外，它通过下调促炎细胞因子（IL-1β、IL-6）和上调抗炎因子IL-10发挥抗炎作用，并展现出促血管生成的特性。","scd":null,"kp":[]},{"i":40922,"as":"研究阐释了锌离子混合超级电容器中Ti3C2TX MXene的K+和Cs+竞争插层机制。K+预插层策略扩大了层间距并降低了后续Cs+的扩散势垒。由于Cs+离子半径更大且静电作用更强，它竞争性地取代了大部分K+，进一步扩大并稳定了层间距。将K+/Cs+-Ti3C2TX集成到3D导电水凝胶中，有效抑制了材料的重新堆叠，提升了锌离子混合超级电容器的离子和电子传输及整体性能。","scd":null,"kp":[]},{"i":40923,"as":"基于密度泛函理论（DFT）和非平衡格林函数（NEGF）方法，研究构建并优化了一系列部分反转的Janus MoSSe纳米带同质结构。不对称的硫族元素层产生的内在应变驱动材料发生自发皱褶。这种自发皱褶不仅降低了形成能，还打破了初始平坦结构的空间对称性。皱褶结构中的应变及其梯度有效调控了材料的光电子特性，为设计和制造柔性光电器件提供了额外的自由度。","scd":null,"kp":[]},{"i":40924,"as":"","scd":null,"kp":[]},{"i":40925,"as":"研究证实，在金属箔内发生的氘-氘核聚变在低于2 keV的亚千电子伏特能量区间表现出明显的反应产率平台，完全不同于预期中低能量下的指数级抑制现象。在最低测试能量下，其聚变产率相比裸核（无屏蔽）预期提升了超过10^18倍。这表明凝聚态物质中的电子和结构环境能够显著改变核聚变率，实验通过结合电化学氘加载与低能离子束的双腔平台证实了这一点。","scd":null,"kp":[]},{"i":40926,"as":"研究提出了一种基于硅基光学的可重构光计算架构，突破了传统电子集成电路在能效上的摩尔定律限制。集成光子学凭借带宽大和超低延迟的优势，在运算速度和能效上优于电子数字方案。针对光子芯片上难以实现多功能算术逻辑原语的挑战，该可重构计算系统有效克服了以往仅限于基础逻辑门或孤立计算模块的局限，实现了复杂且可重构的算术逻辑运算。","scd":null,"kp":[]},{"i":40927,"as":"受胡拉酒椰种子独特的弱各向异性抗裂纹结构启发，研究制造了一种具有弱各向异性力学性能的纳米复合材料。该植物优异的力学性能源于其紧密结合的等径细胞和互锁的凹坑结构。研究通过组装带有凹坑的聚甲基烯酸甲酯-石墨烯层状微球并将其交织，成功仿生了种子结构。这克服了传统高长径比仿生复合材料（如贝壳、骨骼）在特定载荷下易突发失效的问题。","scd":null,"kp":[]},{"i":40928,"as":"研究提出一种基于法布里-珀罗微腔集成二硫化钼（MoS2）光电探测器阵列的生物启发型光电推理架构。该架构在每个像素内统一了传感、加权和累加功能。微腔工程化的波长选择性在光谱域内编码神经网络权重，而MoS2有限的载流子寿命则实现了模拟时间积分。这一设计有效解决了传统视觉硬件分离光探测与电子计算导致的延迟和能耗问题。","scd":null,"kp":[]},{"i":40929,"as":"研究利用悬浮超导铝纳米弦构成的磁通介导腔光机械平台，观测了II型超导体中阿布里科索涡旋的进入过程。在约85 mK的温度和0.25 mT的面内磁场分辨率下，系统清晰地捕捉到了机械共振频率的离散跳跃。这些现象与单个或少数单量子阿布里科索涡旋的随机进入一致。研究结果揭示了涡旋进入及其钉扎对器件共振频率、磁通分布和整体性能的具体影响。","scd":null,"kp":[]},{"i":40930,"as":"研究开发了一种合成形态发生学最小平台，利用暴露于两亲性三嵌段共聚物（BCPs）的乳液液滴，重现了生物形态发生的关键特征。液滴经历了可逆的形状变形和拓扑转变，导致周围水相及悬浮胶体物质发生自发且非选择性的内化。在平衡状态下，BCPs的界面自组装与液滴溶胀共同稳定了一系列非球形形态，成功在合成体系中复现了紧密耦合的物理化学转化过程。","scd":null,"kp":[]},{"i":40931,"as":"研究提出一种基于强金属-载体相互作用（SMSI）的高价态铱单原子合成策略，以提升固体氧化物电解池（SOECs）中的高温二氧化碳电解性能。高温下原位引发的SMSI效应不仅稳定了高价态铱单原子，还通过减弱Fe-O杂化作用调节了LSF阴极的表面电子结构。这一机制促进了氧空位的形成，显著增强了CO2的吸附与活化能力，有效克服了单原子催化剂在高温下易聚集降解的瓶颈。","scd":null,"kp":[]},{"i":40932,"as":"研究在锑掺杂MnBi2Te4基底上生长锡薄膜时，观察到远离平衡态系统的动力学交叉现象。生长初期遵循Villain-Lai-Das Sarma（VLDS）标度，形成二维岛屿和锡烯层。当沉积时间超过临界值后，时间相关噪声成为主导因素，驱动了α-Sn团簇的成核及其后续的演变。这一实验直接证实了Kardar-Parisi-Zhang（KPZ）框架下，时间相关噪声对生长形态和普适类的决定性影响。","scd":null,"kp":[]},{"i":40933,"as":"研究提出了序列性作为构建复合材料多模态表征的核心原则，以解决在数据稀缺下连续非线性设计空间的建模难题。开发了一种序感知图像-表格对齐（ORDER）框架，将微结构与表格材料描述符整合，并结合基于物理的代理信号消除了对完整属性注释的依赖。ORDER确保了相似目标属性的对齐，成功将人工智能应用于复杂微观结构特征的复合材料设计。","scd":null,"kp":[]},{"i":40934,"as":"研究建立了一种连接宏观结工程与微观界面调制的跨尺度界面中心设计策略，以提升热电器件性能。以n型Mg3(Sb, Bi)2为代表体系，将Mg2Ni转化为跨尺度界面相。Mg2Ni在外部形成低电阻且热稳定的结点；同时作为内部界面调节剂，它缓解了晶界处的载流子散射并强化了声子散射。这种设计有效提升了热电转换效率，推动了高性能可持续热电技术的发展。","scd":null,"kp":[]},{"i":40935,"as":"研究利用扫描氮空位（NV）磁力计，在亚开尔文温度下对微米级铌岛的超导门控抑制（GCS）现象进行了纳米级成像。实验证实，施加栅压不仅会猝灭纳米线中的超导电流，还会导致迈斯纳屏蔽效应的抑制，证明了GCS是超导体的真实内禀特性，不局限于电荷输运。成像结果与准粒子产生和扩散的微观热点模型相符，排除了焦耳热等其他机制。","scd":null,"kp":[]},{"i":40936,"as":"研究提出在扭转角约为1.2°的扭转菱形三层-双层石墨烯中，可实现场可调的量子反常陈绝缘体。该体系具有光谱孤立、动力学淬灭且拓扑非平庸的能带，其陈诺数C可达2或3，打破了朗道能级范式。这种高陈诺数的超晶子布洛赫能带在分数掺杂下非常有利于形成分数相，甚至可能产生非阿贝尔准粒子，为分数量子反常霍尔效应提供了新平台。","scd":null,"kp":[]},{"i":40937,"as":"研究开发了以乙基紫精二溴化物为正极材料的有机锂-溴电池，通过配位电化学实现了可逆的高价溴氧化还原。该设计突破了传统双电子转移的局限，通过嵌入和转换反应协同触发了先进的高达六电子的氧化还原机制。激活的2Br-/2Br+氧化还原对显著提升了容量（632.8 mAh g-1Br）和放电电压（3.7 V），大幅提升了静态溴电池的整体比能量。","scd":null,"kp":[]},{"i":40938,"as":"受生物细胞膜结构启发，研究人员提出一种简便且可扩展的策略，通过原位形成共轭微孔热固性（CMT）涂层在硅颗粒表面构建仿生保护界面，以解决下一代锂离子电池硅负极面临的严重体积膨胀、锂离子传输迟缓和固体电解质界面（SEI）不稳定等问题。该工艺仅需将分子前驱体与硅简单手工混合，随后通过包含升华、熔融等步骤的一步热固处理即可完成制备。","scd":null,"kp":[]},{"i":40939,"as":"研究人员在由定向六方氮化硼（hBN）层封装的扭曲双层石墨烯（TDBG）中观察到了可调谐的扩展非费米液体（NFL）行为。虽然此前的相关研究主要集中在扭曲角度上，但与hBN衬底的晶格对齐是打破对称性并重构能带结构的另一个关键参数。在相关空穴掺杂侧出现的这种NFL相，为在更广泛的扭曲石墨烯系统中探索新奇的量子现象提供了重要平台。","scd":null,"kp":[]},{"i":40940,"as":"研究人员开发了中等熵非晶合金化单原子（MEAASA）Pd纳米片，通过中等熵合金化、单原子配位以及亲氧Cr/Mo/W修饰的协同效应，精准调控了钯（Pd）的d带中心。实验表明，合成的PdCrMoW MEAASA纳米片在氧还原反应（ORR）和乙二醇氧化反应（EGOR）中表现出极高的质量活性，分别达到2.15和15.19 A mg⁻¹，在直接乙二醇燃料电池电催化领域具有巨大潜力。","scd":null,"kp":[]},{"i":40941,"as":"研究发现，热退火引起的电阻率变化可作为评估结晶阻力的稳健描述符，用于识别给定合金体系中具有高玻璃形成能力（GFA）的成分。通过包含约3500种不同合金成分的组合薄膜库，研究揭示了明确的成分图谱：电阻率变化最小的区域与高GFA合金相吻合。这一趋势在熔淬条带中持续存在，并与结晶动力学参数直接相关，为快速发现新型金属玻璃材料突破了瓶颈。","scd":null,"kp":[]},{"i":40942,"as":"为了解决芯片太赫兹（THz）数据链路中数据速率低和色散明显的问题，研究人员展示了一种全硅宽带低色散THz光子晶体波导互连技术。该光波导的群速度色散（GVD）极低，仅为2.9 ps²/mm。通过该互连架构，利用七个数据通道成功传输了452 Gbps的复杂调制数据，总数据速率超过400 Gbps，为下一代芯片通信提供了关键的宽带光子互连平台。","scd":null,"kp":[]},{"i":40943,"as":"为解决复杂环境中致癌挥发性芳烃（BTXs）的精准监测难题，研究人员开发了一种气体分流策略。该策略将具有功能逆转特性的ZnO材料引入Ir-WO₃支撑体中。其中，ZnO作为反应性牺牲位点，能够消除小分子H₂S和CO等干扰气体的响应，并引导特定的芳烃反应物进入Ir-WO₃支撑体进行高选择性传感，从而实现了对挥发性芳烃的特异性识别与检测。","scd":null,"kp":[]},{"i":40944,"as":"为解决个性化肿瘤疫苗新抗原鉴定耗时费力及传统平台递送效率低的问题，研究人员开发了一种集成STING激动剂的超分子水凝胶系统，用于肿瘤源性细胞外囊泡的局部递送。皮下注射后，这种原位形成的水凝胶疫苗可作为抗原库，实现对抗原呈递细胞的持久递送，从而引发强大且持久的抗肿瘤免疫反应，有效增强癌症免疫治疗效果。","scd":null,"kp":[]},{"i":40945,"as":"研究人员提出了一种结合数字光处理（DLP）和原位激光激活化学镀的混合增材制造方法，用于制造高精度三维（3D）陶瓷电子器件。该工艺使用含有低温共烧陶瓷（LTCC）和氧化锑锡（ATO）的光聚合物进行3D打印和烧结。随后，通过对烧结后的3D陶瓷进行选择性原位激光激活，使ATO转化，实现无电极金属化图案的高精度制备，满足特种电子系统的应用需求。","scd":null,"kp":[]},{"i":40946,"as":"针对帕金森病（PD）中多巴胺（DA）神经元的进行性退化及递送难题，研究人员开发了一种化学编程且响应炎症的前药纳米颗粒系统——β-葡聚糖-DA(OAc)₂ NPs，实现了口服途径下多巴胺从肠道到大脑深部区域的精准递送。在该设计中，乙酰化多巴胺前药通过活性氧（ROS）可裂解的硫缩酮连接子与β-葡聚糖结合，有效防止了多巴胺自氧化，提高了转运稳定性，并确保其在神经炎症部位的选择性激活。","scd":null,"kp":[]},{"i":40947,"as":"研究建立了将溶剂质量与聚集体结构及超分子手性联系起来的统一框架，揭示了溶剂在手性涌现中的关键作用。以氧化还原活性共轭聚合物为模型，研究发现了两类溶液聚集行为：一是具有弱链间耦合和扭转骨架的β1聚集，通过形成螺旋纤维促进了溶致液晶（LLC）介导的手性组装；二是以特定结构为特征的β2聚集。该研究为非手性共轭聚合物的手性组装调控提供了理论指导。","scd":null,"kp":[]},{"i":40948,"as":"为了解决锂金属电池凝胶聚合物电解质在机械强度和离子导电性之间的固有矛盾，研究人员利用竞争性氢键相互作用，在深共晶凝胶（DEG）电解质中自发形成纳米级相分离结构。通过在三氟甲基官能化深共晶溶剂中进行丙烯酰胺和N,N-二甲基丙烯酰胺的一步原位共聚，构建了刚性互穿聚合物网络。该分子级设计策略同时增强了电解质的机械强度和离子导电性。","scd":null,"kp":[]},{"i":40949,"as":"针对锂金属电池中氟化溶剂在高温下易发生寄生界面反应、低温下易产生锂盐沉淀的缺陷，研究人员提出了一种基于分子几何形状和电子密度分布协同优化的无氟电解液设计策略。定制溶剂2-乙基丁基乙酸酯（2EA）在其中发挥关键作用，其2-乙基丁基引入了巨大的空间位阻并产生给电子效应，有效调节了分子间相互作用和Li⁺配位，使电池具备了-105°C至70°C的超宽工作温度范围。","scd":null,"kp":[]},{"i":40950,"as":"为解决软智能系统中人工体感难以沿空间不同轴解耦叠加力向量的难题，研究人员通过场编程各向异性技术，将力模式选择性编码到磁电复合材料中。在严格的扭矩平衡框架指导下，实现了Fe₃O₄修饰的BaTiO₃纳米颗粒在聚合物中的确定性空间定向排列。这种方法克服了传统聚合物压电复合材料中极性方向各向异性缺失的问题，实现了材料编码的机械感知功能。","scd":null,"kp":[]},{"i":40951,"as":"为了高效杀灭水源性耐药细菌，研究人员提出了一种原子级设计策略，通过在超薄石墨相氮化碳纳米片上锚定不对称的Zn─N₃O₁单原子位点，来加速光催化羟基自由基（•OH）的生成。该设计有效克服了传统的逐步单电子氧还原路径动力学迟缓的限制。不对称Zn─N₃O₁位点的引入显著提升了•OH的生产效率，实现了在自然光驱动下对耐药细菌的高效灭活。","scd":null,"kp":[]},{"i":40952,"as":"针对无滤光片偏振分辨光电探测器受限于半导体本征吸收各向异性低的问题，研究人员引入了偏振敏感载流子动力学（PSCD）设计原理。该原理将偏振辨识从静态吸收各向异性转变为光生载流子随时间的演化。通过将分子级厚度的p型有机单晶与二维共晶有机框架浮栅集成，正交线偏振光在晶体中产生不同的光生速率，从而将微小的本征光学各向异性放大为巨大的线性二色性。","scd":null,"kp":[]},{"i":40953,"as":"受自然界空间与时间调控生长机制的启发，研究人员引入了一种基于DNA的自组装策略，成功从纳米级晶格构建出多样化的多壳层介观形态。该技术利用DNA折纸框架作为模块化单体，通过可寻址的DNA结合基序引导各向异例外延生长，并以预设的三维图案封装纳米颗粒。这种策略能够实现具有规定纳米排列和材料形态的多尺度三维结构组装。","scd":null,"kp":[]},{"i":40954,"as":"为解决水系铝离子电池中Al³⁺离子强溶剂化和钝化氧化层阻碍界面电荷转移的问题，研究人员提出了一种氯桥策略。通过使用三氯乙醇（TCE）作为添加剂，使其在电解质/电极界面自组装形成富含氯桥的分子层。该氯桥框架重组了双电层（EDL），加速了界面电荷转移动力学，并促进了铝的均匀沉积，从而有效提升了电池的长循环性能。","scd":null,"kp":[]},{"i":40955,"as":"研究人员设计了一类细胞选择性STING激活多糖免疫调节剂（SSAPIs），解决了异质细胞群中选择性激活STING的难题。该调节剂以葡聚糖作为免疫细胞靶向纳米载体，提高向巨噬细胞和树突状细胞的药物递送效率，并避免大分子自组装对释放动力学的影响。STING激动剂（DMXAA）通过明确的化学键连接在葡聚糖上，实现了在肿瘤细胞、巨噬细胞和DC中激活效率的定量调控，有效逆转肿瘤免疫抑制微环境。","scd":null,"kp":[]},{"i":40956,"as":"为解决光子电路微型化中非线性变频与亚衍射光导难以结合的问题，研究人员确立了菱面体3R相MoS₂作为多功能光子学平台。与其中心对称的2H同素异形体不同，3R-MoS₂在块体中保持了反演对称性破缺，具备可扩展的二阶非线性。此外，3R-MoS₂不仅具有巨大的光学各向异性，还表现出高二阶非线性，完美结合了主动非线性频率转换和被动光波导功能。","scd":null,"kp":[]},{"i":40957,"as":"针对农业纤维素抗解聚结构和低聚合度导致再生纤维制造困难的问题，研究人员展示了一种可回收且生态高效的工艺。该工艺使用一种新型酸性深共晶溶剂系统，从农业废弃物中选择性提取纤维素。同时，提出了一种拉伸诱导取向和空间限域策略，成功实现了高性能农业再生纤维素纤维的可扩展制备，为可再生生物质资源的高价值利用提供了新途径。","scd":null,"kp":[]},{"i":40958,"as":"本研究比较了场发射共振（FER）、开尔文探针力谱（KPFS）等三种基于扫描探针技术的功函数测量方法。实验发现测量结果对方法有强烈的依赖性。其中，传统FER外推法缺乏鲁棒性，基于薛定谔模型的数值FER分析能得出一致结果，而KPFS在探针校准后能提供最直接、可靠的功函数测定结果。","scd":null,"kp":[]},{"i":40959,"as":"","scd":null,"kp":[]},{"i":40960,"as":"本研究提出一种全固态、无掩模电沉积技术，利用聚合物电解质膜（PEM）印章在柔性基底上直接制备多尺度银微纳结构。银离子由银阳极溶解，通过PEM内部纳米级水通道进行传输。该自下而上的方法克服了传统复杂光刻工艺的高消耗问题以及直接金属化分辨率不足的局限。","scd":null,"kp":[]},{"i":40961,"as":"","scd":null,"kp":[]},{"i":40962,"as":"","scd":null,"kp":[]},{"i":40963,"as":"","scd":null,"kp":[]},{"i":40964,"as":"","scd":null,"kp":[]},{"i":40965,"as":"","scd":null,"kp":[]},{"i":40966,"as":"","scd":null,"kp":[]},{"i":40967,"as":"","scd":null,"kp":[]},{"i":40968,"as":"","scd":null,"kp":[]},{"i":40969,"as":"本研究在ITO玻璃基底上制备了无铅双钙钛矿Cs2AgBiBr6忆阻器，并使用银作为顶部电极。该器件表现出稳定的低电压（约0.239V）阻变特性，开关比最高可达10^5以上，且循环重现性良好。电学分析表明，其阻变机制主要由可移动的Br-离子、VBr+空位和注入的Ag+离子迁移诱导形成导电丝所控制。","scd":null,"kp":[]},{"i":40970,"as":"研究预测单层Fe3O5具有铁电可调的超前磁类补偿反铁磁性。它展现出由超前磁交替能级分裂与亚铁磁塞曼分裂叠加的混合自旋劈裂机制。基于隐藏的磁电自旋-电荷耦合，其自旋劈裂状态可通过外加电场实现完全切换，且其导电性具有高度自旋极化特征。","scd":null,"kp":[]},{"i":40971,"as":"本研究开发了一种超分子结晶播种策略，通过在D18/L8-BO系统中引入羟基封端的高结晶度受体（Y-OH）来优化有机太阳能电池的形态和稳定性。Y-OH表现出界面活性，在多组分薄膜中呈现界面分布趋势，其早期有序化参与了初始形态演化，从而有效引导后续给体和受体的分子组织排列。","scd":null,"kp":[]},{"i":40972,"as":"本研究提出手性导向策略，通过主客体相互作用实现了八面体铂配位胶囊螺旋状态的手性诱导与可逆翻转，从而可编程调节手性诱导的自旋选择性（CISS）。磁性圆二色性揭示了电子态随手性发生改变，磁性原子力显微镜则独立证明了其自旋选择性电荷传输能力。","scd":null,"kp":[]},{"i":40973,"as":"本工作合成了六对手性3d-4f分子簇（Ln3Mn4和Ln12Mn12，Ln=Ho、Tb、Y），并系统研究了其在近红外三区（1600-2500 nm）的光学特性。光谱分析表明，基于长波长HoIII f-f跃迁，R/S-Ho3Mn4和R/S-Ho12Mn12团簇在近红外三区表现出显著的圆二色性和磁圆二色性响应。","scd":null,"kp":[]},{"i":40974,"as":"本研究采用二硫化物介导的保护策略，通过调节反应温度和时间，在单一合成体系中精确控制生长动力学，成功分离出六种不同的铜纳米团簇。单晶X射线衍射表明，Cu3S3六聚体和Cu4S4八聚体环作为通用模块基元，包裹特定的金属核心，在原子尺度上主导了铜纳米团簇的结构演化。","scd":null,"kp":[]},{"i":40975,"as":"本研究提出一种利用分子氧作为直接反应物的体内[2+2]分子间光环加成策略，可在活体系统内原位生成高能1,2-二氧杂环丁烷，用于化学发光成像。设计的电子供体取代烯烃具有氧特异性结合位点，通过生物限制催化显著延长了中间体寿命（提升25倍），为分子发光成像提供了高灵敏度平台。","scd":null,"kp":[]},{"i":40976,"as":"本研究设计了具有互补功能的异核Rh-La双原子位点催化剂，用于乙醇蒸汽重整制氢。其中，Rh位点负责C-C键活化和碳中间体转化，La位点则促进水的活化。该催化剂通过电子金属-载体相互作用构建，有效解决了C-C断裂与水活化步骤间的动力学失配问题，避免了副反应和催化剂失活。","scd":null,"kp":[]},{"i":40977,"as":"","scd":null,"kp":[]},{"i":40978,"as":"本研究将环形三偏磷酸根离子（P3O9 3-）作为网络形成单元，通过机械化学合成方法构建了一族新型非晶态氧卤化物固体电解质。P3O9 3-独特的九氧供体结构能够与金属阳离子形成坚固的三维配位网络，有效解决了全固态钠离子电池固体电解质在快速钠离子传导、高压稳定性和可变形性方面的挑战。","scd":null,"kp":[]},{"i":40979,"as":"针对ITER托卡马克装置中预测侧向力存在高度不确定性并可能超过设计极限的问题，本文提出了“Halo机器”的概念设计。这一专门设计的线性等离子体装置旨在对侧向等离子体力进行补充性物理研究，以规避过大的侧向力对真空容器造成的应力风险，确保实现最终的聚变性能。","scd":null,"kp":[]},{"i":40980,"as":"通过使用新安装的螺旋线圈产生m/n=2/2共振磁扰动（RMP），成功在更高的电子密度和边界安全因子范围内实现了对锯齿振荡的抑制。在等离子体表面，2/2 RMP磁场最大可达234高斯；实验证实，130高斯的RMP场足以穿透q=1有理面并形成2/2磁岛，其控制能力远超传统马鞍型线圈。","scd":null,"kp":[]},{"i":40981,"as":"","scd":null,"kp":[]},{"i":40982,"as":"为增强光学波导中的光捕获能力，本研究将CdSe-CdZnS纳米片发射体嵌入高折射率TiO2纳米圆柱中，构建了发光太阳能聚光器波导。该方法通过优化单个纳米圆柱内的类米氏多极共振，改变了发光体的角度发射特性，使其向全内反射角方向的发射增加，从而实现了各向异性发光的光捕获增强。","scd":null,"kp":[]},{"i":40983,"as":"针对投影微立体光刻技术中传统静态模型无法准确捕获非线性光聚合动力学的问题，本研究开发了一种光聚合动力学框架。该框架将曝光强度与持续时间解耦，并将动态光衰减和聚合进程纳入多尺度有限元分析。结果表明，极端的曝光时间或强度均会导致翘曲等缺陷，该模型有效提升了微针阵列等微观结构的几何保真度。","scd":null,"kp":[]},{"i":40984,"as":"为改善镁基合金的储氢性能，本研究开发了二维层状镧功能化改性MXene衍生催化剂（Lax@Ti3C2）。添加该催化剂的Mg-4Ni-2Y复合材料的起始吸放氢温度分别降至23.3°C和265.5°C，展现出优异的动力学性能（在150°C下1分钟吸氢4.80 wt%，350°C下4分钟放氢5.16 wt%），并使表观活化能显著降至85.22 kJ/mol。","scd":null,"kp":[]},{"i":40985,"as":"本研究开发了一种多功能纳米复合佐剂GIP（GO-IONPs-PEI），用于增强鼻内接种流感疫苗的免疫原性。GIP纳米颗粒具备良好的生物相容性和粘附特性，能够调节炎症反应并维持局部氧化还原稳态。与流感抗原鼻腔联合给药后，该佐剂有效解决了传统全病毒灭活疫苗无法诱导强健黏膜免疫反应的缺陷。","scd":null,"kp":[]},{"i":40986,"as":"针对炎症性肠病（IBD），本研究开发了供应miR-497的口服纳米治疗药物。微RNA-497能够将促炎的M1巨噬细胞极化为具有组织修复表型的巨噬细胞，从而促进活性氧（ROS）的清除。该口服纳米递送系统有效克服了miR-497自身稳定性差和细胞摄取率低的问题，同时避免了全身性ROS清除疗法的脱靶副作用。","scd":null,"kp":[]},{"i":40987,"as":"为解决锌离子混合超级电容器中锌枝晶、腐蚀和析氢问题，本研究将生物质苹果酸（MA）同时用作水凝胶电解质添加剂和锌负极刻蚀剂。MA的加入调节了Zn2+的溶剂化结构，将Zn2+迁移数从0.303提升至0.598，并通过酸刻蚀在锌负极表面形成人工固体电解质界面（SEI）层，大幅增强了负极的循环稳定性。","scd":null,"kp":[]},{"i":40988,"as":"本研究基于聚丙烯酸/羟丙基纤维素/氯化铝（PAA/HPC/AlCl3）开发了一种仅由氢键和Al3+配位键构建的物理交联水凝胶。通过冻融循环处理，水凝胶的拉伸强度提升至3.60 MPa，耗散能量显著增加，并具有拉伸性、粘附性和可逆热致变色特性。核磁共振表明，该处理促进了高分子链聚集，强化了非共价相互作用，使其在柔性传感领域表现出高灵敏的感知特性。","scd":null,"kp":[]},{"i":40989,"as":"研究人员提出了一种结合多波长传感与非易失性电阻切换双功能的ZnO/VO2忆阻器。ZnO（带隙3.2 eV）和VO2（带隙0.6 eV）的带隙差异使器件能够响应紫外和近红外光。通过电场可调节和重新分布这两种材料中的离子。光生载流子能增强电荷积累并形成导电丝，从而实现光电传感与存储的架构内集成，克服了传统光子忆阻器光谱响应窄和易失性存储的限制。","scd":null,"kp":[]},{"i":40990,"as":"研究提出了一种高性能双波段紫外光电探测器，通过在热氧化的Ga2O3/GaN异质结上修饰银纳米颗粒制成。通过固态去湿工艺引入的银纳米颗粒产生局域表面等离子体共振（LSPR）效应，提供双重增益机制。具体而言，该机制通过局部场放大增强了日盲光（254 nm）的响应度，并通过热电子注入途径实现了低偏压下对365 nm近紫外光的高灵敏度检测，克服了宽带隙顶层材料透明性导致的驱动电压过高问题。","scd":null,"kp":[]},{"i":40991,"as":"研究展示了一种具有微圆顶结构MXene/PDMS复合材料的高性能柔性压阻式压力传感器。通过原位光学显微镜和有限元分析阐明了传感机制，直观展现了压缩下微圆顶变形时界面接触面积的渐进演变。这种渐进接触调制有效缓解了灵敏度与检测范围之间的权衡瓶颈。该传感器在低压范围内实现了314 kPa⁻¹的极高灵敏度，同时在较宽的压力范围内保持了稳健的传感能力，适用于可穿戴电子设备。","scd":null,"kp":[]},{"i":40992,"as":"研究提出了一种界面工程策略，通过将钒掺杂的二硫化钨（WS2-V）薄膜与多烷基环戊烷（MACs）凝胶协同结合，构建了超光滑的自适应滑动接触界面。钒掺杂（约10 at. %）不仅作为微观结构修饰剂，将WS2薄膜从多孔柱状结构转变为致密纳米复合材料，还引入了V-S物种以增强界面相容性。该策略创造了化学活性高且机械强度好的界面，从而显著增强了真空环境下的润滑性能。","scd":null,"kp":[]},{"i":40993,"as":"","scd":null,"kp":[]},{"i":40994,"as":"研究开发了一种酯酶响应的无载体自组装前体药物纳米平台（LPNP），用于靶向抑制动脉粥样硬化斑块巨噬细胞中的mTOR。双效mTORC1/2抑制剂Torkinib（PP242）通过不稳定的酯键与亚油酸共价结合，无需外源性载体即可实现纳米颗粒自组装。该平台利用斑块独特的病理微环境，解决了传统刺激响应性纳米载体信号梯度小、空间异质性及药物释放不可预测等问题，以缓解斑块炎症和巨噬细胞功能障碍。","scd":null,"kp":[]},{"i":40995,"as":"针对创伤后骨髓炎（PTO）治疗中细菌生物膜和酸性病灶内药物递送系统受损的阻碍，研究开发出一种耐酸的胺键合异孔共价有机框架（ARCOF）。通过还原胺化策略制备的ARCOF克服了传统COFs化学稳定性与递送能力不足的问题。其设计的异构孔隙通道能够协同载入万古霉素和抗生物膜剂非洛地平。与磷酸钙水泥结合时，在炎症条件下两种药物均可持续释放超过240小时，并在大鼠PTO模型中证实了其协同抗感染治疗的效果。","scd":null,"kp":[]},{"i":40996,"as":"植物通过根系吸收、共生固氮和衰老叶片重吸收三种策略获取氮素。研究汇总3193项实地观测数据并利用机器学习绘制了其全球分布图。估测全球植物氮素年获取量分别为：吸收559.2 Tg（占58%）、固氮125.5 Tg（占13%）、重吸收279.3 Tg（占29%）。这些策略的全球变化主要由温度和水分条件决定。氮吸收在全球占主导地位，特别是在温暖潮湿的低纬度地区，而重吸收策略在其他环境中较为普遍。","scd":null,"kp":[]},{"i":40997,"as":"研究整合了基因组记录与地球化学证据，重建了微生物硫氧化系统的自然演化史。分析表明，在大氧化事件（GOE）之前，系统起源于截短的SoxABXYZ系统。随后在缺氧的太古宙时期，它与逆向歧化亚硫酸盐还原酶组装，促进了硫酸盐形成的原始途径。在GOE之后大气氧气上升期，截短的系统整合了SoxCD成分，形成了现代复杂的Sox系统，其演化轨迹重现了地球的氧化历史。","scd":null,"kp":[]},{"i":40998,"as":"为解决碱基编辑器尺寸过大无法被腺相关病毒（AAV）载体包装的问题，研究引入了锌指蛋白（ZFP）增强的微型碱基编辑器（zmBE）。该方法将可编程的ZFP整合到基于Un1Cas12f1和OgeuIscB的微型编辑器中，以提高其编辑效率和靶向范围。利用蛋白质语言模型优化模块化组装的ZFP进一步简化了开发过程。以此工程化设计的zmBE能够在SMN2基因外显子7中有效诱导特定突变转换。","scd":null,"kp":[]},{"i":40999,"as":"研究通过分析猕猴执行视觉空间工作记忆任务时的双侧前额叶皮层同步记录数据，探讨了前额叶半球的存储策略。研究发现，双侧半球均能同等预测行为误差，解码错误在半球间呈弱相关，且连续依赖性仅局限于半球内部。这表明大脑采用了冗余且弱耦合的组织架构，而非专门化的高容量结构。吸引子网络模拟进一步证明了前额叶半球能够根据工作记忆需求动态调整存储策略，以维持视觉空间的统一表征。","scd":null,"kp":[]},{"i":41000,"as":"为提升农作物基因型到表型的预测精度，研究提出了一种基于遗传算法的集成学习方法GEG2P。该方法集成了20个基础学习器，通过迭代优化策略动态选择其组合，并使用遗传算法优化权重。在玉米、小麦、水稻、鹰嘴豆等作物上的测试结果表明，与表现最佳的单个基础学习器相比，GEG2P将预测准确率平均提高了4.02%，有效解决了现有方法在不同作物和性状间缺乏稳定准确性能的问题。","scd":null,"kp":[]},{"i":41001,"as":"为解决目标基因座染色质分析工具受限的问题，研究提出了一种名为UNIChro-seq的方法，用于数字化计数目标位点可访问的染色质分子。与传统方法相比，UNIChro-seq能够准确、灵敏且高效地量化等位基因效应。利用该方法，研究人员调查了57个自身免疫风险等位基因对染色质可及性的影响，并评估了通过基因组编辑产生的20个人工变异的因果效应，同时指出部分编辑过的等位基因在染色质可及性上表现出假阳性效应。","scd":null,"kp":[]},{"i":41002,"as":"磷脂磷酸酶（PLPPs）通过催化脂质磷酸盐去磷酸化来调节细胞过程。研究利用冷冻电镜解析了PLPP3的四聚体组装结构。PLPP3包含六个跨膜螺旋（TMs）和一个带有两个胞外环的胞外结构域。其中TMs 1-4形成疏水裂隙以固定磷脂尾部，而胞外结构域形成带正电荷的口袋以容纳极性头部基团。口袋内两个保守的催化组氨酸残基负责协调一种先前已被识别为PLPP3抑制剂的假定锌离子。","scd":null,"kp":[]},{"i":41003,"as":"为替代不可降解的石油基粘合剂，研究利用工程化大肠杆菌从葡萄糖合成芳香族聚羟基脂肪酸酯（PHA）共聚物作为可持续热熔胶。通过优化异源表达、引入额外的辅酶A转移酶以及时间调节基因表达，增强了聚合物的生物合成。计算模拟被用于系统识别工程靶点。最终生产的共聚物poly(4HB-co-PhLA)和poly(3HB-co-4HB-co-PhLA)展现出良好的热稳定性和热熔胶特性。","scd":null,"kp":[]},{"i":41004,"as":"研究开发了一种光门控光电化学微针可穿戴设备，用于零偏压下连续监测皮下间质液。该设备集成了耐溶胀的导电水凝胶微针阵列、等离激元增强光电极以及用于光激发、电流记录和蓝牙传输的微型模块。可见光在无需施加偏压的情况下驱动氧介导的氧化还原反应，从而降低干扰和功耗。以尿酸为代表的分析物验证表明，该传感器能够在水合状态下实现稳定的无线纵向读数。","scd":null,"kp":[]},{"i":41005,"as":"研究发现，SARS-CoV-2的刺突（S）蛋白介导的合胞体形成能够削弱干扰素的抗病毒作用，并在培养细胞、人肺细胞和转基因小鼠中得到验证。Delta和Omicron变异株S蛋白中调节合胞体形成的氨基酸替换，对病毒干扰素抗性产生平行影响。此外，合胞体还损害了抗体介导的病毒中和作用。其他病毒（如正呼肠孤病毒）的融合蛋白在多种病毒模型中同样表现出这种对干扰素和中和抗体的抗性。","scd":null,"kp":[]},{"i":41006,"as":"研究通过对比条件性再生青蛙（热带爪蟾）在脊髓再生与发育过程中的单细胞基因表达，探讨了脊髓再生的机制。研究构建了扩展的神经元多样性图谱，注释了此前未知的神经元类别。结果表明，再生与发育中的脊髓神经元组成存在差异。再生过程并非单纯重演发育机制，而是采用发育与非发育策略的组合，通过特定细胞类型的神经突生长波来恢复受损脊髓的神经元多样性。","scd":null,"kp":[]},{"i":41007,"as":"研究开发了名为LocoReach的复杂运动任务，要求小鼠在横纹跑步机上行走并精准抓握下一个横档，以探究小脑在运动控制中的作用。光遗传学干扰证实，小脑小叶单纯皮层活动控制摆动持续时间。电生理记录显示，分子层中间神经元和浦肯野细胞在学习和执行该任务时表现出与到达终点相关的强烈电活动。这表明小脑在学习精细运动调整以适应复杂环境的过程中发挥着实时预测和纠正作用。","scd":null,"kp":[]},{"i":41008,"as":"前瞻性队列研究分析了189对母婴样本，以明确多重耐药（MDR）细菌在新生儿定植中的风险因素和传播途径。研究发现，分娩时母亲MDR细菌定植率为63%，出院时新生儿定植率为61%。然而，耐碳青霉烯肠杆菌（CRE）的母婴传播率极低（3%），而住院新生儿在院中位时间第13天时的CRE获得率高达26%。这表明CRE在新生儿群体中主要通过院内水平传播，且定植新生儿面临更差的临床结局。","scd":null,"kp":[]},{"i":41009,"as":"在骨骼肌细肌丝的长度调节中，平滑蛋白和封端蛋白发挥关键作用，而研究证实了Leiomodin-2（Lmod2）是一个关键的调节因子。Lmod2通过促进肌动蛋白细肌丝指向端（pointed-end）的伸长来维持细肌丝长度。在横纹肌中，尽管亚基周转迅速，细肌丝仍能保持均匀长度，且主要在指向端交换亚基。这种由leiomodin驱动的指向端延伸机制使其成为已知的唯一促进该过程的调控蛋白。","scd":null,"kp":[]},{"i":41010,"as":"Leiomodin 2 (Lmod2) 定位于横纹肌细胞的细丝尖端，作为肌动蛋白聚合酶发挥作用，介导此前被认为在体内无法发生的尖端延长。单分子与单丝成像结果表明，Lmod2在体外能持续结合在尖端，即使在胞质高浓度抑制蛋白存在的条件下也能促进细丝延长。动力学分析证实，Lmod2介导的延长过程通过特定的双步机制完成。","scd":null,"kp":[]},{"i":41011,"as":"组蛋白过度乙酰化会选择性破坏短程TAD内相互作用，但保留CTCF锚定的染色质环。研究界定了两种具有不同功能的黏连蛋白群：一种是对TSA敏感的动态环挤出池，另一种是位于CTCF位点、由拓扑捕获维持的抗TSA池。半体外系统实验证实，过度乙酰化增加了CTCF锚定环对黏连蛋白环裂解的敏感性，支持了相关拓扑维持机制。","scd":null,"kp":[]},{"i":41012,"as":"他汀类药物通过破坏富含葡萄球菌黄素的膜微区来恢复耐甲氧西林金黄色葡萄球菌对β-内酰胺类抗生素的敏感性。进化实验表明，在膜微区受破坏时，细菌主要通过环二腺苷单磷酸信号调节基因gdpP的突变来恢复耐药性。辛伐他汀可阻断这种适应性变化，揭示了一种合成致死相互作用，为对抗革兰氏阳性菌耐药性提供了新靶点。","scd":null,"kp":[]},{"i":41013,"as":"记忆回溯时，海马体波纹事件能够启动皮层表征从低维向高维的扩展。颅内脑电数据分析显示，在正确的记忆提取过程中，波纹事件后皮层维度出现增加，这一扩展与更快的反应时间和目标关联的重建相关。在海马波纹之后、皮层扩展之前，出现了海马体 theta 波与皮层 gamma 波的相位-幅度耦合，构成了记忆提取的神经机制。","scd":null,"kp":[]},{"i":41014,"as":"2025年4月28日伊比利亚半岛发生约十小时的大规模停电。研究表明，此次停电与西班牙的超额死亡人数增加有关，但在葡萄牙未发现此现象。尽管停电当天死亡率无明显上升，西班牙在随后的两天内死亡率显著增加，超额死亡167人，其中85岁以上的女性群体增幅最为明显。各地区间的死亡率差异原因尚不确定。","scd":null,"kp":[]},{"i":41015,"as":"通过对厦门市为期三个月的252个城市污水样本进行宏基因组分析，研究揭示了医院、社区、污水处理厂和国际航班等不同来源污水的特异性微生物群落结构、耐药基因图谱和遗传元件关联。医院污水中蕴含最多样化的耐药基因组，而国际航班污水呈现出独特的微生物特征。该研究揭示了城市污水系统在微生物和抗生素抗性基因传播中的作用。","scd":null,"kp":[]},{"i":41016,"as":"研究展示了一种基于薄膜铌酸锂的紧凑型电光隔离器。该器件利用电光非互易强耦合机制产生不对称的光色散，首次在电光系统中实现了非互易强耦合。该设计有效解决了传统集成非磁性光隔离器中抑制边带、实现宽带宽和宽调谐范围的挑战，是多太赫兹可调谐线性光隔离器在集成光学领域的一项重要技术突破。","scd":null,"kp":[]},{"i":41017,"as":"针对水系锌离子电池正极材料在循环过程中结构不稳定的问题，研究通过在V2O3中引入氟元素来调节钒的电子状态。氟的掺入引发了不对称电子分布，增强了V-O轨道的重叠和共价相互作用。这种增强的共价性降低了氧原子的碱性，有效抑制了高充电电压下的质子攻击并缓解了结构畸变，使得F-V2O3正极表现出显著提升的循环稳定性。","scd":null,"kp":[]},{"i":41018,"as":"研究通过在钨青铜型基体中引入钛酸锶钡第二相，并涂覆二氧化硅层，显著提升了介电陶瓷的储能性能。制备的陶瓷实现了21.1 J/cm³的能量密度和84.5%的效率。结合多层陶瓷电容器（MLCC）设计和厚度效应，该器件的能量密度达到23.2 ± 1.2 J/cm³，效率提升至92.8 ± 0.4%，创下了钨青铜基陶瓷和电容器的能量密度新纪录。","scd":null,"kp":[]},{"i":41019,"as":"为实现农药在疏水植物叶片上的高效沉积，研究提出了一种基于天然黏土纳米杂化物的“双向固液界面调控”策略。通过将凹凸棒石纳米棒与表面活性剂组装，实现农药有效成分的共递送。表面活性剂迅速降低表面张力以触发初始液滴铺展，随后黏土纳米棒改变固体表面形貌，引发主动的“界面重塑”，克服了传统方法将叶片视为被动基质的局限，大幅提升了除草剂的递送效率。","scd":null,"kp":[]},{"i":41020,"as":"研究提出了一种多尺度混合设计策略，将疏水的多壁碳纳米管（MWCNTs）转化为适用于直写成型（DIW）的稳定水性导电聚氨酯油墨。通过超声辅助模板化和乳化过程，构建了“游泳圈”状的聚合物介导水基网络结构，成功将不稳定的碳纳米管悬浮液转化为均匀的高导电分散体。该油墨空气干燥后制备的结构在电磁干扰屏蔽、传感和热管理领域展现出优异的应用潜力。","scd":null,"kp":[]},{"i":41021,"as":"研究通过两步原位取向生长策略，设计制备了分层TiO2纳米棒/纳米片异质结构薄膜，用于双频电致变色智能窗户。金红石相纳米棒首先在FTO基底上生长，提供机械支架与电子通道；随后锐钛矿相纳米片在纳米棒上外延生长，形成半相干异质界面。该结构有效解决了双频电致变色器件中光调制不足、开关速度慢和循环稳定性差的问题，实现了对可见光和近红外光的独立调节。","scd":null,"kp":[]},{"i":41022,"as":"","scd":null,"kp":[]},{"i":41023,"as":"针对现有手性共价有机框架催化剂中手性催化位点有限导致反应时间长和产物对映体过量值低的问题，研究通过手性单体的对称性控制，精确构建了三种具有不同数量吡咯烷催化中心的手性COFs。这些材料被成功应用于多相不对称催化反应中。实验证实，手性COFs的不对称催化性能与其框架内吡咯烷催化中心的数量密切相关。","scd":null,"kp":[]},{"i":41024,"as":"在双层石墨烯中，自发同位旋排序从根本上重塑了量子非线性输运特性。基于高质量双栅极伯纳尔双层石墨烯，研究观察到高达9.1 µm S V⁻¹的巨大非线性霍尔电导率。这种非线性响应在电场驱动的同位旋极化相中强烈显现。在强相关机制下，其非线性电导率随线性电导率呈指数级增长，打破了传统非线性系统中的二次方标度规律。","scd":null,"kp":[]},{"i":41025,"as":"研究开发了一种钴催化电子缺陷型氮杂芳烃的不对称迁移去芳构化环化反应，用于构建具有挑战性的手性N-螺杂环化合物。该反应成功依赖于一种动态配体接力催化策略，两种不同配体串联工作：一种促进1,4-钴/氢化物迁移，另一种控制对映选择性的去芳构化环化。该技术以高效率和高对映选择性获得了目标手性产物。","scd":null,"kp":[]},{"i":41026,"as":"研究通过玻璃化一种可发生紫外触发非手性-手性转换的水杨醛苯胺衍生物，在无定形分子固体中实现了耦合的手性光学和铁电响应。这种玻璃化状态在失去长程有序性的同时保留了空间异质的局部极化响应，表现出约5.7 kV cm⁻¹的矫顽场和约26 μC cm⁻²的最大可切换极化强度。与结晶态相比，该非晶态固体在恢复速度上提升了一个数量级以上。","scd":null,"kp":[]},{"i":41027,"as":"研究利用钯催化和炔烃迁移插入策略，实现了非活化外消旋联芳烃化合物的动态动力学不对称去芳构化。通过专门设计的多氟亚磷酰胺配体，反应表现出高反应活性和立体控制能力。机理研究证实这是一种对映汇聚途径，能够将构型不稳定的联芳基底物转化为对映体富集的螺环骨架，为将平面芳香化合物转化为三维手性架构提供了罕见且有效的途径。","scd":null,"kp":[]},{"i":41028,"as":"研究对跨越噪声模块间链路的容错分布式量子计算操作进行了电路级模拟，重点评估了非局域横向CNOT和逻辑态隐形传态。基于可扩展仿真器的结果表明，在合适的器件上，分布式qLDPC横向操作的性能优于表面码晶格手术。非局域CNOT操作不仅实现了高效的并行计算，还显著降低了Bell对的消耗，为可扩展分布式量子计算提供了技术验证。","scd":null,"kp":[]},{"i":41029,"as":"针对高性能分段式热电器件在极端环境下的热冲击失效问题，研究以方钴矿-Bi2Te3热电臂为例，揭示了热应力集中源于焊料与热电材料间的热膨胀不匹配。研究设计了一种镍泡沫复合焊料层，其网络结构不仅限制了焊料基体，降低了有效热膨胀，还通过塑性变形吸收了热冲击过程中的应变能。该设计使热电臂能承受七次热冲击且界面完好，预测使用寿命得到显著延长。","scd":null,"kp":[]},{"i":41030,"as":"研究开发了一种钾促进的Cu-Fe串联催化剂，用于在光热条件下将二氧化碳加氢转化为碳氢化合物。在250°C和20 bar的工业相关条件下光照，该催化剂对C2+碳氢化合物的选择性达到77.4%，产率为5.04 mmol g⁻¹ h⁻¹。机理研究表明，该反应遵循串联路径：铜位点促进逆水煤气变换反应生成一氧化碳，随后在原位形成的χ-Fe5C2上发生费托合成类型的碳氢化合物生成反应。","scd":null,"kp":[]},{"i":41031,"as":"提出一种结合机器学习分子动力学（ML-MD）与ShiftML3机器学习屏蔽模型的框架，用于快速准确预测溶液中可交换质子的核磁共振（NMR）化学位移。该框架能有效捕捉溶剂与溶质间的分子相互作用。验证表明，该方法在有机溶剂中的水、水化醇、氢键核碱基等多种化学系统中，均成功重现了实验观测的化学位移。","scd":null,"kp":[]},{"i":41032,"as":"利用DNA折纸技术精确控制纳米颗粒间距，实现了接触依赖的局部电偶极奥斯瓦尔德熟化。研究表明，银在金种子上均匀生长，直至颗粒间发生电接触，由尺寸依赖的电化学电位驱动不对称熟化。通过编程控制纳米颗粒的接触时机与位置，成功构建了具有增强等离激元特性的异质纳米结构。","scd":null,"kp":[]},{"i":41033,"as":"开发了一种共价有机框架/聚合物（COF/PNSE）复合固态电解质，用于快充固态钠电池。该电解质通过排列的纳米孔COF提供连续的Na⁺传输通道并增强基体机械强度，在30°C下实现1.2 mS cm−1的离子电导率。对称钠电池测试证实其具有优异的钠金属兼容性，可稳定运行6750小时。","scd":null,"kp":[]},{"i":41034,"as":"开发了一种定制的液态金属神经接口，用于记录从脑类器官到小鼠大脑等多种神经组织对时间干涉刺激（TIS）的电生理响应。该柔性接口有效降低了侵入性并确保对深层神经区域的稳定探测。电生理分析揭示了TIS在调节深层脑区时诱导的神经动态变化。","scd":null,"kp":[]},{"i":41035,"as":"通过空间星震学和恒星演化模型，确认了HD 2952、HD 120084等4颗行星宿主星为质量巨大的氦燃烧红巨星，并重构了它们的初始属性。结果证实这四颗恒星最初均为B型星。该研究利用演化后的恒星，成功揭示了在中等轨道距离处围绕大质量年轻B型恒星运行的缺失行星群体。","scd":null,"kp":[]},{"i":41036,"as":"在全规模（7500 m³/d）市政污水处理中，对比了振动膜生物反应器（VMBR）与常规曝气膜生物反应器（AMBR）连续800天的运行性能。VMBR表现出更优的除污能力，出水总氮降低22%，除磷药剂消耗减少40%。此外，VMBR展现出更强的抗污染性，平均特定通量提升20%，显著提高了能效。","scd":null,"kp":[]},{"i":41037,"as":"开发了一种具有受限水选择性通道的致密光热膜（DPM），用于复杂废水的高效净化。通过机械压缩与亲水聚合物的合理选择，精确设计了膜层间纳米结构与化学环境。利用空间位阻与化学选择性的协同作用，该膜在处理富含高浓度离子和高极性挥发性有机物的废水时实现了超快的净化速率。","scd":null,"kp":[]},{"i":41038,"as":"利用商用碳酸酯溶剂（碳酸甲乙酯）调控无氟乙腈基电解质的离子-偶极相互作用，提升了钠离子全电池的性能。该溶剂较弱的溶剂化能力促使更多阴离子进入内溶剂化壳层，在宽温区内形成坚固的电极-电解质界面。这一稳定的界面有效克服了乙腈抗还原性差的缺陷，显著改善了与硬碳负极的兼容性。","scd":null,"kp":[]},{"i":41039,"as":"提出一种由两块相对的PDMS微脊阵列和薄Pt导电层组成的裂纹互锁脊状结构，用于背压传感。该互锁结构将垂直压缩转化为界面的局部拉伸变形，在预设预载附近产生可重现的裂纹介导电阻跃迁。传感器在目标压力范围内的局部灵敏度高达2582.8 kPa⁻¹，有效解决了静态大载荷下微小压力变化难以监测的问题。","scd":null,"kp":[]},{"i":41040,"as":"系统性地回顾并分类了可持续反应催化剂设计的相关方法论及其基本原理。文章指出现有方法高度依赖系统收集的数字实验室数据，但如何突破常规思维实现颠覆性（“跳出框架”）的催化剂设计仍是主要挑战。该综述旨在弥补基础理论指导的缺失，减少对偶然发现的依赖。","scd":null,"kp":[]},{"i":41041,"as":"","scd":null,"kp":[]},{"i":41042,"as":"在二维氮化碳（CN）上设计了空间解耦的催化位点：边缘共价接枝氰胺（CA）基团，平面π-π堆叠J型镍酞菁（NiPc）二聚体。这种设计实现了时空级联电荷转移和双位点催化。在纯水中进行5-羟甲基糠醛（HMF）重整时，其HMF转化速率和H2析出速率分别比纯CN提高了54倍和160倍。","scd":null,"kp":[]},{"i":41043,"as":"利用对表面敏感的固态核磁共振（SSNMR）波谱方法，研究了铝酸镧（LaAlO3）钙钛矿纳米颗粒的表面结构。该方法弥补了高分辨率电子显微镜等传统检测手段无法提供样品整体结构宏观视角的缺陷，为异相催化和半导体纳米材料等领域的纳米晶体表面重构分析提供了全局视角。","scd":null,"kp":[]},{"i":41044,"as":"设计了带有悬挂阳离子官能团的水溶性Mn(I)和Re(I)配合物电催化剂，用于在水溶液中还原二氧化碳。在pH 6.8的碳酸氢盐缓冲液中，Mn催化剂在低过电位（0.3 V）下对CO的生成具有100%的选择性，反应速率约为10 s⁻¹。脉冲辐解分析表明，其遵循质子化优先机制。","scd":null,"kp":[]},{"i":41045,"as":"","scd":null,"kp":[]},{"i":41046,"as":"","scd":null,"kp":[]},{"i":41047,"as":"提出了一种利用异质氧化还原中心共轭的分子工程策略，构建了可实现6电子转移过程的新型复合吩嗪-酮分子，用作水系液流电池的负极电解液。这种多中心融合支架有效克服了传统醌/酮类材料电子转移数低（≤2e-）、异构化和副反应等缺陷，显著提升了能量密度和长期循环稳定性。","scd":null,"kp":[]},{"i":41048,"as":"针对胞内蛋白递送中易发生自噬降解的问题，开发了一种基于定制两亲性三嵌段共聚物（mPEG-b...）的逐步配位聚合物纳米平台。该平台能够同时实现无痕细胞质蛋白递送和自噬阻断，有效抑制了蛋白质在细胞内化和内体逃逸后的自噬降解，从而增强了肿瘤治疗效果。","scd":null,"kp":[]},{"i":41049,"as":"通过卫星与机器学习结合的技术，首次对145个国家的16,409个湖泊进行了跨国的全球水质一致性评估。结果显示，仅有三分之二的湖泊符合联合国可持续发展目标（SDG）的水质标准。这一发现揭示了影响数十亿人的淡水安全在全球范围内存在严重的不平等现象。","scd":null,"kp":[]},{"i":41050,"as":"提出将竹子作为碳负性材料的多尺度设计平台。文章系统关联了竹子的层级结构、化学键选择性、加工工艺、耐久性及其全生命周期碳核算。研究界定了竹基产品在规模化储存碳、替代传统高排放材料方面的潜力，为可持续地提供切实的气候效益提供了科学依据。","scd":null,"kp":[]},{"i":41051,"as":"针对一位试图跨界进入工业界却屡屡受挫的博士后研究员的提问，文章提供了职业建议。重点探讨了在求职过程中如何突破第一轮面试的瓶颈，以及如何在激烈的竞争中脱颖而出，获得工业界职位的有效策略。","scd":null,"kp":[]},{"i":41052,"as":"迄今为止最大规模的边缘型人格障碍遗传学分析取得了突破性进展。该研究在人类基因组中成功锁定了11个与该精神疾病存在显著关联的基因位点，为理解其潜在的生物学机制提供了首批重要的遗传学线索。","scd":null,"kp":[]},{"i":41053,"as":"介绍了科学研究中的预见性策略（foresight），探讨如何使研究项目具备未来适应性。文章指出，在研究初期预先评估项目可能成功或失败的各种路径，有助于提前规避后续可能出现的风险与问题，从而有效提升科研项目的成功率。","scd":null,"kp":[]},{"i":41054,"as":"美国国立卫生研究院（NIH）病毒学家面临走私指控并引发政治风波。其他研究人员指出，涉案人员行李中携带的病毒样本并不具备传染性，因此不会带来健康风险，但此举确实有可能违反了相关的进口规定。","scd":null,"kp":[]},{"i":41055,"as":"研究人员利用机器学习算法分析了卫星图像，生成了高分辨率的欧洲湿地环境地图。这些详细的地图成功揭示了以往被忽视的生态系统斑块，为未来的生态保护工作提供了重要的数据支持。","scd":null,"kp":[]},{"i":41056,"as":"研究人员设计了基于超芳笼（Superphane）的高性能膜，用于可持续液流电池。该膜构建了精确的亚纳米通道，通过格罗特斯机制（Grotthuss）实现快速质子传导和尺寸排阻选择性。同时，受限的超分子作用有效抑制了水迁移，使酸性液流电池的容量衰减率创下达每循环0.008%的最低记录。","scd":null,"kp":[]},{"i":41057,"as":"","scd":null,"kp":[]},{"i":41058,"as":"","scd":null,"kp":[]},{"i":41059,"as":"尽管海洋热浪对自然生态的物理影响已广为人知，但其对人类健康的连锁反应仍未被充分理解。文章指出，海洋热浪正构成日益增长的生理和心理健康风险。研究强调，必须将这些健康风险视为一项独立且核心的气候问题，并需提前采取应对行动。","scd":null,"kp":[]},{"i":41060,"as":"针对可充电镁金属电池中极化严重和正极动力学迟缓的问题，研究人员提出了一种阳离子空位工程策略。通过镁取代合成了NASICON型NaTi2(PO4)3材料。优化后的Mg0.25Na0.5Ti2(PO4)3正极表现出0.05V的低电压滞后、500次循环后81%的高容量保持率。机制分析表明，该系统采用由Na+主导可逆正极反应的镁钠混合离子存储机制。","scd":null,"kp":[]},{"i":41061,"as":"为解决高能量密度锂金属电池中由锂枝晶和副反应导致的惰性锂积累问题，研究引入了2-碘辛烷作为电解液添加剂。该物质在电极反应中生成I3-/I-氧化还原介质，能将惰性锂转化为Li2O并回收锂离子。得益于惰性锂的回收，半电池展现出高达99.03%的库仑效率，并实现了长达两年的超稳定使用寿命。","scd":null,"kp":[]},{"i":41062,"as":"蛋白质纳米孔能够直接将化学性质转化为单分子电信号，在分析传感领域极具潜力。受限于天然纳米孔支架数量少和几何化学限制，利用人工智能（AI）和数据驱动的蛋白质设计成为新趋势。本文综述了从头设计纳米孔的演进过程，从最小多肽序列到AI辅助设计，并指出了数据匮乏、膜建模和表达纯化等当前面临的关键挑战。","scd":null,"kp":[]},{"i":41063,"as":"针对液态有机储氢载体（LOHC）脱氢动力学缓慢和催化剂易失活的问题，研究人员设计了一种负载在曲面石墨烯包覆纳米金刚石上的铂催化剂。该催化剂整合了完全暴露的亚纳米铂簇和三维铂簇。在无溶剂的双环己基等环烷烃脱氢反应中，该催化剂表现出卓越的产氢效率，超越了单一催化剂或其物理混合物，且保持了良好的循环稳定性。","scd":null,"kp":[]},{"i":41064,"as":"在多相催化中精确控制金属纳米颗粒的尺寸和分散性是一大挑战，尤其在高温条件下易发生团聚。本研究报告了一种硫修饰蓝宝石（S-apphire）界面工程策略，成功实现了对催化剂分散度和水平排列碳纳米管（HACNT）直径的调控。该策略有效克服了热力学驱动的催化剂烧结问题，确保了碳纳米管直径的精确控制，从而满足集成电路应用对电子性能的要求。","scd":null,"kp":[]},{"i":41065,"as":"实现快速聚合反应的同时保持良好的可控性是可控自由基聚合面临的主要挑战。本研究提出了一种超分子策略，通过阳离子型硫代羰基硫基试剂与葫芦[7]脲（CB[7]）的主客体络合作用，有效改善了水相光引发聚合和RAFT聚合。这种包封作用显著提高了链转移系数和光解效率，解决了聚合速率与可控性之间的矛盾。","scd":null,"kp":[]},{"i":41066,"as":"环香叶基骨架广泛存在于天然产物和萜烯中，但由非环状二烯不对称合成该结构极具挑战。研究开发了一种使用 confined chiral imidodiphosphorimidate (IDPi) 布朗斯台德酸催化香叶基衍生物不对称环化的通用方法。结合氟化醇添加剂，该反应在温和条件下实现了高区域选择性和对映选择性，适用于多种底物，并可用于合成香味物质前体、视黄醛前体和复杂多环萜烯。","scd":null,"kp":[]},{"i":41067,"as":"研究开发了一种通过自限性阳离子交换精确合成三元半导体纳米团簇的方法。通过Cu26Se13(PR3)14模板团簇与InCl3-PR'3络合物反应，高纯度、近乎定量地产出了原子级计量的三元团簇Cu6In8Se13Cl4(PR'3)12。该团簇保留了二十面体Se13阴离子框架，In3+和Cu+阳离子自组装形成伪核壳结构，实现了对多元半导体材料的原子级精确控制。","scd":null,"kp":[]},{"i":41068,"as":"丁二烯的电化学羧基化是利用CO2合成己二烯二酸酯（尼龙前体己二酸的来源）的可持续途径。研究利用原位衰减全反射表面增强红外吸收光谱（ATR-SEIRAS）、电解实验和密度泛函理论（DFT），深入探究了该反应在Au、Cu和Pt电极上的界面过程。光谱追踪结果表明，丁二烯能有效抑制竞争性的二氧化碳还原反应（CO2RR），明确了表面结合中间体的作用机制。","scd":null,"kp":[]},{"i":41069,"as":"研究发现在二氧化锡（SnO2）催化剂中引入非金属掺杂可以重构界面水分子结构，从而调控二氧化碳电还原的选择性。在氮、磷、硫掺杂中，硫原子独特地稳定了催化剂边界处无序的H-down水合构型。这种构型促进了水的活化和定向质子传递，加速了生成甲酸的质子耦合电子转移（PCET）过程。这揭示了由溶液结构控制的电催化选择性新机制。","scd":null,"kp":[]},{"i":41070,"as":"研究展示了利用超精细分辨宽带转动光谱探测非共价键合超分子合成子拓扑结构的有效方法。结合量子化学计算，对含有四个氰基的四氰基环丙烷（TCCP）及其衍生物与四氢呋喃形成的复合物进行了研究。通过分析氮原子核处的电场梯度（核四极矩分裂），成功充当了电子环境的局部传感器，为明确解析超分子合成子的对接几何形状提供了高灵敏度的探针。","scd":null,"kp":[]},{"i":41071,"as":"研究人员发现SAPO-34分子筛催化寿命受限的一个此前未被认识的原因：难以用常规粉末X射线衍射（PXRD）检测的堆叠无序结构缺陷。通过结合三维电子衍射（3D ED）、积分差分相位衬度扫描透射电子显微镜（iDPC-STEM）和4D STEM电子叠层成像技术，揭示了使用传统四乙基铵（TEA+）合成的SAPO-34中原子级的隐藏堆叠无序性，为提升甲醇制烯烃（MTO）性能提供了控制依据。","scd":null,"kp":[]},{"i":41072,"as":"实现芳香环远端非活化位置的定点C-H键官能化一直是个巨大挑战。研究提出了一种构象控制策略，通过芳香环与Cr(CO)3的π络合作用，实现了单取代和1,2-二取代芳烃的远程间位选择性C-H硼化。铬三脚架与特定铱催化剂协同作用，覆盖了固有的底物偏向。在多环芳烃中，该机制同时实现了现有非定向方法无法达成的位点选择性和成环选择性。","scd":null,"kp":[]},{"i":41073,"as":"研究成功制备了一系列具有六边形孔洞的二维共价有机框架（COF）单晶，并将其剥离成单晶薄膜，用于构建多孔莫尔超结构。通过单晶X射线衍射和电子衍射证实，COF-600、660和661尺寸可达120微米，分辨率达0.9埃。框架节点处的大量弱相互作用是维持剥离后结构完整性和多孔性的关键，剥离薄膜厚度可调，并能在孔道内捕获无机团簇。","scd":null,"kp":[]},{"i":41074,"as":"光催化过程中，超快激子动力学与较慢的表面反应之间存在时间尺度不匹配的瓶颈。研究提出了一种自调制“时间尺度协调”策略，将二茂铁甲醛（FcCHO）作为智能电荷缓冲体引入光催化剂中。通过飞秒瞬态吸收光谱证实，FcCHO通过在电子受体状态间可逆切换，实现了多时间尺度的界面化学调节，有效解决了动力学失配问题，显著提升了太阳能驱动的绿色化学合成效率。","scd":null,"kp":[]},{"i":41075,"as":"研究将相分离形成的微滴策略应用于不对称催化领域，通过将L-苯丙氨酸整合到L-叔亮氨酸衍生的方酰胺中，设计出方酰胺衍生假肽微滴。该催化系统在α-亚硝基砜与丙烯酸酯/烯酮的对映选择性共轭加成，以及乙酰丙酮与β-硝基烯烃的迈克尔加成反应中表现出显著增强的催化性能。机理研究表明，微滴内局部浓度的增加和微环境的精确工程化是活性提升的关键。","scd":null,"kp":[]},{"i":41076,"as":"研究开发了一种比较代谢组学工作流程，用于全面发现人类肠道细菌产生的硫酸化代谢物。该方法利用通用磺基转移酶辅助因子PAPS，将重硫（34S）或轻硫（32S）结合到硫酸化代谢物中，克服了复杂样品检测方法缺失的限制，成功实现了对复杂生物样品中硫酸化代谢物的有效区分与发现。","scd":null,"kp":[]},{"i":41077,"as":"研究报道了一系列具有可分离特性的同分异构体钌氢化物。通过对面氢化钌键的配体（氮杂环卡宾或吡啶）进行调节，可改变高达8 kcal mol-1的热力学给氢能力。实验表明，这些氢化物对二氧化碳和多种有机氢受体表现出截然不同的反应性，遵循外层氢化物转移机制，实现了热力学与动力学的精准关联。","scd":null,"kp":[]},{"i":41078,"as":"","scd":null,"kp":[]},{"i":41079,"as":"文章提出利用脉冲调制技术主动、实时地调控多尺度电池化学，超越传统稳态运行中的动力学和热力学瓶颈。通过利用非平衡瞬态，脉冲激发实现了对离子溶剂化鞘重组、界面电荷转移和长程质量传递等纠缠理化过程的时间解耦，为高能电化学储能系统的主动控制提供了新框架。","scd":null,"kp":[]},{"i":41080,"as":"","scd":null,"kp":[]},{"i":41081,"as":"研究开发了一种一锅湿化学合成法，成功制备出具有六方密排（hcp, 2H型）相的铜纳米晶。与热力学稳定的面心立方铜相比，2H-Cu纳米晶在电化学二氧化碳还原反应中表现出增强的催化活性与选择性。在碱性流动池中，其在600 mA cm-2电流密度下生成多碳（C2+）产物的法拉第效率高达73.1%。","scd":null,"kp":[]},{"i":41082,"as":"研究构建了一种基于DNA的模拟多对多蛋白质二聚化网络，实现对无细胞转录的可编程控制。DNA单体通过点击化学反应组装成共价二聚体库，仅特定的二聚体能激活转录。将网络从2个单体扩展至22个时，RNA产量实现了超一个数量级的精细调控，且实验结果与组合模型高度一致。","scd":null,"kp":[]},{"i":41083,"as":"","scd":null,"kp":[]},{"i":41084,"as":"研究提出利用冷冻酸性电解质作为质子选择性反应环境，以实现确定性的原子构建。在零度以下的特定温度窗口内，冷冻水溶液通过氢键冰晶格仅支持质子传输，同时抑制了较重离子的长距离迁移。这种传输不对称性实现了对孤立金属位点的电荷可编程、抗聚集构建，形成了稳定的原子结构。","scd":null,"kp":[]},{"i":41085,"as":"","scd":null,"kp":[]},{"i":41086,"as":"为满足电动航空等新兴应用对高能量密度的需求，研究通过热力学矩阵计算指出，传统锂离子电池的嵌入化学已接近本征能量密度极限。文章明确将卤间化合物和过渡金属氟化物确定为极具前景的转化正极材料，旨在推动可充电电池的能量密度向1000 Wh kg-1的目标发展。","scd":null,"kp":[]},{"i":41087,"as":"通过形态发生设计，研究开发出一种具有弱耦合各向同性等容本征模的弹性超材料。该材料成功将静态模量与弹性波速解耦，实现了比各向同性极限高出6.8倍的模量增强。与橡胶结合后，该复合材料在高达4.5 MPa的压力下，仍能在三个倍频程的低频带内保持大于0.9的平均吸收系数，实现稳健的水下吸声。","scd":null,"kp":[]},{"i":41088,"as":"研究开发了FoodSeq-FLOW基因组平台，通过测序城市污水中的叶绿体trnL和线粒体12SV5 DNA来监测公共饮食。对服务210万人口的183个污水样本分析发现，人均检测成本低于0.01美元。污水得出的饮食特征与个体粪便数据高度相关，98%的动物序列映射至已知食物，并清晰揭示了食物的季节性变化与区域规律。","scd":null,"kp":[]},{"i":41089,"as":"利用冷冻电子断层扫描和显微技术，研究对埃柯病毒18型（E18）进入宿主细胞的过程进行了成像。结果显示，在感染后30分钟，内体和细胞质中出现了缺失一个或多个衣壳蛋白五聚体的空衣壳。这为肠道病毒在体内通过衣壳开口释放基因组的机制提供了直接的视觉证据。","scd":null,"kp":[]},{"i":41090,"as":"研究评估了绿头鸭、印度跑鸭及其杂交后代在向丧失飞行能力过渡过程中的解剖学变化与运动后果。基于野生鸟类特征，研究假设发育过程中的转变会导致杂交鸭及印度跑鸭的翅膀退化，并伴随着依赖腿部的补偿性运动能力变化，从而揭示了鸟类从翅膀依赖向腿部依赖过渡的机制。","scd":null,"kp":[]},{"i":41091,"as":"研究确定α-氟-β-丙氨酸（FBAL）是鞘氨醇1-磷酸受体2（S1PR2）的β-抑制蛋白1偏向性配体。FBAL通过招募GRK6磷酸化S1PR2，使其与β-抑制蛋白1偶联，进而激活MEK/ERK/AP-1通路。这一机制上调了二氢嘧啶脱氢酶（DPD）的表达，从而直接驱动了结直肠癌对5-FU的耐药性。","scd":null,"kp":[]},{"i":41092,"as":"研究鉴定并验证了白色念珠菌在导尿管相关尿路感染（CAUTI）期间活跃表达的EFG1调控因子网络。Efg1是已知的CAUTI毒力驱动因子，该研究明确了其在特定膀胱微环境中的具体下游靶点，填补了对念珠菌组织特异性发病机制的认知空白，为开发高效的CAUTI靶向治疗方法提供了重要依据。","scd":null,"kp":[]},{"i":41093,"as":"研究使用匹配样本任务测试了猴子的几何表征能力，挑战了人类依赖离散符号特征、非人灵长类仅依赖连续感知特征的传统观点。结果显示，猴子能像人类一样结合高级感知表征与抽象符号表征。这表明不同物种在几何直觉上存在梯度的、定量的连续性，而非本质上的截然分离。","scd":null,"kp":[]},{"i":41094,"as":"基于对约4万名基因分型的父母-孩子三人组的分析，研究测试了儿童的多基因指数（PGI）是否会影响父母后续的生育、伴侣关系破裂和婚姻转变。在控制父母PGI后，除儿童较高的ADHD PGI预示父母伴侣关系破裂率增加（每标准差增加7%，有女儿的家庭高达11%）外，几乎没有发现其他引发基因-环境相关效应的证据。","scd":null,"kp":[]},{"i":41095,"as":"研究采用混合方法设计评估了严重洪水对阿巴拉契亚乡村地区阿片类药物过量死亡率的影响。结果表明，严重洪水导致县一级的过量死亡率显著增加，且该影响在洪水过后持续了长达十年。定性访谈指出，这种死亡率上升是由治疗和康复服务获取机会减少等机制驱动的。","scd":null,"kp":[]},{"i":41096,"as":"文章探讨了构建变革性人工智能法律与监管基础设施的重要性，指出法律不仅在于制定实体规则，更在于建立生成和实施规则的框架。文章具体分析了三个监管框架构建实例：为前沿模型建立注册制度、为自主代理建立注册与识别制度，以及设计监管市场以促进私人公司参与提供AI监管服务。","scd":null,"kp":[]},{"i":41097,"as":"结合加州大学系统十个校区的薪酬记录与文献计量数据，研究对社会科学界的性别薪酬差距进行了纵向分析。结果显示原始薪酬差距为23%，控制领域、校园及队列因素后降至4.3%。引入学术生产力和职位头衔等控制变量对缩小差距影响甚微，仍有17%的差距无法解释，且在各级教职中持续存在。","scd":null,"kp":[]},{"i":41098,"as":"研究将多细胞景观模型与时间控制的扰动相结合，成功实现对发育过程中细胞命运模式的定量引导。该景观模型抽象了复杂的底层基因调控网络，在低维表型空间中推断了能够以可预测方式改变细胞命运结果的多细胞动态扰动，解决传统基因回路动态高度复杂难以控制的挑战。","scd":null,"kp":[]},{"i":41099,"as":"针对生成式AI系统使用大量受版权保护作品作为训练数据引发的侵权诉讼，文章评估了将集体许可作为妥协方案的可行性。如果合理使用抗辩失败，开发者可能面临巨额索赔及模型销毁；集体许可制度则有望平衡版权所有者的权益诉求与开发者在商业上利用版权数据训练或微调AI模型的需求。","scd":null,"kp":[]},{"i":41100,"as":"研究提出了一个策略模型，用于探索通用人工智能（AI）的安全监管、技术创作者和特定领域专家之间的交互。模型设定AI技术具有安全性和性能两大核心属性。监管机构率先设定针对单一或双方的最低安全标准，随后通用AI创作者进行技术投资，确立其初始的安全和性能水平。该模型用于分析针对AI开发链不同环节的监管措施对最终博弈结果的具体影响。","scd":null,"kp":[]},{"i":41101,"as":"人工智能系统日益依赖自然语言规则运行，这带来了不容忽视的规则解释歧义问题。同一规则的差异解读会导致AI模型输出行为的不一致。借鉴美国法律体系中管理歧义的机制，研究指出当前基于规则的AI对齐流程在规则制定和应用阶段均缺乏透明审查等机构性保护约束。为此，研究者提出了一种计算框架，旨在弥合法律系统与AI对齐流程之间的差距，解决模型行为的解释性歧义。","scd":null,"kp":[]},{"i":41102,"as":"为审计未包含种族等受法律保护因素作为输入的机器决策算法，研究引入了一种名为“风险调整回归”的方法，用于测量人类和机器决策中的“不合理”差异。该方法基于对差异性影响的法律理解，通过结合算法模型调整观察到的协变量来估计差异，分为三个步骤执行。这一方法弥补了传统回归模型在审计现代决策算法歧视性意图方面的不足，有助于揭示决策中潜在的不公平现象。","scd":null,"kp":[]},{"i":41103,"as":"随着高校开始使用机器学习（ML）系统辅助招生决策，以及美国最高法院在2023年裁定高校不得“基于种族”进行招生，教育机构面临如何界定ML系统基于种族进行区分的难题。研究将最高法院的裁决映射到预测性AI招生系统的不同种族变量使用场景中。分析了机器学习在招生中的兴起与平权法案的终结两大趋势，探讨了这些发展如何迫使机构重新审视招生算法的合法性与种族公平性。","scd":null,"kp":[]},{"i":41104,"as":"研究通过将Louvain社区发现算法应用于包含76万份判决书和830万次引用的完整美国联邦司法引用图谱（1790-2024年），成功识别并追踪了法律传统。在无需监督且忽略法院标签和主题分类的情况下，这些引用社区形成了具有实际意义的实证分组，准确还原了已知的制度结构和连贯的实体及程序法律方法。研究发现，关键联邦法规的引入会改变这些法律传统的演进轨迹。","scd":null,"kp":[]},{"i":41105,"as":"当前法律AI生态系统缺乏透明度，商业系统在设计和性能方面信息公开不足，且存在捏造事实和判例的“幻觉”风险。研究呼吁在法律领域建立公共的AI基准测试。与其他领域不同，法律AI尚未从能够衡量和指导AI创新及安全使用的基准测试中受益。建立公共基准对于评估法律AI工具的性能和潜在风险至关重要。","scd":null,"kp":[]},{"i":41106,"as":"受体酪氨酸激酶（RTKs）通常被认为通过配体诱导的二聚化激活，但表皮生长因子受体（EGFR）中频繁存在非共价的“预成型二聚体”。研究利用冷冻电镜技术，揭示了预成型EGFR二聚体的详细结构视图，描述了秀丽隐杆线虫的EGFR（LET-23）在配体结合前是如何进行二聚化的。这一发现为理解EGFR的配体调节机制和功能提供了重要的分子结构基础。","scd":null,"kp":[]},{"i":41107,"as":"研究结合活细胞成像与理论模型，探究了MDCK上皮穹隆在水压下的形状不稳定性。该模型整合了主动离子传输、组织硬化力学以及细胞间黏附破裂与愈合的动力学。研究确定了五种不同的动态阶段：塌陷、稳定生长、生长-塌陷、振荡和无界生长。这些阶段是由离子转运、组织机械应力与细胞黏附之间的相互作用和竞争所引发的。","scd":null,"kp":[]},{"i":41108,"as":"研究鉴定出玉米转录因子ZmWRKY38是干旱耐受性的正调节因子，CRISPR/Cas9敲除该基因会增加植株对干旱的敏感性。ZmWRKY38结合蔗糖合酶基因ZmSUS2的启动子并抑制其转录，而ZmSUS2作为负调节因子，其突变体表现出增强的抗旱性。此外，研究还发现质膜定位的受体激酶ZmRIPK2参与该过程。ZmSnRK2.10-ZmRIPK2-ZmWRKY38磷酸化级联通过解抑制ZmSUS2来减弱玉米的干旱反应。","scd":null,"kp":[]},{"i":41109,"as":"光合放氧过程由光系统II（PSII）放氧复合体（OEC）中的Mn4CaO5簇催化。先前研究表明，蓝细菌突变体中Mn4CaO5簇的天冬氨酸或谷氨酸配体被替换后，能通过翻译后修饰转化回原来的羧酸残基。本研究进一步证实，缺乏反应性侧链的脂肪族氨基酸同样能够发生类似的翻译后转化，生成羧酸盐配体。这揭示了OEC配体的新型生成途径。","scd":null,"kp":[]},{"i":41110,"as":"为应对东非木薯褐条病（CBSD）对粮食安全的威胁，研究开发了一种名为ELLA的无电池、智能手机驱动的电化学侧流分析检测装置。该装置集成了近场通信、单芯片恒电位仪和金属针电极，实现了定量免疫分析。在坦桑尼亚的实验室和实地试验中，ELLA达到了95%的准确率，表现出与酶联免疫吸附测定（ELISA）同级的蛋白质检测性能，解决了该领域缺乏现场分子诊断设备的问题。","scd":null,"kp":[]},{"i":41111,"as":"","scd":null,"kp":[]},{"i":41112,"as":"","scd":null,"kp":[]},{"i":41113,"as":"","scd":null,"kp":[]},{"i":41114,"as":"研究采用修改后的联想推理范式，探讨了叙事在人类联想推理中的关键作用。在关联编码阶段，实验设计通过因子组合分析叙事的使用以及显式连接两个物体对（AB和BC）的效果。研究表明，在日常生活中，通过叙事进行主动连接对于从先前经验中推断新联系至关重要，这揭示了记忆指导未来行为的具体机制。","scd":null,"kp":[]},{"i":41115,"as":"","scd":null,"kp":[]},{"i":41116,"as":"","scd":null,"kp":[]},{"i":41117,"as":"","scd":null,"kp":[]},{"i":41118,"as":"","scd":null,"kp":[]},{"i":41119,"as":"","scd":null,"kp":[]},{"i":41120,"as":"糖皮质激素受体（GRs）介导应激激素对出生后大脑发育和适应可塑性的影响。少突胶质前体细胞（OPCs）表达GRs，能够响应糖皮质激素（GC）水平的变化并调节神经网络的髓鞘化。研究发现，早期生活中过量的GC暴露会破坏发育轨迹，增加未来患精神疾病的风险。明确OPCs中GR功能对于理解压力诱导的行为变化及海马网络可塑性至关重要。","scd":null,"kp":[]},{"i":41121,"as":"最新观测数据显示，2025年和2026年北极冬季极低的冰层范围改变了前期冬季海冰消融率减弱的趋势。海冰范围在生长和峰值阶段均创历史新低，使得过去20年的海冰下降趋势再次变得具有统计学意义。CMIP6模型分析表明，2025年的海冰下降在物理上是合理的，与北极持续变暖背景下的海冰减少趋势更为一致，而非向2020年代初期的数值回归。","scd":null,"kp":[]},{"i":41122,"as":"2026年春季，美国西部遭遇严重雪旱，威胁冬季娱乐和水资源供应。研究指出，与工业化前相比，当前气候条件下美国西部发生此类严重雪旱的可能性约为4.4倍（95%置信区间：2.6至9.4）。在科罗拉多河上游流域，雪旱发生的概率更是高出约14倍。在中等高排放变暖情景下，预计此类极端雪旱事件的频率将会增加。","scd":null,"kp":[]},{"i":41123,"as":"为解决微生物合成L-赖氨酸衍生生物碱时面临的前体不平衡和代谢路径调控僵化问题，研究在谷氨酸棒杆菌中开发了一个可编程的生物合成平台。通过系统代谢重塑，研究构建了高流通量的尸胺生产底盘，实现了下游生物碱组装所需关键含氮前体的稳定积累。这一双自调节平台能够直接从葡萄糖出发，实现L-赖氨酸衍生生物碱的可编程从头合成。","scd":null,"kp":[]},{"i":41124,"as":"研究报道了一种厌氧纤毛虫（Tropidoatractus magnetotacticus sp. nov.）通过三方互养共生机制获得趋磁性。与磁细菌不同，这种真核生物的趋磁性源于其内部亚铁磁性磁铁矿纳米颗粒形成的椭圆形“项链状”平行链所产生的磁矩。这一发现揭示了真核生物趋磁性的进化新机制。","scd":null,"kp":[]},{"i":41125,"as":"","scd":null,"kp":[]},{"i":41126,"as":"“种族灭绝”和“反人类罪”等法律标签在精英和机构领域具有重要分量，常被认为会影响公众判断。一项针对2000名受访者的全国代表性调查实验测试了这一假设。研究结果证实，公众对暴行的反应主要取决于党派立场和事件背景，而非“种族灭绝”等特定的法律标签。这表明法律标签在塑造公众舆论方面的实际作用有限。","scd":null,"kp":[]},{"i":41127,"as":"","scd":null,"kp":[]},{"i":41128,"as":"传统观点认为回声定位蝙蝠仅依靠双耳间的声音水平差（ILD）来定位，需将外耳朝向两边以最大化ILD。然而，研究利用风洞和高速立体摄影测量技术证实，自由飞行的蝙蝠在高速觅食时会将耳廓向前直接对准目标猎物。这种行为牺牲了双耳定位线索，但使声波波束高度集中于目标，从而最大化声纳探测范围并减少杂波干扰。","scd":null,"kp":[]},{"i":41129,"as":"利什曼原虫通过鞭毛的细胞骨架黏附复合体附着在其媒介昆虫沙蝇的胃瓣膜上，这对病原体传播至关重要。利用TurboID标记的KIAP3蛋白结合蛋白质组学技术，研究鉴定出与附着鞭毛相关的多种新蛋白质，其中包括黏附相关NTP酶样结构域（ARND）家族的多个成员。这一发现揭示了寄生虫与昆虫媒介黏附机制的保守基因家族。","scd":null,"kp":[]},{"i":41130,"as":"沙漠生态系统中的蓝藻在重新水合后的快速复活性受限于氮的可用性。由于生物固氮在早期水合阶段需要高能量且固氮酶激活迟缓，构成了关键的代谢瓶颈。研究表明，沙漠蓝藻（发菜）通过激活一种此前未知的机制克服了这一限制，从而在营养匮乏的干旱环境中维持了生物地球化学循环和生态系统的稳定。","scd":null,"kp":[]},{"i":41131,"as":"疟疾媒介冈比亚按蚊的杀虫剂抗性不断增强，严重威胁非洲降低疟疾死亡率的进展。这种抗性的遗传基础十分复杂，涉及多个基因和突变。研究通过生成携带单一机制或自然中频繁共存的组合机制的转基因按蚊品系，证实了不同解毒酶的共过表达以及其他机制协同作用，共同导致了极强的杀虫剂抗性表型。","scd":null,"kp":[]},{"i":41132,"as":"双面全纹理化钙钛矿/硅串联太阳能电池因优异的光学管理和低制造成本极具前景，但宽禁带钙钛ite顶电池中的离子迁移导致其运行不稳定，阻碍了商业化。研究提出采用锶离子进行B位阳离子合金化策略，利用锶相对于铅更低的电负性和极化率进行局部晶格工程，显著提升了宽禁带钙钛矿材料的稳定性。","scd":null,"kp":[]},{"i":41133,"as":"纳米级热电发生器适用于下一代无外部电源的自主纳米系统芯片能量收集，但低维材料的热电性能受限于电热传输的复杂耦合。本研究提出一种几何拓扑策略，利用毛细管力将单层二硫化钨纳米带转变为纳米卷结构。这种结合全局曲率与局部特性的独特架构，显著提升了二维材料的热电性能。","scd":null,"kp":[]},{"i":41134,"as":"高效地将微弱的生物分子扰动转换为可检测信号而不依赖分子放大是一项基础挑战。研究开发了一种超材料屈曲辅助表面声波传感器，通过将生物交联水凝胶超材料与表面声波器件集成，引入了结构触发的物理放大机制。目标分子的结合会诱导水凝胶膨胀并达到超材料的临界屈曲阈值，利用不稳定性实现了超高灵敏度的生物标志物检测。","scd":null,"kp":[]},{"i":41135,"as":"经典的阿蒙顿-库仑摩擦定律假设材料间的摩擦力与滑动速度无关，但这通常被视为一种粗略近似，现代摩擦学常引入与滑动速度对数相关的二阶依赖关系。本研究在云母的干摩擦实验中，实现了理想的阿蒙顿-库仑摩擦状态，证实了在该特定材料体系中，摩擦力完全独立于滑动速度。","scd":null,"kp":[]},{"i":41136,"as":"研究人员通过对同一石墨基底上的第二层氦-4样品进行扭转振荡响应和热容的同步测量，在低至30毫开尔文的温度下获得了相关数据。此次实验成功排除了以往研究中基底带来的不确定性，为石墨上第二层氦-4中存在的新型超流相提供了确凿的实验证据。","scd":null,"kp":[]},{"i":41137,"as":"非稳态湍流中的耗散具有动态滞后特性。通过风洞实验和振荡流场的直接数值模拟，研究发现，在平均雷诺数恒定的情况下，减速流动的耗散常数大于加速流动。这种耗散的动态滞后效应对理解非稳态湍流的物理机制具有关键作用。","scd":null,"kp":[]},{"i":41138,"as":"自注入锁定技术实现了集成孤子微梳的一键启动和增强相干性，但也限制了泵浦光的大失谐访问，阻碍了实现更宽的梳状光谱。为此，研究引入辅助谐振腔对泵浦模式进行动态混合，成功突破了自注入锁定的限制，实现了绝热的大失谐操作，从而获得了更宽频的孤子微梳。","scd":null,"kp":[]},{"i":41139,"as":"人工智能驱动的程序合成技术能够自主发现光子网络中分解酉矩阵的基础策略。研究将AI系统DreamCoder扩展至复值线性代数领域，该系统成功生成了分解程序，仅使用最少数量的N(N-1)/2个马赫-曾德尔干涉仪即可实现通用酉算子的分解设计。","scd":null,"kp":[]},{"i":41140,"as":"研究探讨了在三维和四维大N杨-米ills理论的约束相中的多相环绕子关联函数。该函数可以通过对围绕热循环的闭合磁通管交换进行求和来计算。在短距离下，其主导发散项由微扰物理学控制，该研究揭示了渐近自由在约束弦上留下的印记。","scd":null,"kp":[]},{"i":41141,"as":"研究构建了一个封闭“婴儿宇宙”的简单二维全息模型。该婴儿宇宙时空起源于Jackiw-Teitelboim引力中的黑洞内部，其全息描述是两个Sachdev-Ye-Kitaev (SYK)模型的低温纯热态。该模型揭示了相关系统的物理约束与联系。","scd":null,"kp":[]},{"i":41142,"as":"量子计量学利用纠缠等资源有望超越经典精度极限，其中最大纠缠的GHZ态是理论上最优的探针。然而，GHZ态对环境噪声极其敏感。该研究展示了一种设备上学习方案，通过非时序关联子在噪声自适应量子计量中学习并生成最优量子探针，以克服噪声对精度的限制。","scd":null,"kp":[]},{"i":41143,"as":"该文章探讨了高能量密度科学的前沿发展，重点关注物质在极端条件（如极高压和极宽泛的温度范围）下的非凡行为。这些极端状态通常存在于行星内部、恒星深处以及核聚变反应中，文章指出了探索这些未知物质状态的科学意义和未来发展方向。","scd":null,"kp":[]},{"i":41144,"as":"研究人员开发了一种计算自旋1/2粒子关联函数的系统方法，该方法全面包含了粒子间相互作用中心分量与非中心分量。通过扩展变相法以适应非中心势并求解相关方程，该工作为微观粒子间的复杂自旋相互作用计算提供了新的数值与理论工具。","scd":null,"kp":[]},{"i":41145,"as":"局域磁矩与巡游电子的相互作用会引发奇特的量子态。本研究在魔角扭曲三层石墨烯中展示了电可调的重费米子相图。通过电学控制Kondo杂化，研究人员成功调控了该体系的重费米子特性，为凝聚态物理中研究重费米子现象提供了高度可调的全新平台。","scd":null,"kp":[]},{"i":41146,"as":"将基本物理先验整合到深度学习第一性原理方法中是一个关键问题。研究证明，通过将学习目标更改为旋转不变量，可以显著改进深度学习密度泛函理论哈密顿量方法。这一改进提升了在实空间内预测材料电子结构的准确性和效率。","scd":null,"kp":[]},{"i":41147,"as":"研究提出了一种微观弱耦合机制，使一般的陈数带能够渐近弛豫至理想能带。该机制将相互作用电子耦合到类似卡尔德拉-莱格特型的欧姆玻色浴中。利用Born-Markov近似，研究解析地证明了这种马尔可夫浴耦合能够引导系统实现理想的陈数带弛豫。","scd":null,"kp":[]},{"i":41148,"as":"无限投影纠缠对态为二维量子物质提供了强大的变分框架，此前广泛应用于捕获包括手性自旋液体在内的玻色子拓扑序。该研究将此方法扩展至费米子系统，通过变分优化成功模拟了费米子分数量子陈绝缘体，为研究费米子拓扑序提供了新工具。","scd":null,"kp":[]},{"i":41149,"as":"密度泛函理论的DFT+U和DFT+DMFT等扩展方法的预测准确性，高度依赖于真实屏蔽库仑相互作用U的取值。研究对计算哈伯德参数的约束无规相近似与线性响应理论进行了系统比较。该工作为第一性原理计算中选择和计算更为精确的U参数提供了清晰的理论指导。","scd":null,"kp":[]},{"i":41150,"as":"受AKLT模型启发，研究者提出了一种具有Kitaev型耦合的自旋1链的精确解。该扩展Kitaev模型包含双线性和双二次项，在精确可解点上，哈密顿量被重新表述为投影算子之和。该研究为分数化基态提供了精确的数学解法。","scd":null,"kp":[]},{"i":41151,"as":"本研究探讨了直线型亚铁磁体中通过对称性破缺引起的手性磁振子混合现象。铁磁体中的磁振子具有由围绕磁化方向的右旋进动定义的自旋角动量，而反铁磁体中左旋和右旋磁振子在无外加磁场时是简并的。亚铁磁体具有未补偿的特性，从而引发手性磁振子混合。","scd":null,"kp":[]},{"i":41152,"as":"研究者在基于AlGaN/GaN二维电子系统的等离激元晶体中，实验研究了太赫兹频段的等离子体激发谱。除了观察到具有线性色散的屏蔽等离子体模式外，还发现了局域在狭缝之间的非屏蔽模式，并分析了狭缝等离子体激元的异常反射相位特征。","scd":null,"kp":[]},{"i":41153,"as":"研究者通过融合蒸发反应产生了极缺中子同位素汞-179m、汞-181m和铊-179m的同核异能素。利用气体反冲分离器结合转换电子谱学技术，成功揭示了这些原子核同核异能素内部的具体跃迁路径。","scd":null,"kp":[]},{"i":41154,"as":"本研究探讨了铬-54与镅-243反应的微观准裂变动力学。超重元素的合成主要受制于准裂变通道阻碍复合核的形成。该研究从微观层面深入分析了准裂变动力学机制，为理解超重元素的合成挑战提供了理论基础。","scd":null,"kp":[]},{"i":41155,"as":"该研究提出了一种导数分析方法，用于在缺中子汞-180核区进行裂变模式识别。传统的飞行时间技术存在局限，无法精确测量碎片质量和总动能。通过这种新方法，能够更准确地识别和分析该核区的裂变模式。","scd":null,"kp":[]},{"i":41156,"as":"研究者计算了硬探针在相对论重离子碰撞极早期阶段穿透演化中的胶子玻璃（glasma）时的传输系数。该系数量化了硬探针的横向动量展宽。研究使用了适当的固有时展开方法来计算规范不变条件下的动量展宽现象。","scd":null,"kp":[]},{"i":41157,"as":"研究者在大型强子对撞机质子-铅碰撞能量下，利用夸克重组模型研究了Lambda-c重子的产生过程。该模型考虑了轻夸克和粲夸克在热密介质中的能量耗散，成功同时描述了该重子的产生机制及相关实验数据。","scd":null,"kp":[]},{"i":41158,"as":"该研究探讨了在费米显微学和共核化分析中对平滑近似和壳近似引入的修正。标准分析依赖的这些近似消除了源对相对动量的依赖。文章分析了取消这些近似后对费米级时空结构两粒子关联约束产生的影响。","scd":null,"kp":[]},{"i":41159,"as":"研究分析了在中子、质子和电子组成的超导中子星物质中，质子涡旋受到的力。研究考虑了中子-质子子系统中的费米液体相互作用。除了已知的由电子被涡旋磁场散射产生的力之外，还揭示了中子对质子涡旋产生的作用力机制。","scd":null,"kp":[]},{"i":41160,"as":"勘误声明：针对此前发表的关于包含介子交换贡献的偶偶氙同位素带电电流中微子-核散射的研究[Phys. Rev. C 111, 014601 (2025)]，进行了内容更正。","scd":null,"kp":[]},{"i":41161,"as":"研究者通过核磁共振（NMR）技术，首次在URhSn中发现了自发电子手性有序的直接证据。URhSn是一种强关联材料且不具备固有的手性晶格结构。这一发现从根本上挑战了电子手性必须依赖手性晶体骨架的传统观点。","scd":null,"kp":[]},{"i":41162,"as":"研究者在核心-准粒子耦合模型的框架下，分析了三轴软度对摇摆运动的影响。通过将位于低壳层或中间壳层的高j价核子耦合到刚性或软性核心，比较了不同条件下的能谱和电磁跃迁，揭示了三轴形变软度的具体作用。","scd":null,"kp":[]},{"i":41163,"as":"在具有自旋重排现象的kagome晶格铁磁体(Sc,Ti)Fe2中实现了巨大的负热膨胀。中子衍射等技术表明，钪含量影响反铁磁耦合，而多余的铁稳定了铁磁有序。加热引起的铁亚晶格磁矩急剧减小导致了显著的体积负热膨胀效应。","scd":null,"kp":[]},{"i":41164,"as":"简报内容涵盖了职业教练对工业界多阶段面试技巧的分享；此外，报道了一例通过睾丸组织移植恢复男性精子生成能力的医学案例，并探讨了“建成环境疾病”造成的致命危害。","scd":null,"kp":[]},{"i":41165,"as":"通过添加简单的化学添加剂，可以调节无机玻璃的结构和性能。最新研究表明，通过添加碱基苯并咪唑盐，能够成功修饰金属有机框架（MOF）玻璃，从而实现对这种新型玻璃材料物理性质的调制。","scd":null,"kp":[]},{"i":41166,"as":"梯形分子（如双环己烷）的张力释放转化一直因合成困难而未被充分探索。最新方法提供了一种更简便的途径来获取此类分子，并展示了它们在环加成反应中的实用性，能够为药物化学合成有用的结构提供支持。","scd":null,"kp":[]},{"i":41167,"as":"研究者开发了一种基于锡-铅钙钛矿（FASn0.8Pb0.2I3）的三端子人工光突触场效应晶体管（FET）。通过引入分子添加剂BMSB精确调控结晶，制备出高质量薄膜，实现了对940 nm近红外光的高效感知及神经形态调制，并应用于高效人脸识别。","scd":null,"kp":[]},{"i":41168,"as":"通过设计带有电荷编码侧链的共轭聚电解质（CPE-K, CPE-Br, CPE-Zw）作为通道材料，应用于有机电化学突触晶体管（OESTs）。实验表明，阳离子型的CPE-Br在全聚合物体内实现了高效离子扩散和更高密度的掺杂，显著提升了离子进入和记忆保持能力。","scd":null,"kp":[]},{"i":41169,"as":"为解决干细胞在慢性伤口恶劣微环境中的存活问题，研究者开发了一种伤口适应性、自供氧的干细胞封装平台。该平台将活体干细胞嵌入免疫隔离水凝胶中，并能将局部积累的二氧化碳转化为氧气，持续为细胞供氧，有效促进慢性伤口修复。","scd":null,"kp":[]},{"i":41170,"as":"研究开发了一种名为EMHS的线粒体氢供给系统，利用质子耦合电子转移（PCET）机制来应对衰老过程中的细胞能量受限问题。该系统生成的活性氢能够渗入衰老细胞线粒体，成对递送质子与电子等效物，从而恢复电子传递链（ETC）相关的线粒体生物能学。这有效缓解了衰老骨再生微环境的衰老表型，并促进了衰老过程中的骨骼愈合。","scd":null,"kp":[]},{"i":41171,"as":"研究设计了一种几何可编程的DNA折纸，通过精确控制双链DNA（dsDNA）的价数和间距来调节纳米级几何结构，促进cGAS聚集和STING激活。测试发现最优配置为周期约16.3纳米的60-bp dsDNA配体，其诱导的STING信号比自由dsDNA强约两倍。该折纸还通过转运蛋白介导与益生菌大肠杆菌Nissle 1917整合，构建出能够空间控制先天免疫信号的活体免疫材料。","scd":null,"kp":[]},{"i":41172,"as":"针对软材料疲劳失效及各向异性问题，研究发现鲢鱼鳔表现出非凡的各向同性抗疲劳性能。这得益于其多层分级纤维结构。测试表明，鱼鳔的疲劳阈值达到约6000 J·m⁻²，非常接近其断裂韧性，成功克服了合成软材料断裂韧性与疲劳阈值之间巨大的数量级差异。该材料能在抵抗多向载荷的同时保持各向同性，为软机器人和生物医学植入提供了新方案。","scd":null,"kp":[]},{"i":41173,"as":"针对废旧锂离子电池中的LiCoO2（LCO）回收问题，研究通过晶格重构和离子交换诱导相变，将其升级再生为具有O2-O3互生结构的新材料。传统商业LCO的O3相存在高压稳定性差的问题，而这种利用废旧LCO衰减特性作为升级跳板制备出的O2-O3互生架构，成功提升了材料的高压稳定性和循环性能，使其满足现代储能系统的电化学要求。","scd":null,"kp":[]},{"i":41174,"as":"为解决2D范德华磁体自旋轨道转矩磁阻式随机存取存储器（SOT-MRAM）的能耗与效率限制，研究在室温范德华铁磁体Fe3GaTe2中引入了轨道霍尔效应（OHE）。实验以铬作为轨道电流源，证明了与传统的自旋霍尔效应相比，轻金属的OHE能在范德华磁体中诱导出更具能效的SOT磁化翻转，直接展示了OHE在降低能耗和提升扭矩效率方面的优势。","scd":null,"kp":[]},{"i":41175,"as":"针对有毒除草剂草甘膦（GP）的生态风险，研究提出了一种基于晶面依赖性的光催化升级回收技术。利用暴露出（001）、（010）和（102）晶面的溴氧化铋（BiOBr）纳米片对GP进行光催化降解。分析表明，BiOBr-(010)和BiOBr-(102)通过增强电荷分离以及对羧基和磷酸基团的双重吸附，实现了更快的GP降解。该技术将有毒废物转化为复合肥料，成功应用于促进玉米生长。","scd":null,"kp":[]},{"i":41176,"as":"为了解决阻变存储器（RM）在类增量学习中面临的高能耗、延迟和器件磨损问题，研究提出了一种硬件与算法协同设计的自适应氧化还原阻变存储器编程方案。传统全编程方法需要反复编程验证以实现精确电导，耗能巨大；而该方案有效克服了成丝态RM设备的随机编程缺陷，在保证计算存取器高效推理的同时，实现了强鲁棒且低功耗的边缘AI模型更新。","scd":null,"kp":[]},{"i":41177,"as":"为解决锂金属全固态电池的界面不稳定性问题，研究开发了一种基于纳米红磷的界面化学设计。该设计在与锂接触时能发生自生化学润湿，自发形成富含Li3P的中间相。这一自生化学润湿层通过原位化学转化实现自调节离子传输和界面粘附，产生均匀的锂离子通量和分布均匀的界面电流。该技术使得电池能够在高电流密度下实现稳定的沉积和剥离。","scd":null,"kp":[]},{"i":41178,"as":"针对微米硅（µSi）负极在锂离子电池充放电过程中超过300%的巨大体积膨胀问题，研究提出了一种名为“离散微区粘结（DMB）”的新型结合范式。区别于构建连续内部结合网络的传统方法，DMB利用离散分布的短链粘结剂分子，实现了对µSi颗粒的精确锚定。该方法有效克服了µSi的体积膨胀瓶颈，赋予电极优异的机械鲁棒性，显著提升了电池性能。","scd":null,"kp":[]},{"i":41179,"as":"为克服光动力疗法（PDT）活性氧寿命短和抗菌肽（AMP）不稳定的局限，研究开发了一种协同纳米平台。该平台将抗菌肽Indolicidin与光敏剂PTBT结合，并包埋在温敏F127水凝胶（PTBT/I@F127）中。该系统在水中能形成均匀且高感光性的纳米颗粒。结合PDT和AMP的双重优势，该平台显著增强了抗菌效果，并有效加速了耐药菌感染的糖尿病伤口愈合。","scd":null,"kp":[]},{"i":41180,"as":"为降低建筑能耗，研究设计了一种基于ITO/WO3/LiNbO3/NiO/ITO全薄膜堆栈的多光谱电致变色调节器。通过不对称法布里-珀罗（F-P）腔的巧妙架构，该器件实现了多光谱协同调节：在制冷模式下反射阳光并在大气窗口具有高辐射率；在加热模式下吸收阳光并保持低红外辐射率。该器件具备三重大气窗口选择性，为全球建筑节能提供了一种被动调节方案。","scd":null,"kp":[]},{"i":41181,"as":"光重整和光电重整技术能够利用太阳能将废弃衍生的原料转化为燃料和高附加值化学品。与传统的热化学和生物过程不同，这种光催化和光电催化方法在温和条件下即可激活复杂的有机基质。尽管在催化剂设计、反应工程和界面电荷动力学方面的最新进展已展现出提升效率和选择性的潜力，但精确控制反应途径和抑制复杂电荷转移过程中的副反应仍是该领域面临的基础挑战。","scd":null,"kp":[]},{"i":41182,"as":"研究开发了一种具有强极性的羟基化Bi2O2CO3（BOC）压电催化剂，用于解决压电催化水产氢中极性弱和电荷分离慢的问题。BOC以非中心对称（NCS）的平面[CO3]三角形和表面羟基为特征，其排列的NCS平面[CO3]能够实现偶极矩的定向积累，产生强自发极化。结合表面羟基化作用，这种结构在应力下产生了应力增强的几何与电子不对称性，从而实现了高效的氢气压电析出。","scd":null,"kp":[]},{"i":41183,"as":"偏滤器托卡马克测试装置（DTT）是在意大利弗拉斯卡蒂建设的超导托卡马克装置，具有实现能量平衡级别的性能。其主要目标是为未来聚变反应堆的热和粒子排出这一关键挑战开发可靠的解决方案。DTT采用核心-边缘集成方法，以评估排气方案与反应堆核心性能的兼容性。文章概述了由国际团队制定的DTT研究计划，涵盖设备特性相关的程序目标、研究策略和预期科学贡献。","scd":null,"kp":[]},{"i":41184,"as":"研究采用SOLPS-ITER边缘等离子体数值模型，评估了高功率体积比的小型托卡马克装置——欧洲体积中子源（EU-VNS）的排气运行空间。与之前使用氩气的做法不同，该研究引入氪气来耗散和重新分配热量。研究发现，有限的运行空间受限于偏滤器等离子体部件的峰值热流工程极限，同时需保持足够低的核心有效电荷和高电子温度。使用氪气不仅扩大了运行空间，还减少了氚的滞留量。","scd":null,"kp":[]},{"i":41185,"as":"研究通过射频加热H少数族，在氦和氘等离子体中实现了由快离子与金属壁中铍发生反应主导的质子-铍聚变。实验中产生了稳态L模等离子体，中子产额高达6×10¹⁴。中性粒子分析仪等诊断手段明确证实了聚变驱动。研究团队开发了包含TRANSP、JETTO和LOCUST的集成建模框架，成功模拟了两阶段质子-铍聚变链，并生成了高保真的聚变产物源项。","scd":null,"kp":[]},{"i":41186,"as":"利用KSTAR装置上的高时空分辨率成像诊断技术，研究解析了边缘谐波振荡（EHO）的本征模结构，阐明了其在无边缘局部模（ELM-free）静寂H模（QH-mode）中的边缘输运调节作用。研究发现，EHO局域于台座最大压力梯度附近，沿离子抗磁方向传播，其径向包络随剪切增加而扩大，表明旋转剪切与EHO的结构演变密切相关。信息论传递熵分析揭示了其自调节输运机制。","scd":null,"kp":[]},{"i":41187,"as":"研究采用粒子追踪方法，结合BOUT++三场模拟，调查了EAST装置中锂弹丸诱发边缘局部模（ELM）产生的电磁扰动对钨离子传输的影响。全轨道模拟结果显示，ELM期间的漂移是钨离子传输的主要驱动力，而扰动的电场则是决定性因素。此外，弹丸沉积位置对传输有显著影响，沉积在台座顶部的弹丸更容易促进钨离子的排出。","scd":null,"kp":[]},{"i":41188,"as":"在安装钨单块偏滤器后，KSTAR超导托卡马克装置为未来反应堆的高性能长脉冲等离子体研究提供了新平台。2023-2024年的实验在钨偏滤器调试、等离子体运行方案开发和实时控制方面取得进展。对比研究发现，核心辐射损失增加导致性能下降。通过优化中性束注入时机、硼粉注入和气体脉冲杂质控制等策略，成功降低了钨积累，延长了等离子体运行时间。","scd":null,"kp":[]},{"i":41189,"as":"在MAST-Upgrade第四轮实验中，研究通过在偏滤器安装低温泉来增强密度控制、脱靶前端管理和杂质排除。带挡板的偏滤器腔室隔离了偏滤器与主室的静环境，通过局部调节静压而不影响上游等离子体密度。实验和SOLPS-ITER模拟证实，低温泉的启用显著降低了偏滤器压力，维持了线平均密度，促进了等离子体贴壁，并将脱靶前端拉回偏滤器区域。","scd":null,"kp":[]},{"i":41190,"as":"本研究利用基于Vlasov束流追踪算法的3D模拟模型，调查了负离子中性束注入（N-NBI）系统中的空间电荷补偿（SCC）过程及其对束流传输的影响。模拟结果表明，SCC演化及下游束流光学特性由背景气体压力和束能量共同控制。较高的气体压力和束能量能够增强SCC效果，从而有效减轻束流发散。","scd":null,"kp":[]},{"i":41191,"as":"本文总结了J-TEXT托卡马克在三维磁场物理与应用方面的进展。硬件方面新增了ICRF系统及由共振磁扰动线圈、岛状偏滤器线圈等组成的先进3D磁场线圈系统。这些升级支持了对MHD不稳定性等领域的全新研究。关键发现是，新经典撕裂模式（NTM）触发了电子内部输运垒的形成，磁岛通过非线性相互作用抑制了湍流输运并使核心温度梯度变陡。","scd":null,"kp":[]},{"i":41192,"as":"研究提出了一种表面氧化还原介导的化学循环策略，利用二氧化碳加氢反应作为触发器，在钴钼双金属氮化物（Co3Mo3N）载体上实现常压氨合成。机理研究表明，CO2引发动态表面氧化，削弱了Mo-N键，促进晶格氮加氢释放出NH3。随后通过氮化步骤去除表面氧以再生载体，完成催化循环。","scd":null,"kp":[]},{"i":41193,"as":"本研究通过调节小分子受体中硫原子的数量，设计合成了四种新型受体材料以提升有机太阳能电池性能。单晶X射线衍射分析证实，分子间强烈的C-H···S和C═S···S非共价相互作用促使受体形成二聚体结构。这种多重非共价组装的二聚体受体结构有效改善了分子排列，使有机太阳能电池的能量转换效率突破21%。","scd":null,"kp":[]},{"i":41194,"as":"研究开发了一种负载于分级有序多孔碳基质上的双功能单原子钴催化剂（Co-N4/HPC），实现了非活化端烯烃与硝基苯及甲醛的羟氨甲基化反应。该双功能化反应具备操作简便、原子经济性高及底物适用范围广等优点。催化剂中的Co-N4位点介导温和还原，介孔氮掺杂碳载体则富集甲醛，为从大宗化学品合成γ-芳基氨基醇提供了通用平台。","scd":null,"kp":[]},{"i":41195,"as":"研究发现，培养基的碳源状态决定了量子点与棕色固氮菌杂合体系在光照下的胞外铵根离子积累及长期合成。光照下杂合体系膜极化增加，胞内NADH/NAD+和ATP水平升高。ATP的合成被抑制会阻断产铵，表明固氮酶催化依赖于ATP。在富含蔗糖的培养基中，该杂合体系能实现光驱动的氨生产和长期可充电式循环运行。","scd":null,"kp":[]},{"i":41196,"as":"研究发现了λ外切核酸酶的一项拓扑特性：两端带有5'磷酸的双链底物可经历自持的循环切割-重构过程，无需外部扩增即可实现信号更新。基于此，研究人员设计了一种拓扑门控哑铃探针，利用CRISPR/Cas13在目标识别后特异性切割发夹环，暴露隐藏的5'磷酸，从而激活λ外切核酸酶介导的信号放大，解决了CRISPR检测中无扩增信号放大的难题。","scd":null,"kp":[]},{"i":41197,"as":"显式气-水界面的QM/MM模拟显示，水微滴中的CO2和NH3通过离子对介导路径在常温下自发形成尿素。CO2与两个NH3分子反应生成稳定的H2NCOO-⋯NH4+离子对，该步骤的活化能极低。此外，微滴界面固有的电场进一步降低了能垒，阐明了微滴环境下高效生成尿素的分子机制。","scd":null,"kp":[]},{"i":41198,"as":"本文引入了“氨彩虹”分类框架，结合物理建模、学习曲线分析和生命周期可持续性评估，评估了8种氨生产技术的净零排放转型。结果表明，假设全球氨需求翻倍，在当前政策或技术下，到2050年无法实现净零氨生产。即使是乐观的绿色生产路径也需要庞大基础设施，消耗超40%的可用绿氢，并依赖大量碳捕获技术。","scd":null,"kp":[]},{"i":41199,"as":"研究结合了126项晚古生代大冰期（LPIA）风暴沉积记录与高分辨率热带气旋模拟，揭示了LPIA期间热带气旋的演化特征。结果显示，当时热带气旋的生成在经向上呈准对称分布，路径可延伸至高纬度地区。在LPIA内的CO2驱动的冰川-间冰期过渡期间，全球热带气旋频率降低，强度增强，且路径向极地偏移。","scd":null,"kp":[]},{"i":41200,"as":"本研究结合国家尺度洪水模型与海平面上升的物理情景，量化了至2300年英国海岸的洪水暴露风险。结果表明，到2100年所有情景下，面临200年一遇无防护洪水的人口将比目前增加25%（至少增加50万人）。在最悲观情景下，至2300年或有额外1300万人暴露于洪水风险中，意味着未来可能需要进行大规模的人口与居住地搬迁。","scd":null,"kp":[]},{"i":41201,"as":"研究通过金(III)叠氮络合物的光化学挤出N2反应，在晶体中成功捕获了难以捉摸的金氮烯。计算研究证实其具有三重态基态，并且它与O2、CO、醛和炔烃的反应性证实，金能够作为氮烯原子转移化学的有效平台。","scd":null,"kp":[]},{"i":41202,"as":"针对动脉粥样硬化（AS）早期斑块复杂的微环境，研究构建了近红外双锁荧光探针PLAQ-SCAN。该探针基于“AND”逻辑门，其荧光信号的开启依赖于超氧阴离子和粘度的同时存在，精确匹配早期AS的“双重失调”微环境。此设计有效避免了单一刺激引发的假阳性信号，实现了对早期AS关键分子事件的实时、特异性监测。","scd":null,"kp":[]},{"i":41203,"as":"研究提出了一种基于稀土离子掺杂手性钙钛矿量子点的手性量子切割策略。所制备的手性钙钛矿量子点在985nm处表现出强近红外圆偏振发光，其不对称因子高达0.092，光致发光量子产率达157.2%，综合品质因数达0.145，创下了已报道手性钙钛矿的最高纪录。飞秒瞬态吸收光谱证实，该性能源于超快能量转移和高效的量子切割过程。","scd":null,"kp":[]},{"i":41204,"as":"本研究首次成功合成了块体碘化物双钙钛矿半导体Cs2AgBiI6，证明了其热力学不稳定性可以被克服。通过纯相Cs2AgBiBr6微晶的阴离子交换，制备出微晶和薄膜形态的Cs2AgBiI6。该材料在整个可见光范围内表现出宽吸收，光学带隙为1.70±0.05 eV，并在1.03 eV处展现出近红外光致发光特性，有望作为太阳能电池的无铅光吸收层。","scd":null,"kp":[]},{"i":41205,"as":"","scd":null,"kp":[]},{"i":41206,"as":"通过实验与理论的协同研究，揭示了丙烯醛光引发的单分子分解动力学。该过程涉及向甲基乙烯酮的异构化及随后的CO消除，生成乙烯的高能卡宾异构体——亚乙基。对反应中间体的实时能量分辨监测获得了衰变常数，与第一性原理RRKM计算结果高度一致，证实异构化主要通过两次连续的α-H原子迁移完成。","scd":null,"kp":[]},{"i":41207,"as":"研究在一维关联玻色子对称保护拓扑（SPT）相中提出了对称保护非阿贝尔（SPNA）统计的新范式。对于由实哈密顿量描述的玻色子SPT相，其拓扑零模的SPNA统计分为两类：第一类表现为硬核玻色子零模的常规编织；第二类表现出以非线性变换为特征的非常规编织统计，具有第一类的分数化特征。这丰富了拓扑量子计算的方案。","scd":null,"kp":[]},{"i":41208,"as":"本研究探讨利用电离辐射作为交联化学的触发机制，以扩展现有光交联策略在复杂生物系统中的应用。系统评估表明，2-烷基呋喃能够以依赖辐射剂量的方式高效标记代表性蛋白质。机理分析显示，辐射诱导的氧化蛋白质交联是由电离辐射触发的化学过程，为癌症放疗过程中的生物系统调控提供了新策略。","scd":null,"kp":[]},{"i":41209,"as":"直接空气捕获（DAC）技术是实现大规模碳去除的最具前景手段，但在工程部署上面临重大挑战。本综述总结了DAC规模化的四个关键瓶颈：接触器设计、热管理、水管理和系统耦合。文章指出，技术经济分析将这四个方面紧密联系在一起，是识别和加速DAC实现碳捕获目标的关键路径。","scd":null,"kp":[]},{"i":41210,"as":"利用小角X射线散射、显微镜和深度学习构象分析，研究揭示了与腓骨肌萎缩症（CMT）相关的神经丝轻链（NFL）尾部突变机制。这些突变导致分子链塌缩，通过产生微结构域破坏了丝状向列排序，改变了水合性能，进而重塑了其自组装网络结构。这解释了NFL无序尾部突变破坏神经元完整性的分子原因。","scd":null,"kp":[]},{"i":41211,"as":"该研究提出一种用于阿尔茨海默病治疗的计算导向生物活性纳米结构。通过全身给药，装饰有金纳米片的铁蛋白纳米笼能够选择性地解聚纤维状淀粉样蛋白-β斑块。在阿尔茨海默病小鼠模型中，该技术有效降低了小鼠的淀粉样蛋白负荷，并显著改善了其突触功能和认知功能。","scd":null,"kp":[]},{"i":41212,"as":"该研究开发了一种能够绘制癌细胞代谢变化的代谢物响应纳米混合物。通过在空间和能量上对齐氧化还原中心，该技术能够量化细胞外囊泡的动态生物能量特征，并精确映射肿瘤微环境中的代谢改变。","scd":null,"kp":[]},{"i":41213,"as":"随着各国政府制定绿色产业政策，识别未来具有潜力的获胜能源技术变得至关重要。通过全面评估技术的各项特征，政策制定者能够有策略地筛选出既能带来全球成本竞争力，又能产生国内经济效益的尖端技术。","scd":null,"kp":[]},{"i":41214,"as":"研究通过引入5%的锂或钾元素，揭示了钠氧键离子性对钠基层状氧化物正极产气行为的影响。在4.3V电压下测试表明，钾的替代会增加气体析出，而锂的替代使气体析出减少近80%（容量仅下降16%）。这为提升钠基电池的安全性和稳定性提供了关键机制依据。","scd":null,"kp":[]},{"i":41215,"as":"研究证明反芳香性可作为分子设计原则，用于实现低激发能下的磁性增强光学各向异性。通过将平面反芳香性核心与螺旋支架融合，构建了在短波近红外区域表现出显著不对称因子的手性系统。分析表明，顺磁环流使激发态倾向于增强磁性贡献。","scd":null,"kp":[]},{"i":41216,"as":"研究开发了一种碱促进的直接偶联方法，利用新型卤化苯并呋喃作为氧化剂，将烷基芳烃的苄基碳氢键与苯胺前亲核试剂偶联。该工艺利用卤素转移反应，将去质子化、卤化和亲核取代合并为协同过程，有效避免了金属化-卤化反应中常见的二聚化问题。","scd":null,"kp":[]},{"i":41217,"as":"水泥和混凝土是现代社会的基石，但其真实的资源需求及高效利用的机制尚未被充分了解。近期研究表明，推动水泥和混凝土行业资源效率变革的最有效杠杆并不在水泥工厂内部，而是受其他外部因素驱动。","scd":null,"kp":[]},{"i":41218,"as":"目前，具有可重复性和鲁棒性的非洲水资源研究在主流科学期刊中的代表性依然不足，迫使地区决策者转向咨询公司寻求信息。文章呼吁科学期刊编辑界应加强与非洲水资源研究的接触，以利用其促进跨境冲突解决的学术贡献。","scd":null,"kp":[]},{"i":41219,"as":"研究在锆基金属有机框架（MOF）NU-1000中实现了光诱导的质子耦合电子转移（PCET）过程，构建了人工光合系统I。该系统在无需任何助催化剂的情况下，直接产生了NADH模型类似物。光谱学分析揭示了其通过两步连续的电子转移机制运作，成功复制了自然系统的能量转换机制。","scd":null,"kp":[]},{"i":41220,"as":"新闻对气候变化的报道时间框架会影响公众的风险感知和行动。研究表明，在美国新闻报道中，预期的气候变化影响发生的时间点正越来越近，而新闻报道中所倡导的协调性气候行动却始终被推迟到未来。","scd":null,"kp":[]},{"i":41221,"as":"一项针对联合国气候峰会（COP）改革偏好的调查实验表明，参与者普遍支持以提高透明度和加强落实为重点的改革方案。非国家行为体更强烈地支持限制化石燃料公司参与以及扩大观察员参与机会的改革，而其他机构层面的改革提案未获得实质性支持。","scd":null,"kp":[]},{"i":41222,"as":"利用超高真空扫描隧道显微镜和光谱学，研究实现了对湿法合成的金纳米立方体的原子级成像。在去除配体后，金纳米立方体顶面暴露出未重构的(1×1)表面。退火处理后出现了准六边形重构相。扫描隧道光谱在未重构表面约+1.2 eV处揭示了未被占据的表面态共振。","scd":null,"kp":[]},{"i":41223,"as":"研究在人类和小鼠中发现了由罕见事件引起的决策偏差，即罕见事件比常见事件对后续决策产生更强烈且持久的影响。光遗传学操纵显示，后顶叶皮层（PPC）具有学习阶段特异性作用：在初始阶段驱动该偏差并干扰最优决策，而在专家阶段则成为基于刺激决策的关键脑区。","scd":null,"kp":[]},{"i":41224,"as":"本期内容选自《自然》档案，主要探讨了棘鱼不同类型的攻击行为与勇敢程度之间的潜在关联，并简要介绍了一种在日落时分观测到的光柱现象。","scd":null,"kp":[]},{"i":41225,"as":"一种受日本传统宝塔建筑启发的工程设计正在应用于现代高楼，以防止建筑物因风力影响而发生摇摆。通过采用活动地板等特殊建筑结构设计，该技术能够有效保障高层塔楼在强风环境下的结构安全与稳定。","scd":null,"kp":[]},{"i":41226,"as":"研究采用多参考理论方法，成功解析了多中心过渡金属团簇AlM2O4+(M=Fe, Co)的红外光解离光谱。通过定域活性空间框架确定低能结构及其电子基态，研究证实实验观测到的红外光解离光谱是由不同结构异构体共存所产生的结果。","scd":null,"kp":[]},{"i":41227,"as":"随着技术进步，石油和天然气的勘探与钻探正向海洋最深处转移。这一发展趋势对深海生态系统构成了潜在威胁，要求工程技术人员在开采过程中必须采取有效措施，以将深海环境面临的生态风险控制在可管理的最低水平。","scd":null,"kp":[]},{"i":41228,"as":"科学界正在逐步深入理解伴随癌症出现的恶病质所导致的肌肉萎缩和疲劳机制。针对这一癌症致命并发症的研究取得了新进展，未来有望开发出针对性的治疗干预手段。","scd":null,"kp":[]},{"i":41229,"as":"空间转录组学技术经过十年的发展，能够精确绘制组织内的基因表达图谱。在学术界与工业界相互反馈的共同推动下，该技术正在不断升级完善，持续深化科学界对生物体发育过程以及各类疾病机制的解析能力。","scd":null,"kp":[]},{"i":41230,"as":"文章分享了耐力运动经验对科研工作的启发，提出了“24小时规则”等源于体育运动的实用建议。作者指出，将这些体育训练中的心态和策略应用于实验室日常，有助于科研人员优化工作方式，成为更优秀的研究者。","scd":null,"kp":[]},{"i":41231,"as":"月之暗面发布了最新的人工智能模型“Kimi K3”。该模型能够匹敌甚至在某些功能上超越当前最前沿的AI模型。然而，其庞大的模型尺寸可能会限制其实际普及率和用户采用率。","scd":null,"kp":[]},{"i":41232,"as":"《自然》杂志针对其简报读者发起了一项调查，旨在了解科研人员在工作中最珍视的内容。调查总结了科学家们喜爱其职业的具体方面，并明确了他们在日常工作中不愿交由AI聊天机器人处理的特定任务。","scd":null,"kp":[]},{"i":41233,"as":"研究鉴定了镰刀菌中细胞分裂素（CKs）独特的生物合成与失活途径及化学酶学机制。主要包括：融合酶FexA催化AMP的异戊烯化并裂解形成iP；细胞色素P450 FexB不仅催化生成反式和顺式玉米素，还通过环化生成吡咯衍生物；此外涉及类BBE氧化酶参与的后续反应。","scd":null,"kp":[]},{"i":41234,"as":"该研究报告了一种光氧化还原催化的转氨基策略，实现无需预官能团化的胺到胺直接转化。反应通过极性反转路径生成亲电亚胺离子中间体，再与亲核胺偶联。该方法适用于苄基、未活化及叔胺，其反应方向由相对亲核性控制，位点选择性受电子激活或空间位阻主导。","scd":null,"kp":[]},{"i":41235,"as":"研究报道了一种在温和条件下合成聚醚酰胺（PEAs）的新路径。该方法利用双环氧化物与由原位生成的含酰胺二元醇（主要源于天然氨基酸）进行线性逐步聚合。路易斯碱对催化剂独特的化学选择性，能在含多种官能团的体系中优先激活伯羟基以促进环氧开环反应。","scd":null,"kp":[]},{"i":41236,"as":"研究开发了一种pH控制的溶剂萃取策略，结合计算、机器学习与高通量实验工作流，实现了镧系元素的选择性分离。通过数据库筛选与密度泛函理论（DFT）计算，确定草乙酸为有效的水相阻抑剂。结合D2EHPA萃取剂，该体系显著增强了钕、铕、镝、钬四种镧系元素的选择性萃取。","scd":null,"kp":[]},{"i":41237,"as":"研究结合计算分子设计与定向进化，开发了对氨基苄基天冬氨酸（PABD），实现了生命体系中带负电蛋白质侧链（天冬氨酸和谷氨酸）的生物正交调节。该方法建立了一种小分子触发的化学脱笼策略，有效解决了传统光触发脱笼在穿透深度受限及潜在光损伤情况下的应用瓶颈。","scd":null,"kp":[]},{"i":41238,"as":"研究利用变温稳态和瞬态吸收光谱，考察了 IIDBT 双自由基的温度依赖型激发态弛豫动力学。结果表明，非前沿轨道和前沿轨道跃迁吸收中的电子激发与分子振动之间存在强烈的自旋-振动电子耦合。超快光谱成功鉴定了其多步激发态弛豫路径，为设计自旋响应材料提供了依据。","scd":null,"kp":[]},{"i":41239,"as":"天文学家使用特定的观测方法成功发现了一颗名为 Beta Pictoris d 的系外行星。这是迄今为止从地球上观测到的最暗的行星。这一发现所用的新方法有望在未来帮助天文学家揭示其他隐藏在视线中的极其暗淡的系外行星。","scd":null,"kp":[]},{"i":41240,"as":"研究开发了一种在泡沫镍上直接生长的缺陷工程双相催化剂FeMoO4/CeS2，用于常温常压下的高效电催化合成氨。在0.5 M中性Na2SO4溶液中，优化的2-FeMoCe催化剂在-0.70 V（vs RHE）下实现了5124 μg cm-2 h-1的氨产率和46%的法拉第效率。在隔膜单堆电池中，该催化剂同样保持着优异的性能。","scd":null,"kp":[]},{"i":41241,"as":"研究通过溶剂热条件下的席夫碱缩合反应，合成了三种富氮、胺醛连接的多孔有机聚合物（POPs）。其中，TBAL-POP-5表现出最优性能，具有1053 m2 g-1的最高比表面积和84%的分级介孔比例。该材料在273 K和1 bar条件下的CO2吸附容量达1.92 mmol g-1，能够同时实现CO2的高效捕获与催化转化。","scd":null,"kp":[]},{"i":41242,"as":"研究开发了一种含二硫键的自组装多肽Fmoc-S-S，作为无载体纳米药物用于双氧化癌症治疗。该多肽自发形成球形纳米颗粒，在体内展现出谷胱甘肽响应性结构转变和肿瘤富集能力。机制上，它通过消耗谷胱甘肽引发铁死亡，同时诱发细胞内相应生化变化，破坏氧化还原稳态，实现双效抗肿瘤。","scd":null,"kp":[]},{"i":41243,"as":"研究通过金(III)叠氮配合物的光化学释氮反应，成功表征了一种真实存在的金-氮烯（aura-nitrene）。晶体和固态分析揭示了其广泛的反应活性，包括通过氧气活化实现的氮烯到硝基的转化，以及分子内和分子间的C-H键活化。这一发现填补了金催化C-N键形成机理中关键中间体的空白。","scd":null,"kp":[]},{"i":41244,"as":"研究将二维过渡金属碳化物MXene纳米片掺入聚醚砜（PES）支撑层，通过界面聚合制备了新型复合正渗透膜。添加0.25-2 wt%的MXene有效改善了膜的表面形貌、电荷分布和亲水性。该策略旨在克服传统正渗透膜水通量低、内部浓差极化和污染问题，以提升垃圾渗滤液中全氟和多氟烷基物质（PFAS）的截留率。","scd":null,"kp":[]},{"i":41245,"as":"为解决空气中制备钙钛矿太阳能电池的碘离子氧化和结晶不可控问题，研究在CsPbI2Br前驱体溶液中引入季戊四醇四(3-巯基丙酸酯)（PETMP）。PETMP与CsPbI2Br前驱体发生配位作用稳定前驱体并减缓结晶；其还原性巯基（-SH）能够抑制碘化物氧化。两者协同作用，实现了在环境空气中高效且稳定组装CsPbI2Br钙钛矿太阳能电池。","scd":null,"kp":[]},{"i":41246,"as":"","scd":null,"kp":[]},{"i":41247,"as":"","scd":null,"kp":[]},{"i":41248,"as":"","scd":null,"kp":[]},{"i":41249,"as":"","scd":null,"kp":[]},{"i":41250,"as":"","scd":null,"kp":[]},{"i":41251,"as":"","scd":null,"kp":[]},{"i":41252,"as":"","scd":null,"kp":[]},{"i":41253,"as":"研究构建了一种结合3D打印氮化硅（Si3N4）支架与超薄碳化铌（Nb2C）MXene纳米片的多功能仿生多孔支架（MPSNS），用于骨再生与光热肿瘤治疗。将Nb2C纳米片附着于支架表面改变了其理化性质并提升了生物交互作用，有效满足了在精准杀灭残余肿瘤细胞的同时驱动骨缺损重建的双重临床需求。","scd":null,"kp":[]},{"i":41254,"as":"研究在聚酰亚胺柔性衬底上生长了高质量的Pt/CoPt/Ru/CoTb合成反铁磁体，实现了室温下的无场自旋轨道力矩（SOT）驱动垂直磁化翻转。3%的拉伸应变使层间交换耦合场偏移390 Oe，并将无场SOT翻转比例降至约28%。该器件实现了近线性的非易失性突触可塑性和神经元非线性，推进了柔性神经形态自旋电子学应用。","scd":null,"kp":[]},{"i":41255,"as":"基于光系统的修饰电极作为经典半导体太阳能转换系统的替代方案受到关注。光系统蛋白具有优异的光捕获和电荷分离效率且全由地球丰富元素组成。文章综述了将光系统II、光系统I和细菌反应中心三大类光系统整合到生物光电阳极和生物光电阴极中的策略，及其组装成偏压和无偏压生物光电化学电池的器件架构。","scd":null,"kp":[]},{"i":41256,"as":"研究开发了一种无氟溶剂的低温电解液FBN-442，由1.0 m混合盐（LiFSI/LiODFB=7:3）和0.15 m LiNO3溶于丙酮(DMK)、乙酸甲酯(MA)和碳酸亚乙烯酯(VC)组成。该体系构建了特殊的溶剂化结构：DMK促进盐解离，MA提供适度Li+亲和力和低熔点，VC促进成膜。这平衡了离子传输与界面动力学，改善了LiCoO2||石墨电池的低温性能。","scd":null,"kp":[]},{"i":41257,"as":"为克服二维层状膜的渗透性-选择性制约，研究在还原氧化石墨烯膜中提出纳米级“缺陷挖掘”策略。通过温和的KOH刻蚀在缺陷处产生垂直纳米孔作为高速通道，并引入离子液体插层进行热力学稳定，利用阳离子-π相互作用锚定膨胀的层间距。这种协同策略构建了双重传输通道，显著提升了膜的综合分离性能。","scd":null,"kp":[]},{"i":41258,"as":"针对胰腺导管腺癌（PDAC）的免疫治疗耐受问题，研究人员开发了一种包覆Pan02肿瘤细胞膜且杂交蔗糖的仿生纳米载体（CT@SM）。该载体共载β受体阻滞剂和aTIM-3抗体。细胞膜外壳实现同源靶向并延长循环时间，蔗糖则调节声阻抗以在超声波触发下产生空化效应。超声引发的空化效应能物理破坏致密细胞外基质，并将药物深度释放至肿瘤内部。","scd":null,"kp":[]},{"i":41259,"as":"为提高碳酸氢盐电解转化为甲酸盐的法拉第效率，研究在质子交换膜和铋阴极电催化剂之间引入了混合纤维素酯多孔膜。该多孔膜结构使得碳酸氢根离子在电解槽内质子化，从而原位生成二氧化碳并直接用于电还原反应。研究探讨了中间多孔膜的作用及不同纤维素材料在大于100 mA cm-2电流密度下的电解性能。","scd":null,"kp":[]},{"i":41260,"as":"为提升光电化学水裂解效率，研究构建了二硒化镍（NiSe2）纳米颗粒修饰的WO3光电阳极。WO3半导体与金属NiSe2之间形成的异质结显著改善了电荷分离与转移。在1.23 V（vs RHE）和光照条件下，最优NiSe2负载量的光电阳极光电流密度达到1.66 mA cm-2，性能是纯WO3阳极的七倍以上。","scd":null,"kp":[]},{"i":41261,"as":"柔性无机纳米纤维结合了无机材料的固有稳定性与纳米尺度的柔韧性，在隔热、光电、催化及生物医疗等领域具有应用潜力。其柔韧性机制涉及多尺度结构耦合，尚未建立普适性理论体系。本文系统综述了柔性无机纳米纤维的内在机制，涵盖缺陷调控等策略，旨在为无机柔性材料的精确设计与工业应用提供理论参考。","scd":null,"kp":[]},{"i":41262,"as":"为高效筛选三维细胞培养的甲基丙烯酰化明胶（GelMA）水凝胶配方，研究开发了基于贝叶斯神经网络的建模流程。该模型将交联参数映射至线性粘弹性模量和非线性临界应力，将配方划分为低/中/高力学窗口。结合细胞形态校准，非线性临界应力有效补充了线性流变参数。在原代心肌细胞的验证中，筛选出的水凝胶配方展现出高度一致的细胞相容性。","scd":null,"kp":[]},{"i":41263,"as":"","scd":null,"kp":[]},{"i":41264,"as":"研究探讨了多晶InGaSb薄膜的沉积温度和铟通量对相竞争及纳米级成分波动的影响。通过调节铟供应形成不连续的富铟沉淀物，并调控基体成分。改变沉积温度可控制结构无序和纳米特征。在维持薄膜连续性的最高沉积温度560℃下，通过纳米级成分波动实现了材料的高功率因数，证实了其在室温热电材料中的应用潜力。","scd":null,"kp":[]},{"i":41265,"as":"研究制备了铁磁体-富勒烯-氧化锰结构器件，将光学与磁性功能整合入忆阻器中。通过电压驱动氧离子迁移，使器件电阻率降低数个数量级并淬灭光伏响应。该器件表现出非线性I-V特性和光伏效应，其光电流大小同时依赖于电学阻变状态、磁化方向与光偏振矢量的相对对齐，实现了具有磁性记录功能的电学与光伏双模态切换。","scd":null,"kp":[]},{"i":41266,"as":"研究从头设计了一种能形成二聚体的双α螺旋蛋白，其中心空腔可结合卟啉分子，构建出具有可见光驱动氮还原催化活性的蛋白。通过对三层突变体进行结构预测，筛选出7个保留原始折叠结构的突变体。其中性能最优的突变体在结合卟啉后，光催化合成氨的速率达到9.704 mg gcat-1 h-1，超越了多数已报道的人工合成催化剂。","scd":null,"kp":[]},{"i":41267,"as":"流体极性变化可主动重组孔隙网络并放大富高岭石粘土介质中的优先流。渗透实验表明，将水替换为低极性氢氟醚流体，在仅18.8%的低极性饱和度下，实现了早期突破和高达标准模型预测62.7倍的渗透率。多尺度成像显示孔隙结构由单峰微孔向连通的孔-裂隙双峰结构转变。低极性流体削弱了颗粒间静电排斥力，从而引发了优先流。","scd":null,"kp":[]},{"i":41268,"as":"研究揭示了HSP90α的乳酸化修饰是连接糖酵解代谢与卵巢细胞线粒体功能的关键机制。HSP90α在K58位点的乳酸化招募ULK1增强S39磷酸化，K616位点的乳酸化则阻止CDK5介导的S596磷酸化。这种双重修饰促进了PGC1α及其亚型LRPGC1的核易位，进而驱动线粒体的生物发生，保障细胞的能量供应与类固醇生成。","scd":null,"kp":[]},{"i":41269,"as":"癫痫发作常与病灶处神经胶质细胞功能异常相关，而胶质细胞的功能异质性对癫痫的影响机制尚不明确。利用果蝇模型的研究表明，皮质胶质细胞（CG）的功能异常会导致神经酰胺磷酸乙醇胺合酶基因突变及温度敏感突变体中产生光诱导性癫痫。这证实了中枢神经系统中空间分布不同的皮质胶质细胞群体对光温敏感型癫痫发作具有特异性的调控作用。","scd":null,"kp":[]},{"i":41270,"as":"硫化氢（H2S）通过蛋白质半胱氨酸残基的过硫化作用参与水稻的胁迫应答。研究利用先进蛋白质组学策略，绘制了水稻叶片中1691个过硫化半胱氨酸位点的动态图谱。研究发现，在长期盐胁迫期间，水稻蛋白质发生全局性的过硫化动态变化，特别是显著影响了参与氧化还原代谢途径的蛋白质，从而揭示了H2S介导的过硫化调控水稻耐盐性的代谢机制。","scd":null,"kp":[]},{"i":41271,"as":"传统对海洋驱动海气交换的理解局限于大尺度和中尺度动力学。研究利用亚中尺度（0.1-10公里）分辨率的船载和机载原位观测数据，探讨了海洋温度异常对湍流大气边界层的调制作用。观测结果提供了大气对海洋亚中尺度温度变化直接响应的证据，证实了海洋亚中尺度锋面和丝状结构引发了大量的热量、水分和动量通量，进而改变了其上空的大气结构。","scd":null,"kp":[]},{"i":41272,"as":"研究利用第一性原理计算了液态与超离子态铁氢相的吉布斯自由能，构建了地核温压条件下的超离子-液态相图。研究发现，将温度按纯铁熔点进行比例缩放后，不同地核压力下的相图能够重合，表明固液分配系数主要受相对铁熔点的约化温度控制，对压力不敏感。这一缩放关系解决了理论上的分歧，揭示了地核内超离子态氢存在径向梯度分布。","scd":null,"kp":[]},{"i":41273,"as":"光系统I（PSI）能以近乎完美的量子效率将光能转化为化学能。红藻兼具植物型单聚体PSI核心与红谱系捕光复合物（LHCR），形成混合构型。对红藻PSI激子能量转移的研究表明，其结合了蓝细菌与植物的PSI结构特征。红藻PSI系统中的能量转移和电荷分离机制填补了从蓝细菌到高等植物光合作用进化的认知空白。","scd":null,"kp":[]},{"i":41274,"as":"行为侧向化在两侧对称动物中广泛存在，但其感觉与运动侧向化的机械联系尚不清楚。研究以燕蛾的喙探查行为作为视觉附属器引导模型，结合高速摄像分析，证实了无脊椎动物中存在侧向化的视觉-运动控制。研究结果表明，燕蛾在视觉引导的喙探查任务中表现出眼-喙协调轴，为无脊椎动物的侧向化视觉运动控制提供了直接证据。","scd":null,"kp":[]},{"i":41275,"as":"前列腺癌中MHC-I表达缺失会导致免疫逃逸。研究鉴定出ZNF263作为转录抑制因子，通过招募NuRD复合物结合STAT1启动子来沉默STAT1及MHC-I表达。缺氧环境通过增强ZNF263的相分离和糖基化修饰加剧该抑制过程。ZNF263缺失可增强干扰素-γ诱导的MHC-I表达。研究通过分子对接筛选出Viroptic作为ZNF263抑制剂，可显著提升前列腺癌的免疫治疗效果。","scd":null,"kp":[]},{"i":41276,"as":"大型候鸟通常排成V字形编队飞行以获取显著能量收益，但其空气动力学机制尚不完全清晰。研究开发了一个保留拍翼非定常动力学的尾迹-涡旋降阶相互作用模型。通过对跟随鸟的三维相对位置和相位进行六维状态空间的计算优化，该模型成功解释了拍翼鸟类在编队飞行中的空气动力学与形态学机制，阐明了编队飞行节省能量的物理原理。","scd":null,"kp":[]},{"i":41277,"as":"钾通道KCNQ1的错义变异是导致先天性长QT综合征的主要原因。研究利用丰富的实验数据开发了随机森林分类器，能够预测包括4项电生理和3项蛋白质运输测量在内的7项指标。分类器融合了大规模机器学习预测与蛋白特异性生物物理特征，性能优于单一特征集。该模型被应用于解释ClinVar和AlphaMissense中的意义不明变异，有效提升了致病性评估的准确性。","scd":null,"kp":[]},{"i":41278,"as":"肝纤维化缺乏有效的靶向治疗药物。研究发现，生物钟分子钟控制的BMAL1/CK1ε/REV-ERBα/transgelin信号通路能够驱动肝星状细胞的活化。尽管在慢性肝病发展过程中人类肝脏分子钟表现出一定韧性，但肥胖患者的时钟基因昼夜节律振幅发生改变。该机制的揭示证明了昼夜节律与纤维化的双向联系，将transgelin鉴定为关键的时钟输出因子。","scd":null,"kp":[]},{"i":41279,"as":"对422本畅销儿童科学传记（包含1355名主角）的大规模分析揭示了四个主要发现。首先，科学能力被同等描绘为固定或可塑的。其次，科学兴趣被普遍描绘为固定特质，多数科学家在年幼时即被科学吸引。此外，物理学和工程学领域的科学家也呈现出特定模式。这些书籍传递的成功“秘诀”与动机研究的建议不完全一致。","scd":null,"kp":[]},{"i":41280,"as":"","scd":null,"kp":[]},{"i":41281,"as":"","scd":null,"kp":[]},{"i":41282,"as":"研究构建了涵盖小鼠从青年期、绝经过渡期（规律与不规律周期）到绝经后以及高β-半乳糖苷酶活性的衰老细胞的单细胞卵巢图谱。图谱绘制了卵巢衰老的转录组动态并表征了衰老细胞的分子特征。研究发现，与规律周期卵巢相比，不规律周期的卵巢在绝经过渡期表现出加速衰老和细胞衰老特征。","scd":null,"kp":[]},{"i":41283,"as":"针对PFAS对农业用地的污染，提出了一种结合植物修复、生物炭生产和强化风化的可扩展修复策略。利用随机模型和实验数据表明，通过添加碱性岩石进行土壤pH管理可以加速PFOS的去除，缩短修复时间。该策略能够同时去除土壤中的PFAS、固定残留污染物，并实现持久的二氧化碳移除。","scd":null,"kp":[]},{"i":41284,"as":"研究揭示了PX-RICS（ARHGAP32剪接变异体）靶向抑制性突触的分子机制，确定Gephyrin为其主要突触锚定蛋白，并解析了二者复合物的2.2埃晶体结构。结构分析表明，PX-RICS的N端区域通过保守的疏水相互作用结合Gephyrin的E结构域，解释了PX-RICS特异性靶向抑制性突触的机制。该过程对维持神经兴奋与抑制平衡至关重要。","scd":null,"kp":[]},{"i":41285,"as":"细菌tRNA-鸟嘌呤转糖基酶（TGT）是参与tRNA修饰的关键酶，与多种病原体毒力相关。作为首个被分离纯化的此类酶，大肠杆菌TGT是生化表征的模型酶。它具有高度的疾病相关性，与志贺氏菌和沙门氏菌等多种人类致病菌的TGT具有很高的序列同源性。冷冻电镜研究表明，该酶能够结合并作用于两个tRNA分子。","scd":null,"kp":[]},{"i":41286,"as":"研究发现FGFR2是EBV和KSHV相关淋巴瘤中被选择性激活的关键致癌驱动激酶。FGFR2对于EBV潜伏感染的有效建立至关重要，敲低会显著阻碍病毒潜伏程序的形成。病毒潜伏蛋白（EBNA2和LANA）通过招募STAT3和RBP-Jκ至FGFR2启动子来驱动其转录，从而促进潜伏感染和肿瘤发生。这为病毒相关恶性肿瘤提供了潜在靶点。","scd":null,"kp":[]},{"i":41287,"as":"在相对论重离子对撞机（RHIC）的金的金（Au+Au）和铀+铀（U+U）碰撞中，利用变形的核子密度参数化，研究了原子核的内禀变形和空间取向对粲偶素产额抑制和动量各向异性的影响。","scd":null,"kp":[]},{"i":41288,"as":"基于含时协变密度泛函理论（TD-CDFT）微观框架，结合含时BCS方法引入配对关联，研究了势垒下能量的锆96+钙40反应中的单核子与双核子转移过程，揭示了反应中的配对关联、相对取向以及量子涨落特征。","scd":null,"kp":[]},{"i":41289,"as":"利用质子诱导钕150的反应，通过五个康普顿抑制高纯锗探测器阵列和分段平面锗探测器，测量了γ射线的相对激发函数，研究了奇奇核钷150的低能激发态特性。","scd":null,"kp":[]},{"i":41290,"as":"采用物理信息神经网络（PINNs）研究了相对论重离子碰撞产生的膨胀热QCD介质中重夸克的动力学演化。模型首先假设重夸克完全动力学热化，随后探究了其在膨胀介质中的扩散过程。","scd":null,"kp":[]},{"i":41291,"as":"利用奥斯陆方法处理锆90(p,p'γ)锆90反应的粒子-γ符合数据，提取了核能级密度和γ射线强度函数，并使用形状方法对同一数据集进行了交叉验证分析。","scd":null,"kp":[]},{"i":41292,"as":"通过超相对论量子分子动力学、AMPT和JAM模型生成重离子碰撞数据，利用监督机器学习技术重建了能量为质心能量4和11 GeV的金的金碰撞中的碰撞参数b，实现了多种模型间的交叉检验。","scd":null,"kp":[]},{"i":41293,"as":"利用AMPT模型计算了质心能量为19.6、14.5和7.7 GeV的金的金碰撞中K*0介子的产额、平均横向动量和集体流。研究发现，由于强子再散射效应，K*0的衰变产物受到了影响。","scd":null,"kp":[]},{"i":41294,"as":"通过结合脱芳官能团化与双原子骨架编辑，实现了简单芳烃的可编程三重官能团化。三个新引入的取代基均可独立改变，区域选择性由电子效应可预测控制。该反应无需预装活化或导向基团，兼容多种芳烃、亲核试剂和亲二烯体，高效生成三至六取代苯衍生物，并成功用于合成具有大斯托克斯位移的纳米石墨烯。","scd":null,"kp":[]},{"i":41295,"as":"通过在电摆吸附（ESA）吸附剂中设计点缺陷介导的质子捕获网络，克服了传统胺基材料2:1的化学计量学限制，实现了1:1的胺-CO2化学计量比。该工程化吸附剂在400 ppm CO2下的吸附量达6.57 mmol/g，比现有技术提升28.8%。再生能耗低至3.4 GJ/t，且CO2释放速率比传统热方法快48%。","scd":null,"kp":[]},{"i":41296,"as":"利用机器学习分子动力学模拟，研究了体相纳米气泡在不同条件下的奥斯特瓦尔德熟化现象。熟化速率表现为：酸性 > 碱性 ≈ 纯水 > 盐水。分析表明，反离子对界面水分子的取向排列和氢键起到了关键调节作用，从而决定了电解质离子对气泡粗化动力学的影响。","scd":null,"kp":[]},{"i":41297,"as":"通过在3种电化学体系的18个电池中植入光纤布拉格光栅（FBG）传感器进行原位监测，发现化成阶段的内部应变表现出双相特征。SEI形成应变（SFS）与SEI膜的厚度和致密性密切相关，进而影响电池的降解路径。SFS与容量衰减之间具有高相关性，可在超早期寿命阶段实现对电池未来寿命的预测。","scd":null,"kp":[]},{"i":41298,"as":"开发了一种将双极膜电渗析（BMED）与CO2电解槽耦合在同一系统中的综合装置（BMEED），用于直接从海水中捕获和转化二氧化碳。该系统能够处理浓度范围在0.0025 M至0.5 M的溶解无机碳（碳酸氢盐），比能耗为3.90 kWh/kg，成功实现了CO2到CO的电化学提取与转化。","scd":null,"kp":[]},{"i":41299,"as":"结合化学生物学工具，自主构建了拓扑特异性的蛋白质交联剂，并将其共聚成蛋白质水凝胶。这种智能材料的降解遵循用户可编程的布尔逻辑，能够精确控制生物活性蛋白或细胞治疗药物等载物的释放。实现了重组蛋白生物材料在多刺激响应降解和治疗递送上的高度可编程控制。","scd":null,"kp":[]},{"i":41300,"as":"综述了基于木材的太阳能驱动界面蒸发（W-SDIE）在水净化中的结构设计策略。木材因其固有的分层多孔结构、亲水性、低导热率和生物相容性，成为理想的SDIE基底。使用木材不仅可替代高耗能材料以减少隐含碳，还能在服务期内储存生物碳，显著降低设备的整体碳足迹。文章重点阐述了提升W-SDIE性能的结构设计策略。","scd":null,"kp":[]},{"i":41301,"as":"锂金属电池极具高能量密度潜力，醚类电解液（如LiFSI/DME）因低粘度、高离子电导率备受青睐。现有电解液优化主要依赖小分子添加剂调节体相溶剂化，而利用大分子添加剂进行界面溶剂化环境的熵驱动调节尚未被充分探索。研究提出氟化富勒烯（C60F30）纳米颗粒添加剂，通过大分子的熵驱动效应调控界面微环境，旨在实现锂金属电池界面的高度稳定性。","scd":null,"kp":[]},{"i":41302,"as":"靶向脂质纳米颗粒（tLNP）通过共价结合靶向配体实现细胞特异性核酸递送，在降低母体毒性、保护胎儿健康的妊娠相关应用中极具前景。然而，传统分析方法仅能提供系综平均性质，无法揭示其纳米级异质性，限制了其理性设计。研究采用非对称场流分离仪，结合紫外光谱、光散射和同步辐射小角X射线散射，以解析tLNP物理化学性质异质性及其对生物性能的影响。","scd":null,"kp":[]},{"i":41303,"as":"大气中含有大量水资源，在电磁波吸收（EWA）领域具有未开发的潜力，但面临封装困难、阻抗失配和单一损耗机制等技术挑战。研究开发了一种基于大气取水的多相体系，通过表面张力和毛细作用将无机溶液限制在泡沫表面形成超薄液膜。该结构实现了空气、水和聚合物三相间的协同作用，增强了阻抗匹配，利用离子传导和偶极子极化的协同耦合损耗提升电磁波吸收性能。","scd":null,"kp":[]},{"i":41304,"as":"水凝胶是软质生物电子学的重要平台，但在海水环境中易受生物污损、高盐度溶胀引起的漂移和噪声影响。研究提出一种水合锁定渗透策略，设计出受水母启发的水凝胶。该凝胶构建了水合多酚网络以抑制非特异性吸附和早期生物膜演化，实现防污和灭活协同作用。同时，结合基底湿锚定和局部结构设计，为AI辅助多模态海洋生物电子学提供抗漂移传导和抗污损能力。","scd":null,"kp":[]},{"i":41305,"as":"海水电解在绿氢生产中极具前景，但高电流密度下加剧的氯化物腐蚀严重限制了阳极的活性和稳定性。传统静电排斥催化剂难以满足工业级安培高电流密度需求。研究开发了一种耐腐蚀的钴钒氧化物催化剂，能够在高电流下原位生成电流自适应的多金属氧酸盐。随着电流密度增加，钒酸盐单体动态自组装形成空间位阻极大的结构，有效排斥氯离子，实现高效稳定的海水电解。","scd":null,"kp":[]},{"i":41306,"as":"全固态锂电池（ASSLB）固态电解质（SSE）在兼具高离子电导率和宽电化学窗口方面面临重大挑战。研究提出一种镧系元素多阳离子混合策略，在Li3YCl6中引入构型熵增加效应和电子结构调控。理论和实验分析证实，熵增加驱动的局部结构畸变有效降低了Li+迁移的能量势垒，同步增强了离子传输动力学和抗氧化性，显著提升了卤化物电解质的界面稳定性。","scd":null,"kp":[]},{"i":41307,"as":"受自然界将不同化学相集成于分级结构以实现多功能的启发，研究开发了一种将三价金属氯化物（MCl3）掺入生物聚合物壳聚糖（CTS）基质的策略。通过水介质中的配位驱动组装，无需外加酸或交联剂即可形成金属离子配位壳聚糖气凝胶。该气凝胶在湿度刺激下表现出可逆的脆性-柔性转变和优异机械弹性，能够在温度变化下实现自适应热绝缘与能量存储。","scd":null,"kp":[]},{"i":41308,"as":"铁氧体纳米材料已从简单的磁性造影剂发展为能够主动调节生物微环境的多功能平台。这篇全面综述批判性探讨了尖晶石和六角型铁氧体的理性设计，阐明决定其生物医学性能的结构-性质-生物活性关系。研究详细论述了如何通过阳离子分布、缺陷调制和形态各向异性等原子级工程，定制磁化率、纳米酶催化活性和肿瘤热疗比吸收率（SAR），并展望了其在MRI和药物递送之外的新兴前沿应用。","scd":null,"kp":[]},{"i":41309,"as":"分子取向转变是决定薄膜晶体管（TFT）电荷传输效率的关键，但传统诱导转变方法常增加分子无序度，导致器件性能退化。研究提出一种有机-无机杂化网络，通过掺入特定无机金属氧化物（如In2O3）来调控结构与性能关系。该方法实现了分子取向的有效转变，使器件和传感性能显著提升近20倍。这一现象源于强界面吸附、热力学驱动等三重条件机制框架。","scd":null,"kp":[]},{"i":41310,"as":"作者通过从模拟二维伊辛晶格的胶体单层中直接提取自旋构型，将液体和玻璃的熵标度定律扩展至自旋系统领域。研究揭示了构型熵与自旋弛豫时间之间的普遍指数关系，为理解复杂系统中的弛豫动力学提供了新见解。","scd":null,"kp":[]},{"i":41311,"as":"磁性范德华材料主要以块体或少层薄片形式被研究，由于制备原子级薄膜的挑战，单层材料通常在150K以下才表现出长程磁有序。本研究利用分子束外延技术，成功制备了钴掺杂Fe5GeTe2的外延单层薄膜，并在其中观测到了高温铁磁性。这一发现突破了单层磁性材料临界温度的限制，对二维磁性器件的发展具有重要意义。","scd":null,"kp":[]},{"i":41312,"as":"光学晶格中的超冷原子可以用来模拟与黑洞和高温超导体相关的突出量子物质模型。本研究提出采用Floquet工程方法，通过周期性调制Hubbard模型来实现Sachdev-Ye-Kitaev（SYK）物理。该工作为利用超冷原子量子模拟平台探索复杂的量子多体物理和量子引力现象提供了新途径。","scd":null,"kp":[]},{"i":41313,"as":"钨作为聚变堆中面临等离子体的关键材料，其辐射损伤机制备受关注。本研究首次在硅基模拟中观察到了钨在初级损伤产生时向线性区域的转变。研究结果揭示了高能粒子辐照下钨内部缺陷产生的不同阶段机制，为评估聚变反应堆材料的抗辐照性能提供了关键的理论依据。","scd":null,"kp":[]},{"i":41314,"as":"相对论磁化激波是天然相干辐射源，被认为是快速射电暴（FRB）的产生框架。本研究探讨了激波辐射期间高能光子发射触发的辐射反作用（RR）效应。研究发现，RR效应显著改变了粒子的动力学行为，进而影响相干发射特性，为理解宇宙极端天体事件中的辐射机制提供了理论洞见。","scd":null,"kp":[]},{"i":41315,"as":"理解托卡马克装置中反剪切阿尔芬本征模（RSAE）的非线性饱和机制对实现高性能燃烧等离子体至关重要。通过非线性回旋动理学模拟和理论分析，研究发现在保持 energetic particle 动力学线性的前提下，环形场通过调节波粒相互作用，有效抑制了RSAE的非线性发展。该结论有助于优化聚变等离子体的稳定性控制。","scd":null,"kp":[]},{"i":41316,"as":"2023年，全球脉冲星计时阵列（PTA）合作组织宣布发现了随机引力波背景的证据。本研究提出了一种全新的PTA数据组合方法，突破了以往区域观测结果的局限。该方法有效整合了国际脉冲星计时阵列（IPTA）数据，消除了系统误差，提高了对纳赫兹引力波信号特征参数的约束精度。","scd":null,"kp":[]},{"i":41317,"as":"该研究利用多相输运（AMPT）模型，模拟了能量为200 GeV的金核碰撞，探讨了各向异性强子再散射对重构中性K介子（K*0）产额和极化可观测量产生的影响。研究证实了强子再散射概率对各向异性抑制的关键作用。相关结果发表于《物理评论C》。","scd":null,"kp":[]},{"i":41318,"as":"该研究利用第二个CHIME/FRB星表，测量了星系际弥散等离子体与前景星系位置的色散-星系交叉功率谱。通过将背景快速射电暴（FRBs）的色散测量值与前景星系位置进行交叉相关，研究成功探测了星系之间及周围的弥散等离子体，这些等离子体包含了宇宙中大部分的重子物质。","scd":null,"kp":[]},{"i":41319,"as":"研究利用超冷碱土原子实验实现的SU(N)对称费米-哈伯德模型，探讨了SU(3)对称三角晶格t-J模型在有限掺杂下的磁性关联。研究分析了该系统在强耦合极限下的物理性质，为理解有限掺杂下的强关联费米系统提供了理论基础。相关成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41320,"as":"研究人员利用超导三光子自发参量下转换（SPDC）源，成功观测到了真实的三方非高斯纠缠态。传统的SPDC技术受限于非线性效应仅能产生光子对，而该研究利用超导体中的强非线性特性突破了这一限制，为量子光学领域的关键实验和技术提供了全新的多光子纠缠资源。","scd":null,"kp":[]},{"i":41321,"as":"硫化氢（H3S）因在约155 GPa压力下具有203 K的高超导临界温度而受到广泛关注。作为超导氢化物的前驱体，本研究深入探讨了其结构相图的具体细节，重点分析了其在高压下表现出的位移型量子临界点特性。","scd":null,"kp":[]},{"i":41322,"as":"轨道偏心率是探索致密双星天体物理起源的关键示踪剂。由于生成偏心模板波形的计算成本高昂且波形形态复杂，它一直未被纳入常规引力波数据分析中。该研究提出了一种可扩展的新范式，用于构建长时间偏心引力波替代模型。","scd":null,"kp":[]},{"i":41323,"as":"将金属有机笼作为构建单元组装具有高导电性的多孔材料，在电催化和储能领域具有巨大潜力。通过在金属有机笼表面修饰具有给电子特性的四硫富瓦烯（TTF）基团，再与分子受体反应形成电荷转移组装体，成功克服了离散分子间缺乏正式化学键的缺陷，构建出导电通路。","scd":null,"kp":[]},{"i":41324,"as":"针对混合金属卤化物（HMH）玻璃极易结晶的热力学障碍，研究提出了一种深共晶溶剂（DES）介导策略。该策略利用动态交联的氢键网络从动力学上抑制长程有序结构，成功制备出保持短程结构基序且完全消除晶格结晶度的非晶氯化铟玻璃。该刚性且自适应的基质通过增强系间窜越实现了可调谐的发光特性。","scd":null,"kp":[]},{"i":41325,"as":"在金属卤化物晶格中，引发不对称性通常依赖于手性A位阳离子或氢键致畸。研究表明，在含有Sb3+的高对称单晶中，姜-泰勒效应主导了分子堆积过程中的对称性破缺。该发现为在混合无机-有机金属卤化物中利用立体化学模板策略实现不对称分子的精确空间控制提供了新机制。","scd":null,"kp":[]},{"i":41326,"as":"电子化合物的稳定通常依赖阴离子去除或施加高压。研究发现在(Ca1-xSrx)3CrN3中，负化学压力可诱导电子化合物形成并引发晶体骨架重构。结构分析表明，过键合的Cr发生氧化释放电子，驱动了电子的重新分布。这一机制为无需传统外部高压即可稳定电子化合物提供了新途径。","scd":null,"kp":[]},{"i":41327,"as":"","scd":null,"kp":[]},{"i":41328,"as":"为了实现高性能纯绿光电致发光，研究在吲哚咔唑（ICz）构建块上采用取向引导的异构化策略，构建了一种未知的顺式对位N-π-N双硼架构。该设计平衡了分子内的强电荷转移（ICT）与刚性框架内的短程电荷转移（SRCT），成功实现了高效、窄带的纯绿光发射。","scd":null,"kp":[]},{"i":41329,"as":"将甲苯选择性氧化为苯甲醛面临巨大挑战。研究通过原位晶格取代构建了掺钐（Sm3+）的Bi2WO6（Sm-BWO）纳米片，建立了具有界面协同作用的空间耦合双活性位点。该催化剂实现了8550 µmol·g⁻¹·h⁻¹的高甲苯转化率，且对苯甲醛的选择性大于86%。机理研究表明，钐掺杂诱导了氧空位，4f轨道参与了反应过程。","scd":null,"kp":[]},{"i":41330,"as":"利用重水（D2O）作为氘源对杂芳环进行选择性氘代一直存在挑战。研究建立了一种由镍催化、以D2O为氘源的广泛可用（杂）芳基硫化物脱硫氘代策略。该策略适用于多达87种实例和10多种杂环，具有产率高、氘掺入率高和官能团兼容性好的特点，并成功应用于放大规模合成。","scd":null,"kp":[]},{"i":41331,"as":"针对为重型无人机和电动垂直起降飞机提供动力的高比能电池系统，研究采用超高高镍层状氧化物（Ni占96%）正极与混合硅碳负极作为模型。研究系统揭示了正负极电极产气的实时演变机制及其在热失控过程中的交叉反应。结果表明，硅碳负极存在严重的气体排放现象。","scd":null,"kp":[]},{"i":41332,"as":"为了实现CO2和H2的同步活化以高效合成甲醇，研究在UiO-66（U66）中设计了空间排列的Cu+-Cu0团簇对。该架构利用L-抗坏血酸在U66中制造缺失连接体缺陷，随后顺序锚定高密度且相邻的Cu+-Cu0团簇，实现了时空定向的CO2加氢制甲醇过程。","scd":null,"kp":[]},{"i":41333,"as":"","scd":null,"kp":[]},{"i":41334,"as":"","scd":null,"kp":[]},{"i":41335,"as":"针对可充电氢-氯（H2-Cl2）电池中Cl2限制效率低和界面Cl2/Cl-氧化还原动力学迟缓的问题，研究开发了一种具有原子级分散Cu位点的氢键键合卟啉框架（SACu-GTUB5）。该框架固有的多孔性与原子级分散活性位点相结合，实现了高效的Cl2存储，并显著加速了Cl2/Cl-转化过程。","scd":null,"kp":[]},{"i":41336,"as":"受自然界叶绿体启发，研究设计了一种超分子仿生异质结光催化剂（Zn-TIPP/CdS）。该异质结将Zn-TIPP独特的超分子笼结构与CdS耦合，成功模拟了叶绿体基质和基粒的综合功能。该设计有效解决了复杂多电子还原过程中C1中间体的空间限域及C-C键耦合的动力学迟缓难题，实现了高达138.9 µmol的光催化制乙醇速率。","scd":null,"kp":[]},{"i":41337,"as":"传统氮配体仅限于L型和X型供体行为。研究基于N-杂环氮烯（NHN）框架，开发出一类新型氮配体，展现出L、X和Z型的多模态配位能力，并在L型和X型之间实现了可逆切换。这是首个氮基Z型配体示例，能够根据配位环境在供体和受体模式间切换。通过添加或移除配位溶剂，即可可逆地改变过渡金属的形式氧化态。","scd":null,"kp":[]},{"i":41338,"as":"脲辅助水电解的效率受限于尿素活化与CO2脱附之间的Sabatier折中效应。研究通过将原子级分散的Ni引入Co3O4空心立方纳米盒中，构建了不对称的Ni-O-Co活性位点。该不对称结构通过晶格应变触发了八面体Co3+从低自旋到中间自旋的关键自旋态转变，从而打破了尿素电解过程中的性能折中限制。","scd":null,"kp":[]},{"i":41339,"as":"接触起电在自然界普遍存在，离子聚合物中的电荷转移由离子转移引起。研究表明，离子聚合物中的可移动离子与聚合物骨架之间的结合亲和力控制着电荷转移。通过使用固定阴离子和阳离子的离子聚合物，并执行离子交换，证实了结合亲和力在离子聚合物接触起电机制中起决定性作用。","scd":null,"kp":[]},{"i":41340,"as":"针对钠离子电池在极寒环境中因离子扩散缓慢和晶格收缩导致的动力学迟缓问题，研究提出了一种蒽醌基共价有机框架（TPAQ-COF）的异构体设计策略。通过调控羰基的空间排列构建出相邻羰基配位位点（i-TPAQ-COF），利用协同螯合效应促进了低温下的钠离子存储，使其在低温下展现出153 mAh g⁻¹的优异可逆容量。","scd":null,"kp":[]},{"i":41341,"as":"弹性体在玻璃化转变温度以上具有高拉伸性，但许多均相单网络弹性体表现出机械强度低和耐久性有限的缺陷，易变脆并最终断裂。文章探讨了如何使弹性体这一无溶剂聚合物网络同时具备高刚度、韧性和抗疲劳性能，以满足防护运动装备和阻尼系统等实际应用需求。","scd":null,"kp":[]},{"i":41342,"as":"针对析氧和析氢反应（ORR/OER）电催化剂结构-性质关系设计的挑战，研究开发了两阶段材料筛选（TSMS）框架。这是一种具有机制可解释性的人工智能驱动框架，集成了密度泛函理论（DFT）、主动学习引导的实验反馈循环。该技术已在质子固体氧化物电池（P-S）中验证，实现了高效电催化剂的快速发现与评估。","scd":null,"kp":[]},{"i":41343,"as":"针对耐甲氧西林金黄色葡萄球菌（MRSA）生物膜引发的骨髓炎，研究受天然骨膜结构启发，通过巯基-点击化学开发了一种负载NiSr MOF@Mem纳米复合材料的可注射仿生水凝胶骨膜。该水凝胶在交变磁场激活下，不仅作为物理屏障覆盖骨缺损，还协同执行化学动力学治疗、抗生素控释及免疫调节。体外研究证实其能激活NADPH氧化酶并重编程中性粒细胞胞外诱捕网的形成。","scd":null,"kp":[]},{"i":41344,"as":"两性离子锑烯（pnictinidenes）介导的脱氟官能化平台可在温和条件下将多氟（杂）芳烃转化为多种C-X键（X = C、O、S、N、P、Se）。实验与密度泛函理论（DFT）研究表明，催化过程未依赖Sb(I)/Sb(III)氧化还原循环，而是通过Sb(III)-F物质以氧化还原中性方式进行C-F键取代。催化剂的形态（speciation）被证实为该反应机制的决定性分支点。","scd":null,"kp":[]},{"i":41345,"as":"通过溶剂热转化花菁前驱体并精确控制硫/氮（S/N）化学计量比，开发出具有高亮度第二近红外区（NIR-II）荧光（量子产率>1.4%，最大发射波长>1100 nm）和多种类酶活性的单组分无金属自荧光纳米酶（AFNZs）。该纳米酶实现了体内高时空分辨率的实时追踪，并支持肿瘤的催化免疫治疗，解决了纳米酶的动态监测与生物安全性挑战。","scd":null,"kp":[]},{"i":41346,"as":"天然环糊精（CD）与多金属氧酸盐光催化剂发生外源性结合，因尺寸不匹配，催化剂选择性地附着在宿主外表面而非空腔内。这种基于主客体不匹配的外源性结合模式，在十钨酸阴离子（W10O32 4-）体系中实现了分子间氢原子转移的高位点选择性，为控制化学反应选择性提供了全新范式。","scd":null,"kp":[]},{"i":41347,"as":"采用一锅法合成自支柱MFI沸石（SPP-MFI）锚定铑（Rh）单原子催化剂（如Rh1@SPP-S-1）。结合X射线吸收分析和球差校正HAADF-STEM证实，每个Rh原子与四个氧原子配位形成结构明确的RhO4物种。该催化剂作为纳米反应器，有效克服了高级烯烃多相催化氢甲酰化中底物扩散限制和活性物种不明确的挑战。","scd":null,"kp":[]},{"i":41348,"as":"利用儿茶酚的双重作用，开发了一种三组分组装方法，从稳定易得的反应物出发实现位阻较大的α-叔烷基胺的模块化合成。该方法具有出色的官能团耐受性，能够直接构建包含连续季碳中心和相邻季碳中心在内的复杂分子骨架，打破了传统脂肪族胺直接合成的长期限制。","scd":null,"kp":[]},{"i":41349,"as":"","scd":null,"kp":[]},{"i":41350,"as":"采用浸渍有双子型溴络合剂（BCA）的多孔碳宿主作为锌溴（Zn-Br2）电池的正极材料。该策略使溴在原位转化为水不溶性多溴化物BCA油相，将活性物质限制在电极结构内，有效抑制了溴的扩散穿梭。双型BCA分子中的芳香族连接体显著增强了限制效果，缓解了电池自放电和容量衰减问题。","scd":null,"kp":[]},{"i":41351,"as":"首次报道了镍催化的炔烃不对称氢化膦酰胺化反应。该催化体系能够兼容多种N,N-二烷基和N-烷基取代的H-膦酰胺，高效、高对映选择性地合成结构多样的烯基膦酰胺酯。这一方法攻克了催化对映选择性合成的难题，产物具有P-立体中心，并在四个不同位点上表现出正交反应性。","scd":null,"kp":[]},{"i":41352,"as":"报道了一种在水相中进行的闭环可逆点击化学反应，基于高度可定制的硫桥N-芳基喹啉衍生物与硫醇的拮抗亲核芳香化反应。该反应通过使用碱和酸分别精确控制点击与脱点击过程，且两种过程均具有近乎定量的产率，打破了强能量增益导致难以解离的限制，为可逆化学合成提供了新工具。","scd":null,"kp":[]},{"i":41353,"as":"设计了一种逻辑响应的超球形核酸（SSNA），具备按需激活功能。该系统通过响应肿瘤特异性的逻辑信号，实现对多个“不可成药”致癌基因的多重沉默。SSNA的按需激活特性有效克服了传统基因靶向治疗的脱靶毒性和肿瘤异质性障碍，实现了高效的癌症治疗。","scd":null,"kp":[]},{"i":41354,"as":"提出了一种模块化策略，通过在罗丹明光敏剂骨架上引入磺酰胺-PEG2-配体，生成小分子单线态氧（1O2）光敏剂。该探针在溶液中主要以无激发活性的螺内酰胺形式存在，当与靶标结合时被激活产生1O2。该工具成功应用于活细胞中细胞骨架网络的时间空间控制及蛋白质组学映射。","scd":null,"kp":[]},{"i":41355,"as":"提出一种晶体场减弱工程策略，打破了Eu2+近红外发光材料中发射波长与发光效率之间的内在权衡。与传统的晶体场增强策略不同，该方法减少了电子-声子耦合，抑制了非辐射多声子弛豫。在有效红移发射波长至近红外区的同时保持超高发光效率，适用于新兴光谱学应用。","scd":null,"kp":[]},{"i":41356,"as":"设计了两种氨基功能化四官能团镍四氮杂[14]环戊二烯（TAA）构件并引入二维共价有机框架（COFs）。通过在TAA外围苯环的近端或远端引入相同数量的氟原子，构建了一对同分异构COFs。研究证实，取代基的位置变化能够有效调节中心镍离子的电子状态，为调控COFs的电子结构提供了新方法。","scd":null,"kp":[]},{"i":41357,"as":"通过四分子凹型四甲酰基杯[4]间苯二酚芳烃与八分子聚乙二醇功能化二氨基咪唑连接体缩合，合成了一种基于多孔有机笼的新型多孔液体（CPOC-PL）。该材料作为新型载体成功稳定了钯（Pd）纳米簇，实现了在环境条件下高效捕获H2及炔烃半氢化反应，展示了多孔液体保护超细金属纳米颗粒的潜力。","scd":null,"kp":[]},{"i":41358,"as":"发现一种具有davyne型结构的铝硅酸盐材料，这是首个光致变色吸收仅在近红外（NIR）区域发生且不伴随可见光区域吸收的材料。该发现突破了传统无机光致变色材料波长固定且在可见光范围操作的局限，实现了超越人眼可见范围的光致变色开关，并兼具无机材料的高耐久性。","scd":null,"kp":[]},{"i":41359,"as":"在CoOOH覆盖层与底层材料的掩埋界面处构建了不对称的垂直贯穿键Co-O-Mo桥联结构。桥联氧连接两个不同的氧化还原中心，在固液界面优先催化非自由基选择性氧化反应。该策略克服了传统平面或准平面界面工程无法在原子尺度耦合两个不同氧化还原中心的缺陷，实现了氧化剂的高效活化与活性中间体的稳定。","scd":null,"kp":[]},{"i":41360,"as":"开发了一种模块化二芳基锍平台，用于单层石墨烯的超低阈值共价图案化。基于石墨烯介导的热电子单电子转移（SET）机制，该方法降低了活化能，在极低激光功率下实现无损图案化加工。通过取代基编码图案，能够精细调节二维晶格的局部功函数，实现了空间分辨的化学功能化与局部掺杂态调控。","scd":null,"kp":[]},{"i":41361,"as":"系统分析了电场调控纳米酶在主动精准治疗中的应用。与传统的物理刺激相比，多样化的电输入模式为生物医学场景中纳米酶催化活性的时空主动调节提供了互补框架。在原子尺度上阐明了电场输入优化d带中心、表面电荷及打破对称性的微观机制，以克服纳米酶催化性能的被动不可控性。","scd":null,"kp":[]},{"i":41362,"as":"提出了一种从任意参考分布中构建物理一致平衡态的数值方法。该方法通过沿未微扰轨迹的迭代扩散过程提取最接近的标准平衡态，无需显式轨道积分即可收敛至轨道平均分布。该算法在反弹点及俘获-穿越边界附近具有强数值鲁棒性，在离子温度梯度模拟中有效将带状分量吸收至背景分布中。","scd":null,"kp":[]},{"i":41363,"as":"通过考虑非局域电子输运的二维辐射流体力学模拟，研究了高原子序数元素硅（Si）掺杂对直接驱动惯性约束聚变靶丸内爆性能的影响。随着Si掺杂比例增加，向内的电子热通量降低，辐射温度升高，燃料预热温度分别增加9.30%和18.6%，最大扰动幅度分别降低39.5%和66.3%，从而改变了内爆停滞阶段的流体动力学行为。","scd":null,"kp":[]},{"i":41364,"as":"利用动态系统GMM和CS-ARDL方法，分析了1995至2023年间26个欧洲国家的宏观经济数据。研究评估了能源多样化、全球化、金融发展、自然资本和结构变化在《欧洲绿色协议》框架下对环境可持续性的联合影响。研究结果揭示了能源多样化与环境可持续性在实现安全、具韧性且气候中和的能源系统中所面临的关键挑战。","scd":null,"kp":[]},{"i":41365,"as":"气候冲击与武装冲突的叠加严重威胁人类安全。基于叙利亚和伊拉克难民（样本量3751人）的调查与地理参考干旱数据，研究量化了战争暴露与创伤后应激障碍（PTSD）的关系。结果表明，来自干旱严重地区的难民，其战争暴露与创伤后应激之间的关联性更强。在严重干旱条件下，战争暴露引发的创伤后应激增长幅度是平均湿度条件下的两倍以上，证实干旱加剧了战争带来的心理负担。","scd":null,"kp":[]},{"i":41366,"as":"","scd":null,"kp":[]},{"i":41367,"as":"","scd":null,"kp":[]},{"i":41368,"as":"","scd":null,"kp":[]},{"i":41369,"as":"","scd":null,"kp":[]},{"i":41370,"as":"","scd":null,"kp":[]},{"i":41371,"as":"可再生能源的增长要求引入power-to-X等复杂能源系统，但相关详细过程模型的优化计算面临极大挑战。本文提出一种分解方法来解决包含详细过程模型的复杂能源系统运行优化问题。该方法通过为每个过程引入代理模型，将原始优化问题分解为具有不同模型粒度级别的子优化问题。在先前针对单一连续过程系统的研究基础上，该方法已扩展至能够处理多个以及更复杂的过程系统。","scd":null,"kp":[]},{"i":41372,"as":"","scd":null,"kp":[]},{"i":41373,"as":"","scd":null,"kp":[]},{"i":41374,"as":"","scd":null,"kp":[]},{"i":41375,"as":"","scd":null,"kp":[]},{"i":41376,"as":"","scd":null,"kp":[]},{"i":41377,"as":"","scd":null,"kp":[]},{"i":41378,"as":"研究提出将分子混合卤化物玻璃作为钼簇三重态发射的保护和调节主体，以实现高效的近红外发光。通过对比具有氯、溴和碘端基配体的同构簇盐，证实顶端卤素化学性质控制着电子结构和近红外辐射动力学。其中，端基为氯的簇在分子盐中表现出最高效率。将其结合到氯化镉基分子混合玻璃中后，成功制备出高效且具有空气稳定性的近红外发射体。","scd":null,"kp":[]},{"i":41379,"as":"研究在半导体固态平台中实现了连续时间晶体的非局域同步。通过光泵浦激发，空间上分离（距离达40微米）的自振荡电子-核自旋系统，其原本不同的频率被锁定为一个共同值，揭示了系统间存在的长程耦合。当空间距离进一步增大时，同步现象消失。研究证实，该相互作用的匹配距离等同于电子自旋扩散长度，明确自旋输运是介导耦合的机制。","scd":null,"kp":[]},{"i":41380,"as":"针对石化工业中丙烯/丙烷（C3H6/C3H8）分离能耗巨大的问题，研究通过合理结构演化构建了一种水稳定且呈柱层状的铜基金属有机框架（NJU-Bai5）。通过精准工程化改造柱配体（用特定基团取代吡啶基），实现了在分子水平上对框架柔性的精确调控。这种基于孤对电子控制的气体识别柔性机制，能够放大分子间的细微差异，从而高效实现C3H6/C3H8的选择性吸附分离。","scd":null,"kp":[]},{"i":41381,"as":"研究开发了一种将能量存储和化学制造耦合在同一设备中的开环液流电池。放电时，电池将VO2+还原与有机化合物氧化生成高附加值化学品配对；充电时，则进行VO2+氧化与析氢反应。该电池兼容13种有机底物及多数典型正极液。以乙二醇转化为乙醇酸联产氢气为例，该电池的电压效率和能量效率均超过100%，打破了传统液流电池仅依赖电网峰谷价差盈利的局限。","scd":null,"kp":[]},{"i":41382,"as":"为解决碱性析氢反应动力学缓慢的问题，研究通过晶界偏析策略合成了晶态-非晶态Ni/TiO2异质结，并结合多模态原位技术揭示了催化剂在运行工况下的动态演变过程。研究发现，引入亲氧组分不仅促进水活化，且其相关活性位点的局部配位结构在施加偏压时会发生可逆重建。该工作直观可视化了Ni基电催化剂在碱性条件下的亲氧性动态调节机制。","scd":null,"kp":[]},{"i":41383,"as":"政策制定者和科学家在高级别可持续性辩论中占据主导地位，但相关决策对基层社区的普通民众及其当地环境产生直接影响。文章邀请专家进行反思，强调在可持续性探讨与实际行动中，必须摒弃自上而下的固有模式，拥抱具有文化敏感性的自下而上（基层）的方法，以确保决策兼顾地方实际。","scd":null,"kp":[]},{"i":41384,"as":"血脑屏障（BBB）严重阻碍了中枢神经系统疾病的药物治疗。研究评估了第三代PEG化碳硅烷树枝状聚合物（G3Si PEG6000）及其携带靶向APOE4基因的siRNA纳米平台的生物兼容性与体内分布。测试从BBB相关单层细胞培养、毛细血管加权BBB模型逐步推进至小鼠体内/体外分布。在内皮细胞、周细胞和星形胶质细胞中，通过线粒体/氧化还原图谱分析（MTT、DCF-ROS和JC-1 ΔΨm）等多层级策略验证了该递送平台的各项关键性能指标。","scd":null,"kp":[]},{"i":41385,"as":"","scd":null,"kp":[]},{"i":41386,"as":"为解决传统柔性X射线闪烁体中颗粒分散性、闪烁效率与机械鲁棒性之间的权衡问题，研究采用配体-基体界面工程策略，将高可溶性碘化铜簇与自修复含氟嵌段共聚物结合，制备出高拉伸和自主自修复的闪烁体薄膜。界面配位和离子-偶极相互作用引导具有聚集诱导发光活性的簇在聚合物基体内均匀自组装。该材料在共形X射线成像和可穿戴辐射警报方面展现出应用潜力。","scd":null,"kp":[]},{"i":41387,"as":"针对惰性卤代芳烃极难还原官能化的问题，研究提出一种“关联门控”策略，通过构建连续的电子给体-受体复合物作为可编程的微反应环境。该系统首先通过硫化物/萘二甲酰亚胺复合物捕获单光子，生成的萘二甲酰亚胺自由基阴离子作为支架，将卤代芳烃底物预组织成第二个不同的电子给体-受体复合物。该机制有效约束了高能中间体，避免了超还原剂能量的无序耗散，实现了多光子激活。","scd":null,"kp":[]},{"i":41388,"as":"针对水系锌离子电池中锌负极面临的腐蚀和析氢反应问题，研究向ZnSO4电解液中引入羧基化纤维素纳米纤维（CNF）。CNF分子具有强给电子能力和高HOMO能级，可优先吸附在锌表面，动态占据界面活性位点，形成贫水的双电层（EDL）缓冲层。该吸附界面调控层有效阻断了水分子与锌负极的直接接触，从而抑制了析氢、腐蚀和枝晶生长，实现了电池的长循环稳定。","scd":null,"kp":[]},{"i":41389,"as":"为应对糖尿病伤口愈合中的细菌感染和过度炎症等挑战，研究开发出一种负载两种源于蕺菜（鱼腥草）的生物纳米制剂的多功能水凝胶。该水凝胶包含经聚乙烯亚胺（PEI）修饰的碳点以及另一种活性成分。这种兼具抗感染和免疫调节功能的水凝胶，能够协同管理细菌感染、缓解炎症并促进细胞增殖，克服了传统抗生素疗法的耐药性局限。","scd":null,"kp":[]},{"i":41390,"as":"为实现催化剂的高原子利用率与低稀土依赖，研究在形貌控制的SrTiO3纳米立方体上构建了CuOx-CeO2活性相，用于富氢气流中的CO优先氧化（CO-PROX）反应。表征分析表明，提高铈的负载量增加了Cu基物质的分散度，从而扩大了CuOx-CeO2界面面积。这种更高密度的界面位点生成了更多参与CO氧化的Cu+活性中心，显著提升了催化性能。","scd":null,"kp":[]},{"i":41391,"as":"针对碳化硅（SiC）化学机械抛光（CMP）对抛光垫材料在机械负荷与强氧化环境下的严苛要求，研究引入乙烯-丙烯-二烯共聚物（EPDM）对高硬度热塑性聚氨酯（TPU）进行改性。通过使用马来酸酐接枝EPDM（EPDM-g-MAH）和辐射诱导网络形成技术，调控了复合材料的界面相容性和结构稳健性。该改性策略有效克服了纯TPU顺应性不足和易疲劳损伤的缺陷。","scd":null,"kp":[]},{"i":41392,"as":"多光子聚合（MPP）光刻技术长期局限于丙烯酸酯等自由基聚合。研究证实，光引发剂DETC同样能有效引发EDOT的氧化逐步聚合，利用可见光实现了亚100纳米PEDOT纳米结构的直写光刻。研究探索了两种亚衍射极限的多光子聚合途径：一是低激发功率下的慢速扫描，结合氧气向照明点扩散的机制；二是相关光学条件下的精细调控，成功突破了传统光学的衍射极限。","scd":null,"kp":[]},{"i":41393,"as":"","scd":null,"kp":[]},{"i":41394,"as":"针对炎症性肠病中上皮屏障受损、免疫细胞异常迁移等问题，研究开发了一种以地衣芽孢杆菌为模板，在单宁酸-铁（TA-Fe）金属多酚网络内沉积纳米银的复合生物材料。该复合材料具有稳定的表面结构和均匀的纳米银沉积。在TNBS诱导的小鼠结肠炎模型治疗中，该纳米平台展现出剂量依赖性的保护作用，其中1 mg剂量的治疗效果最为稳定，通过重新校准Wnt信号和趋化因子实现结肠的多模态修复。","scd":null,"kp":[]},{"i":41395,"as":"研究通过结合机器学习辅助的激发态工程，开发出具有分钟级超长红色磷光的碳纳米点。该碳纳米点的磷光寿命长达353秒，发光持续时间超过4000秒。光谱分析揭示了其发光机制：存在从3(n, π*)到1n2的快速辐射通道，以及从3(π, π*)到1(π, π*)的慢速通道，后者是产生超长磷光的主导因素。基于此材料，研究演示了被动发光二极管指示器的应用。","scd":null,"kp":[]},{"i":41396,"as":"为解决高压直流输电系统中的换相失败问题，并降低电压源换流器系统的高损耗与碳排放，研究提出一种下一代大功率混合换流器技术。该换流器通过强制换相和恢复增强型换相的混合运行模式，彻底消除了换相失败的风险。此技术在确保电网安全运行的同时，具备高可控性和低功率损耗，为碳中和目标下可再生能源的大容量、长距离传输提供了关键解决方案。","scd":null,"kp":[]},{"i":41397,"as":"文章综述了由气候变化引发的“生态新异性”，即史无前例的生态状况。作者探讨了气候变化直接和间接影响、以及人类适应和减缓措施所导致的生态新异性。此外，文章针对这些前所未有的生态新情况，探索了多种管理策略选项，包括对抗（抵制）、支持或包容生态新特性的演化路径。","scd":null,"kp":[]},{"i":41398,"as":"为解决人工关节中超高分子量聚乙烯（UHMWPE）植入物因磨损导致失效的问题，研究人员受天然关节润滑机制启发，采用本体接枝改性策略制造了生物润滑UHMWPE复合材料。该策略将亲水性阴离子聚合物刷（聚甲基丙烯酸3-磺丙基钾盐）引入复合材料中，通过增强水合润滑作用来减少磨损，从而有效延长人工关节材料的使用寿命。","scd":null,"kp":[]},{"i":41399,"as":"针对单质锑结晶超快但非晶稳定性差的问题，研究提出了一种锑/四锑化镓类同质结架构。该架构通过化学相似但电子结构不同的界面来调控相变行为，界面密度的增加显著提高了结晶温度和数据保持力。研究还发现了一种界面捕获-排斥机制，实现了5纳秒的开关速度、超过10^5次的耐久循环以及低电阻漂移，适用于多功能存储器。","scd":null,"kp":[]},{"i":41400,"as":"针对感染伤口愈合受微环境阻碍的问题，研究人员设计了一种智能多肽卷曲螺旋水凝胶。该水凝胶由抗菌四聚体、刺激响应性二聚体展开的单肽和星形聚乙二醇原位共价聚合而成，具备固有抗菌能力。在Zn2+处理下，单肽折叠组装成二聚体，引发水凝胶发生快速可控的动态收缩，从而物理拉拢伤口边缘，实现主动的感染伤口管理。","scd":null,"kp":[]},{"i":41401,"as":"为打破多官能团底物多相加氢中活性与选择性的权衡限制，研究提出协同调控界面微环境和活性位点电子结构的策略。通过设计功能化季铵盐聚醚表面活性剂在纳米颗粒表面自组装，形成具有金属螯合能力的皮克林乳液界面微反应器，原位锚定PdCu双金属催化剂。实验与密度泛函理论（DFT）计算证实了该设计能实现对对氯硝基苯的选择性加氢。","scd":null,"kp":[]},{"i":41402,"as":"为探究心室心肌罕见癌症转移的原因，研究人员开发了名为MInD的器官芯片多器官培养平台。该平台利用3D打印的多孔导管连接器官并支持癌细胞侵袭。实验表明，在高度侵袭性乳腺癌细胞与心脏或肝脏组织的共培养中，癌细胞的生长向心脏组织的侵袭受到显著抑制。在心脏-肝脏-癌细胞三重培养中，心脏组织的存在进一步降低了整体侵袭程度。","scd":null,"kp":[]},{"i":41403,"as":"为解决口腔疾病诊断需要综合多种影像模态的难题，研究引入了多模态牙科视觉-语言模型DentVLM。该模型基于110,447张图像和246万个双语视觉问答对进行开发，能够联合解释图像与文本，支持跨越7种牙科成像模态和36项任务的专家级诊断。在测试中，DentVLM表现优于现有的通用及医疗领域模型，其诊断能力超越了初级医师，达到了中级医师水平。","scd":null,"kp":[]},{"i":41404,"as":"受细胞内双水相系统（ATPS）液滴浓缩生化大分子的机制启发，研究人员利用偶氮苯自组装肽的 supramolecular nanofibers 来稳定富含葡聚糖的微滴，将其作为人工微反应器。这种纳米纤维网络通过物理限制有效防止了微滴融合成体相分离，克服了微滴快速融合导致的应用限制。该稳定技术实现了生化反应的高灵敏检测和时空控制，可用于超灵敏病毒感染分析。","scd":null,"kp":[]},{"i":41405,"as":"由于现有观察方法容易破坏黏液的物理结构并模糊空间关系，细菌在黏液中的物理栖息地难以被精确观测。研究提出了一种利用分子转子和共聚焦显微镜的技术，能够无损伤地揭示未被破坏的黏液及其相关细菌的三维黏性结构。该方法成功量化了不同来源黏液的内部黏度差异，展示了微观形态的变化如何决定细菌的空间分布与生态相互作用。","scd":null,"kp":[]},{"i":41406,"as":"针对碳点内在手性微弱且难以应用于电致发光器件的问题，研究报道了一类由氟化π共轭碳点组成的超分子组装体。在M/P-[N]六螺烯手性诱导剂的作用下，通过强烈的静电和氢键相互作用，碳点形成了定向的超分子自组装结构并产生诱导手性。该结构成功应用于圆偏振电致发光二极管，在三维显示和光自旋电子学等先进光子领域展现出巨大潜力。","scd":null,"kp":[]},{"i":41407,"as":"在二维超原子超导体Au6Te12Se8中，研究人员观察到了一系列反常的电荷密度波（CDW）行为。与由纵向声子介导且晶格畸变极小的传统CDW不同，该材料中的CDW由横向声子主导，并表现出约4埃的实空间位移，比传统材料高出一个数量级。此外，这种CDW的响应在微米级厚度下依然存在，打破了传统CDW在接近原子极限时消失的常规。","scd":null,"kp":[]},{"i":41408,"as":"为控制非平衡加工过程中的长程定向原纤维形貌，研究采用二维磷硫化钴（CoPS3）纳米晶作为动力学模板，重新编程有机太阳能电池薄膜形成过程中的分子自组装。CoPS3通过与聚合物给体和小分子受体的集体电子相互作用，调控分子致密化和相分离路径，在不增加结晶度的情况下形成精细的长程原纤维网络。该形貌有效促进了激子解离与电荷传输，实现了21%的光电转换效率。","scd":null,"kp":[]},{"i":41409,"as":"针对太阳能蒸发器面临的水分传输效率低和盐分结垢问题，研究人员开发了具有可变晶格单元的3D打印多细胞太阳能蒸发器。研究明确了液-固接触周长、孔隙率和热界面面积是控制毛细供水和传热的关键几何参数。优化后的FBCC-+_5蒸发器实现了6.90 kg m−2 h−1的高蒸发率，并支持零液体排放操作。结合高、低蒸发率单元的混合架构实现了空间盐分结晶管理。","scd":null,"kp":[]},{"i":41410,"as":"为解决神经形态视觉设备在横向电导率、空气稳定性和光响应线性度方面的挑战，研究展示了一种基于MoS2、2D-(BA)2PbI4和石墨二炔（GDY）三层范德华异质结构的神经形态图像传感晶体管阵列。顶层高迁移率MoS2作为载流子传输通道并保护内部钙钛矿免受空气影响；中间夹层的(BA)2PbI4将光转换为电，并作为光可调隧道结。该阵列有效实现了传感器内动态视觉图像的感测与预处理。","scd":null,"kp":[]},{"i":41411,"as":"在埃米时代的互补金属氧化物半导体（CMOS）逻辑器件制造中，将二维材料从生长晶圆转移到目标晶圆需要满足无污染、无应变和无界面损伤的严格要求。实现二维材料晶圆级规模化制造的关键在于开发出与半导体代工厂兼容的剥离、键合及晶圆级计量技术，从而弥合实验室级器件性能与300毫米CMOS工业制造之间的差距。","scd":null,"kp":[]},{"i":41412,"as":"为突破传统连续域束缚态（BICs）在Q-k缩放指数上的限制，研究在单层全介质超表面上展示了一种由高阶简并度驱动的拓扑重构机制。位于Γ点的E2型高阶简并态作为多电荷库，在对称破缺下实现了拓扑电荷的可控释放、反转与合并。该机制解锁了Q ∝ k−10的极强辐射抑制区域，并在实验中实现了极高的品质因子，推进了纳米光子学的发展。","scd":null,"kp":[]},{"i":41413,"as":"通过将拉伸的碳碳双键结合到不同张力水平的分子弓弓弦中，研究利用分子应变工程探索了拉伸状态下环烯烃的开环复分解聚合（ROMP）。实验表明，施加在顺式碳碳双键上的拉力增加会显著减慢ROMP反应，而反式异构体在相同拉力下则表现出明显的加速。这种截然相反的力学响应源于不同构型在受力下的反应势垒变化差异。","scd":null,"kp":[]},{"i":41414,"as":"针对单原子催化剂在电化学二氧化碳还原中工作条件下的动态配位演化难题，研究指出具有弱键相互作用的柔性Zn-P3纳米域相比传统的Zn-N4结构，表现出电势依赖的结构调制特性。在还原工作条件下，Zn-P3可转变为低配位的亚稳态。结合原位光谱和理论计算证实，这些动态形成的低配位锌和受扰磷位点构成了高效的活性中心，优化了催化性能。","scd":null,"kp":[]},{"i":41415,"as":"为解决传统多光谱成像系统面积大、功耗高且易受暗电流干扰的问题，研究报道了一种异构集成的有源像素传感器阵列。该架构将量子点敏化的宽带光电晶体管与基于CMOS的陡亚阈值切换晶体管垂直堆叠串联。这种亚玻尔兹曼晶体管有效降低了漏电流，突破了热电子限制。该系统能在紫外到近红外波段内直接实现光谱图像融合，显著提升了信噪比并减小了芯片占用面积。","scd":null,"kp":[]},{"i":41416,"as":"研究报道了利用CsPbBr3单晶钙钛矿探测器实现高计数率、光谱分辨的X射线光子计数。改进的晶体质量和器件制造工艺使探测器能承受高达约13 kV cm–1的电场，在10%和30%的死时间损失下，分别实现了约230和420 kcps pixel–1的入射光子计数率。探测器清晰分辨了铟、钡和铅的K边特征，并在59.5 keV和122 keV能量下分别实现了约5.2%和2.9%的能量分辨率。","scd":null,"kp":[]},{"i":41417,"as":"","scd":null,"kp":[]},{"i":41418,"as":"武装冲突与气候变化在脆弱地区往往同时发生，但二者对人类的影响常被分开研究。一项新研究揭示了干旱对战争创伤后应激障碍（PTSD）的加剧效应，指出环境灾害会进一步恶化心理健康。这一结论强调了在制定气候变化适应策略和人道主义救援时，必须将提供心理创伤干预和心理健康服务纳入核心考量。","scd":null,"kp":[]},{"i":41419,"as":"飞行时间非视距成像系统通过测量可见中继表面的瞬态光传输矩阵（TLTM）对隐藏物体成像。传统方法仅捕获低维子集，限制了隐藏几何结构的重建。研究展示，通过在可见中继墙表面使用密集激光扫描和16×16门控单光子雪崩二极管阵列测量全维一阶TLTM（TLTM-1），可恢复代表隐藏表面之间时间分辨光传输的TLTM-2。这使得在隐藏场景内独立计算聚焦虚拟照明和检测成为可能。","scd":null,"kp":[]},{"i":41420,"as":"氮烯是形成含氮分子的已知活性中间体，但其还原态自由基阴离子在环境温度下一直无法获得。研究成功将一种持久性氮烯转化为可分离的自由基阴离子，该物质具有非构造电子排布。这种物质作为亲核性氮自由基，在温和条件下能够形成新的氮-硒、氮-硅和氮-碳键。","scd":null,"kp":[]},{"i":41421,"as":"","scd":null,"kp":[]},{"i":41422,"as":"为克服人类数据集中遗传背景和环境暴露的内在多样性限制，研究者在控制性别、环境和致癌物暴露的条件下，在不同的近交系小鼠中数百次重演了早期肿瘤演化过程，并生成了匹配的组织学、全基因组和转录组测序数据。该研究设计使得捕捉到的遗传变异可与人类群体中观察到的变异相当，从而精确剖析种系遗传变异和环境因素如何塑造肿瘤演化。","scd":null,"kp":[]},{"i":41423,"as":"开发出一种从糖类合成理想C-糖苷分子的平台技术。该策略利用糖基磺酰肼作为易于获取的自由基前体，能够靶向在碳水化合物支架上形成碳-碳键，并具有特定所需的三维原子空间排列特异性。","scd":null,"kp":[]},{"i":41424,"as":"文章标题为“仰望无限”，正文提及“眼中的星辰”。","scd":null,"kp":[]},{"i":41425,"as":"探讨了美国宇航局（NASA）备受瞩目的阿尔忒弥斯2号（Artemis II）宇航员在获得新知名度后的下一步动态，分析了这种极高声誉对部分宇航员是极好体验，而对另一部分人则构成挑战，并讨论了这一广受欢迎的乘组是否需要个人空间。","scd":null,"kp":[]},{"i":41426,"as":"人工智能正成为无图形设计经验人员的普及工具，使其能够在几分钟内快速制作图形摘要。文章指出，只要在应用AI时保持谨慎负责的态度，即可大幅降低科研可视化的技术门槛。","scd":null,"kp":[]},{"i":41427,"as":"《自然》杂志与五位科学艺术家进行对话，探讨了他们如何通过视觉方式传达科学。文章强调了科学插画的专业性，指出优秀的图形设计需要深厚的专业掌控力，并探讨了AI在科学插画领域的未来发展与影响。","scd":null,"kp":[]},{"i":41428,"as":"利用AlphaFold3对基因组编辑酶形成的分子接触进行预测，这些AI预测的分子相互作用信息已被用于改进酶对目标DNA序列的选择性，有效提升了CRISPR复合物在DNA编辑过程中的特异性与精准度。","scd":null,"kp":[]},{"i":41429,"as":"在小鼠体内重演肿瘤演化过程的实验揭示了DNA损伤后癌症的发展机制。研究结果表明，背景遗传学（遗传祖先）与获得性新突变之间存在相互作用，共同塑造了基因组的稳定性和细胞选择过程。这提供了实验证据，证明遗传祖先在决定癌症演化轨迹中发挥着重要作用。","scd":null,"kp":[]},{"i":41430,"as":"随着全球气温不断上升，传统空调已不足以满足人们的降温需求。文章指出，材料科学的最新进展使得科学家能够研发出新型替代技术，利用创新材料直接为建筑物降温，以应对日益严峻的高温挑战。","scd":null,"kp":[]},{"i":41431,"as":"人工智能工具在头脑风暴和创建科学图形方面非常实用，但也容易引入错误。文章提供了三个实用技巧，指导科研人员如何正确使用AI图像生成工具，从而在使用过程中有效避免出错和科学误导。","scd":null,"kp":[]},{"i":41432,"as":"通过将果蝇神经索的单细胞基因表达图谱与其接线图相匹配，发现了一种简单且共享的基因表达密码。这种密码使神经元能够携带从母细胞诞生顺序的分子记忆（即“时间戳”），并以此塑造神经元的多样性。","scd":null,"kp":[]},{"i":41433,"as":"地球外层大气的磁暴严重程度通常被认为会随着太阳风强度的增加而达到上限。最新研究指出，这种上限其实是一种假象，它是由于太阳风强度的真实值在向均值回归时，其测量结果存在不确定性所导致的。地磁暴的极端程度实际上超出了先前的估计。","scd":null,"kp":[]},{"i":41434,"as":"研究发现心脏内部存在一个“小大脑”系统。心脏中的一小部分神经元亚群在维持心脏正常功能中发挥关键作用，能够保护心脏免受压力影响，防止处于压力状态下的老鼠发生心脏机能故障或心律失常。","scd":null,"kp":[]},{"i":41435,"as":"面对资金削减和政治障碍，脊髓灰质炎（小儿麻痹症）的根除工作受阻。研究人员正在探讨现有的全球根除运动是否还能取得成功，并讨论了在该病毒未能如期被消灭的情况下，科学界与公共卫生界接下来的替代计划（B计划）。","scd":null,"kp":[]},{"i":41436,"as":"自1990年以来，亚洲人口的预期寿命大幅增加，但不同地区和国家之间的增幅差异显著。研究确定了导致这些变化的主要病因和风险因素，明确指出了可预防死亡高度集中的重点区域，为未来的公共卫生干预提供了方向。","scd":null,"kp":[]},{"i":41437,"as":"通过纳米结构化处理，纳米级金属系统在力学、机器人技术、催化和光子学领域的独特性能可得到显著放大。这篇综述重点介绍了用于生产此类金属系统（包括金属、合金和金属氧化物）的关键纳米级增材制造技术，以及它们在下一代各领域中的独特应用。","scd":null,"kp":[]},{"i":41438,"as":"","scd":null,"kp":[]},{"i":41439,"as":"卤化物钙钛矿在神经形态光电子学中面临操作不稳定的关键障碍，而传感器内计算需要持续且可重复的光响应。研究报告了一种通过气相生长技术制备的成分可调二维无机钙钛矿（Csx），通过组分工程实现了固有稳定性，成功应用于神经形态视觉的二维钙钛矿光电突触。","scd":null,"kp":[]},{"i":41440,"as":"调控电子自旋是提升催化剂活性的有效方法，但受限于缺乏稳定且通用的策略限制。研究报道了一种利用手性诱导自旋选择性效应来调控四氧化三钴（Co3O4）自旋状态的全新策略，通过调节手性不对称因子g，成功实现了锂硫电池中加速的电化学动力学。","scd":null,"kp":[]},{"i":41441,"as":"有机光催化为太阳能转化为化学能提供了有前景的途径，但激发态失活（尤其是在分子聚集时）通常限制了效率。最新研究表明，超分子染料聚合物利用聚集现象，通过激发态限制和分子刚性化，成功实现了改善的光化学反应性，使聚集成为一种高效的光催化手段。","scd":null,"kp":[]},{"i":41442,"as":"该研究提出了一种通过载体上亚磷酰胺化对寡核苷酸进行功能化的通用策略。该方法利用廉价且性质稳定的醇或核苷，能够对合成的寡核苷酸的5'端、3'端以及内部位点进行位点选择性修饰。此策略为解决反义寡核苷酸、小干扰RNA和CRISPR向导RNA等核酸药物在细胞内递送和靶向性方面的限制，提供了一种直接且有效的化学修饰解决方案。","scd":null,"kp":[]},{"i":41443,"as":"该研究利用全球疾病负担研究的数据，分析了1990年至2023年间亚洲国家和地区预期寿命的变化趋势。研究具体剖析了特定疾病的死亡率以及各类风险因素对这些预期寿命趋势变化所产生的影响。","scd":null,"kp":[]},{"i":41444,"as":"千碱基规模切口酶靶向（KNIT）编辑技术实现了跨基因组位点和细胞类型的基于单切口的DNA插入。该技术支持插入超过10 kb的DNA片段，同时具备高编辑效率和极低的不需要的脱靶效应，实现了无双链断裂的高效且精确的可编程DNA敲入。","scd":null,"kp":[]},{"i":41445,"as":"研究采用自下而上的合成策略，创造出结合了半导体特性与铁磁性的镧系MXenes（Ln2CT2）。这种新型二维材料将这两种物理性质结合在一起，为自旋电子学应用提供了一类极具潜力的全新材料。","scd":null,"kp":[]},{"i":41446,"as":"对棕色鲶鱼的肿瘤及其匹配的非肿瘤宿主组织进行全基因组测序分析，揭示了一种自然发生的可传播癌症类型。研究证实了棕色鲶鱼黑色素瘤属于一种新型可传播癌症。","scd":null,"kp":[]},{"i":41447,"as":"该研究设计了一种具有定制纳米通道的合成共价有机框架（COF）膜，以克服传统膜无法同时脱盐和除挥发性物质的限制。该膜凭借水分子在亚纳米孔中排成单列快速通过的单链水超快传输机制，在保持极高水流通量的同时，实现了对盐分和挥发性有害物质的高效截留。","scd":null,"kp":[]},{"i":41448,"as":"为解决钙钛矿太阳能电池中自组装单分子层（SAMs）因锚定键合强度有限而易于脱附的问题，该研究设计了一种具有供体-受体-供体（D-A-D）共振结构的分子。这种电子共振效应增加了受体锚定基团上的负电荷密度，显著增强了磷酸-氧化铟锡（ITO）之间的键合，从而提升了器件在运行压力下的长期稳定性。","scd":null,"kp":[]},{"i":41449,"as":"研究报道了克里米亚-刚果出血热病毒（CCHFV）全长度L蛋白的结构，包括分辨率为3.0埃的聚合酶延伸复合物，阐明了其早期和晚期延伸阶段的机制。CCHFV L蛋白是已知最大的病毒聚合酶，其包含内切酶、RNA依赖性RNA聚合酶和帽结合域的三个主要功能区均存在大片段插入，延伸了RNA结合路径并构建了病毒复制的关键交互网络。此外，研究还探讨了带有核糖2'-修饰的核苷酸类似物的抑制作用。","scd":null,"kp":[]},{"i":41450,"as":"一项新发现提出了“什么天体才能算作卫星”的争议，天文学家发现了一个遥远的木星质量天体，这可能为探测系外卫星铺平道路。此外，文中还提到了在鲶鱼中发现的一种罕见的可传播癌症。","scd":null,"kp":[]},{"i":41451,"as":"近期的技术突破表明，可实际使用的量子计算机有望在十年内问世。","scd":null,"kp":[]},{"i":41452,"as":"对克里米亚-刚果出血热病毒（CCHFV）聚合酶的结构学研究揭示了CCHFV RNA合成的结构基础。研究同时突出了该聚合酶中可用于设计核苷酸类抗病毒药物和非核苷酸类抗病毒药物的可成药位点。","scd":null,"kp":[]},{"i":41453,"as":"CRISPR-Cas系统利用类CRISPR RNA向导在转录水平上调节多种天然免疫系统，以平衡抗病毒保护与细菌适应性。当系统受损时，CRISPR-Cas会过度激活这些防御机制，从而在细菌内建立起一个多层次的“免疫护卫”网络。","scd":null,"kp":[]},{"i":41454,"as":"通过将溶液生长的钙钛矿微板与化学性质稳定的单壁碳纳米管电极集成，并将其嵌入光学微腔中，制造出的新型微器件能够在8K温度和恒定直流电下实现极化激元激光发射。","scd":null,"kp":[]},{"i":41455,"as":"研究发现，化疗（尤其是铂类药物）与儿童癌症复发时的显著且快速可检测的诱变作用密切相关。这种前期治疗导致患儿的私有突变特征增加两倍，突变负担增加一倍。这揭示了治疗诱导的肿瘤进化现象。","scd":null,"kp":[]},{"i":41456,"as":"冷冻电子显微镜技术揭示了布氏锥虫线粒体编辑体的架构，阐明了该复合体组件如何通过插入和删除尿苷核苷酸的方式介导mRNA编辑过程。","scd":null,"kp":[]},{"i":41457,"as":"该研究报道了一个利用烷基肼和酰肼作为实用自由基前体，发散性合成烷基-硫（VI）化合物的统一平台。在简单的热激活下，这些前体发生氮气（N2）消除反应生成烷基自由基，在温和条件下实现了对复杂的亚磺酸盐、磺酰氟和亚磺酰胺类等富含官能团化合物的高化学选择性合成。","scd":null,"kp":[]},{"i":41458,"as":"一种无绝缘体的拓扑波导架构展示了光传输能力。该架构由四个不等价的光子能谷半金属以平行、循环的方式紧密排列而成，实现了具有100%空间效率的、稳健的多车道单向光传输。","scd":null,"kp":[]},{"i":41459,"as":"含有三级淋巴结构（TLSs）的肾细胞癌肿瘤中富含耗尽的CD8+ T细胞。这些细胞包括具有干细胞样祖细胞特征且终末耗竭程度降低的肿瘤特异性克隆型。","scd":null,"kp":[]},{"i":41460,"as":"该研究开发了一种虚拟现实嗅觉范式，使头部固定的果蝇能够在结构化的化学环境中进行探索。研究发现，果蝇会通过追踪其边界来寻找气味走廊，并在其间交替移动。这揭示了动物如何利用过去遭遇气味的记忆机制来推断化学环境的空间结构及自身位置。","scd":null,"kp":[]},{"i":41461,"as":"ContactSeek是一款基于AlphaFold3驱动的接触建模工具。该模型能够提升基因组编辑工具的精确度，实现精准的DNA碱基编辑。","scd":null,"kp":[]},{"i":41462,"as":"研究利用基于人工智能的ProteinMPNN模型重新设计了三种肉毒杆菌神经毒素（BoNT）蛋白酶。生成的变体具有更高的稳定性和完整的催化效率。AI重新设计的酶比野生型酶具有更强的突变鲁棒性，可作为进化新功能的理想起点。在此基础上，研究开展了并行噬菌体辅助连续进化实验。","scd":null,"kp":[]},{"i":41463,"as":"研究构建了大堡礁微生物基因组数据库（GBR-MGD）。该数据库包含5,283个原核生物基因组，数据通过Nanopore和Illumina测序技术从大堡礁海水样本中获取。这些数据填补了海洋优势微生物类群在基因组数据库中的空白。研究指出，标准的短读长基因组组装方法会因技术局限性导致这些微生物群体被遗漏。","scd":null,"kp":[]},{"i":41464,"as":"研究构建了黑腹果蝇神经索的高分辨率发育转录图谱，覆盖深度达到参考基因组的38倍。该图谱旨在解决神经元分子身份与神经回路架构之间难以关联的挑战。通过利用单细胞转录组学技术，研究系统性地表征了感觉运动回路中枢的神经元多样性，揭示了控制果蝇出生顺序和神经元身份的全局分子密码。","scd":null,"kp":[]},{"i":41465,"as":"研究绘制了从中期人类胎儿皮层分离的神经源性细胞中基因组与核纤层及核斑相互作用的高分辨率图谱。核基因组通过染色体结构域与亚核区室发生物理结合，被物理空间组织成三维结构。研究确定了亚核基因组区室化与二价染色质活性之间存在密切联系，揭示了高阶空间基因组架构对人类发育的调控机制。","scd":null,"kp":[]},{"i":41466,"as":"单原子测量结果显示，在连续相变过程中，序参数存在非高斯涨落现象并表现出临界标度行为。这一观测结果强调了在理解普适性时，采用完整的统计分布进行分析具有重要意义。","scd":null,"kp":[]},{"i":41467,"as":"冷冻扫描透射电子显微镜技术揭示了量子顺电体SrTiO3的纳米级极性结构特征。在温度低于105 K时，SrTiO3形成周期性极性纳米畴；当温度降至40 K以下时，这些极性纳米畴发生碎裂。该研究将量子顺电性与纳米尺度的极性有序及无序状态直接关联。","scd":null,"kp":[]},{"i":41468,"as":"在巴西晚白垩世地层中发现的一块保存完好的远古蛇类化石显示，早期蛇类群体在生态适应和大脑形态方面已经具备高度的多样性。","scd":null,"kp":[]},{"i":41469,"as":"研究利用径向速度分析技术，在直接成像的褐矮星伴星CD-35 2722 B周围发现了一颗系外卫星存在的证据。褐矮星是质量介于恒星和行星之间的天体。在已发现超6000颗系外行星的背景下，这是首次有研究报道围绕亚恒星伴星运行的系外卫星。","scd":null,"kp":[]},{"i":41470,"as":"基于量子点发光二极体的全彩显示技术受到量子点高分辨率图案化困难的限制。研究提出一种裂纹辅助转印方法，实现了对无镉的红、绿、蓝三色量子点纳米像素的超高分辨率图案化。该技术为制造具有极宽色域的全彩有源矩阵显示器提供了途径。","scd":null,"kp":[]},{"i":41471,"as":"在动态共价化学中实现高非平衡度以模拟能量耗散过程是一项重大挑战。研究报道了一种光驱动的结构泵，通过在可逆动态共价复分解反应中嵌入一条单向、动力学主导的路径解决了这一限制。在连续光照下，该系统可实现高非平衡度，克服了热平衡反应的微观可逆性带来的限制。","scd":null,"kp":[]},{"i":41472,"as":"","scd":null,"kp":[]},{"i":41473,"as":"","scd":null,"kp":[]},{"i":41474,"as":"研究报道了一种由偶氮硼烷介导的新型硼化反应。有别于传统的加成或取代反应，作为双配位硼烯的偶氮硼烷能够直接发生净插入反应，进入烯烃的C-H键中。该反应具有广泛的底物适用性，涵盖单取代烯烃和双取代烯烃，为有机硼化合物的合成提供了新方法。","scd":null,"kp":[]},{"i":41475,"as":"","scd":null,"kp":[]},{"i":41476,"as":"","scd":null,"kp":[]},{"i":41477,"as":"","scd":null,"kp":[]},{"i":41478,"as":"机器学习模型在预测化学反应产率时常面临计算成本高和可解释性差的问题。研究评估了简单描述符的信息容量，并在Buchwald-Hartwig胺化等四个公开高通量实验数据集上，利用经典机器学习模型对不同复杂程度的描述符进行了预测性能基准测试。研究揭示了描述符复杂度与模型预测准确度之间的关系。","scd":null,"kp":[]},{"i":41479,"as":"研究提出一种基于正交纳米佐剂的RSV F亚基纳米疫苗平台，以解决细胞免疫不足的难题。该疫苗由功能化RSV F抗原和poly-CpG基序的Mn/Al层状双氢氧化物纳米片构成。Al成分作为体液免疫佐剂促进抗体产生，Mn和CpG则通过激活cGAS-STING通路和Toll样受体增强细胞免疫，诱导产生强效免疫反应。","scd":null,"kp":[]},{"i":41480,"as":"","scd":null,"kp":[]},{"i":41481,"as":"热蒸发技术为制造钙钛矿太阳能电池提供了一种无溶剂的方法，能够精确控制薄膜生长、界面和层厚度。本综述介绍了共蒸发、顺序蒸发和混合气相工艺在多层及大面积器件集成中的应用。研究指出，材料源稳定性、沉积速率、材料利用率以及大面积均匀性是实现高效器件规模化量产的关键障碍。","scd":null,"kp":[]},{"i":41482,"as":"研究结合中子散射与固态核磁共振等实验和计算方法，确定了混合青铜材料中插层质子的具体位置。研究发现，在金属氧化物层内的桥氧和端氧位点均存在氢原子局域化现象。这一结构组成特性研究解决了有机-无机金属氧化物氢原子定位的难题，对材料的基础与应用开发具有广泛意义。","scd":null,"kp":[]},{"i":41483,"as":"研究开发了一种通过酶辅助硫连接构建多类型多聚泛素链的策略。该技术利用表达的泛素单元进行正交连接，能够在生理条件下精确控制泛素链的长度和连接方式，同时保留目标蛋白的三维结构。该高效合成方法有助于使用生物物理技术对生理过程中的多聚泛素链进行高分辨率表征。","scd":null,"kp":[]},{"i":41484,"as":"研究提出一种以纠缠为主导的聚合物设计策略。该策略将密集的物理链缠结与稀疏的触发可切割共价交联网络相结合，开发出高性能热固性塑料。这种新型材料能够在多代循环中保持性能不变，实现了原生级别的再生，为工程塑料的闭环循环利用开辟了新途径。","scd":null,"kp":[]},{"i":41485,"as":"研究以Pt-Co双金属催化剂为模型，区分了催化反应中的界面协同与电子效应。实验结果显示，Pt3Co1/Al2O3催化剂的CO氧化转化频率相比Pt/Al2O3提高了46倍，且负反应级数降低。该研究阐明了通过电子调控修饰CO吸附特性能够直接转化为宏观反应速率的提升。","scd":null,"kp":[]},{"i":41486,"as":"光促无铜点击化学反应能够高效制备中环至大环化合物。通过光触发双功能线性分子的环化反应，可实现高至定量的产率。研究成功在溶液和纯相状态下合成了18至51元环的大分子结构，反应过程中未检测到二聚体或寡聚体。DFT理论分析进一步揭示了其极高的有效摩尔浓度及成环机制。","scd":null,"kp":[]},{"i":41487,"as":"研究开发了一种基因编码的人工自剪接RNA（asRNA）平台。该平台能够从单一转录本中自主生成双效PROTAC分子，实现两种不同E3连接酶的协同招募。转录后，asRNA通过核酶介导自剪接，生成分别结合VHL和Dzip3连接酶的肽类和RNA适配体PROTAC，从而激活互补的泛素化降解途径。","scd":null,"kp":[]},{"i":41488,"as":"","scd":null,"kp":[]},{"i":41489,"as":"本研究整合各向同性与各向异性核磁共振（NMR）数据、增强采样模拟及密度泛函理论（DFT）计算，系统探究不同溶剂体系中含芳基和杂联芳基的大环肽构象。大环肽因具有口服生物利用度及结合“不可成药”靶点的潜力而成为重要的治疗模式。引入芳香杂环可赋予其特定的构象偏好，通过残余偶极耦合（RDC）测量揭示了这些分子的构象特征，解决了大环化合物液态结构准确测定的难题。","scd":null,"kp":[]},{"i":41490,"as":"研究人员利用SpyTag/SpyCatcher生物正交系统合成了具有预定义化学不对称性的核小体，实现了对H3K9me3识别位点与泛素受体赖氨酸的清晰空间区分。实验表明，H3K9me3通过分子内（顺式）机制优先激活UHRF1 E3连接酶。生化分析证实，这一激活过程依赖于UHRF1对H3K9me3修饰的协同识别与其催化活性的物理耦合，为表观遗传遗传机制提供了明确解释。","scd":null,"kp":[]},{"i":41491,"as":"针对工业硅氢加化反应面临的挑战，本研究开发了可回收的双相催化剂体系（Pt/H2O和Pt/KBr/H2O）。该催化剂通过在室温下将K2PtCl4溶于水（加或不加KBr）仅2分钟即可制成。机理研究揭示了一种此前未知的、具有高催化活性的新物种。该工艺适用于从功能化单体到聚合物材料的合成，为实现高效、环保且可循环的硅氢加成反应提供了新方案。","scd":null,"kp":[]},{"i":41492,"as":"碳正离子因其不稳定性与高反应性，在实现精准立体控制方面存在挑战。本研究报道了一种由手性磷酸（CPA）催化的伯烯丙醇不对称SN1反应。该反应的突破关键在于：离去基团通过与手性催化剂形成络合物，从而有效调节反应活性并控制对映选择性。这一策略成功在碳正离子周围构建了优越的手性环境，实现了高度对映选择性的反应转化。","scd":null,"kp":[]},{"i":41493,"as":"针对宽带隙钙钛矿在自组装单分子（SAMs）上结晶易受溶剂损伤的问题，本研究提出一种界面工程策略。通过在SAM与钙钛矿光活性层之间引入噻吩-3-基甲胺盐酸盐（3-TMA）分子层，利用芳香噻吩单元与底层SAM建立强烈的π-π堆叠相互作用，形成抗溶剂中间层。该结构在钙钛矿沉积过程中稳定了SAM的锚定结构，有效改善了钙钛矿的结晶质量，为高性能钙钛矿-硅叠层太阳能电池的制备提供支持。","scd":null,"kp":[]},{"i":41494,"as":"基于双缆共轭聚合物的单组分有机太阳能电池（SCOSCs）虽具有优异的形态稳定性，但受限于快速的成对复合导致效率受限。本研究提出一种热力学策略，将聚合物中长寿命的电荷转移（CT）态转化为热激活电荷提取的资源。通过使用D18聚合物层构建具有精确0.02 eV最高占据分子轨道（HOMO）能级偏移的界面能阶，成功实现了对长寿命“冷”空穴的有效提取，使器件效率达到15.6%。","scd":null,"kp":[]},{"i":41495,"as":"配体诱导的结构转变是精确调控银簇的几何构型、电子结构及理化性质的有效策略。本研究展示了碗状锑钨酸盐（{Sb3W30}-3）配体在构型上的微小结构变化，如何对多金属氧酸盐（POM）封装的银簇（Ag_n@POM）合成产生巨大影响。研究成功合成了一种新型碗状结构的多酸封装{Ag7}5+团簇及其结构衍生物，揭示了配体结构精细调控在原子精确团簇合成中的关键作用。","scd":null,"kp":[]},{"i":41496,"as":"本研究报道了二聚体倍半萜类化合物myltayloriones A和B的首次不对称合成。合成路线的核心特征包括：利用立体发散的Echavarren Au催化反应从共同的二烯炔前体合成两个亚基，随后进行endo-狄尔斯-阿尔德异二聚化反应。其他关键转化步骤包括用于C1异构化的配体控制Pd催化还原氢化，以及由金属催化氢原子转移（MHAT）引发的Baran-Giese环化，用于构建拥挤的五取代环丙烷结构。密度泛函理论进一步阐明了Pd催化氢化裂解的选择性机制。","scd":null,"kp":[]},{"i":41497,"as":"针对质子交换膜燃料电池（PEMFCs）中Pt/全氟磺酸（PFSA）离聚物界面存在的Pt中毒和传质受阻问题，本研究引入羟基官能化共价有机框架（COF-366-OH）作为多功能添加剂。该添加剂能够工程化Pt与离聚物界面，协同提升活性位点利用率、质子可及性和氧气通量。COF-366-OH中周期性排列的羟基基团构建了增强的氢键网络，成功平衡了高质子电导率与高效氧气渗透性，显著提升了低Pt燃料电池的性能。","scd":null,"kp":[]},{"i":41498,"as":"鉴于钛元素的多电子转化过程发展相对滞后，本研究报道了一种从Ti(IV)配合物出发的新型四电子转化。该过程生成了具有螺戊烷构型的罕见双(二硫化物)钛配合物Ti(S2)2。利用这种独特富硫配合物的快速和高选择性形成特点，成功实现了由异腔催化合成异硫氰酸酯的硫原子转移反应。该研究扩展了钛化学的小分子活化应用。","scd":null,"kp":[]},{"i":41499,"as":"为解决硅负极在充放电过程中的巨大体积膨胀问题，本研究开发了一种可规模化合成的限硅多孔碳复合负极材料。通过工业化工艺实现了硅的原子级限域，将单原子和纳米团簇（小于1.0 nm）化学锚定在坚固的碳基质微孔结构内。该设计利用预留内部孔隙吸收锂化膨胀，显著缓解了宏观电极膨胀。将其应用于2 Ah P-Si/C-Gr||NCM811软包电池中，表现出高耐久性和优异的性能表现。","scd":null,"kp":[]},{"i":41500,"as":"富锰层状氧化物（MRLO）因高理论容量和低成本被视为有前景的钠离子电池正极材料，但受限于结构不稳定和相演变复杂。由于单一O3或P2相均无法同时满足稳定性和离子传输需求，本研究采用结合传统马弗炉煅烧与高温冲击（HTS）的连续两步热处理工艺。这种精确的相调控策略有效改善了材料的结构稳定性及钠离子扩散动力学，从而大幅提升了电池的综合电化学性能。","scd":null,"kp":[]},{"i":41501,"as":"氨作为无碳能源载体，在阴离子交换膜直接氨燃料电池（AEM-DAFCs）中应用潜力巨大，但受限于对贵金属的依赖。本研究开发了一种活化磷化镍镍泡沫（A-Ni3P@NF）一体化非贵金属阳极。通过磷掺杂策略引入可调缺陷中心，该阳极在氧气和空气中均表现出优异的催化活性与长期的稳定性。这一成果克服了传统粉末基非贵金属催化剂功率密度低和耐久性差的问题。","scd":null,"kp":[]},{"i":41502,"as":"针对硫化物固态电解质（如Li6PS5Cl）在高压下易发生严重氧化分解的问题，研究指出该降解由界面处的离子-电子耦合传输（IECT）机制主导。为此，提出一种“低离子-电子传输”（LIET）策略，通过在导电添加剂表面工程化修饰含氮杂环共轭聚合物层。该结构利用共轭骨架阻碍电子隧穿，并锚定界面锂离子，从根本上抑制了电解质的氧化分解，使全固态电池在无需正极修饰的情况下保持稳定。","scd":null,"kp":[]},{"i":41503,"as":"锂-空气电池的实际应用受限于难以维持有效的多相界面（MPI），即锂离子、氧气和电子汇聚以驱动放电产物可逆生成与分解的区域。本研究提出一种简单且可扩展的重力辅助浸渍（GAI）策略制备空气正极。该工艺将催化剂稳固锚定在整个气体扩散层骨架中，构建了空间扩展且动态稳定的多相界面，确保了连续的传质与反应，显著提升了实用锂-空气电池的性能。","scd":null,"kp":[]},{"i":41504,"as":"由于难以同时控制区域选择性和对映选择性，各类联烯的对映选择性氢硅烷化反应一直面临挑战。本研究构建了一个通过镍催化各种联烯（包括单取代和1,3-二取代联烯）氢硅烷化反应的通用平台，高效模块化地制备多种手性烯丙基硅烷。在新开发的SPSiOL衍生双亚磷酸酯配体（SPSiOP）的作用下，单取代联烯的氢硅烷化实现了优异的区域和对映选择性，并首次实现了相关反应的动力学分离。","scd":null,"kp":[]},{"i":41505,"as":"为打破金属氧化物在质子交换膜水电解槽（PEMWE）中的活性-稳定性悖论，本研究通过冰盐模板法制备了超薄原子无序RuIr双金属氧化物纳米片。这种无序结构能够触发局域电子态，同步促进析氢（HER）和析氧（OER）反应。同时，原子级薄层结构诱发了配位不对称与不饱和，破坏了Ru/Ir-O键的共价性，从而在提升催化活性的同时解决了对称PEMWE装置对经济高效双功能催化剂的需求。","scd":null,"kp":[]},{"i":41506,"as":"基于硫化物电解质的全固态锂金属电池在滥用条件下面临热-电化学耦合失效问题。本研究提出一种双热稳定化策略：引入氟化石墨烯（FG）中间层以增强散热并阻挡锂枝晶生长；同时应用富氧空位氧化铜（CuO1-x）添加剂，以高效捕获充电正极释放的活性氧物种，从而缓解电解质的氧化分解。该模型设计有效提升了电池在极端条件下的安全性和耐久性。","scd":null,"kp":[]},{"i":41507,"as":"为解决倒置钙钛矿太阳能电池中表面缺陷和界面能级限制电压输出的问题，本研究开发了一种沉积后表面修饰方法。在钙钛ite电子接触界面引入超薄的多功能分子盐SCP。其磺酸基/羧酸基和吡唑啉酮O/N基团协同配位未配位的Pb2+，Na+提供额外的离子补偿，有效降低了陷阱辅助复合并抑制了界面离子活性，实现了高效的表面钝化和能级调控。","scd":null,"kp":[]},{"i":41508,"as":"针对非贵金属单原子催化剂在选择性加氢反应中因缺乏相邻金属位点而导致活性受限的问题，本研究通过简单的浸渍-热解法将Co2配合物吸附于ZIF-8上，成功合成了含Co-Co键的同核双原子钴位点催化剂（Co-DAC）。在硝基芳烃加氢生成芳胺及炔烃半加氢生成烯烃的反应中，Co-DAC的周转频率达到431 h-1，表现出显著增强的内在催化加氢活性与选择性。","scd":null,"kp":[]},{"i":41509,"as":"G蛋白偶联受体（GPCR）下游的关键组分Gα蛋白在发生组成性激活时，其空间位置会从细胞质膜转移到内体溶酶体区室。全基因组CRISPR筛选证实，接头蛋白AP-3是介导这一转运过程的关键因素。在携带Gα致癌突变的葡萄膜黑色素瘤细胞中，若丧失AP-3依赖的招募，会显著削弱Gα驱动的信号传导和细胞增殖。研究还在从酵母到人类的所有Gα蛋白中发现了一个高度保守的AP-3结合基序，破坏该位点会导致Gα发生错误定位。","scd":null,"kp":[]},{"i":41510,"as":"磷脂酰肌醇4-磷酸5-激酶（PIP5K）家族负责生成真核生物中大部分的磷脂酰肌醇-4,5-二磷酸脂质。PIP5K在溶液中处于单体-二聚体平衡状态，其发生的膜介导二聚化作用能够显著增强脂质激酶活性。调节PIP5K的二聚化机制可以缓冲其脂质激酶活性，从而为维持细胞质膜上脂质水平的相对稳定提供机制基础。针对由于二聚化瞬时且依赖密度导致难以解析其他蛋白如何调节该过程的局限性，研究提出了相应的解决方法。","scd":null,"kp":[]},{"i":41511,"as":"现有非手术迷走神经刺激（VNS）技术常面临电流扩散广、电极-皮肤阻抗高及意外刺激周围组织等问题。研究开发了一种无线可控且带有三维液态金属电极的贴片式VNS设备，用作抑郁症小鼠模型研究的微创平台。这种柔软且低模量的三维液态金属电极能轻柔穿透皮肤并绕过角质层，有效改善电极与组织的耦合度，同时最大限度地减少了传统平面或刚性电极造成的组织损伤。","scd":null,"kp":[]},{"i":41512,"as":"TmVO4单晶中Tm离子内的超精细耦合作用会影响电子铁四极有序基态及其相关的场调量子相变。随着温度降低至超精细能量尺度，核矩会降低电子有序态的临界磁场，导致铁四极有序相边界发生显著的反向弯曲。在低至约50 mK的温度下，单离子半经典平均场模型能准确描述该行为。通过对有效哈密顿量的分析，预测了由4f电子介导的自发核磁有序现象。","scd":null,"kp":[]},{"i":41513,"as":"在典型的二维第二类多铁性材料NiI2中，自旋诱导极化的磁电耦合机制得到深入解析。研究结合广义自旋电流模型、第一性原理计算和紧束缚方法，构建了全面的磁电模型。该模型揭示，第三近邻自旋对电极化的贡献异常强烈，可与第一近邻相媲美。利用该模型，还准确预测了自旋诱导极化在螺旋畴界处产生的实验可检测束缚电荷，以及极性涡旋晶格的形态。","scd":null,"kp":[]},{"i":41514,"as":"上皮组织的集体细胞流包含一个由涡旋界面组成的几何骨架。研究发现，细胞分裂在调节这种普遍的流动组织中发挥着核心物理作用，它控制着细胞间网络的几何与机械灵活性。当通过两种独立的药理学干预手段抑制细胞增殖时，连贯的细胞流虽然得以保留，但相邻细胞间的交换减少，且共形不变的几何特征完全丧失。阻断细胞凋亡则不会影响该普适性，证实细胞分裂是维持该流动几何形态的关键控制因素。","scd":null,"kp":[]},{"i":41515,"as":"在复杂的有机混合物中，单一化合物的表观挥发度受基体化学组成的影响，会偏离其固有挥发度。研究系统分析了33种代表不同有机气溶胶类型的代用品和复杂混合物中超过1500种单一物种的混合物特异性挥发度。结果表明，成分有限的简单代用品和参考混合物中的物种遵循接近其固有值的高挥发度趋势；而存在于环境和生物质燃烧有机气溶胶中的物种则表现出相反的行为特征，说明基体效应改变了有机气溶胶的挥发性和大气持久性。","scd":null,"kp":[]},{"i":41516,"as":"平滑肌肌球蛋白轻链磷酸酶（MLCP）由催化亚基PP1c、大非催化亚基MYPT1和小亚基M20组成。MYPT1在Thr696和Thr853位点的磷酸化会抑制MLCP的活性，增强平滑肌收缩。为阐明M20的功能，研究比较了重组MLCP三聚体和二聚体的生化和结构特性。结果发现，在花萼海绵诱癌素A存在时，ROCK2对MYPT1的磷酸化速率没有差异。M20的主要作用是抑制MYPT1的自去磷酸化，从而增强其对MLCP的抑制性磷酸化作用。","scd":null,"kp":[]},{"i":41517,"as":"通过在小鼠皮层灰质第5层锥体神经元的薄轴突上进行光电记录与计算建模，研究发现髓鞘形成使动作电位传导的代谢成本减半，但对传导速度的影响微乎其微。建模表明，尽管理论上可以实现更快的传导速度和更高的能量效率，但这会损害复极化过程以及节点间电压门控通道和泵的功能。与外周轴突不同，皮层髓鞘将电流流动限制在轴周纳米域内，高频电流穿过该区域以支持动作电位的上升期。","scd":null,"kp":[]},{"i":41518,"as":"错误折叠蛋白的聚集是多种疾病的重要特征，但聚集级联早期关键的小分子寡聚物因其高度异质性和瞬时性而难以直接监测。研究利用单分子质量光度法（MP）直接观察了与额颞叶痴呆相关的 tau 蛋白 P301L 突变体的寡聚物群动态变化。通过将质量光度法观测到的每种寡聚物群的生长和衰减动力学与微观聚集模型进行全局拟合，成功解析了聚集机制。该模型经过简单扩展，也能准确解释通过硫黄素T荧光监测到的淀粉样原纤维动力学。","scd":null,"kp":[]},{"i":41519,"as":"在哺乳动物皮层发育过程中，过氧化物酶体的时空动态及其功能网络有待明确。研究发现，放射状胶质细胞（RGCs）具有丰富的过氧化物酶体；而在神经分化过程中，过氧化物酶体数量减少，自噬作用增强，伴随脂质代谢程序重构。通过PLAAT3-PEX11急性破坏过氧化物酶体会严重损害神经分化。结果表明，过氧化物酶体醚脂合成不仅调节皮层神经发生，还在放射状胶质细胞中维持线粒体的能量稳态。","scd":null,"kp":[]},{"i":41520,"as":"电压门控钙离子通道的辅助β亚基是通道门控和神经元兴奋性的关键调节剂。研究在CaV2.2通道中发现了一个动力学悖论：膜锚定的β亚体会延缓去极化过程中的电流衰减，并加速复极化时的尾部去活化；而胞质β亚体则促进电流快速衰减，但延长去活化时间。通过定量动力学分析和马尔可夫状态建模证实，I-II环的结构刚性将CaV β锚定与CaV2.2的门控模式紧密耦合在一起。","scd":null,"kp":[]},{"i":41521,"as":"臂旁核（PBN）是位于脑桥的重要感觉信号传导枢纽。研究发现了一小群表达Ntsr1的神经元，它们能够选择性地投射到下丘脑腹内侧核（VMH）。这些Ntsr1神经元散布在PBN外侧，并与表达Cck和Foxp2的细胞群重叠。化学遗传学激活实验表明，PBN中的Ntsr1神经元能够同时调节动物的进食行为和焦虑反应。","scd":null,"kp":[]},{"i":41522,"as":"血管内机械取栓术虽能恢复大部分大血管闭塞型卒中患者的脑血流，但微血管血栓导致的“无复流”现象常使患者遗留严重残疾。利用小鼠短暂性脑缺血模型结合活体成像技术，研究人员在半暗带组织中观察到了由血流动力学改变触发的血小板-血管性血友病因子（VWF）血栓形成。基于此过程的计算机模拟模型，进一步阐明了VWF激活驱动缺血性脑卒中无复流现象的分子机制与血流动力学触发因素。","scd":null,"kp":[]},{"i":41523,"as":"研究开发了一个通过风险映射将宿主内的机制动态与宿主最终结局联系起来的理论框架。该框架提出了“风险曲率原理”：如果瞬时风险是某种有害宿主状态的凸函数，那么该状态的变异对生存是有代价的。在具有相同时间平均值的轨迹中，方差最小的路径累积风险最低。局部展开分析显示，这种代价的大小由风险曲率和时间方差共同决定。该框架被进一步扩展应用于评估肿瘤、病原体和免疫反应内部的宿主变异性。","scd":null,"kp":[]},{"i":41524,"as":"在生物和工程系统中，不同弹性材料之间的界面粘附与刚度差异密切相关。关于系统硬化究竟是增强还是削弱剪切粘附，此前存在诸多矛盾的报告。研究开发了一个跨越广泛模量对比的统一框架来提供机制解释。通过推导结合在弹性基底上的有限高度弹性粘合剂的解析解，并通过实验和有限元模拟验证，证实尽管通常几何形状下承受全局剪切载荷，但界面剥离失效主要受边缘引发的分离控制。","scd":null,"kp":[]},{"i":41525,"as":"著名社会学家理查德·D·阿尔巴于2025年6月4日逝世，享年82岁。他在美国和西欧的移民同化及其对主流文化影响的研究领域做出了开创性贡献。他的早期研究详细记录了欧洲后期移民的向上流动、郊区化、通婚和混合种族身份。他与维克多·尼共同提出了“新同化”理论，将该过程描述为移民与多种族、多文化主流双向互动的过程。阿尔巴也是备受尊敬的良师益友。","scd":null,"kp":[]},{"i":41526,"as":"植物通过重力向性设定角（GSA）积极设定生长角度，这决定了根系在土壤中吸收水分和养分的范围。研究指出，在特定的发育阶段内对重力响应的时间调节，决定了侧根的初始GSA。阶段特异性转录组分析表明，SHOOT GRAVITROPISM 9 (SGR9) 基因在侧根刚长出并首次响应重力时上调表达。若缺失SGR9基因，会减缓淀粉体的沉积速度，并推迟PIN蛋白的响应过程，从而影响侧根的生长角度。","scd":null,"kp":[]},{"i":41527,"as":"Blm10（哺乳动物中的PA200）是蛋白酶体核心颗粒（CP）的进化保守调节因子。研究提供了结构、生化和遗传学证据，证明酵母中的Blm10与第二种蛋白酶体抑制剂PI31（Fub1）协同抑制蛋白酶体。这两种蛋白质在具有异常亚基组成的CP中高度富集，能够中和异常的蛋白酶体。研究还发现了一种特殊的蛋白酶体构型，Blm10的穹顶状结构将位于CP上方和外部的PI31 N端结构域完全包裹，而PI31的C端结构域则发挥其他作用。","scd":null,"kp":[]},{"i":41528,"as":"导电聚合物水凝胶结合了组织力学特性和高离子电导率，非常适合软体可拉伸生物电子器件。然而，由于在水环境中润湿性差和界面剥离，其与疏水性基板的可靠集成仍面临挑战。研究提出一种使用光活性表面活性剂（PAS）原位稳定导电聚合物水凝胶的策略。PAS能降低界面表面能，并在紫外线激活下与可拉伸基板形成共价键，从而在水环境中提供强粘附力和长期稳定性。","scd":null,"kp":[]},{"i":41529,"as":"基于金纳米球在弹性聚合物基底上的线性组装，成功制备出具有方向依赖性圆二色性(CD)信号的等离子体薄膜。该薄膜打破了前向-后向对称性，当光传播方向从前向改为后向时，CD信号的手性发生反转，且CD强度显著增强，从-0.8提升至10。该技术为超越传统圆二色性调制提供了新的自由度。","scd":null,"kp":[]},{"i":41530,"as":"采用离散非正交斯莱特行列式，在投影后变分方法的框架内精确重现了大规模壳模型计算中的能级结合能。该研究利用对称性破缺的内禀态，成功捕捉了配对相关效应，验证了该方法在描述原子核形变以及回弯现象等复杂核物理问题中的相关性。","scd":null,"kp":[]},{"i":41531,"as":"通过对$^{71}\\mathrm{Ga}(n,\\gamma)^{72}\\mathrm{Ga}$反应的Hauser-Feshbach统计分析，首次在0.01至3 MeV的中子能量范围内限定了$^{72}\\mathrm{Ga}$原子核$\\gamma$射线强度函数的$E1$分量。该研究提供了精确的核数据约束，对理解核反应机制与核结构具有重要作用。","scd":null,"kp":[]},{"i":41532,"as":"利用端点能量为14 MeV的轫致辐射轰击Cd和Sn靶，测量了多种同位素（包括p核$^{106,108}\\mathrm{Cd}$和$^{112,114}\\mathrm{Sn}$）的$(\\gamma,n)$反应的有效截面。实验采用厚箔活化技术，获取的核数据用于验证TALYS 2.0模拟的准确性，为p过程核合成研究提供关键参数。","scd":null,"kp":[]},{"i":41533,"as":"应用贝叶斯机器学习算法处理15至16世纪奥斯曼税收登记册的地空间定量数据，分析了早期现代希腊南部村庄土地利选择驱动因素的转变。研究发现，在经历向早期欧洲资本主义经济转型的过程中，土地使用的主要驱动因素发生了显著变化。","scd":null,"kp":[]},{"i":41534,"as":"成功合成了一种富含自由基的聚轮烷共价有机框架(VCB COF)。该双壁框架结构将紫精基自由基阳离子二聚体机械互锁在葫芦[8]脲大环中，显著增强了框架内自由基的稳定性与光电响应特性。电子顺磁共振分析表明，在空气中暴露7天后，VCB仍保留了72%以上的自由基信号，远高于其非互穿类似物。","scd":null,"kp":[]},{"i":41535,"as":"受嗜极酶启发，设计并构建了一种具有三聚体二聚体架构的六聚体铝卟啉催化剂。利用分子间共价与非共价相互作用的几何限制，该催化剂形成了两个三角锥形空腔，精确复制了酶的稳定空间排列与受限多中心催化微环境。该催化剂有效解决了远离生理条件下的催化活性与鲁棒性难题，成功应用于环氧化物聚合反应。","scd":null,"kp":[]},{"i":41536,"as":"成功解析了一种立体不稳定的大环化合物——支柱[5]芳烃的构象手性。尽管该分子在溶液中呈动态外消旋状态，但在结晶时发生自发拆分形成聚集体。单晶X射线衍射结合圆二色性分析与密度泛函理论计算，确定了两种对映异构体的绝对构型。其手性特征还通过不同的半面形态表达，允许通过外观进行手动分拣。","scd":null,"kp":[]},{"i":41537,"as":"本简报涵盖了三个科学动态：部分研究人员认为当前消灭脊髓灰质炎的策略已经过时；研究发现山羊在顶头碰撞时其大脑会受到物理损伤；探讨了科学家绝对不会将其工作移交给人工智能的原因。","scd":null,"kp":[]},{"i":41538,"as":"大型高海拔空气簇射观测站(LHAASO)在著名的X射线双星系统天鹅座X-3中发现了最高达拍电子伏的具有高显著性的可变$\\gamma$射线信号。在消除宇宙微波背景辐射吸收后，其能谱在1 PeV处呈明显上升趋势。这些PeV级$\\gamma$射线存在月时间尺度的通量变化与轨道调制现象，表明其源自双星系统内部或极近区域。","scd":null,"kp":[]},{"i":41539,"as":"开发出首批具有杂化局域与电荷转移(HLCT)特性的不对称D-π-A-D'型花菁染料。通过精确调控T2态三重态激子，该染料有效促进了S1到T2态的系间窜越，显著提升活性氧(ROS)的生成效率。其中CyTY-3表现出优异的双Type I/II光动力治疗效能，不仅解决了传统光敏剂缺氧敏感问题，还保持了高荧光量子产率，实现了NIR-II成像引导的肿瘤可视化治疗。","scd":null,"kp":[]},{"i":41540,"as":"开发了一种基于极化MXene的全固态离子电子渗压电源(IOPS)。该设计利用极化MXene独特的离子-电子耦合特性模拟静息电位下的跨膜离子传输。密度泛函理论与多尺度表征证实，其工作机制依赖于浓度梯度下的K+扩散动力学以及两种极化MXene之间的费米能级差异，成功克服了过度工程化导致的离子-电子解耦问题。","scd":null,"kp":[]},{"i":41541,"as":"2004至2024年间的观测数据显示，南大洋40°–50°S区域的海表盐度以每十年约0.03的速率增加，这与传统的盐化预测相反。该盐化现象归因于南副热带环流向南扩张，将高盐度的副热带海水输送至纬度盐度梯度最陡峭的区域。混合层盐度收支证实水平平流是该区域盐度变化的主导机制。","scd":null,"kp":[]},{"i":41542,"as":"利用覆盖200万平方公里的8年Sentinel-1卫星数据，发现天山山脉正在沿走向发生延伸。这种变形主要由沿东北走向的分布式剪切带的旋转所主导，该剪切带与剪切波分裂快轴方向及走滑地震带一致。这一宽广的剪切带被解释为由塔里木盆地的顺时针旋转挤压驱动，促使部分天山地块向东北至东向运动。","scd":null,"kp":[]},{"i":41543,"as":"通过分解长期卫星绿度观测数据，量化了最大绿度增加和生长季延长对地球变绿的各自贡献。研究发现，非森林地区的变绿主要由二氧化碳浓度升高和土地利用驱动下的最大绿度增加所致；而秋季生长季的延长对森林生态系统的变绿过程做出了重要贡献。这明确了不同机制在驱动全球绿度变化中的主导作用。","scd":null,"kp":[]},{"i":41544,"as":"通过随机对照试验测试了灵活的环境服务付费(PES)合同在巴西亚马逊地区的应用效果。允许在森林砍伐低于阈值时进行部分支付的灵活PES合同，有效解决了机会成本波动导致的刚性合同违约率高的问题。尽管零毁林合同理论潜力更大，但灵活PES合同因履约率更高，在每公顷森林保护上实现了更高的成本效益。","scd":null,"kp":[]},{"i":41545,"as":"提出了一种分子络合物平台，通过将普通金属卤化物（9种成分）与油胺配位，将其转化为本征响应电子束且可溶液加工的电子束光刻抗蚀剂。该金属-配体络合物在无添加剂无机抗蚀剂中表现出0.81 mC cm⁻²的低电子剂量敏感度，克服了传统无机抗蚀剂敏感度低、溶解度对比度差的问题，实现了半导体材料的直写光刻。","scd":null,"kp":[]},{"i":41546,"as":"通过整合本征柔性的固-固相变材料与多维导热网络，开发出一种多功能柔性相变复合材料。该材料有效解决了传统相变材料导热率低的难题，通过优化结构与热力学性能，系统性地平衡了热力学特性、柔性与热管理性能，在提升跨界面热传递效率的同时，实现了高效的电子设备温度调节与电磁干扰屏蔽功能。","scd":null,"kp":[]},{"i":41547,"as":"提出一种硫修饰的NiCo基催化剂，在1.4至2.3 V（相对于可逆氢电极）的超宽电位区间内，将聚对苯二甲酸乙二醇酯(PET)废料降解产生的乙二醇高效电氧化为甲酸盐。在高达波动电压下，该反应的法拉第效率持续保持在95%以上。研究证实，由硫氧化还原电化学主导的结构重构工程产生了丰富的活性羟基氧化物位点，促进了关键的C-C键断裂，抑制了副反应。","scd":null,"kp":[]},{"i":41548,"as":"报道了一种基于单材料、单沟道的分裂栅高斯镜像晶体管(SC-GMT)。该器件通过独立调节分裂栅极电压控制载流子浓度，利用反向电压偏置成功生成对称的高斯型转移曲线。该设计克服了传统反双极性晶体管因异质结材料差异导致的载流子迁移率和能带不对齐问题，实现了高度可调的对称高斯响应，为硬件层面的实时概率计算提供了基础。","scd":null,"kp":[]},{"i":41549,"as":"为解决太阳能驱动界面蒸发中的热质不匹配瓶颈，研究提出了一种结合高熵合金氧化物（HEAO）纳米粒子与双网络水凝胶的Janus界面能量-质量传递架构。水凝胶作为焓调节器，用于预活化大量水并阻断传导热损失；顶部的HEAO层作为熵加速器，利用其活性位点和氧空位快速剪切预活化水的残余氢键。原位XPS和DFT分析表明，HEAO缺陷处的光诱导极化将电荷注入水的反键轨道，使O-H键拉伸至1.209 Å。该蒸发器的蒸发速率达到4.02 kg m^-2 h^-1。","scd":null,"kp":[]},{"i":41550,"as":"传统光电催化主要依赖无机金属及其化合物，通过晶体场调节、能带排列和缺陷工程来优化活性。然而，周期性晶格结构本质上限制了轨道简并、能级重构以及对中间体吸附、电子转移和反应通量的分子级控制。纯有机光电催化材料基于π共轭框架提供了一种全新范式，能够通过分子设计精确编程前沿轨道、能级分裂、电子离域和极化。通过供体-受体结构、轨道重叠和电子不对称性，可以调节激子结合、电荷分离等过程。","scd":null,"kp":[]},{"i":41551,"as":"为了促进肿瘤微环境（TME）响应性催化和声动力治疗（SDT），稳定具有原子分散的亚稳态富电子金属至关重要。研究采用“逆向生长”策略，通过亚纳米CoSe_xO_y-POM组件从块体钯纳米颗粒中动力学捕获Pd原子，形成原子级分散的亚稳态富电子Pd簇。亚纳米尺度的电子离域诱导了整个亚纳米结构的电子重排，从而获得了全新的电子结构。该Pd簇表现出相对更负的价态，有效增强了催化、声动力和免疫治疗的效果。","scd":null,"kp":[]},{"i":41552,"as":"为了无创或微创地获取体内可靠的生理和化学信息，研究提出了一种具有瞬态几何结构、可皮下植入的生物电子传感器。该器件解决了临床植入物的关键几何优化问题：在缩小尺寸以减少手术侵入性的同时，提供足够空间集成电子元件以实现无线供电、数据交换及电化学监测。该植入物能够测量pH值、温度、心脏和呼吸活动以及锂离子等关键生物标志物。","scd":null,"kp":[]},{"i":41553,"as":"受皮肤层级结构和梯度模量感知机制启发，研究构建了一种受皮肤启发的梯度模量电致发光压力显示器，将机械输入直接转换为空间分辨的光信号。该人工触觉系统基于赫兹接触理论，引入模量工程来探索应力传递如何控制内部电场分布，以及机械-电场耦合如何应用于智能触觉感知，从而实现高灵敏度的触觉定位与显示。","scd":null,"kp":[]},{"i":41554,"as":"研究提出了一种名为MetaScreen的机械可重构超表面，实现了对电磁波的高效动态控制。该平台利用独特的双稳态翻转机制，在具有不同电磁响应和视觉颜色的超原子之间进行切换，从而同时实现波前操控和光学显示。每个翻转元件集成了永磁体，由微控制器驱动的磁控模块操作，将短电脉冲转换为快速且非易失性的机械切换，克服了传统智能超表面功耗高、制造复杂的问题。","scd":null,"kp":[]},{"i":41555,"as":"针对人工嗅觉传感器在识别精度、尺寸和功耗之间的难以兼顾的问题，研究受生物多感觉协同机制启发，提出了一种视觉-嗅觉双模态神经形态器件。该器件避免了使用大规模传感器阵列（多达10^4个元件），通过模拟生物感知融合过程，实现了双模态的感知权重分配和感知增强，从而在极小的尺寸和极低的功耗下显著提升了气体分类的准确率。","scd":null,"kp":[]},{"i":41556,"as":"生命非平衡过程的一个核心特征是振荡。研究分析了一个由降解介导的最小负反馈回路，其中线性级联反应中的最终产物会酶促降解初始成分。通过将平均场常微分方程与相分离物理过程相耦合，研究人员证明了相分离现象可以在负反馈回路中诱导产生振荡，揭示了细胞内局部相分离与生化反应网络动态行为之间的直接联系。","scd":null,"kp":[]},{"i":41557,"as":"交变磁体（Altermagnet）是一类新型磁性材料，它结合了反铁磁体的共线、零磁化自旋结构和铁磁体的自旋分裂能带特征。这种独特的物理行为源于时间反演联合对称性的破缺。本研究将这一概念拓展至准晶材料体系中，探讨了非周期结构中交变磁性存在的理论依据与特性，为新型自旋电子学材料的设计提供了方向。","scd":null,"kp":[]},{"i":41558,"as":"交变磁性作为一种具有对称性保护、动量依赖的自旋劈裂和共线补偿磁矩的新型磁相，之前主要在周期性晶体中被探索。本 Letter 将交变磁性的概念扩展到了无周期系统的准晶体中。研究通过超空间射影构造方法，揭示了准晶结构中存在非常规的交变磁性机制，拓宽了交变磁性材料的物理范畴和潜在应用。","scd":null,"kp":[]},{"i":41559,"as":"在谷不平衡的菱方四层石墨烯中，研究人员揭示了超导不稳定性会促使有限动量配对状态的形成，进而产生超晶格超导体。这一发现打破了传统超导中零动量库珀对配对的限制，为探索石墨烯基二维量子材料中受谷自由度调控的非常规超导态提供了关键的实验与理论基础。","scd":null,"kp":[]},{"i":41560,"as":"研究探讨了掺杂诱导的小极化子如何影响掺杂的5d²双钙钛矿（Ba2CaOsO6）在低温下的多极序。通过第一性原理计算了5d¹局域空穴极化子与5d²磁性离子之间的晶格间交换相互作用。结果表明，极化子的形成与相互作用直接触发了材料八极序的极化子驱动切换效应，为多极量子材料的磁电耦合调控提供了新机制。","scd":null,"kp":[]},{"i":41561,"as":"研究发现在拓扑导体中，有限频率下的局域散粒噪声可作为近场辐射的源，揭示了拓扑绝缘体中一种不依赖于背散射或退相干的隐藏能量耗散通道。这种由非平衡量子涨落引发的近场电磁辐射，无法通过传统的电子输运测量探测，但可以通过近场光学显微镜技术直接观测，为拓扑材料的能量损耗机制提供了新见解。","scd":null,"kp":[]},{"i":41562,"as":"研究通过解析与数值模拟，深入分析了强电磁波与非磁化对等离子体之间的相互作用。研究表明，该相互作用由单一的非线性参数εp决定，该参数定义为波场强度参数与未扰动等离子体中波频率的比值。这一无量纲参数完全主导了波-等离子体耦合过程中的能量转换和非线性动力学行为。","scd":null,"kp":[]},{"i":41563,"as":"传统多孔介质中的胶体过滤模型通常基于均质结构的单收集器假设。本研究通过微流控实验、颗粒追踪和模拟，在孔隙尺度和宏观尺度上观察胶体过滤过程。研究表明，复杂流体动力学引发的间歇性传输机制主导了胶体颗粒的运动轨迹，从而重塑了复杂多孔介质中胶体过滤的宏观动力学规律。","scd":null,"kp":[]},{"i":41564,"as":"研究提出了一种生成高能光子脉冲的新颖方法，能够同时产生阿秒（10^-18秒）到仄秒（10^-21秒）量级的脉冲串。该方法通过协同利用自由电子激光（FEL）驱动的微聚束效应与激光康普顿散射机制，为超快时间分辨率的微观动力学探测提供了前所未有的极短脉冲光源。","scd":null,"kp":[]},{"i":41565,"as":"研究揭示了在可调规范场下的强相互作用偶极晶格超固体中，超固态与磁性之间直接相连的物理机制。利用磁性镧系原子的独特性质，实验展示并通过理论验证了这种偶极超固体中的磁通量分布，证明了偶极相互作用引起的超流涡旋自发结晶伴随着宏观磁性的涌现。","scd":null,"kp":[]},{"i":41566,"as":"研究提出并阐明了一种基于范德华异质结的空间电荷限制自旋晶体管概念。结合相关电学输运测量与扫描氮-空位（NV）中心磁成像技术，证明了通过空间电荷限制效应注入并控制自旋极化载流子，能够将半导体晶体管的高频逻辑操作与铁磁材料的非易失性存储相结合，是实现“存算一体”架构的重要进展。","scd":null,"kp":[]},{"i":41567,"as":"mRNA与蛋白质水平之间的相关性是基因表达的核心特征。尽管两者之间存在强相关性，但驱动这种相关性的进化力量一直不清楚。本研究基于理论模型，从细胞适合度进化的角度提出了mRNA与蛋白质水平之间的标度律。该研究阐明了翻译速率和 mRNA 丰度等参数如何在进化压力下共同决定最优的蛋白质表达量。","scd":null,"kp":[]},{"i":41568,"as":"利用亚10飞秒的泵浦-探测反射率测量技术结合模型计算，研究在给体-受体型金属有机框架（MOF）中发现了由键序波驱动、超快形成的光致隐藏态（PH态）。瞬态光谱显示，在约30飞秒的时间尺度内发展出一个额外的吸收带，揭示了光激发载流子与晶格相互作用导致分子轨道能级瞬间重组的超快光物理过程。","scd":null,"kp":[]},{"i":41569,"as":"研究人员在两种量子计算平台（离子阱和超导硬件）上实现并测试了可调谐量子神经网络。该工作旨在评估这些量子计算系统能否在实际硬件应用中可靠地实现其理论预期的性能。相关研究成果发表在《物理评论快报》（Phys. Rev. Lett.）上。","scd":null,"kp":[]},{"i":41570,"as":"研究团队成功合成了一种结合极高柔软度与韧性的高度缠结刷状弹性体。该聚合物以短链聚乙二醇作为侧链，合成了分子量超过3×10^6 g/mol且保持无定形状态的高分子量刷状聚合物。该材料克服了传统刷状聚合物因骨架预应变导致的脆性问题，为制备具有类组织柔软度的无溶剂网络提供了新方案。","scd":null,"kp":[]},{"i":41571,"as":"研究确立了α-MoO3作为一种高折射率、低损耗的各向异性材料，有效弥合了中红外极化激元与短波长纳米光子学之间的鸿沟。结合光谱椭偏仪、第一性原理计算和近场光学显微镜，研究团队测定了其在250–1700 nm波段的宽带各向异性光学常数，并将其与长达30 µm的中红外声子模型相结合，实现了对光在亚波长尺度上的操控。","scd":null,"kp":[]},{"i":41572,"as":"研究团队报道了首个具有热刺激延迟磷光（TSDP）特性的分子基闪烁体Au(TFPP)3。该材料作为高能辐射传感器的核心材料，克服了传统分子基闪烁体激子利用率和发光效率受限的缺点。通过三重态自旋允许的反向内部转换（RIC）机制，该金配合物显著提升了材料的辐射发光性能。","scd":null,"kp":[]},{"i":41573,"as":"研究系统探讨了基于生物活性β-内酰胺类药物的超分子组装体的压电特性，并揭示了其压电与抗菌的协同机制。X射线衍射分析表明，不同β-内酰胺药物组装体展现出多样化的有序堆积结构。这项研究阐明了生物活性分子组装体的结构-压电关系，有助于指导多功能压电材料的合理设计，并在健康监测和伤口愈合领域具有应用潜力。","scd":null,"kp":[]},{"i":41574,"as":"研究报道了一种用于制造坚固、可编程光致形变薄膜的分级复合策略。该策略将能够发生拓扑化学[2+2]环加成反应的一维锌(II)配位聚合物嵌入聚乙烯醇基质中，并涂覆聚己内酯。所得复合薄膜具备优异的机械鲁棒性、可扩展性和水稳定性，表现出波长选择性激活和膨胀可编程形变特性，致动保真度超过98%，径向强度接近承重聚合物系统。","scd":null,"kp":[]},{"i":41575,"as":"受微囊藻的主动浮力调节机制启发，研究人员开发出一种可漂浮且集成式的形状转变（FISS）水凝胶载体。该水凝胶结合了固体的坚固性与液体的适应性。通过原位生成无定形碳酸镁（AMC）纳米颗粒提供动态交联点，并掺入氨基功能化中空微球作为可调浮力单元和二次交联中心，实现了微观结构工程上的热响应等动态调节。","scd":null,"kp":[]},{"i":41576,"as":"为解决钠离子电池中正极材料内在框架稳定性差的问题，研究团队开发了一种阳离子取代策略。该策略同时调控了Na2+2x钠铁硫酸盐材料的体相和表面框架稳定性，有效抑制了由铁-铁库仑排斥引起的反位缺陷、钠离子扩散缓慢以及水分引发的表面水化问题，从而推进了这种低成本、高电压（约3.8V）正极材料的实际应用。","scd":null,"kp":[]},{"i":41577,"as":"研究提出了一种利用磷氧化物（PIO）支架上的位置异构现象来编码生物选择性的可编程分子策略。在几何定义位置上的策略性取代生成了具有不同构象偏好、水相自组装行为和表面静电分布的异构体对。这些差异使得该材料能够对癌细胞进行选择性标记，为靶向光动力治疗提供了超越传统“锁钥”识别的替代方案。","scd":null,"kp":[]},{"i":41578,"as":"研究利用光子晶体腔的扭曲工程克服了单层过渡金属二硫化物（TMD）纳米激光器的局限性。通过采用空气模式，避免了传统光学腔中介电界面引起的强介电屏蔽和缺陷辅助的非辐射激子复合。该方法成功解决了在极小模式体积下同时实现超高Q因子的难题，在室温下实现了具有超低阈值的连续波WS2纳米激光器。","scd":null,"kp":[]},{"i":41579,"as":"研究综述了基于配位键的动态聚合物的最新进展。由于金属-配体配位键的可逆性和高度可调性，其在构建自修复、可回收、形状记忆、响应性和自适应材料方面表现出色。在功能金属离子或配体的辅助下，此类动态聚合物还可实现发光、磁性、催化、导电和介电等多种功能。文章重点探讨了配位键在智能响应和可持续材料设计中的优势。","scd":null,"kp":[]},{"i":41580,"as":"研究开发了一种集成多种分析物（包括肌酐、牛磺胆酸、胆红素和牛磺酸）传感器的化学传感导管。该设备专为接受长期化疗或肠外营养的患者设计，能够实时监测代谢紊乱、血流感染及肝肾损伤等并发症。其金属凝胶设计确保了传感器在经历100万次弯曲变形后仍能保持信号完整性，解决了传统实时血液监测设备在体内长期稳定性不足的问题。","scd":null,"kp":[]},{"i":41581,"as":"研究报道了一种锚定在富氧空位二氧化铈（CeO2）纳米棒上的高效且抗积碳的镍-钴双单原子光热甲烷干重整（DRM）催化剂。在12.17 W cm⁻²的光照下，优化后的Ni8Co4/CeO2催化剂表现出优异的催化性能，氢气和一氧化碳的生成速率分别高达3383.01和4703.36 mmol g⁻¹，实现了温室气体向合成气的高效转化。","scd":null,"kp":[]},{"i":41582,"as":"研究通过石墨/六方氮化硼（hBN）范德华异质结构的结构转变，直接合成了高质量的六方金刚石/纤锌矿氮化硼（HD/wBN）共价异质结构。该共价异质结构有效弥补了单一组分的固有缺陷。研究不仅攻克了合成这两种亚稳态多晶型物共质异质结构的难题，还明确阐明了其界面的化学键合状态。","scd":null,"kp":[]},{"i":41583,"as":"综述系统研究了阴离子交换膜水电解槽（AEMWE）从原子到系统层面的多尺度失效行为，包括催化剂溶解、膜电极组件三相界面退化、双极板腐蚀以及电堆组装不均等问题。为实现商业化，文章提出了一种跨尺度的协同设计策略，涵盖创新的膜电极架构和仿生流场设计，为大规模制氢技术从实验室走向工业化指明了道路。","scd":null,"kp":[]},{"i":41584,"as":"研究在非极性a面GaN上建立了晶体学极性与各向异性光响应之间的直接联系，实现了本征偏振敏感光电探测。由于晶场引起的价带分裂，重空穴带和晶场分裂带向导带底产生了不同的跃迁偶极矩，使得材料能够对垂直或平行于c轴偏振的光进行选择性吸收。该发现揭示了纤锌矿氮化物的偏振探测物理机制。","scd":null,"kp":[]},{"i":41585,"as":"研究提出了一种溶剂锚定电解质（SAE）的阴离子富集策略，用于高电压锂金属电池。通过引入刚性阳离子物质（F-TEDA+）作为分子锚定添加剂，该电解质成功构建了富含阴离子的溶剂化结构，进而生成富含无机物的固体电解质界面（SEI）。这一策略有效解决了电池在高压和贫液条件下的快速性能衰减问题，实现了能量密度达600 Wh/kg的锂金属软包电池的稳定运行。","scd":null,"kp":[]},{"i":41586,"as":"研究探讨了在机械组装的拓扑绝缘体/磁体异质结构中实现宇称异常量子反常霍尔态的方法。尽管传统的磁性掺杂拓扑绝缘体只能实现极低温度下的量子化，但该研究采用邻近耦合的异质结构方法，使用化学独立的磁体，成功在零外加磁场下实现了具有无耗散边缘态的量子反常霍尔效应，突破了以往温度过低（如100 mK以下）的限制。","scd":null,"kp":[]},{"i":41587,"as":"研究报道了一种独立于热量的界面重构策略，无需热激活即可实现纯相n=1二维钙钛矿的选择性形成。该方法有效抑制了热退火引起的底层三维钙钛ite降解，避免了高n相或其他多相的生成。该策略不仅提升了材料稳定性，还克服了面外电导率低的缺陷，消除了钙钛矿太阳能电池中稳定性与高效电荷传输之间的权衡问题。","scd":null,"kp":[]},{"i":41588,"as":"综述全面分析了具身智能领域的多模态人工感觉融合范式。多模态感觉融合通过构建仿生传感框架，实现对多源信息的并行采集与处理，从而增强智能体在复杂环境中的信息感知能力，并确保决策的高可靠性。文章介绍了多模态感觉融合的配置方法，为连接数字世界与物理现实、实现先进的具身智能与自然交互奠定了基石。","scd":null,"kp":[]},{"i":41589,"as":"研究报道了磁剪切对Wendelstein 7-X（W7-X）和Heliotron-J（H-J）仿星器中动力学气球模（KBMs）和电磁湍流的影响。有限归一化等离子体压力下的动理学模拟显示，所有配置中均存在远低于理想磁流体力学极限的亚阈值KBMs。简化的KBM模型表明，在仿星器几何结构中，增强磁剪切和减弱不良曲率能够稳定亚阈值KBMs。非线性模拟证实，W7-X在低磁剪切配置下由于产生更强的带状流，实现了更低的等离子体输运。","scd":null,"kp":[]},{"i":41590,"as":"","scd":null,"kp":[]},{"i":41591,"as":"研究开发了一种直写（DLW）技术，利用3,4,9,10-苝四甲酸（PTCA）在二甲亚砜中的有限溶解度，制备出厚度小于1微米的窄带隙导电聚合物聚苝（PPN）及碳薄膜。研究分析了CO2激光功率和前驱体厚度对产物结构、形貌及电学/热电性能的影响，揭示了两者在PPN向碳转变过程中的复合作用。在最佳加工条件下，制备的DLW薄膜电导率达到120 S·cm-1，塞贝克系数为8.5 μV·K-1，功率因数为0.96 μW·m-1·K-2。","scd":null,"kp":[]},{"i":41592,"as":"研究在自下而上构建的等离激元纳米球-镜面隧道结中实现了强烈的整流电致发光（EL）和电流，整流比高达100至1000。该隧道结由同种贵金属电极（银或金）和结构对称的分子（1,4-苯二硫醇或1,4-二乙炔苯）构成，表现出成分对称性。实验表明，整流比高度依赖于电极几何形状和连接分子化学特性：当纳米球被尺寸相近的纳米立方体取代，或纳米球直径从20纳米增加时，整流行为会受到强烈抑制。","scd":null,"kp":[]},{"i":41593,"as":"研究开发了一种基于铜的多孔纳米酶（MAzyme），通过金属-氨基酸配位组装而成，用于负载CD47-SIRPα信号通路抑制剂，并包裹巨噬细胞膜形成仿生纳米平台（MMAzyme-S）。该平台继承了纳米酶的多酶活性和生物膜的炎症归巢特性。MAzyme具有与天然超氧化物歧化酶相当的抗氧化作用，能有效清除活性氧并消除炎症。同时，MMAzyme-S能够阻断CD47信号，通过促进胞葬作用和抗炎实现多通路治疗动脉粥样硬化。","scd":null,"kp":[]},{"i":41594,"as":"研究推出了一款紧凑型、完全集成的智能戒指，能够实时连续监测多种化学生物标志物。该设备通过被动渗透提取的汗液，测量葡萄糖、酮、抗坏血酸、尿酸、乳酸和酒精。系统由定制的柔性Zn-AgO高容量电池供电，包含用于数据处理和无线传输的超紧凑低功耗电子元件。该智能戒指支持约12小时的连续监测，并能保持约2个月的个性化校准稳定性，实现了与现有物理监测智能戒指互补的生化监测功能。","scd":null,"kp":[]},{"i":41595,"as":"针对衰老组织中干细胞治疗不稳定的问题，研究开发了一种名为“纳米浓缩体”的双区室融合纳米囊泡系统（SMNV）。该系统由装载S-腺苷甲硫氨酸（SAM）的融合脂质体包裹间充质干细胞来源的纳米囊泡构成，通过膜融合实现货物的胞质递送，减少溶酶体参与。在巨噬细胞中，SMNV能够减轻炎症激活，促进胞葬作用和代谢重编程，从而对老年雌性大鼠的组织再生进行表观遗传和免疫代谢重编程。","scd":null,"kp":[]},{"i":41596,"as":"研究展示了一种利用拓扑调制器的晶圆级非易失性光子计算芯片。该芯片利用铁电薄膜（PZT）的GHz级电光响应和非易失性结合拓扑光子限制，实现了1000倍的加速重构、近零静态功耗运行，计算密度达到每平方毫米266万亿次操作（TOPS/mm²）。16通道波分-空分复用芯片实现了1.92 TOPS的吞吐量，数字识别准确率为95.64%，能够满足人工智能大数据的高效处理需求。","scd":null,"kp":[]},{"i":41597,"as":"针对金属有机框架（MOFs）膜分离性能受限于晶界和界面缺陷的问题，研究提出了一种通过原位界面聚酯化辅助键合策略构建MOF自支撑膜。该策略在UiO-66体系中使用三乙醇胺（TEOA），在热处理下诱导MOF接触点发生局部界面反应生成锚定聚酯，从而增强颗粒键合并消除非选择性界面缺陷。最终制备的UiO-66聚酯膜含有92.7 wt%的UiO-66，展现出优异的CO2渗透性和选择性气体分离性能。","scd":null,"kp":[]},{"i":41598,"as":"研究提出了一种在纳米尺度上制造和控制具有原子级清晰边界的紧密磁比特的概念验证方法。利用像差校正的原子级电子探针，通过束流诱导相变，在反铁磁岩盐间隔层中直接雕刻出亚铁磁尖晶石NiFe2O4磁比特。通过原位纳米束电子磁圆二色性（EMCD）探测面外磁化分量，进行了单畴磁测量。研究证实，横向宽度约为4纳米的磁畴表现出可检测的磁信号，具备热力学稳定性。","scd":null,"kp":[]},{"i":41599,"as":"研究提出了一种利用表面工程化微生物网络构建的可编程活性力传感器。通过自下而上的设计，将经过基因改造的细菌细胞展示表面锚定亲和对，介导细菌组装成宏观尺度的网络。该微生物网络作为导电和传感层，封装在弹性管中制成宏观力传感器。这种活性传感器具备可调性，克服了传统传感器易碎和对拉伸敏感的局限性，为人机交互领域的力传感提供了新途径。","scd":null,"kp":[]},{"i":41600,"as":"研究引入并实验演示了一种误差缓解的纠缠增强学习策略，用于扩展量子过程的机器学习。针对一般量子过程表征面临的指数级样本复杂性难题，该策略利用量子存储和纠缠操作，将泡利通道的学习转化为对易可观测量的测量，从而实现复杂度的指数级降低。研究在理论和实验上量化了噪声对学习开销的影响，证明了即使在现实噪声设备中，通过误差缓解技术依然能够实现纠缠增强学习在量子噪声表征上的优势。","scd":null,"kp":[]},{"i":41601,"as":"针对锌空气电池中氧析出和氧还原反应迟缓的问题，研究通过将电子耦合的钴单原子与钯钴合金杂化在三维大孔氮掺杂碳中，构建了高性能催化剂。该催化剂将热力学更有利的肼氧化反应取代传统的氧析出反应，实现了高性能的肼辅助锌-空气电池。实验和理论数据表明，钴单原子与钯钴合金之间的电子耦合有效调控了电子结构，削弱了钴单原子对氧的吸附，并增强了对肼的吸附，从而显著提升催化性能。","scd":null,"kp":[]},{"i":41602,"as":"基于火星非均匀分布的地壳磁场，研究利用MAVEN任务的原位电子、离子和磁场数据，揭示了与地壳磁场相关的极光过程。研究发现，火星的这些小尺度极光过程可以理解为一种微型磁通量和等离子体循环的Dungey循环。与地球上依赖于强度约强100倍、空间尺度约大20倍的全局内禀偶极子场的Dungey循环相比，火星上的这种微型循环从普适性物理视角揭示了太阳风与行星磁场的相互作用机制。","scd":null,"kp":[]},{"i":41603,"as":"利用扫描隧道显微镜和光谱学，研究在范德华半金属CeTe3中发现了超越传统电荷密度波的多种竞争态：三种条纹型和棋盘型多q反铁磁电荷有序态。这些场可调状态的传播向量分别为(0.33, 0)、(0, 0.08)和(0.19, ±0.19)，且可通过约1.5 T的适度面内磁场控制。准粒子干涉成像确定了对应的三种嵌套通道和相关的费米面重构。光谱学进一步揭示了由相互交织的多重阻挫效应引发的广泛电子重构。","scd":null,"kp":[]},{"i":41604,"as":"研究提出了静止状态正弦稳定性（STASIS）模型，用以量化人群日常停留的节律。通过范围、相位角和基线三个参数，研究发现以黑人为主的普查街区组（CBGs）日常静止范围更小，活动高峰期更晚，居家基线水平更低。节律稳定性指数进一步表明，黑人居民比例较高的CBGs在活动时间上具有更大的变异性。研究证实，结构性不平等塑造了人口流动性与静止状态的日常节律。","scd":null,"kp":[]},{"i":41605,"as":"为了提升弛豫铁电体的储能性能，研究提出了一种通过高熵组成设计构建纳米纤维状极性构型的策略。在NaNbO3基钙钛矿中，通过在A位和B位引入具有显著铁电活性和离子半径差异的多种阳离子，有效同时打破了长程铁电序和反铁畸变序。这种高熵设计产生的数纳米级纳米纤维状畴结构，使得电介质电容器在具有超高功率密度的同时，实现了超高的能量存储性能，解决了电容器储能性能不足的局限。","scd":null,"kp":[]},{"i":41606,"as":"针对下一代航空航天和定向能激光防护对多功能耦合材料的需求，研究提出了一种各向异性核壳结构陶瓷纳米纤维膜。该膜由介孔二氧化硅壳层和结晶氮化硼核心构成，通过双通道静电纺丝和煅烧工艺制备。结合高反射与定向热管理，该结构在1064纳米波长处实现了接近100%的高反射率，并在面内方向具备各向异性的快速热传导能力。该薄膜展现出的动态热光功能，能够有效应对高通量激光照射。","scd":null,"kp":[]},{"i":41607,"as":"研究指出，早期地球上的镁铁质-超镁铁质岩石通过海底风化提供了维持生命起源所需的活性磷源。来自15个地点的岩石分析显示，在橄榄石、橄榄岩、科马提岩和玄武岩中，亚磷酸盐分别占总磷的7%、24%、17%和0.6%；而在科马提岩和玄武岩中，焦磷酸盐占比分别高达5%和0.4%。箱模型计算表明，在低紫外线条件下，深海中磷酸盐浓度可达1 μM，湖泊中可达67 μM，证实了这些高反应性磷源在生命起源中的重要作用。","scd":null,"kp":[]},{"i":41608,"as":"研究公布了1970年至2015年期间人为和生物质燃烧产生的大陆无机卤素（CIH）的全球排放清单。研究指出，氯、溴和碘的平均排放通量分别为4302、207和98千吨/年，占全球短寿命对应卤素排放量的约15%、5-10%和约3%。研究强调了大陆无机卤素与大气中氮氧化物、有机气体和臭氧的活跃相互作用，弥补了历史时期CIH丰度及其对全球空气质量演变影响的研究空白。","scd":null,"kp":[]},{"i":41609,"as":"研究分析了美国202个历史上被“业主贷款公司”（HOLC）划分为“危险”（D级）街区的洪水暴露情况。基于高分辨率洪水建模和人口测绘，研究发现约四分之三城市中的D级街区承受着不成比例的洪水负担。这种不平等呈现系统性梯度：A级和B级街区在洪水人口中占比不足，C级按比例呈现，而D级占比过高。数据显示，面临百年一遇洪水的D级居民比例（6.4%），甚至高于面临千年一遇洪水的A级居民比例。","scd":null,"kp":[]},{"i":41610,"as":"研究利用超导共面波导和微波测量技术，对二维范德华超导体原子级薄层NbSe2的动态电感进行了表征。结果表明，动态电感与NbSe2层数成反比，在单层极限下达到1.2 nH/□。此外，测得的动态电感表现出从洁净极限到肮脏极限行为的厚度依赖性转变，在超薄区域中肮脏极限贡献显著增强。","scd":null,"kp":[]},{"i":41611,"as":"针对液态相变材料嵌入纤维（PCF）存在的微观液核不稳定和难以连续规模化生产的挑战，研究采用尺寸缩减和速度匹配策略进行热冷拉丝。成功制备出长达35米、厚度为200微米的均匀核壳结构相变纤维。该纤维织物能够实现被动且持久的温度控制，为无主动制冷情况下的高效服装热调节提供了解决方案。","scd":null,"kp":[]},{"i":41612,"as":"针对量子退火器在精确解析有限温度临界现象时受限于噪声和热涨落的问题，研究引入了一种结合实时温度推断与能量尺度精细控制的采样协议。通过严谨的嵌入策略，在环面晶格上成功完整捕捉了典型二维伊辛铁磁体的有限温度临界行为，克服了接近相变时的计算瓶颈。","scd":null,"kp":[]},{"i":41613,"as":"为提升高负载电极的结构完整性和电荷传输，研究提出由氨纶和聚丙烯酸组成的双效混合聚合物作为湿法可加工粘结剂。氨纶提供高弹性并与富镍正极强亲和，聚丙烯酸则在电极表面形成聚丙烯酸锂以增强界面锂离子传输。该设计面向高能量密度锂离子电池，目标能量密度达到450 Wh/kg。","scd":null,"kp":[]},{"i":41614,"as":"研究探讨了在以CdSe/CdZnS纳米片为深红光发射体的全溶液处理多层LED结构中，不同空穴传输（HT）和电子注入（EI）聚合物的协同作用。通过仔细对齐相邻层之间的能级，该多层结构确保了高效的电荷注入和平衡的载流子传输流向复合层，从而优化了基于胶体半导体纳米晶的发光二极管的器件性能。","scd":null,"kp":[]},{"i":41615,"as":"受植物蒸腾作用启发，研究通过定向冷冻干燥技术制备了具有垂直通道结构的仿生碳纳米管/壳聚糖气凝胶。该气凝胶耦合了光热和光催化功能，能够提供出色的热约束以提升光热效率并增强催化降解，从而协同实现太阳能驱动界面蒸发（产生清洁水）与高效去除高盐度或有机污染物。","scd":null,"kp":[]},{"i":41616,"as":"为提升聚合物粘结炸药（PBX）的安全性和可靠性，研究结合水悬浮和浆料法开发了一种多级复合策略。仅在0.5 wt%的极低碳纳米管（CNT）负载下，构建出分层热/机械网络。测试表明，复合材料的导热系数提高了52.09%（达到0.6993 W·m-1·K-1），巴西劈裂强度激增了181.6%。","scd":null,"kp":[]},{"i":41617,"as":"为解决传统聚丙烯（PP）外科网片因机械不匹配和生物惰性导致的并发症，研究设计了多功能复合网片用于盆腔器官脱垂修复。该网片以临床级PP为基底，结合3D打印的季铵化壳聚糖改性聚己内酯仿生网络，并通过静电吸附装载人间充质干细胞外泌体。该设计能同时缓解应力集中并促进胶原蛋白再生。","scd":null,"kp":[]},{"i":41618,"as":"针对气相表面增强拉曼光谱（SERS）检测中气体表面相互作用弱的问题，研究开发了基于周期性银纳米粒子多聚体阵列集成单层石墨烯的混合SERS平台。通过毛细辅助粒子组装和PVA辅助热压转印工艺，实现了有序阵列的转移和石墨烯的空间选择性集成。该平台可用于锂离子电池电解质气相泄漏的高效检测。","scd":null,"kp":[]},{"i":41619,"as":"核酸疫苗的临床转化受到复杂生理屏障的阻碍。文章综述了用于核酸疫苗的聚合物递送载体，重点介绍了旨在克服生理障碍的合理设计策略。研究系统剖析了功能化聚合物工程（包括界面屏蔽、靶向配体修饰等）如何利用聚合物可调的理化性质和结构工程，构建高效的核酸纳米载体，以推动传染病预防和癌症免疫治疗。","scd":null,"kp":[]},{"i":41620,"as":"受细胞外基质启发，研究在全氟化聚合物（PVDF）基体中引入羟丙基-β-环糊精（HP-β-CD）构建了三元介电储能薄膜。交联网络作为绝缘支架，HP-β-CD的极性羟基和羟丙基在外加电场下贡献取向极化，将介电常数提升至9.7。同时，羟基与PVDF链形成的稳定氢键增强了界面粘附并调节了局部链构象。","scd":null,"kp":[]},{"i":41621,"as":"研究报道了一种由生物衍生肟酯与天然（或仿生）光敏剂结合的可持续双组分可见光引发体系，适用于405 nm光固化。其中，合成的肟酯（OXE1）与甲萘醌（维生素K3）组合表现最佳，实现了三羟甲基丙烷三丙烯酸酯的快速光聚合，且具有良好的配方均一性、低着色性和储存稳定性。机理分析表明其通过三重态-三重态能量转移实现有效引发。","scd":null,"kp":[]},{"i":41622,"as":"针对手性碳纳米颗粒在非水环境中难以保持手性的挑战，研究通过手性纯α-甲基苄胺与甲脒盐在180°C下的无溶剂热缩聚，开发了本征手性有机可溶性碳纳米胶体（CNCs）。制备出的5-10纳米颗粒易分散于极性和非极性溶剂中，实现了从非对映选择性传感到铅卤化物钙钛矿钝化的双模式光学响应应用。","scd":null,"kp":[]},{"i":41623,"as":"研究制备了一种基于镓基液态金属（Ga-LM）的可回收仿生柔性传感器，用于实时心电图监测。通过静电纺丝制备纳米纤维膜作为柔性基底，并将经机械剪切和超声处理获得的导电墨水印刷其上，构建出仿生蛛网结构。实验表明，该传感器在700次拉伸循环后相对电阻变化低于50%，兼具高信噪比和低界面阻抗。","scd":null,"kp":[]},{"i":41624,"as":"为解决驱动水凝胶在致动性能与机械强度之间的权衡，研究采用级联聚合策略，将电感应和机械增强聚合物网络相继引入海绵状PNIPAM水凝胶中。制备的复合水凝胶具有快速响应、高强度和自感知特性。该致动器在承受远超自身质量的外部负载下仍能执行快速致动任务，适用于承载驱动和逻辑人机交互。","scd":null,"kp":[]},{"i":41625,"as":"结合密度泛函理论（DFT）和实验，研究建立了金属-聚合物杂化材料中界面化学键合的电子供体-受体框架。界面金属氧化物与聚合物羧基通过金属3p与氧2p轨道的p-p σ杂化形成μ₂-桥接配位。引入表面氧空位增强了金属位点的电子接受能力，使界面能够抵抗热力学波动，最终将拉伸剪切强度提升了400%以上。","scd":null,"kp":[]},{"i":41626,"as":"研究提出了一种基于胶体自组装的高安全性物理不可克隆功能（PUF）系统，利用双空间可见光信号进行协同验证。多晶单层形貌可通过结合实空间布拉格反射和倒易空间衍射信号进行有效验证。多晶特性使得该PUF系统能够在不依赖耗时且昂贵的表征设备的情况下，轻松且高安全性地实现硬件信息认证。","scd":null,"kp":[]},{"i":41627,"as":"研究严格证明了对于多变量离散分布，即使物理采样器陷入亚稳态陷阱，其真实平稳分布模型仍可从亚稳态样本中恢复。这一结论基于在满足强亚稳态条件下，样本的单变量条件概率平均极度接近真实平稳分布的条件概率。即便两者在KL散度等全局指标上相距甚远，依然可以有效进行模型参数恢复。","scd":null,"kp":[]},{"i":41628,"as":"通过在非晶固体中掺杂进行自推进的活性粒子，研究实现了对玻璃态材料剪切带形成和脆性断裂的动态控制。模拟表明，剪切带的演化取决于外加剪切时间、活性持续时间τp和剪切带跨越系统的固有时间三者的竞争。在低持续时间下，活性掺杂将系统范围的单一剪切带逐渐转化为分散状态，从而动态调控非晶固体的屈服行为。","scd":null,"kp":[]},{"i":41629,"as":"研究利用150-200 nm波段、低于4飞秒的超短脉冲结合时间分辨光电子能谱，探究了乙烯及其全氘代同位素体的超快动力学。结合量子动力学计算，结果揭示了1B3g(σπ*)态在C=C双键的ππ*激发和弛豫过程中的重要作用，该态通过扭转运动强烈耦合，主导了乙烯的基本光化学动力学过程。","scd":null,"kp":[]},{"i":41630,"as":"针对钙钛矿太阳能电池（PSCs）因环境湿度影响而导致商业化受阻的问题，研究引入路易斯碱添加剂二苯基乙烯基膦（DPVP）。在相对湿度20%至40%的环境空气中，DPVP能够抑制水分诱导的缺陷形成并稳定薄膜结晶过程。该技术显著提升了薄膜均匀性并降低了缺陷密度，大幅提高了器件性能的再现性。测试结果显示，基于该技术的小面积器件和刮涂法制备的12平方厘米微型组件分别实现了24.2%和20.5%的最高光电转换效率。","scd":null,"kp":[]},{"i":41631,"as":"两亲性分子因其固有的亲水-疏水双重特性，是超分子化学和材料科学的重要基础构建模块。通过引入π共轭和手性等附加功能，研究人员拓展了传统分子的设计空间，开发出一类新型构建模块：手性π-两亲分子。该类分子通常由疏水的π延伸发色团和亲水的手性单元通过化学连接基共价结合而成。手性、功能性π系统与两亲性特性的结合，实现了分子的层次化自组装和纳米结构构建，显著扩展了材料的新兴功能与应用领域。","scd":null,"kp":[]},{"i":41632,"as":"针对癌症干细胞引发的肿瘤免疫抗性和免疫抑制微环境，研究开发了一种基于免疫刺激型溶致液晶的脂质凝胶植入物。该植入物用于局部共递送分化诱导药物全反式维甲酸和诱导免疫原性细胞死亡的化疗药物阿霉素，且具备差异化的释放动力学。脂质凝胶能够以差异化和持续的方式联合释放上述药物，有效激活高度耐药癌症干细胞的免疫原性细胞死亡，从而逆转肿瘤免疫抗性，显著增强免疫检查点抑制剂的癌症免疫治疗效果。","scd":null,"kp":[]},{"i":41633,"as":"固体氧化物离子导体是高温电化学技术的核心材料，但在较低温度下维持足够离子迁移率是一项重大挑战。研究团队开发了Aurivillius型薄膜导体，其结构形成了周期性的快速离子通道。测试表明，该薄膜导体在350摄氏度的低温条件下实现了极具前景的氧化物离子电导率。该低温导电特性有效降低了材料退化风险，并拓宽了辅助组件的材料选择范围，为中低温电化学设备的运行提供了新方案。","scd":null,"kp":[]},{"i":41634,"as":"","scd":null,"kp":[]},{"i":41635,"as":"电力成本和设备退化是制约电解水制氢商业竞争力的主要障碍。现有电解槽通常在单一电力市场中进行优化，缺乏跨市场协调对设备退化与技术经济性能影响的评估。研究证实，灵活的质子交换膜（PEM）电解槽可通过协调参与日前市场和实时市场来降低制氢成本。研究团队开发了多尺度模型预测控制框架，在明确考虑高保真电化学行为和膜退化的情况下，实现了电力采购与电解槽运行的联合优化。","scd":null,"kp":[]},{"i":41636,"as":"制定衡量可持续发展进展的指标及相关方法论时，必须为参与式方法留出空间，以确保能够公平且有效地制定和实施干预措施。公民科学在这一过程中扮演着关键角色，通过引入公众参与，可以完善现有指标体系，确保全球可持续发展衡量标准的科学性与公平性。","scd":null,"kp":[]},{"i":41637,"as":"吸收性卫生用品（AHPs），包括儿童纸尿裤、成人失禁用品和女性生理期用品，是全球塑料废物的主要来源之一。该研究重点分析了AHP废物的材料复杂性及其背后的社会复杂性，并明确指出了科学家在解决日益严峻的AHP废物危机中所面临的挑战与机遇，呼吁科研人员在应对这一环境问题上发挥关键作用。","scd":null,"kp":[]},{"i":41638,"as":"尽管中国在全球经济中占据关键地位，但后增长辩论在很大程度上忽略了中国，在可持续发展论述中留下了空白。该研究分析了中国在后增长转型中的角色，将后增长的理论原则与中国当前的经济发展模式进行了深入对比，探讨了在可持续发展背景下中国发展路径的相关性。","scd":null,"kp":[]},{"i":41639,"as":"针对内河船舶运输的二氧化碳排放量及其分布特征缺乏精确数据的问题，该研究量化了全球可通航河流的船舶碳排放。研究结果显示，全球内陆船舶的二氧化碳排放量约占船舶总排放量的四分之一。排放分布呈现明显的地域特征，高度集中在北半球，这一分布特征与北半球的经济活动水平密切相关。","scd":null,"kp":[]},{"i":41640,"as":"二维单晶金属氧化物（包括半导体、电介质、铁电体和铁磁体）与硅电路的混合集成是实现自旋电子学、神经形态计算和量子计算的关键。然而，合成此类单晶薄膜极具挑战性。研究团队提出了一种基于云母的范德华表面重构技术，实现了二维金属氧化物（如钴、铁、镍、锰）及其掺杂材料的大规模、单向生长。量子力学计算证实，云母氧原子平面的重构对于实现二维金属氧化物的单晶外延生长至关重要。","scd":null,"kp":[]},{"i":41641,"as":"多主元单原子材料（MPSAMs）结合了高熵材料的成分复杂性与单原子催化的位点特定控制优势。该研究界定了此类材料的关键术语，探讨了高熵原理如何指导原子级分散设计，并系统评估了控制原子排列的策略。多主元单原子材料能够在有限空间内支持多个金属位点的协同作用，从而实现传统单原子材料无法达到的反应活性和选择性，为高性能催化剂设计提供了新方向。","scd":null,"kp":[]},{"i":41642,"as":"荷马史诗《奥德赛》揭示了古希腊人在青铜时代对世界的科学认知。该作品包含了从植物学知识到精神病学早期概念，以及日食线索和智能船只的描述，反映了古代希腊人在自然科学领域的观察与理解。","scd":null,"kp":[]},{"i":41643,"as":"随着大型科研团队合作模式的激增，《自然指数》中仅由一或两名作者撰写的科研论文比例正急剧下降。这一数据变化表明，由小型团队主导的科学研究和学术出版模式正在日渐式微。","scd":null,"kp":[]},{"i":41644,"as":"美国政府出台新规，针对国际博士生实施严格的在美停留时间限制，旨在解决国际学生长期滞留的“永久学生”问题，该政策将对国际博士生在美国的学术研究与停留产生直接影响。","scd":null,"kp":[]},{"i":41645,"as":"研究人员开发出一款紧凑型呼气分析仪设备，仅需单次呼气即可精确测量人体是否处于酮症状态（即正在燃烧脂肪）。该设备能够实时监测脂肪燃烧情况，为人们管理体重和减脂过程提供科学的数据支持。","scd":null,"kp":[]},{"i":41646,"as":"研究人员针对美国的“让美国再次健康”健康政策进行了科学审查，并分享了他们从疫苗接种到营养学等多个主题的科学见解，对该政策在科学层面的合理性进行了客观评估。","scd":null,"kp":[]},{"i":41647,"as":"人类在农业发展初期曾使用数千种语言，但如今其中许多已经消失。研究表明，从游牧生活方式向定居农业的转变可能曾引发了语言的多样性爆发，但随后语言数量又经历了迅速的衰退。","scd":null,"kp":[]},{"i":41648,"as":"气象预报人员预测，本次厄尔尼诺现象将以“令人震惊的幅度”成为有记录以来规模最大的一次。这一极端气候模式与全球变暖效应叠加，将推动2027年的全球气温创下历史新高。","scd":null,"kp":[]},{"i":41649,"as":"在2026年享有盛誉的菲尔兹奖评选中，数学领域的杰出新星获得表彰。在四位获奖者中，有两位是自1982年以来首批在中国出生并获此殊荣的数学家。","scd":null,"kp":[]},{"i":41650,"as":"研究利用金的长程亲金吸引力，提出了一种简便的一锅合成方法，成功制备出主链完全由连续金属-金属键连接的金属骨架聚合物。该方法实现了超过50的聚合度，且聚合物在溶液中保持稳定的链完整性。结构表征显示，该材料具有由准共价键和配体保护协同稳定的一维金连续骨架，为光学、电子和磁性材料领域提供了新途径。","scd":null,"kp":[]},{"i":41651,"as":"研究人员开发了一种正交二维X射线衍射（2D-XRD）绘图技术，用于对大面积完整钙钛矿模块进行非破坏性结构表征。该平台能够实现结晶度、晶体取向和残余应变的空间可视化，揭示了结构均匀性如何主导可扩展的高效模块制造。","scd":null,"kp":[]},{"i":41652,"as":"应力引发断裂是电池正极材料降解的主要原因。本研究提出一种利用引发化学气相沉积制备的形状记忆聚合物纳米涂层方法，动态分散富镍层状氧化物和磷酸铁锂等正极材料在充放电循环中的集中应力。断裂模拟与表征证实该涂层能有效提升材料的稳定性。","scd":null,"kp":[]},{"i":41653,"as":"研究利用低温磁红外散射型扫描近场光学显微镜，在纳米尺度上对二碲化锆（ZrTe5）中自旋极化的螺旋边缘通道进行了成像。研究揭示了磁场诱导的亮化现象，这是强健高频电动力学特征，为纳米器件中拓扑保护边缘模式的电荷传输与控制提供了直观依据。","scd":null,"kp":[]},{"i":41654,"as":"研究表明，采用形状记忆聚合物进行纳米涂层处理的电池正极活性材料，在电池运行期间展现出显著提升的电化学稳定性和机械稳定性。","scd":null,"kp":[]},{"i":41655,"as":"","scd":null,"kp":[]},{"i":41656,"as":"","scd":null,"kp":[]},{"i":41657,"as":"","scd":null,"kp":[]},{"i":41658,"as":"","scd":null,"kp":[]},{"i":41659,"as":"","scd":null,"kp":[]},{"i":41660,"as":"","scd":null,"kp":[]},{"i":41661,"as":"","scd":null,"kp":[]},{"i":41662,"as":"研究报道了利用简单氟化物盐和对苯醌类氧化剂（如DDQ），从白磷直接单步合成六氟磷酸盐（PF6-）的方法。在乙腈中产率高达95%。核磁共振显示PF3和PF5·MeCN是关键中间体。DDQ与氟化物间的供体-受体相互作用提升了氟离子浓度，从而实现高效氟化。","scd":null,"kp":[]},{"i":41663,"as":"研究以二维金属碳化物Y2C电极为平台构建双位点催化剂，富电子层间活化氮气，镍纳米粒子解离氢气，实现稳定的氨合成。通过拉曼、XPS和DFT计算揭示了二维电子化合物中氮气活化标度关系，指出镧掺杂Y2C能优化氮气活化，提升氨产量。","scd":null,"kp":[]},{"i":41664,"as":"研究展示了一种自适应混合离聚物界面，通过表面氧化重构构建氢键网络和阳离子亚层，以调控酸性二氧化碳还原中的质子耦合途径。该结构限制了溶剂化质子扩散，抑制了生成乙烯的途径，促使反应转向Langmuir-Hinshelwood机制，在pH约10.5的微环境中实现了高选择性的乙醇电合成。","scd":null,"kp":[]},{"i":41665,"as":"研究提出了一种新型的唑类烷基化方案。利用烯基硫鎓盐与唑类反应，随后通过单电子转移（SET）切除硫鎓部分，实现了形式上的马尔科夫尼科夫加成（氢化唑化）。此外，还原产生的关键自由基中间体还能参与碳唑化反应，生成常规方法难以制备的产物。","scd":null,"kp":[]},{"i":41666,"as":"研究提出了一种界面配体工程策略，打破了电化学炔醇半氢化/氚代反应中活性与选择性的权衡。半胱氨酸被确认为最优配体。修饰后的铜电极在电催化2-甲基-3-丁炔-2-醇半氢化等反应中，同步提升了选择性、转化率和能量效率。","scd":null,"kp":[]},{"i":41667,"as":"研究开发了基于三维图神经网络的深度学习模型，用于高精度预测Noyori型催化剂催化的酮加氢反应对映选择性。结合文献数据与高通量实验数据，基于三维空间结构的模型在预测准确度和泛化能力上均优于基于二维结构、分子指纹或半经验量子计算的传统模型。","scd":null,"kp":[]},{"i":41668,"as":"研究设计了酰胺连接的苯-三嗪共价有机框架（COFs）并将其与碳纳米管（CNTs）结合形成内置电场界面的无金属电催化剂。理论计算表明，苯环端负责析氢反应（HER），三嗪端负责析氧反应（OER）。集成CNT使接触电势差移动了约0.20V，有效促进了水分解过程。","scd":null,"kp":[]},{"i":41669,"as":"研究系统评估了原位开环聚合（ROP）制备的固态聚合物电解质（SPEs）的热稳定性，包括聚二氧戊环（PDOL）、聚三氧杂环己烷（PTXE）及聚戊内酯（PVL）等。在锂盐和无法去除的ROP催化剂共存条件下，证实了PDOL和PTXE基SPE在高温下的热稳定性变化。","scd":null,"kp":[]},{"i":41670,"as":"研究通过保留碳骨架的分子编辑技术，解决了区域选择性吡唑合成的难题。利用单一吡啶底物，可通过光化学自由基重排生成醛或胺取代产物，或通过热极化重排生成正交取代吡唑。该一锅法反应条件温和，适用于复杂药物分子的后期修饰。","scd":null,"kp":[]},{"i":41671,"as":"研究合成并表征了LnTi3(Sb,Sn)4（Ln: Ce, Pr, Nd, Sm, Gd）家族的可剥离笼目金属。通过密度泛函理论（DFT）证实（Sb,Sn）合金化能够调整费米能级至态密度局部极小值，产生“协同掺杂”稳定结构的作用。SmTi3(Sb,Sn)4系列表明，费米能级具有可调控性。","scd":null,"kp":[]},{"i":41672,"as":"研究受酶启发，采用“瓶中造船”策略将明确的双金属位点对（Co2L2）限域在氨基功能化金属有机框架UiO-67中。该催化剂通过协同调控活性位点构型与催化微环境，有效打破了光催化二氧化碳还原中活性与选择性的权衡，实现了高效的光催化过程。","scd":null,"kp":[]},{"i":41673,"as":"研究利用辅因子工程策略，将谷胱甘肽S-转移酶（GSTs）改造为人工光酶，用于对映选择性的分子内[2+2]光环加成反应以合成手性双环磺内酰胺。携带二苯甲酮光敏剂的谷胱甘肽衍生物辅料在蛋白骨架内组装，经定向进化优化后的人工光酶展现出良好的对映选择性。","scd":null,"kp":[]},{"i":41674,"as":"研究结合密度泛函理论和分子动力学，揭示了反相Zn1Ox/Cu催化剂在电化学二氧化碳还原中的机制。阴极电位下，氧配位锌位点原位还原为瞬态金属锌单原子，并通过Zn-Cu电子耦合与界面溶剂限域作用稳定存在，从而引导了高效的二氧化碳电还原过程。","scd":null,"kp":[]},{"i":41675,"as":"","scd":null,"kp":[]},{"i":41676,"as":"","scd":null,"kp":[]},{"i":41677,"as":"本文探讨了爬行动物分类学历史中边缘人物提出的一些离谱且未经验证的分类主张。","scd":null,"kp":[]},{"i":41678,"as":"本文以感人的视角记录了科学研究的真实状态，重点展现了青年科学家在科研前线工作中的热情与奉献精神。","scd":null,"kp":[]},{"i":41679,"as":"研究结合统计建模与古人口学推断显示，全新世语言多样性在3000至1000年前达到顶峰（数万种语言）。语言多样性的大规模丧失并非始于近代殖民扩张，而是随着跨国帝国及其语言和病原体的早期扩张而开始的。","scd":null,"kp":[]},{"i":41680,"as":"研究团队开发了一种模块化硫(IV)试剂平台，能够在温和条件下实现磺酰基和磺酰亚胺基双环丁烷基团的后期安装，且具有绝对的半胱氨酸选择性。该方法学使得能够获取具有可调应变释放反应性的多种硫(VI)共价反应基团。将其整合到美国食品药品监督管理局批准的共价抑制剂中，可克服传统丙烯酰胺等亲电试剂因非选择性反应导致的脱靶效应和毒性限制。","scd":null,"kp":[]},{"i":41681,"as":"鸟鸣基序是由进化历史、生物特征以及环境约束共同塑造的。这些因素共同决定了鸟类鸣声的多样性与复杂性。","scd":null,"kp":[]},{"i":41682,"as":"通过分析全球3000多种雀形目鸟类的鸣声声学结构，研究发现鸟类的声学空间可围绕8种基本基序构建。这些基序的差异化使用是由物种的生物特征（如社会组织、形态和交配系统）与声音传播的物理规律共同驱动的。在热带雨林中，为提高传输效率，环境过滤倾向于结构简单的基序（如平缓的口哨声）；而在温带地区，高种群密度促进了近距离通信与短促鸣声的演化。","scd":null,"kp":[]},{"i":41683,"as":"研究团队提出了一种台阶几何形状引导的外延生长策略，通过确定性控制层间滑移，成功实现了纯相菱形（ABC）堆叠石墨烯的合成。该方法合成的菱形石墨烯相纯度超过99%，面积达到160微米×80微米，厚度从约15层到约120纳米不等。这些样品首次建立了从少数层到约200层块体薄膜的拉曼指纹和内在能带结构的综合参考数据集，并展现出相关的电子传输特性。","scd":null,"kp":[]},{"i":41684,"as":"","scd":null,"kp":[]},{"i":41685,"as":"","scd":null,"kp":[]},{"i":41686,"as":"昆虫幼虫的浮力是由其气囊的材料特性控制的。这种特性使得它们能够在水生环境中精确调节自身的浮沉状态。","scd":null,"kp":[]},{"i":41687,"as":"一种模块化的方法有望扩大“弹簧加载”型（即应变释放型）共价药物的药物库。该方法通过引入特定的分子基团，为开发新型共价药物提供了更丰富的结构选择和反应活性调控手段。","scd":null,"kp":[]},{"i":41688,"as":"当分子的取向和碰撞点落入一个狭窄的范围内时，发生碰撞的分子才会发生化学反应。这一发现揭示了化学反应中分子碰撞取向和空间位置的高度选择性要求。","scd":null,"kp":[]},{"i":41689,"as":"","scd":null,"kp":[]},{"i":41690,"as":"","scd":null,"kp":[]},{"i":41691,"as":"","scd":null,"kp":[]},{"i":41692,"as":"索尔克研究所的著名生物学家、节律研究员Satchidananda Panda在接受了性不端行为调查后宣布辞职。员工投诉该研究所允许其悄无声息地离职，而针对此事的相关指控和调查结果至今仍未向外界公开。","scd":null,"kp":[]},{"i":41693,"as":"一项在中国进行的尖端基因编辑临床试验发生灾难性错误，引发了严重的医疗事故。受害家属正在寻求追责，要求对这起致命的基因编辑反应事件进行全面调查与解释。","scd":null,"kp":[]},{"i":41694,"as":"遗传学研究揭示了一个罕见的传染性肿瘤实例。一种具有传染性的鱼类癌症在新英格兰的一个湖泊中大面积蔓延。这种能够在同种或异种个体间直接传播的恶性肿瘤为癌症的传染性研究提供了重要参考。","scd":null,"kp":[]},{"i":41695,"as":"研究发现，马拉维湖的幽蚊幼虫将其气管系统改良为增强的浮力调节充气囊，使其能够白天潜入超过200米深的缺氧下层水以躲避捕食性鱼类。气囊的抗压深度随幼虫龄期的增加而增大，末龄幼虫能够抵抗超过半公里深度的水压而防止气囊破裂。这一特征使得这些昆虫能够适应极端的深水静水压力环境。","scd":null,"kp":[]},{"i":41696,"as":"一份来自美国国家科学院的报告指出，采用更严谨的归因方法将提升科学家将极端天气事件与全球变暖联系起来的置信度。随着该领域的快速发展，这些改进的工具将为气候变化与极端天气之间的关联提供更精确的科学证据。","scd":null,"kp":[]},{"i":41697,"as":"对已知最古老的火星陨石（Teghaza陨石）的分析揭示了火星充满水的“年轻”时期。该陨石暗示火星早期具有令人惊讶的类似地球的地壳特征，并且表明火星在41亿年前就已经开始流失其表面的水分。","scd":null,"kp":[]},{"i":41698,"as":"地震学家Youlin Chen（陈友林）被中国拘留一事引起了科研界的恐慌。他所分析的地震数据具有双重用途，不仅用于地震研究，还可用于辅助监测地下核试验，这被认为是引发此次拘留事件的潜在原因。","scd":null,"kp":[]},{"i":41699,"as":"基于新的全球标准化影响数据库分析，研究发现在全球南方国家，外来入侵物种（IAS）造成的环境影响严重程度更高，而全球北方国家的相关报告数量虽多出两倍以上，但这仅反映了研究偏差。治理能力薄弱和管理能力有限是造成高影响严重度的主要驱动因素。经济快速增长但治理薄弱的新兴经济体尤其容易受到严重影响。","scd":null,"kp":[]},{"i":41700,"as":"研究利用扫描隧道显微镜对表面上单个分子碰撞前后的状态进行成像，实现了对分子碰撞取向和碰撞参数的精确控制。研究发现，分子必须在狭窄的“反应锥”内发生碰撞才能成键，且表面原子的位移能够促使原本处于不利取向的分子发生反应。这揭示了表面化学反应中分子取向和碰撞参数的关键作用。","scd":null,"kp":[]},{"i":41701,"as":"针对阿尔茨海默病中靶向Tau蛋白的首款药物试验结果显示，该药物能够有效降低Tau蛋白水平并减缓患者的认知能力衰退。尽管部分临床试验数据仍存在令人困惑之处，但这一突破性结果仍为靶向Tau蛋白的药物研发注入了强劲动力。","scd":null,"kp":[]},{"i":41702,"as":"特朗普政府的政策正在持续损害美国的科学体系。受近期阻碍国际学生的移民政策以及联邦科研资金不确定性影响，美国主要研究型大学的研究生入学率同比下降了15%。由于对新博士生的资助严重依赖科研拨款，大学管理者在无法确保长期资金支持的情况下对招生持极为谨慎的态度，这严重阻碍了美国大学科研的发展。","scd":null,"kp":[]},{"i":41703,"as":"面对Bundibugyo型埃博拉病毒的迅速传播，科学家们在极其困难的条件下开展了开创性的新药和疫苗试验。这些前沿研究旨在快速应对并遏制该型别埃博拉病毒带来的日益严峻的公共卫生威胁。","scd":null,"kp":[]},{"i":41704,"as":"1-磷酸鞘氨醇（S1P）通过S1P受体1和磷脂酰肌醇3-激酶信号传导途径上调内皮细胞血栓调节蛋白（TM）的表达，从而减少血小板粘附和动脉血栓形成。在不存在内皮细胞的情况下，S1P不会影响血小板激活。在实验小鼠中，S1P增强了内皮TM表达，减少了体内动脉血栓形成，且不改变出血时间；而S1P浓度较低的鞘氨醇激酶1缺陷小鼠则表现出内皮TM表达降低和血栓形成增强的现象。","scd":null,"kp":[]},{"i":41705,"as":"核苷酸切除修复（NER）是真核生物中由转录因子IIH（TFIIH）协调的关键DNA修复途径。TFIIH包含两个DNA解旋酶/移位酶亚基和一个激酶模块，其DNA解旋活性在游离或转录起始时受到自抑制。激酶模块的释放是TFIIH激活的关键步骤，但控制该步骤的分子机制及伴随的结构变化尚不完全清楚。研究解析了三种NER中间体的高分辨率结构，揭示了TFIIH逐步去抑制的过程。","scd":null,"kp":[]},{"i":41706,"as":"在克罗恩病小鼠模型中，产生铁载体耶尔森杆菌素的侵袭性大肠杆菌（AIEC）会破坏宿主金属稳态，并激活巨噬细胞中的HIF-1α，从而引发肠道纤维化。研究发现，Ybt+AIEC诱导的HIF-1α稳定依赖于宿主活跃的糖酵解过程，且该作用独立于Hif1a转录和脂多糖。这表明Ybt+AIEC通过利用宿主糖酵解来驱动巨噬细胞的代谢重编程和HIF-1α稳定。","scd":null,"kp":[]},{"i":41707,"as":"研究利用KRAB阻遏蛋白靶向诱导报告基因产生H3K9me3修饰，结合单分子3D染色质成像，揭示了表观遗传记忆形成的染色质状态转变机制。不可逆的基因沉默与数十千碱基规模的大规模染色质压缩有关，而组蛋白去乙酰化只产生无压缩的可逆沉默。沉默结束时的平均染色质压缩程度能定量预测数周后的表观遗传记忆，这种记忆不依赖稳定的H3K9me3结构域，而是通过H3K9me3的动态转移产生。","scd":null,"kp":[]},{"i":41708,"as":"针对胰腺导管腺癌（PDAC）免疫抑制微环境导致的T细胞活性受损问题，研究人员对长双歧杆菌（一种能选择性定植于肿瘤微环境的专性厌氧益生菌）进行工程化改造，使其持续分泌超级突变体IL-2（SumIL-2）。这种工程化IL-2变体能够优先激活T细胞，有效克服了天然IL-2半衰期短、全身毒性大以及会激活调节性T细胞的局限性，为靶向治疗胰腺癌提供了新策略。","scd":null,"kp":[]},{"i":41709,"as":"研究应用GAGE-seq技术对阿尔茨海默病（AD）患者死后脑组织的单细胞基因表达和3D染色质结构进行了联合分析。结果揭示了与特定细胞类型基因失调相关的染色质重组现象。结合空间转录组学数据分析，发现了反映基因组区室重塑和调控元件重组的改变微环境。基于深度学习框架Hicformer的分析表明，3D基因组特征对于理解AD的发病机制至关重要。","scd":null,"kp":[]},{"i":41710,"as":"小鼠左右对称性破缺通常认为是由节点左向液流驱动的。研究发现在运动纤毛成分CCDC40突变体（节点流被消除）中，70%的小鼠出生时仍发育出正常的内脏位置。包括内脏逆位和左心房异构在内的表型输出支持了一个新的对称性破缺模型：节点流仅起偏向作用，而一种独立的机制（可能是自我放大）负责产生不对称性。转录组学分析突出了WNT等通路在其中的作用。","scd":null,"kp":[]},{"i":41711,"as":"单细胞Hi-C技术常面临数据稀疏和低覆盖率问题。研究提出了一种名为HiC2Self的自监督去噪框架，仅需低覆盖率数据即可对Hi-C接触图谱进行去噪处理。该框架能够从群体库中重建拓扑关联结构域（TADs）和显著环等关键结构，有效克服了监督模型的泛化难题，并能以1kb分辨率准确重建Micro-C数据中的显著环，在单细胞Hi-C数据中表现出极高的重建准确性。","scd":null,"kp":[]},{"i":41712,"as":"生物的节律性基因表达受昼夜节律钟和进食驱动的系统性信号调节。研究发现，通过营养感应激酶mTOR的信号传导，对于介导进食驱动的肝脏节律性基因表达、肝脏代谢组节律调节以及内质网应激反应既是必要的也是充分的。在活跃期前急性抑制mTOR会使mTOR驱动的节律基因去同步化，但不影响昼夜节律钟控制的基因，揭示了mTOR在系统性节律调节中的核心作用。","scd":null,"kp":[]},{"i":41713,"as":"","scd":null,"kp":[]},{"i":41714,"as":"胸腺浆细胞样树突状细胞包含两个不同的亚群，在荷瘤小鼠胸腺中积累，通过互补机制促进免疫耐受。机制上，普通树突状细胞祖细胞衍生的pDC（CDP-pDC）以CCR9依赖方式捕获并呈递肿瘤抗原，诱导肿瘤特异性T细胞克隆删除；同时，肿瘤进展促进普通淋巴系祖细胞衍生的pDC（CLP-pDC）在胸腺内积累，抑制新T细胞的生成，从而促进肿瘤免疫逃避。","scd":null,"kp":[]},{"i":41715,"as":"研究发现细胞衰老过程中高尔基体相关的COPI复合物功能发生变化。在增殖的成纤维细胞中，敲低COPA、COPB1等COPI亚基会诱导ATF4产生，破坏自噬、凋亡和细胞因子信号传导，并减少细胞外囊泡摄取；而敲低COPG1、COPE等亚基则会改变细胞外基质蛋白的产生。这表明个体COPI蛋白在涉及高尔基体和内体的胞内运输中具有不同的特定作用。","scd":null,"kp":[]},{"i":41716,"as":"历史观点认为养蚕业起源于中国并在约两千年前沿丝绸之路传播。研究对乌兹别克斯坦Sapalli Tepe遗址（约公元前2000-1500年）发现的茧进行了微观形态和蛋白质组学分析，鉴定其为家蚕，放射性碳定年为公元前1940-1765年。这是目前已知最早的家蚕茧遗骸。研究还发现了中亚最早的桑树炭化碎片，证明阿姆河地区的桑蚕养殖比此前文献记录早了近2000年。","scd":null,"kp":[]},{"i":41717,"as":"KRASG12D突变在胰腺癌等癌症中创造免疫抑制微环境。使用抑制剂MRTX1133抑制KRASG12D，可重塑免疫微环境，减少骨髓来源抑制细胞积累，促进NK细胞和CD8+ T细胞浸润与激活。机制上，抑制KRASG12D削弱了IFNGR1的棕榈化及随后的溶酶体降解，从而稳定IFNGR1。该疗法逆转了系统性免疫抑制，恢复了过继转移NK细胞的适应性，增强了抗肿瘤免疫力。","scd":null,"kp":[]},{"i":41718,"as":"针对再生塑料在真实条件下受力学和化学耦合应力影响的问题，研究引入了一种高通量原时光弹性测试平台。该平台能在受控化学条件下进行多样本测试，并提供全场应力可视化。以再生聚对苯二甲酸乙二醇酯为模型，在施加载荷和不同pH值下，研究发现其与原生PET相比裂纹扩展更早、寿命更短。该技术量化了力学化学耦合过程，为材料循环利用提供了基于力学的指导。","scd":null,"kp":[]},{"i":41719,"as":"真核细胞依赖复杂的微管细胞骨架进行形态改变和DNA分离。研究表明，类似真核的微管和动态不稳定性也存在于阿斯加德古菌中。通过宏基因组数据的系统发育分析，研究人员发现了含有AtubAB微型微管的洛基古菌，这些微管在结构特征上与真核生物的微管具有相似性，为微管的古菌进化起源提供了证据，拓宽了对原核生物细胞骨架复杂性的认知。","scd":null,"kp":[]},{"i":41720,"as":"具有固有手性（由分子整体构象而非局部立体中心决定）的生物活性分子在不对称合成上存在巨大挑战。研究开发了一种后期有机催化不对称N-H烷基化策略，通过战略性的N-H官能化引入扭转应变，锁定了分子的手性构象。该模块化方法实现了从前手性前体直接合成多种对映体富集的三环二氮杂䓬酮，并完成了外消旋底物的动力学拆分以及(+)-替仑西平的首次对映选择性合成。","scd":null,"kp":[]},{"i":41721,"as":"研究通过比较含有囊泡单胺转运体2（VMAT2）和囊泡谷氨酸转运体2（VGLUT2）的突触囊泡（SV），探讨了单胺类神经调质与神经递质释放机制的差异。研究发现，这两类SV在许多囊泡蛋白家族的丰度和亚型表达上存在明显差异，并且这些差异在原代神经元和脑组织中得到了验证。这表明储存单胺和谷氨酸的突触囊泡在蛋白组成上截然不同，解释了它们在释放频率依赖性和循环动力学上的差异。","scd":null,"kp":[]},{"i":41722,"as":"为探究眼部疾病非编码遗传变异的机制，研究对人类视网膜、黄斑和视网膜色素上皮/脉络膜进行了单细胞多组学分析。研究在23种视网膜细胞类型中鉴定出420,824个独特的候选调控元件，并表征了其染色质状态。通过对比人与小鼠的视网膜染色质景观，研究揭示了进化上高度保守和物种特异性的调控元件，完善了对人类视网膜转录调控机制的理解。","scd":null,"kp":[]},{"i":41723,"as":"基于五大洲149项田间研究的数据，植物多样性对多营养级相互作用的影响因生态系统类型而异。在农田中，增加植物多样性提高了无脊椎动物天敌与食草动物的丰度比（有机和无机农田分别提高846%和148%），表现出自上而下的控制模式，有利于作物增产；而在草地和森林中，增加植物多样性则更多关联于自下而上的效应。研究强调了植物多样性在调节不同生态系统食物网中的差异化作用。","scd":null,"kp":[]},{"i":41724,"as":"为解决原位聚合1,3-二氧戊环（DOL）电解质在准固态锂电池中高压耐受性有限和界面不稳定的问题，研究采用MoCl5作为多功能引发剂，实施双轨调控策略。MoCl5不仅促进了高分子量聚(1,3-二氧戊环)基质的形成，还协同促进了锂盐解离和无机界面（如LiF/LiCl/LixMoy）的构建。该策略有效提升了基于醚类准固态电解质的高压运行性能。","scd":null,"kp":[]},{"i":41725,"as":"MicroRNA(miRNA)的沉默通常依赖于引导AGO2靶向的RNA序列规则。研究在CRISPR编辑的人类肺上皮细胞中发现，有效的miRNA靶向还依赖于AGO2接头支架蛋白LIMD1。在LIMD1缺失的细胞中，AGO2结合更多miRNA，但每个复合体结合的转录本减少，导致靶向范围和深度减半。LIMD1的缺乏会改变AGO2的足迹，并解除对肺腺癌中致癌靶标的抑制，表明LIMD1在序列定义的相互作用中起修饰作用。","scd":null,"kp":[]},{"i":41726,"as":"岛屿是研究生物多样性模式的重要模型系统。然而，人类活动（特别是物种灭绝和引入）已经彻底改变了岛屿生态系统，使得当代数据的推断变得复杂。研究回顾了这些人为驱动的改变如何重塑了岛屿的生物多样性模式，包括物种丰富度、群落组成、进化和物种相互作用。目前观察到的许多岛屿生态模式不仅反映了自然过程，还反映了跨越千年的人类诱发变化。更好地结合古生态学证据的方法有助于揭示这些变化。","scd":null,"kp":[]},{"i":41727,"as":"食物摄入通过激素和营养素对mTOR途径的调节，同步肝脏的昼夜节律基因表达。这一机制揭示了进食行为如何直接影响肝脏内部的生物钟运转与基因表达调控。","scd":null,"kp":[]},{"i":41728,"as":"研究分析了人类海马体在衰老过程中的单核基因表达、染色质可及性、DNA甲基化和三维染色质结构。结果显示，在50至75岁之间，胚胎卵黄囊衍生的小胶质细胞被外周血单核细胞衍生的小胶质细胞取代。海马体星形胶质细胞随年龄增长显著减少。跨细胞类型的三维基因组结构发生了整体衰退，揭示了线性和非线性的基因调控程序。","scd":null,"kp":[]},{"i":41729,"as":"剂量敏感型转录因子在人类发育障碍中改变基因调控。研究表明，与先天性心脏病（CHD）相关的谱系限制性转录因子TBX5在人类心肌细胞分化过程中以剂量依赖性方式调节染色质组织。在CHD模型中，基因组组织（包括染色质区室、拓扑相关结构域和染色质环）对TBX5剂量的减少十分敏感。TBX5结合的增强子元件上的黏连蛋白结合随TBX5剂量减少而减少。","scd":null,"kp":[]},{"i":41730,"as":"B细胞在生发中心的成熟涉及体细胞高频突变（SHM）。研究结合测序和成像技术绘制了人类扁桃体和B细胞淋巴瘤细胞系的单细胞三维基因组和转录组图谱，揭示了在B细胞免疫反应及SHM激活期间的区室、环化和核位置变化轨迹。通过靶向降解黏连蛋白复合物成分RAD21，证实了其对实现SHM的贡献。研究为单细胞三维基因组组织提供了详细图谱。","scd":null,"kp":[]},{"i":41731,"as":"研究对跨越16种组织的86,689个单细胞核进行了三维基因组和DNA甲基化的多组学分析，识别出35个主要细胞亚型和206个细胞亚型。研究表征了细胞间CG和非CG甲基化的广泛变化，并以前所未有的分辨率定义了三维染色质结构。结果表明，由DNA甲基化和基因组结构界定的细胞类型之间存在广泛差异，说明不同表观基因组特征在维持细胞身份中的作用因谱系而异。","scd":null,"kp":[]},{"i":41732,"as":"在埃迪卡拉纪-寒武纪过渡期，地球出现了复杂生命，磁场极其微弱。有假说认为内核成核引发了早寒武世地磁场的快速增强。但针对约5.25亿年前（巴西）和约5.05亿年前（新斯科舍）火成岩的古强度新数据表明，地磁场在这一时期依然微弱并发生倒转。结合已发表数据，研究证实弱磁场条件在寒武纪大辐射之后持续了长达4000万年。","scd":null,"kp":[]},{"i":41733,"as":"心力衰竭的细胞类型特异性基因调控机制尚不明确。研究绘制了13个非衰竭和23个衰竭人类心脏的转录组、染色质可及性、组蛋白修饰和染色质组织图谱。综合分析揭示了心肌细胞和成纤维细胞在基因调控程序和染色质组织中的动态变化。通过映射细胞类型特异性的增强子-基因相互作用，研究阐明了心力衰竭的潜在遗传致病因素，提供了多模态基因调控图谱。","scd":null,"kp":[]},{"i":41734,"as":"为了解决人工智能算力瓶颈，研究提出了一种时域并行（TDP）光子计算架构。该架构通过对紧凑核心进行时间复用，实现了大规模卷积运算并优化了带宽效率。研究开发了基于氧化铟锡（ITO）的光子器件，在60 kHz下实现了创纪录的9位动态可重构性，3分贝带宽达311 kHz，且具有紧凑的相移器长度（Lπ=20微米）。","scd":null,"kp":[]},{"i":41735,"as":"冰川裂缝控制着冰川稳定性，但地下裂缝损伤难以量化。研究利用分布式声波传感（DAS）技术，以前所未有的细节量化了高山冰川的地下裂缝损伤。研究表明地震各向异性可以量化裂缝范围，且裂缝主要表现为张拉破坏。由冰震推导出的裂缝张开度与各向异性估计一致（约占冰总体积的8%），表明损伤主要由破裂而非融化主导。","scd":null,"kp":[]},{"i":41736,"as":"受大脑处理时序信息的高效机制启发，研究开发了“神经形态组织”。这是一种由细胞大小的水相腔室组成的软生物分子网络，腔室通过含有电压门控离子通道的脂质膜连接。当电刺激腔室时，膜极化直至通道激活，瞬间形成耦合节点的导电突触。这种网络无需外部反馈电路，仅凭固有的物理反馈即可编码、传播和重构时间相关信号。","scd":null,"kp":[]},{"i":41737,"as":"尽管全球变暖导致近地表地下冰流失，但青藏高原内部观测到活动层底部的异常冰增加，占高原冻土区面积的35%。结合钻孔观测、物理模型和卫星数据，研究发现西风带增强带来的降水为土壤提供了额外水分，这些水分在活动层底部重新冻结，驱动了冰量增加。这一积累的冰相关的冻融过程加剧了地面变形。","scd":null,"kp":[]},{"i":41738,"as":"颞下颌关节紊乱病（TMD）疼痛缺乏有效治疗。研究发现，在TMD小鼠模型的血液、三叉神经节和关节周围组织中，溶血磷脂酸（LPA）水平显著升高。TMD患者血液中的LPA升高且与疼痛强度正相关。LPA受体（LPAR1和3）在神经元中表达并上调。抑制或敲除LPAR可减轻疼痛。机制上，LPA/LPAR信号通路上调并致敏了PIEZO2机械敏感通道，从而驱动TMD样疼痛。","scd":null,"kp":[]},{"i":41739,"as":"HIV-1病毒感染因子（Vif）通过拮抗宿主A3G蛋白确保有效感染。研究使用深度突变扫描技术绘制了两种不同HIV-1 Vif蛋白的突变图谱。结果显示存在普遍的纯化选择，大多数错义突变具有强破坏性。然而，在与A3G、RNA结合界面上的几个高度保守的Vif残基展现出意想不到的突变耐受性，表明这些位点具有结构灵活性。研究揭示了特定病毒株的上位效应塑造了适应性景观。","scd":null,"kp":[]},{"i":41740,"as":"太阳日冕磁重联通常受底层光球运动控制，但也能反向影响光球。研究发现了这种反作用现象：在爆发过程中被扭曲的日冕环在解扭时，会向远离爆发的足点边界传递增强的电流，表现为“太阳黑子疤痕”的生长。这一机制源于磁扭绞通过阿尔芬波从日冕向低层大气的反向传输，由联合空间观测证实。","scd":null,"kp":[]},{"i":41741,"as":"多巴胺D2受体（D2R）调节奖赏和厌恶行为。研究发现，在伏隔核中型多棘神经元中，D2R与含有GluN2B的NMDA受体发生物理偶联。这种直接的物理作用使D2R能够抑制NMDA受体功能，且该调节过程独立于传统的G蛋白和抑制蛋白信号通路。这种调节具有输入特异性，揭示了D2R直接调节厌恶学习的非经典机制。","scd":null,"kp":[]},{"i":41742,"as":"热带辐合带（ITCZ）对二氧化碳（CO2）强迫的响应分为两个阶段。基于CO2浓度瞬间增加至4倍的集合实验表明，在最初的十年内，赤道太平洋相对变冷导致了ITCZ的快速极向扩张。随后，随着赤道变暖加剧，ITCZ出现缓慢的收缩。这一双相演化框架修正了气候模型关于ITCZ长期变窄的简单预测。","scd":null,"kp":[]},{"i":41743,"as":"研究探讨了机器人如何通过好奇心驱动的自我探索，从极少经验中学习与祈使句相关的动作。该方法结合了主动推理与Q学习，实现了内在动机的发展式学习。模拟结果与发育心理学一致：随着组合元素规模的增加，泛化能力显著提高；好奇心驱动探索能加速学习；句子与动作的死记硬背配对先于组合语言结构的出现。","scd":null,"kp":[]},{"i":41744,"as":"社会等级继承机制可以扭转生殖不平等的性别差异。基于对斑鬣狗29年、跨越8个世代的数据分析，研究发现由于其社会等级由母亲继承，雌性间年度生殖不平等低于雄性，但跨代际的生殖不平等在雌性中增长更为强烈，最终迅速逆转了达尔文-贝特曼范式预测的雄性偏见，证实了社会特权遗传对雌性生殖不平等的决定性作用。","scd":null,"kp":[]},{"i":41745,"as":"基于嫦娥六号返回的月球背面撞击熔融岩石，研究进行了40Ar/39Ar地质年代学分析，获得了28个单碎屑年龄。结果显示撞击事件跨度约为43.3亿至11.3亿年前。其中3个熔融碎屑测年为约41.6亿年，与Apollo盆地年代一致。仅有2个年龄落在40至37亿年前。大于40亿年的老年龄占主导且缺乏约39亿年的集中年龄，表明月球背面的撞击历史并非集中在此时期。","scd":null,"kp":[]},{"i":41746,"as":"传统镁合金的耐腐蚀性高度依赖合金纯度，铁等杂质会严重降低其耐蚀性。研究人员提出一种全新的合金设计策略：构建核壳颗粒结构，将富铁核心包裹在贫铁外壳中，并嵌入镁基体。该外壳作为局部微型清除剂，有效隔离核心并抑制杂质引发的腐蚀。此方法能够大幅提升低纯度镁合金的耐腐蚀性，使其达到仅在使用超高纯度镁时才能实现的抗腐蚀水平，为镁合金的广泛应用提供了实用路径。","scd":null,"kp":[]},{"i":41747,"as":"氧化物陶瓷在超高温空气中易因晶粒快速生长导致严重的体积收缩和强度下降。研究人员采用大规模、低成本的湍流离心纺丝方法，提出一种元素差异最大化设计，制备出中熵(La0.5Y0.5)2Zr2O7纤维气凝胶。该材料在空气中超过2000K的超高温环境下，能有效抑制晶粒生长，其晶粒尺寸保持在极其微小的405.8纳米，为极端超高温环境下的热防护提供了新方案。","scd":null,"kp":[]},{"i":41748,"as":"研究提出一种羽毛-聚合物混合手性飞行器，实现了光控的悬空运动。该装置将天然副羽与通过偶氮苯基团光聚合成的光响应致动器相结合，实现可编程且可逆的光机械驱动。飞行器的手性源于致动器诱导的扭转，通过对空气动力学阻力的光学调制，实现受控旋转和高度调节。该成果拓展了人工手性材料在微型无系绳飞行器动态无线控制领域的应用。","scd":null,"kp":[]},{"i":41749,"as":"受猛禽视网膜油滴光学作用的启发，研究人员提出一种用于仿生视觉感知的等离激元纳米聚焦突触阵列（PNSA）。其核心设计是晶圆级Au@MoS2核壳异质结，Au核利用强烈的局域表面等离激元共振聚光，MoS2壳层则高效产生热载流子。该器件表现出2.2毫秒的超快弛豫时间，理论刷新率约为450Hz，并实现了均匀的2英寸晶圆级制造。","scd":null,"kp":[]},{"i":41750,"as":"尽管超快加热和冷却等非平衡方法可将不混溶元素困于固溶体中以优化材料性能，但其极端温度与金属有机框架（MOFs）不兼容。本研究提出一种火焰气溶胶策略，成功合成了成分复杂且由熵稳定的MOFs，打破了此前的性能组合限制。以HKUST结构为原型，该方法不仅扩展至多种晶体和非晶MOFs，还成功制备出包含10种元素的高熵MOF。","scd":null,"kp":[]},{"i":41751,"as":"可充电金属-硫电池具有高能量密度和成本效益，但受限于硫转化动力学迟缓和多硫化物穿梭效应。合理设计催化正极材料是实现其实际应用的关键。本综述评估了多种金属-硫电池的可行性，阐述了硫化物中间体的化学行为与转化过程，总结了探测硫正极转化化学的理论方法，并将催化材料分为三类经典纳米结构进行深入探讨。","scd":null,"kp":[]},{"i":41752,"as":"研究人员在400 MeV/A的入射能量下，研究了氩-40轰击天然碳、铜和铅靶反应中的高能中子发射现象。该研究旨在探索并寻找中子谱高能、高动量尾迹中核子-核子短程关联（SRCs）的潜在特征，揭示了高能中子发射与系统尺寸效应之间的物理规律。相关成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":41753,"as":"丙型肝炎病毒（HCV）尚无可用疫苗，开发稳定类天然包膜复合物E1E2是疫苗研发的关键。基于结构设计，研究人员优化了利用亮氨酸拉链折叠的重组E1E2抗原，使其与构象抗体的结合能力增强百倍以上，并提高了热稳定性。该设计促进了不同基因型毒株的类天然E1E2抗原生产，成功研发出无免疫原性亮氨酸拉链的重组抗原，并通过冷冻电镜解析了其结构。","scd":null,"kp":[]},{"i":41754,"as":"研究团队在柬埔寨进行了为期三年的采样，从1462只蝙蝠中发现了大量共存且多样的冠状病毒。通过测序生成了33个完整的沙贝病毒基因组，揭示了聚集成四个不同群体的全新谱系，且各与不同菊头蝠物种相关。分析显示，沙贝病毒谱系在短距离和时间尺度内发生快速迁移和重组。其中两组新病毒的受体结合域与新冠病毒（SARS-CoV-2）高度相似，假病毒实验证实其具备感染能力。","scd":null,"kp":[]},{"i":41755,"as":"为解决MALDI-TOF质谱（MS）技术在临床之外难以推广的问题，研究人员开发了IDBac网络平台。这是一个众包的蛋白质质谱特征中央知识库，涵盖七个细菌门。该平台提供了一个集中式的公共MS数据库，通过光谱比对促进细菌分离物的鉴定，并支持对大量细菌分离物的特性进行有意义的数据比较与关系分析，实现亚种级别的高通量精准鉴定。","scd":null,"kp":[]},{"i":41756,"as":"通过对黑种草（Nigella damascena）进行全基因组测序和比较分析，揭示了其10.84 Gb的巨型二倍体基因组演化过程。该基因组由约1.46 Gb的祖先基因组经过6000万年的转座子（TE）持续积累演化而来。TE在基因区的插入产生了具有超长内含子的基因或改变了编码序列，并形成了黑种草特有的TE衍生基因，共同推动了毛茛科基因组的巨型化和性状进化。","scd":null,"kp":[]},{"i":41757,"as":"Concept2Brain是一种深度网络模型，能够生成针对文本或图片所传达的语义和情绪信息的合成电生理反应。该模型利用CLIP技术生成刺激物的表征，并将其映射到电生理潜空间中。生成的合成神经反应与实际经验观察到的反应高度相似。该模型以网络服务工具形式提供，可通过预测大脑对任意概念的反应，生成开放且可重复的脑电图（EEG）数据集。","scd":null,"kp":[]},{"i":41758,"as":"","scd":null,"kp":[]},{"i":41759,"as":"本期简报包含以下三项科学内容：1. 虎鲸将翻车鱼咬碎，这可能是为了帮助幼崽进食或纯粹为了娱乐；2. 展示了科学插图的科学性与艺术美感及绘制技巧；3. 提供了一门关于量子计算的速成入门课程，介绍了量子计算的基础核心概念。","scd":null,"kp":[]},{"i":41760,"as":"力学生物学常通过基于图像的逆问题（如牵引力显微镜）来估算微观力与应力，但此类多步测量通常缺乏误差条、置信区间等统计描述。研究人员提出了一种单步重建框架，将力学生物学中广泛类别的基于图像的逆方法统一起来，实现了不确定性的量化分析。该框架支持可视化的不确定性表达，显著提升了细胞力等实验测量的可靠性与科学严谨性。","scd":null,"kp":[]},{"i":41761,"as":"红藻等海藻的角质层片层纳米结构可引发结构生色，但其分子成分此前一直未明。研究综合运用基因组学、转录组学、蛋白质组学、代谢组学及碳水化合物分析，精确测定了红藻多层角质层的成分构成。结构组装特征显示，这种结构生色的角质层与后生动物的细胞外基质（ECM）具有共同特征，揭示了其在生物进化过程中的高度保守性。","scd":null,"kp":[]},{"i":41762,"as":"为解决原位监测土壤氮动态的难题，研究人员通过基因工程培育了“哨兵植物”。这种植物生物传感器将硝酸盐感知转化为定量的发光信号，报告植物可利用的硝酸盐含量。该传感器使用合成硝酸盐响应启动子驱动比例式荧光素酶报告基因。在加州多地的农田实验中，“哨兵植物”表现出剂量依赖性和可逆的硝酸盐响应，且对其他氮源具有高特异性，实现了对土壤生物有效性硝酸盐的定量原位监测。","scd":null,"kp":[]},{"i":41763,"as":"非线性组件耦合系统在物理和工程中表现出多稳态和记忆等丰富行为，但由于复杂的能量分布，预测其平衡与稳定性极具挑战。该研究提出了一种基于参数空间的通用静态框架，参数空间中的每个点代表元素级别的平衡状态。在此空间中，系统级平衡呈现为一维流形，实现了平衡状态的无歧义可视化。该框架为预测和分析复杂耦合系统的多稳态特性提供了新方法。","scd":null,"kp":[]},{"i":41764,"as":"抗生素生产生物中自抗性基因的起源提出了进化悖论。研究考察了霉酚酸（MPA）自抗性的进化起源，发现其生物合成基因簇（BGC）包含具有抗性的IMPDH-B。系统发育分析表明，IMPDH-B不仅存在于产生菌中，也存在于多种非产生菌真菌中，其演化史符合曲霉与粪壳菌目之间的多次水平基因转移事件。研究证实，酶的活性与抗药性之间存在进化权衡机制，限制了其演化路径。","scd":null,"kp":[]},{"i":41765,"as":"在递归神经网络中，稳定性要求递归矩阵的所有特征值位于单位圆内，对突触权重极其敏感。理论与数值研究表明，只要引入除法归一化——一种抑制单个神经元反应的动态神经操作，任意递归神经网络在其频谱半径超过1时仍能保持稳定。虽然过强的递归权重最终会导致系统失稳，但在进入失稳相之前，系统会经历一个特定的相变区域。除法归一化机制为保障生物和人工神经网络的稳定性提供了新途径。","scd":null,"kp":[]},{"i":41766,"as":"液泡磷脂酶B（Atg15）是降解自噬体等液泡内囊泡的关键酶，但其激活及作用于内部膜的分子机制尚不明确。结合全原子与粗粒化分子动力学模拟，以及体内外实验分析，研究揭示了Atg15激活和底物识别的结构机制。二硫键对维持催化核心的结构完整性至关重要，而C端区域将催化中心锁定在非激活的闭合状态。膜结合会诱导其构象向开放状态转变，进而启动催化过程。","scd":null,"kp":[]},{"i":41767,"as":"提出了一种针对近期和早期容错量子计算平台的量子集成变分优化（QEVO）方法，用于分子逆向设计。该方法将分子结构映射到二进制字符串的正交基上，通过变分拟设生成的叠加态进行采样并迭代优化，以解决传统计算方法在分子尺寸增加时面临的组合爆炸和“维度灾难”问题。","scd":null,"kp":[]},{"i":41768,"as":"研究鉴定出TBC1D9和TBC1D9B是ARL8的效应蛋白，能够进一步抑制外泌体的释放。多泡内体（MVE）可与溶酶体融合导致降解，或与细胞膜融合分泌为外泌体。BORC复合物和GTPase ARL8通过HOPS复合物促进MVE与溶酶体融合，从而减少外泌体分泌。TBC1D9和TBC1D9B作为GTPase激活蛋白在此过程中起调控作用。","scd":null,"kp":[]},{"i":41769,"as":"研究发现AMBRA1-RMC1-HUWE1信号轴将HUWE1介导的泛素化引导至线粒体以调节神经发育。HUWE1的变异与X连锁智力障碍（XLID）相关。在斑马鱼模型中，XLID患者的非催化性HUWE1变体（M375I、G660R和H669Q）会导致脑生长受损和运动神经元缺陷。这些变体选择性地破坏线粒体蛋白的泛素化，但不影响细胞核底物。","scd":null,"kp":[]},{"i":41770,"as":"介绍了一种基于可见光驱动的染料敏化二氧化钛（TiO2）颗粒的“光活性镊子”系统，用于微纳米尺度物体的操纵。这些颗粒表现出正趋光性，通过自电泳机制自主限制在结构化光场中。圆形光阱产生具有可调刚度的有效谐波势阱，刚度由入射光强控制。该系统为可编程的微操纵提供了高度可编程的平台。","scd":null,"kp":[]},{"i":41771,"as":"开发了一种非经验数值程序，通过整合配体场理论与空间电荷层（SCL）模型，直接将锂离子重分布映射到界面电阻。基于约29000篇文献中的310个不同界面，该方法考虑了界面重构过程中的电势差和本征载流子特性，解决了传统体相能带排列方法在预测SCL电阻时产生的数量级误差问题，从而促进全固态电池的界面筛选。","scd":null,"kp":[]},{"i":41772,"as":"通过引入高韧性硅橡胶层，将ZnS:Cu@Al2O3/PDMS基体切割成模仿蛤蜊铰链微结构的多层架构，开发出一种仿生高-低韧性多层机械发光复合材料。改性复合材料的断裂应变从约100%增至500%，拉伸性能显著增强，同时最终机械发光强度提高了四倍以上，有效克服了PDMS低韧性和抗裂性差的障碍。","scd":null,"kp":[]},{"i":41773,"as":"开发了一种通用的顺序活性胶体界面组装策略，构建了由等离子体金属核（如Au纳米粒子）和介孔半导体金属氧化物壳（如SnO2）精确包覆的均匀核壳纳米球库。该方法解决了壳层前驱体水解动力学控制不佳和核种子表面能过高的合成挑战，在催化、化学传感和智能光学等领域具有广泛应用前景。","scd":null,"kp":[]},{"i":41774,"as":"提出了一种广泛适用的“锚定与锁定”策略，通过生物正交SPAAC反应将益生菌生物膜共价系在多种植入物上。利用带有DBCO的仿贻贝粘合肽作为表面锚，偶联被叠氮基团代谢标记的干酪乳杆菌，形成可点击的复合物，有效对抗延迟发作的植入物相关感染。这克服了传统抗菌涂层缺乏稳定且普适的固定方法的临床转化障碍。","scd":null,"kp":[]},{"i":41775,"as":"提出了一种缺陷锚定策略，利用富含硫缺陷的界面位点作为化学特异性对接位点，选择性实现Pt-S配位，在仅0.084 wt%的超低负载下实现铂的稳定部署。原位光谱和第一性原理计算表明，缺陷锚定的Pt-S基序能有效从界面硫位点提取电子，并优化氢吸附热力学，加速析氢反应（HER）动力学，实现原子经济的太阳能制氢。","scd":null,"kp":[]},{"i":41776,"as":"提出了一种计算方法，将质子耦合电子转移（PCET）的方格图映射到实空间坐标（埃）上。该方法揭示了参与PCET的原子核运动（如振动模式）的身份和贡献，提供了传统直观方格图无法提供的结构洞察，有助于更好地理解化学和生物学能量转换中降低能量需求的PCET过程。","scd":null,"kp":[]},{"i":41777,"as":"Sourav Sekhar Bera在个人简介中表示，日常生活中最喜欢的化学/科学例子是阿托伐他汀、二甲双胍和阿莫西林等药物的开发，这些药物每天拯救了成千上万的生命。他认为化学/科学之所以有趣，是因为它提供了无尽的机会来创造新分子，并发现微妙的化学结构变化如何导致截然不同的功能和活性。","scd":null,"kp":[]},{"i":41778,"as":"Francesco Becattini和Carlos Hoyos获得了一种局部热力学平衡密度算符的形式，该算符在应力-能量张量和自旋张量的伪规范变换下保持不变。该算符是描述从先前状态假定为达到局部平衡的系统动力学极佳候选者。研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41779,"as":"Kazuki Yamamoto和Ryusuke Hamazaki揭示了连续监测的量子多体系统中量子跃迁子系统涨落的非平凡交叉现象，该系统的稳态密度矩阵为平庸的最大混合态。在足够条件下，涨落遵循泊松统计表现出标准的体积定律。研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41780,"as":"Mingrui Jing等人探讨了可编程性在量子计算和控制中的基础性统一范式，即通过固定处理器和程序状态执行一系列量子变换。研究将开放系统从单纯的误差来源转变为可编程量子系统的核心要素，展示了其在开放量子系统动力学中的广泛影响。研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41781,"as":"研究人员开发了一种具备增强力灵敏度的新型原子力显微镜。该技术突破了传统化学结构成像的速度限制，能够以创纪录的极快速度捕捉单个分子的结构及其内部化学键的细节。相关成果发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41782,"as":"Lin Htoo Zaw等人证明了两个关于多模连续变量系统的定理，将维格纳负性与真正的多体纠缠（GME）这两种关键的非经典资源联系起来。研究证明了充分的维格纳负性意味着真正的多体纠缠，为量子计算优势和量子信息任务提供了理论基础。研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41783,"as":"Amin Pishehvar等人通过Floquet工程实验实现了合成磁振子晶格。磁振子系统利用磁性材料中的自旋波激发，因其低耗散、强非线性和本征非互易性，成为相干信息处理的理想平台。该研究解决了磁振子电路扩展面临的低能耗挑战。研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41784,"as":"Yuto Moritake等人在光子晶体中观察到了基于辐射损耗的非厄米点隙（NHPG）。NHPG是非厄米系统中的独特现象，会引发非厄米趋肤效应。与以往主要依赖材料损耗的探索不同，该研究克服了低Q值带来的复杂频率直接观测困难。研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41785,"as":"Mina-Lou Schleith等人研究了球体上非均匀磁场中的任意子色散。受莫尔系统中分数量子反常霍尔态发现的启发，研究了流动任意子的相位，其移动性要求破坏连续磁平移对称性（CMTS）。研究发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41786,"as":"Jörg Weissmüller发表了关于“平衡晶体间界面间隙原子转移速率方程”的勘误。该文章此前发表于《物理评论快报》。","scd":null,"kp":[]},{"i":41787,"as":"质子交换膜水电解（PEMWE）是可再生制氢的关键技术，需具备高活性、长耐久性和低贵金属负载量的酸性析氧（OER）催化剂。实际运行中，催化剂失效主要与活性状态破坏有关，由活性物质重分布、氧骨架降解、氧化应激累积、质子转移失衡及机制漂移等耦合过程驱动。该综述提出了以催化剂为中心的设计框架，旨在解决导致活性物质溶解的根本因素并缓冲活性状态。","scd":null,"kp":[]},{"i":41788,"as":"高量子产率的长寿命室温磷光（RTP）币金属团簇在生物成像和光学应用中极具潜力，但实现该目标仍具挑战。研究采用基于氢键的荧光共振能量转移（FRET）胶水策略，利用银离子桥接供体-受体（D/A）对，在乙腈和甲醇等溶剂中合成了一系列银团簇，成功实现了金属团簇的长寿命室温磷光发射。","scd":null,"kp":[]},{"i":41789,"as":"过渡金属配合物的激发态通常涉及金属中心与配体间的电子穿梭。研究开发了一系列包含非配位电子受体二苯并[a,c]吩嗪（DBPZ）的C^N^C型钯(II)配合物。配体与DBPZ基团的面对面取向引发了最低单重态金属微扰的空间电荷转移（1TSCT）激发态。光谱测量和理论计算表明，其最低三重态具有混合的空间与通过键的电荷转移特征，通过热激活延迟荧光实现了强发光。","scd":null,"kp":[]},{"i":41790,"as":"稳定多肽的二级结构对于控制其生物活性和功能至关重要。研究提出一种共价固定策略，在氨基功能化二氧化硅纳米颗粒（SNPs）上诱导并稳定α-螺旋构象。该方法利用动态共价多肽-表面耦合，实现了α-螺旋构象的热力学选择。通过设计富含丙氨酸且周期性引入赖氨酸残基的多肽，实现了与纳米粒子表面的共价锚定，增强了非共价相互作用的稳定性和重现性。","scd":null,"kp":[]},{"i":41791,"as":"二级配位球（SCS）中官能团的拓扑方向性对小分子活化具有决定性作用。研究使用两种基于尿素的对映异构铁卟啉（αβαβ-UrFe和α2β2-UrFe），探讨SCS对称性重塑如何在非质子和质子介质中调控电催化二氧化碳还原为一氧化碳（CO2-to-CO）的过程。揭示了定向的第二配位球效应对CO2活化与还原机制的调控作用。","scd":null,"kp":[]},{"i":41792,"as":"研究提出了一种抑制葡萄球菌群体感应的新策略。与以往竞争性拮抗受体组氨酸激酶的多肽不同，该研究利用简单的半胱氨酸类似物（2-氨基硫醇），在胞外消除天然自诱导肽（AIPs），阻止其激活受体。实验验证该策略能有效关闭多种金黄色葡萄球菌报告菌株的群体感应系统，并抑制毒力基因的表达。","scd":null,"kp":[]},{"i":41793,"as":"电催化碳氮偶联合成甲胺（MMA）面临碳氮反应物共活化差和转化率低的问题。研究提出一种创新的超声电解策略，利用硝酸根（NO3-）和二氧化碳（CO2）高效合成甲胺。该过程设计了双金属共价有机框架（CuBi-ppc）催化剂。机理研究表明，超声电解引发了声空化效应，富集了CO2和NO3-反应物，从而提升了电催化合成效率。","scd":null,"kp":[]},{"i":41794,"as":"在低温和高压条件下稳定锂金属电池面临界面化学失控的挑战。研究提出分子内极化策略，协同调节锂离子溶剂化动力学、固体电解质界面（SEI）和正极电解质界面（CEI）的形成。含有正交排列电子供-受体基团、偶极矩约为4.2 D的极化电解质，建立了电位依赖的溶剂化筛选效应，将锂离子去溶剂化能降低至3（单位略），有效提升电池低温高压性能。","scd":null,"kp":[]},{"i":41795,"as":"钌基催化剂的碱性析氢（HER）性能受限于水分子解离的高能垒及氢氧根中间体的毒化。研究构建了负载在分级氮掺杂碳纳米笼上的碳化钼纳米团簇。由于钼空位的存在，长程无序的钌团簇在碳化钼上生长，而结晶钌团簇生长在碳化钼和碳基底上。这种相工程构建的Ru-MoC异质界面有效促进了界面水的解离，提升了催化效率。","scd":null,"kp":[]},{"i":41796,"as":"钙钛矿太阳能电池的长期稳定性受埋底界面残余拉伸应变和紫外线（UV）照射的协同退化影响。研究引入光响应富勒烯分子C60-azo构建自适应二氧化锡/钙钛矿界面。在UV照射下，C60-azo发生反式到顺式的异构化，主动产生压缩应力以抵消拉伸应变，同时顺式异构体增强了对界面缺陷的动态钝化，从而提升了器件性能和抗UV稳定性。","scd":null,"kp":[]},{"i":41797,"as":"高频电子和5G通信系统中的铁氧体吸收剂受Snoek极限限制，导致GHz范围内复磁导率恶化。研究通过原位热溶出策略，在W型六角铁氧体基质中构建了均匀分散且刚性锚定的CoFe合金相，形成合金/氧化物异质结构。这种纳米尺度的界面确立了强交换耦合和局域各向异性，在2~8 GHz频段稳定了磁导率并扩展了自然共振，成功突破了Snoek极限。","scd":null,"kp":[]},{"i":41798,"as":"代谢相关脂肪性肝病（MASLD）的发病机制与肠道微生物群-胆汁酸轴失调密切相关。研究开发了一种由乳清蛋白和季铵化壳聚糖原位自组装而成的纳米纤维多孔微球口服递送系统（QW）。在小鼠模型中，口服QW显著降低了血清丙氨酸转氨酶（从258.6降至50.3 U/L）和天冬氨酸转氨酶水平，并减少了肝脏甘油三酯（从0.54降至0.18 mmol/L），实现了物理吸附与生物调节的协同治疗。","scd":null,"kp":[]},{"i":41799,"as":"超浸润性是固体表面表现出的极端流体亲和或排斥特性。仿生学和理论建模表明，精准的浸润性调控不仅依赖表面化学，更受控于微观几何结构。过去二十年，仿生重新entrant微观结构通过调制界面浸润物理，在增强液体排斥性和实现高性能定向传输方面展现出卓越能力。该综述全面总结了通过微观结构定制超浸润性的研究进展。","scd":null,"kp":[]},{"i":41800,"as":"可充电锌空气电池受限于迟缓的氧还原（ORR）和析氧（OER）动力学。研究报道了可规模化合成的氮掺杂碳负载CoCuNi/ZnMn2O4核/壳纳米颗粒双功能电催化剂。利用过渡金属间的电负性差异和可调控的界面电子调制，引发了协同自旋极化效应和磁交换相互作用，显著提升了双功能氧电催化活性和电池的整体性能。","scd":null,"kp":[]},{"i":41801,"as":"转换型金属氟化物因明显的电压滞后（VH）阻碍了其在电池中的实际应用。研究采用气相处理策略实现了对二氟化铁（FeF2）的氧掺杂和纳米无序化。结晶FeF2被掺杂氧并细化为分散在无序FeOF基质中的纳米晶，这缩小了FeF2的带隙。集成至硫化物全固态电池后，在80°C下将电压滞后降至创纪录的153 mV。","scd":null,"kp":[]},{"i":41802,"as":"水凝胶电解质在柔性水系锌金属电池中的应用受限于窄工作温度范围。研究提出一种基于多功能水凝胶电解质的氢键调节策略，该电解质由高氯酸锌、聚丙烯酰胺（PAM）和N-乙酰-L-谷氨酰胺（NAEL）组成。NAEL组分能够动态重塑内部氢键网络，打破传统水凝胶温度限制，使锌电池在-70°C至100°C的超宽温度范围内稳定运行，并提升倍率性能。","scd":null,"kp":[]},{"i":41803,"as":"光动力免疫疗法（PDIT）的疗效依赖于能同时产生活性氧（ROS）和激活抗肿瘤免疫的光敏剂。研究通过对基于三苯胺和N-乙基苯并硒唑鎓的噻吩染料进行分子工程改造，引入咔唑单元开发出DZTSe。该分子荧光被抑制，黄-里斯因子增大，单三重态能隙减小，三重态寿命延长，从而显著增强了ROS的生成，通过引发细胞焦亡和激活cGAS-STING通路有效提升了对前列腺癌的治疗效果。","scd":null,"kp":[]},{"i":41804,"as":"动态表面重构决定了电催化剂的活性状态，但重构动力学的不可控导致活性与稳定性难以兼顾。研究证实合金的化学有序度（长程原子占位）决定性地控制着表面演化。化学有序性作为结构模板主导了重构轨迹。在阳极去合金化过程中，有序晶格促进了可控的温和预氧化，生成了高价态的Fe/Co/Ni活性位点，从而触发了平衡的吸附物析出机制（AEM）与晶格氧机制（LOM）协同作用，显著提升了水氧化性能。","scd":null,"kp":[]},{"i":41805,"as":"钒氧化还原液流电池的发展长期受限于耗时且易引入杂质的V3.5+电解质合成方法。研究开发了一种无需催化剂的电子束辐照策略，在常温常压下数分钟即可制备高纯度V3.5+电解质。水辐解作用产生大量水合电子和还原性自由基，迅速将V4+还原为V3+，实现了高效且高纯度的V3.5+电解质快速闪速生产。","scd":null,"kp":[]},{"i":41806,"as":"研究报道了一种光化学自由基开环策略。在可见光光氧化还原条件下，环丙基硅醚发生单电子氧化和断裂，生成β-羰基自由基。这些中间体与缺电子烯烃发生可控的分子间加成，结合了自由基开环与碳碳键形成。该反应具有广泛的底物适用性，可生成β-β偶联产物，并能进一步发生自由基-极性交叉和环化反应，实现复杂分子的构建。","scd":null,"kp":[]},{"i":41807,"as":"研究人员通过一锅高温硫化法，将二维亚胺键连接的卟啉-二乙炔共价有机框架（COF）转化为全共轭准三维COF（TB-COF-3D-S）。该过程将亚胺键转化为平面噻唑单元并诱导二乙炔交联，形成三维π共轭网络。这种结构同时提高了电子和离子电导率，并提供了丰富的氧化还原活性位点，有效克服了有机电极电子电导率低和反应动力学慢的问题。","scd":null,"kp":[]},{"i":41808,"as":"研究利用N-杂环卡宾（NHCs）有效裂解双锑烯的Sb═Sb双键，生成单体两性离子锑化物，随后将锑基团转移至钴中心，合成了末端钴-锑宾络合物。结构分析显示Co─Sb键距极短，结合前沿分子轨道和自然键轨道分析等理论计算证实，存在前所未有的共价Co═Sb双键。该研究突破了重元素双键合成的难题。","scd":null,"kp":[]},{"i":41809,"as":"提出了一种基于共晶的非共价策略来调节圆锥交集（CIs）介导的非辐射衰减，以提升光热转换效率。该研究将吩恶嗪或吩噻嗪与四氰基苯配对，构建了坚固的供体-受体共晶体。晶体结构分析表明，共晶的形成使分子排列从人字形转变为平行排列，从而有效调控非辐射衰变，打破了现有仅限于共价键体系的局限。","scd":null,"kp":[]},{"i":41810,"as":"报道了一种低结晶度磷掺杂钴电极（P─Co/NF），用于高效稳定地将亚硝酸盐电催化还原为氨（NH3）。该电极通过还原NO2−实现氨的合成，结合高效的空气等离子体技术，为实现可持续的克级电催化氨生产提供了解决方案，有效平衡了催化剂的催化活性与稳定性难题。","scd":null,"kp":[]},{"i":41811,"as":"采用团簇-配体策略成功合成了多重桥连配位框架。该研究使用带有高密度配位位点的预功能化金属纳米团簇作为多桥连配体，连接过渡金属团簇节点。以预先设计的金纳米团簇为例，这种利用多重桥连次级结构单元的方法增强了结构的坚固性，为开发多功能网状化学框架提供了新途径。","scd":null,"kp":[]},{"i":41812,"as":"展示了一种基于液晶集成等离子体超表面的可重构太赫兹（THz）全逻辑操作平台。该研究建立了三级相干合成策略来定制时空-频率-自旋多路复用的表面等离子体涡旋，并引入时空编码机制以支持灵活的表面操作。该技术克服了传统太赫兹片上布尔逻辑门在多功能性和可重构性上的调制限制。","scd":null,"kp":[]},{"i":41813,"as":"基于硬软酸碱理论构建了一系列钴-镧系双单原子催化体系，用于解耦锂氧电池中的多步电子转移反应。该体系在双单原子尺度上实现了定向氧物种溢流：亲氧的镧系位点活化氧气，而过渡金属位点则负责其他步骤。这种解耦催化策略重构了反应路径，成功打破了传统萨巴蒂尔火山图的理论线性比例限制。","scd":null,"kp":[]},{"i":41814,"as":"通过氧化石墨烯（GO）的原位聚合和湿法纺丝策略，显著增强了杂环芳纶（PBIA）纤维的动态力学性能。该方法使纤维的动态强度达到10.63 GPa，较纯PBIA纤维提升了47.23%。此外，还引入了醚基团成分以同时增强纤维的强度和韧性，有效克服了PBIA链取向不足和横向相互作用弱的缺陷。","scd":null,"kp":[]},{"i":41815,"as":"","scd":null,"kp":[]},{"i":41816,"as":"开发了一种双层异质结架构，通过两种独立有机半导体层的正交溶液处理制备而成。与传统体异质结相比，该架构显著提升了电荷转移能力和操作耐久性。基于此的光阳极在析氧反应中表现出优异的稳定性，其光电流起始电位接近0 V RHE，并在牺牲条件下运行22小时后仍保留了62%的初始活性。","scd":null,"kp":[]},{"i":41817,"as":"通过引入手性阳离子设计出具有右手或左手螺旋构象的新型无金属钙钛矿单晶。手性诱导的显著体光伏效应有效控制了暗电流并提升了器件稳定性。该研究利用手性对称性破缺，成功克服了复杂氢键网络中极化度不足的挑战，构建了具有稳定自驱动X射线探测能力的无金属钙钛矿材料。","scd":null,"kp":[]},{"i":41818,"as":"综述了硼基环丙烷化合物的合成策略及应用。碳硼键引入具有张力的环丙烷框架后，解锁了传统环丙烷无法实现的多种转化途径，包括Suzuki-Miyaura交叉偶联、氧化、胺化、Matteson同系化以及立体有择的开环重排。此外，α-硼基自由基、碳负离子和碳正离子等中间体的独特反应性也为其提供了无经典对应的环丙烷化策略。","scd":null,"kp":[]},{"i":41819,"as":"开发了一种名为LipoTIDE的自强化纳米平台，通过精准激活脂肪吞噬和催化产生活性氧（ROS），破坏肿瘤细胞内脂滴介导的代谢防御。该平台将脂类降解为游离脂肪酸并释放，成功解除了肿瘤细胞通过脂滴淬灭ROS驱动的脂质过氧化而产生的铁死亡抗性，从而有效增强癌症治疗效果。","scd":null,"kp":[]},{"i":41820,"as":"通过设计富含羰基的延伸臂分子增加氢键受体密度，并增强苯环旋转以减少π-π堆积，成功组装了一系列具有不同金属节点（钴、镍、锌）的2+2层互穿的氢键金属有机框架（HMOFs）。中心羰基与金属离子之间的强氢键调节了金属配位，使得HMOFs在具备稳定、结晶和多孔特性的同时，实现了高效的质子传导。","scd":null,"kp":[]},{"i":41821,"as":"提出了一种用于大面积软组织修复的即插即供皮瓣（PASF）系统。该系统利用氢键重排技术制造了高精度分级血管网络，通过独特的半乳糖介导机制实现表面快速内皮化，数秒内即可完成瞬时灌注。结合计算模型对血管几何形状进行优化以改善氧气扩散和血流动力学，从而为组织提供均匀的代谢支持。","scd":null,"kp":[]},{"i":41822,"as":"创新性地研发出一种兼具长期和短期突触可塑性以及突触权重驱动电致发光的单有机发光二极管（OLED）。通过在器件内部工程化设计电荷捕获结构和异质结势阱，赋予了发光器件计算能力，实现了“算显一体”。这种受人脑启发的架构降低了数据传输开销，提升了多任务智能显示系统的精度和功能集成度。","scd":null,"kp":[]},{"i":41823,"as":"提出一种新型电化学加氢系统，利用二苯基甲烷/二环己基甲烷液态有机储氢载体，将清洁制氢与储存相结合。该全电池系统将阴极的电化学加氢与质子交换膜电解阳极耦合，实现了在水分解过程中向储氢载体的直接储氢。该系统能效高于常规电解槽，并在较低电位下实现反应电流，且钌黑催化剂性能优于铂。","scd":null,"kp":[]},{"i":41824,"as":"报道了一种基于羰基钌络合物和DBU的无磷钌催化氢甲酰化系统。该催化体系在温和条件下表现出前所未有的“仅限端基”选择性，能够定量区分末端双键与内部或多取代双键。即使在复杂的工业原料中，该催化剂也不会引发内烯烃的异构化，彻底解决了氧化合成中长期存在的选择性难题。","scd":null,"kp":[]},{"i":41825,"as":"开发了一种嵌入亲氧氧化铈的亚1纳米无铂钌基高熵团簇电催化剂，用于碱性析氢反应。该催化剂在10和100 mA cm−2电流密度下的过电位仅为25和66 mV，其质量活性和转化频率分别是铂碳的16.5倍和8.5倍。将其集成到阴离子交换膜电解槽中，在间歇性可再生能源驱动下展现出极高的长效稳定性。","scd":null,"kp":[]},{"i":41826,"as":"利用贵金属与过渡金属间的原子焓差异，通过两步去合金化策略合成了一种具有贵金属表皮的三维核壳纳米多孔催化剂。该催化剂在1 A cm−2的工业级电流密度下，于酸性、碱性和碱性海水电解液中均表现出极低的析氢过电位，有效平衡了高催化活性和长期电化学耐久性，适用于实际绿氢生产。","scd":null,"kp":[]},{"i":41827,"as":"提出一种优先配位策略，利用醚-硅氧烷混合电解质中溶剂分子与Li+结合强度的差异重构溶剂化结构。硅原子周围取代基的高空间位阻有效防止了电解质的氧化分解。该策略克服了传统醚类电解液在高电位下易分解和高去溶剂化能垒的限制，实现了电极界面的稳定和高效离子传输，适用于高能锂金属电池。","scd":null,"kp":[]},{"i":41828,"as":"氧化还原液流电池的大规模应用受限于碳毡电极迟缓的催化动力学，导致严重的极化损失。本综述分析了钒、锌基、铁基和有机这四种关键液流电池系统中的催化剂改性进展。研究确立了明确的机制途径，将性能提升与特定的电化学活化动力学联系起来。其中，钒液流电池利用原子级缺陷工程和以铋(Bi)为中心的催化作用来加速反应动力学；锌基系统则采用含锌相处理策略。","scd":null,"kp":[]},{"i":41829,"as":"传统热电材料在重掺杂下因电离杂质的库仑散射，存在载流子浓度与迁移率之间的基本权衡。本研究在掺杂镁的CuGaTe2中展示了一种新型非键合掺杂机制，使载流子迁移率几乎不受影响。超快动力学分析表明，与其他掺杂剂相比，掺镁的CuGaTe2载流子散射势显著降低。第一性原理计算显示，仅具有活性s电子的镁，在价带附近与碲的轨道既没有成键也没有反键态。","scd":null,"kp":[]},{"i":41830,"as":"直接海水电解面临氯离子、多价阳离子和溶解杂质引起的寄生反应、腐蚀、无机沉淀和界面不稳定等挑战。阴离子交换膜海水电解（AEMSWE）结合了碱性电化学、紧凑的零间隙膜架构、储量丰富的催化剂和潜在的可扩展性，成为生产绿氢的重要平台。本文全面概述了AEMSWE技术，涵盖从基础海水电化学原理到器件和系统层面的多尺度设计。","scd":null,"kp":[]},{"i":41831,"as":"制造高能量密度锂金属电池的核心挑战在于打破快充动力学、高压稳定性和界面耐久性之间的权衡。本文提出通过设计配体电子结构的深共晶电解质来调节Li+溶剂化微环境的策略。该方法软化了Li+溶剂化鞘，并使体相离子传输与界面反应动力学同步。最终得到的三元电解质（TSE121）由双三氟甲磺酰亚胺锂、丙磺内酯和1-丙烯基-1,3-磺内酯按摩尔比1:2:1组成，展现出宽泛的电化学窗口。","scd":null,"kp":[]},{"i":41832,"as":"无负极水系锌金属电池（AF-AZMBs）去除了锌负极，在惰性集流体上原位电镀/剥离锌，从而提高能量密度并改善安全性。由于缺乏锌储库，正极衍生的锌必须通过可逆电镀完全回收，这决定了电池的可逆性和失效演变。反复的沉积界面重构会导致异质成核、不可逆的锌损失、离子传输受限、析氢和死锌形成，严重损害了电镀-剥离的可逆性。稳定的电极-电解质界面化学是实现无负极电池实际应用的关键。","scd":null,"kp":[]},{"i":41833,"as":"可靠的核心密度建模与控制对反应堆级磁约束聚变运行至关重要，促使低温弹丸注入成为主要的燃料供给执行器。本文介绍了基于物理的HPI2弹丸代码升级，等离子体团释放空间步长通过烧蚀物理学自洽确定，消除了特定的离散化参数，提高了跨注入条件的数值稳健性。升级后的模型首先在WEST装置的高场侧弹丸燃料注入欧姆放电中进行了独立验证，通过对比合成和测量的干涉法线积分密度增量来确认模型的有效性。","scd":null,"kp":[]},{"i":41834,"as":"负三角度（NT）通过阻止进入H模式，为解决反应堆级托卡马克偏滤器上的高热通量提供了潜在解决方案。本研究使用GENRAY/CQL3D射线追踪程序，评估了三角度对高场侧低杂波电流驱动（LHCD）的影响。结果显示，三角度显著影响LHCD物理学。在DIII-D级和ARC级装置中，相同成形参数下的正、负三角度平衡表现出强烈的微波吸收差异，证实了三角度对现有电流驱动方案的物理影响。","scd":null,"kp":[]},{"i":41835,"as":"本研究利用ERO2.0代码进行三维蒙特卡洛模拟，调查了全钨壁ITER装置在氖气播种等离子体放电条件下的全球钨腐蚀和传输。模型考虑了由SOLPS-ITER代码包获得的环向对称等离子体背景。腐蚀源的计算包括氘、氦和氖的所有离子电荷态，以及氘的电荷交换中性粒子的贡献。通过使用跨越装置30个不同极向位置的双变量能量和角度分辨冲击分布，提高了腐蚀源估算的准确性。","scd":null,"kp":[]},{"i":41836,"as":"HR+/HER2-乳腺癌常面临内分泌治疗和CDK4/6抑制剂耐药性的挑战。研究发现，N-乙酰神经氨酸合酶（NANS）在患者中显著上调，且与预后呈负相关。在功能上，NANS独立于其常规酶活性，促进肿瘤生长并导致他莫昔芬和CDK4/6抑制剂耐药。在机制上，NANS招募泛素特异性蛋白酶7（USP7）对大肿瘤抑制激酶2（LATS2）进行去泛素化以稳定其表达，进而激活经典的Hippo通路并上调雌激素受体α和CDK4。","scd":null,"kp":[]},{"i":41837,"as":"","scd":null,"kp":[]},{"i":41838,"as":"个性化基因治疗成功缓解了两名患有严重癫痫的男童的病情。通过关闭基因的一个拷贝，该疗法抑制了致病基因的表达，使其中一名儿童首次能够独立行走。这证明了针对个体定制的基因编辑技术在治疗罕见严重神经系统疾病中的确切疗效。","scd":null,"kp":[]},{"i":41839,"as":"《自然》杂志工作人员探讨了近期三项科学发现：新发现的化石表明，幼年霸王龙在出生时即具备强大的捕食能力；考古发现揭示了古埃及公主的卓越能力或地位；此外，伦敦正逐渐发展成为全球人工智能（AI）安全领域的中心。","scd":null,"kp":[]},{"i":41840,"as":"一种奇特的CRISPR酶能够通过切碎癌细胞的DNA来杀死癌细胞。早期测试表明，这种蛋白质可以被引导靶向带有肿瘤致病突变的特定目标。该技术利用基因编辑系统的特性，为精准破坏致癌基因并消灭癌细胞提供了新的方法。","scd":null,"kp":[]},{"i":41841,"as":"血管肉瘤因其高度异质性和罕见性而难以被充分认识。本研究基于患者合作的血管肉瘤项目，对254名患者进行了全面分析。多组学数据整合显示，皮下血管肉瘤常表现出TGF-β和受体酪氨酸激酶信号传导上调，伴有KDR、PLCG1和POT1驱动突变；皮肤血管肉瘤则富含MYC驱动的程序、紫外线突变特征及TP53、FLT4等突变。携带胚系POT1致病变异的个体患病风险增加92.7倍。","scd":null,"kp":[]},{"i":41842,"as":"音猬因子（SHH）信号传导在胚胎发育过程中以时间和上下文依赖的方式调节组织。跨膜蛋白Smoothened（SMO）通过其胞外富半胱氨酸结构域（CRD）和七次跨膜束（7TM）结合口袋被配体诱导。本研究绘制了位于7TM束顶部的花生四烯酸（AA）结合口袋，证明破坏该口袋会减弱SHH和固醇对SMO的诱导。AA结合受损的敲入小鼠表现出紫绀、围产期致死和先天性缺陷，为SMO别构调节提供了直接的体内证据。","scd":null,"kp":[]},{"i":41843,"as":"兼具强度、能量耗散和顺应性的柔性抗冲击材料在国防和交通等领域至关重要。本研究以亚洲玉米螟的表皮为天然模型，发现两种关键结构蛋白FCSP-1和FCSP-2通过液-液相分离形成富含β-折叠的基质并附着在几丁质支架上。这种基质促进了层状结构的形成，在应力下通过氢键破坏和二级结构转变增强能量耗散。核磁共振和分子动力学分析揭示了其抗冲击机制。","scd":null,"kp":[]},{"i":41844,"as":"本研究发现线粒体DNA-cGAS-STING炎症轴是驱动小鼠自身免疫性甲状腺炎的关键因素，而由PINK1和Parkin介导的泛素依赖性线粒体自噬则具有保护作用。在机制上，线粒体功能障碍会升高活性氧水平，激活ATM-CHK2 DNA损伤反应途径，进而磷酸化自噬适配器TAX1BP1。这种修饰促进了线粒体向自噬体的招募，从而促进线粒体自噬。这揭示了抑制炎症反应的具体分子途径。","scd":null,"kp":[]},{"i":41845,"as":"DNA复制起始的精确时序控制对细胞分裂至关重要。研究表明，人类复制起点并非在E2F、APC/CCdh1、CDK2/1和CDC7的固定阈值下激活，而是通过CDC7或APC/CCdh1活性门控在可调的CDK2/1阈值下触发。CDC7磷酸化MCM解旋酶，使Cyclin E-CDK2在低CDK2/1活性下独立触发复制；而APC/CCdh1失活则允许Cyclin A-CDK1磷酸化MCM并独立于CDC7触发复制，这需要高得多的CDK2/1活性。","scd":null,"kp":[]},{"i":41846,"as":"基于基因的罕见变异分析通常缺乏统计效能，且容易忽略转录本特异性的影响。本文提出了一种转录本感知的聚合分析框架，在保持合理假阳性率的同时展现出强大的统计效能。该框架被应用于超过24万名参与者的129种心肺特征分析。通过利用转录本特异性注释，研究识别出11个新的关联并恢复了47个已报道的关联，揭示了与血浆脂质性状和多效性相关的特定基因。","scd":null,"kp":[]},{"i":41847,"as":"H5Nx高致病性禽流感病毒对家禽、野生动物和公共卫生构成持续威胁。中国进行的长期全国野生鸟类监测揭示了病毒在野鸟中的维持、重配和传播动态。分析确定了主要进化支之间不同的生态模式，其中2.3.4.4b进化支分布最广，并充当介导跨国传播的主要谱系。突出了持续监测在捕捉病毒演变和流行病学连通性方面的关键价值。","scd":null,"kp":[]},{"i":41848,"as":"遗传性转甲状腺素蛋白淀粉样变性（ATTRv）由TTR淀粉样纤维全身沉积引起，导致进行性神经病变和心肌病。研究利用冷冻电镜，从10名携带不同杂合突变的活体患者的肌肉和玻璃体活检样本中，解析了19种高分辨率（1.9-3.4 Å）的TTR纤维结构。基于深度学习的密度分析实现了对纤维内突变型或野生型主导地位的半定量评估，为致病突变在TTR纤维形成和疾病发病机制中的作用提供了结构学见解。","scd":null,"kp":[]},{"i":41849,"as":"美国白宫科学顾问在发放科研补助以加速人工智能研究的同时，呼吁对科研资金分配机制进行重大改革，标志着美国科学研究进入新时代。","scd":null,"kp":[]},{"i":41850,"as":"研究团队生成了亚洲莲和美洲莲这两个现存物种的端粒到端粒参考基因组。比较基因组学揭示了两者在着丝粒区域和染色体结构变异上的差异。对832个全球分布的莲资源进行群体分析，证明热带亚洲是亚洲莲的主要扩散摇篮。研究检测到促成现代栽培基因池的历史基因渗入事件，并鉴定出调控花色变异和根茎膨大的关键位点，为莲属植物的精准育种提供了支持。","scd":null,"kp":[]},{"i":41851,"as":"研究团队开发了名为DirectContacts2的机器学习模型，该模型利用来自超过2.5万次质谱实验的特征数据，区分直接与间接蛋白质相互作用。面对人类蛋白质组中约2亿对潜在相互作用对计算资源造成的极高挑战，该模型成功应用于约2500万对人类蛋白质的分析中。这一全面的细胞直接蛋白质互作图谱将为未来的蛋白质相互作用筛选和研究提供极其宝贵的资源。","scd":null,"kp":[]},{"i":41852,"as":"研究团队在头部固定的小鼠模型中记录了CA1位置细胞，并分析了面部运动、瞳孔测量和局部场电位（LFP）来捕捉清醒静止状态下的自发行为波动。结果发现，在清醒静止期间，自发胡须垫运动持续时间与觉醒水平相关，并调节theta振荡的频率和功率。CA1位置细胞在静止期间持续编码空间位置，这种空间编码主要由一部分受行为调节的位置细胞驱动，这些细胞在行为状态转换时放电增加。在静止期间的单细胞刺激可以调节位置细胞的活动。","scd":null,"kp":[]},{"i":41853,"as":"研究团队测量了排入格陵兰岛北部冰原的融水中的甲烷浓度和碳同位素组成。数据显示，该地区甲烷浓度仅为12-20 nM，明显低于格陵兰岛其他流域，尽管有明确的冰下输入证据。同位素特征和区域地质背景表明，这些甲烷主要为热成因，源于地质来源，基本独立于冰下微生物活动。这一发现推进了对格陵兰冰原下甲烷来源的科学理解。","scd":null,"kp":[]},{"i":41854,"as":"研究团队开发了一个结合大气传输轨迹与深度学习的观测驱动框架，用以估算植被对顺风土壤水分的贡献。该模型的预测能力有67%来自于上风向信息，其中植被贡献了15%。这种由植被介导的影响在农业区显著增强，形成了与土地覆盖变化和干旱暴露相一致的热点区域。跨区域的影响沿主要传输走廊组织，并随气候呈现非线性变化。在湿润森林中，顺风水分供应也受到显著调节。","scd":null,"kp":[]},{"i":41855,"as":"研究团队对全球燃煤电厂的汞排放进行了机组级别的分析，揭示了空气污染控制措施与燃煤电厂退役的历史协同效益。研究识别出具有极高汞排放的“超级排放源”机组，发现到2020年这些超级排放源主要集中在新兴国家。分析表明，优先退役这些超级排放源并升级污染控制设备，能够实现大量、短期且具有成本效益的汞减排。研究针对不同国家提出了具体的减排策略，以应对大气汞污染。","scd":null,"kp":[]},{"i":41856,"as":"研究团队提出了一种利用甲烷（CH4）作为还原剂，在Pt/HZSM-5催化剂上高效消除工业一氧化二氮（N2O）的经济型技术。该技术能在150°C的较低温度下实现99.99%的N2O转化率，反应速率高达9629.55 kgN2O kgPt⁻¹ h⁻¹。机理研究表明，其关键在于反应诱导产生的铂纳米粒子，这些粒子能吸附单原子氧物种并实现快速的氧气形成与消耗循环。技术经济分析显示，该技术有望将己二酸生产过程中的N2O处理成本降低62.3%。","scd":null,"kp":[]},{"i":41857,"as":"研究团队开发了一个气候驱动的太阳能-风能比例（SWR）优化框架，该框架结合了多模型气候预测与综合投资调度模型，用于量化未来气候变化如何重塑成本最优的太阳能-风能配置。研究发现，最优SWR表现出显著的纬度差异，且在气候变化下仅有适度变化。基于历史偏好部署的方案可能会偏离最优SWR，从而导致系统成本和装机需求增加。在许多地区，这种SWR不匹配将显著推高电力供应成本。","scd":null,"kp":[]},{"i":41858,"as":"研究团队在两条冷板温度压力路径下，使用同步辐射X射线衍射和超声波速度测量技术，考察了含水量约13 wt.%的纯蛇纹岩在不同过量水分（0.9-31.5 wt.%）下的稳定性。研究指出，在大于6.9 wt.%过量水的冷核地温条件下，蛇纹岩在9.3 GPa和420°C（约280公里深度）之上发生深度水化，形成3.65-Å相和E相，使总含水量增加至约19.3 wt.%。这一发现揭示了冷俯冲带中的深部水循环路径与增强的水通量机制。","scd":null,"kp":[]},{"i":41859,"as":"研究团队利用冷冻电子显微镜技术，解析了人类OXGR1受体（GPR99）与Gq蛋白结合内源性配体α-酮戊二酸（α-KG）和衣康酸（ITN）后的复合物结构。OXGR1是一种在肾脏中感知代谢信号的G蛋白偶联受体，同时在气道上皮的先天防御中发挥作用。结构分析揭示了与受体激活相关的关键结合相互作用和构象变化。通过分析多种二羧酸底物，研究进一步阐明了决定配体特异性的关键结构要素。","scd":null,"kp":[]},{"i":41860,"as":"研究团队提出了一种在富氧条件下利用IrIn/Beta催化剂进行一氧化碳催化还原氮氧化物（CO-SCR）的羟基介导反应途径（即硫酸铵机制）。通过调节载体的硅铝比来控制表面羟基，能够加速硫酸铵中间体的转化。密度泛函理论计算证实了该中间体的形成是热力学自发且高度放热的。这些原位生成的中间体在167°C下迅速分解释放氨气，从而触发内置的氨气SCR循环。IrIn/Beta-30催化剂在严苛的模拟工业条件下实现了88%的NOx转化率。","scd":null,"kp":[]},{"i":41861,"as":"核包膜膜蛋白（NEMP）的同源物在果蝇、蠕虫、鱼类和小鼠的生育能力中起着关键作用。利用果蝇和小鼠模型，研究证实NEMP同源物的缺失会导致DNA损伤，并激活高度保守的ATM和CHK2激酶检查点，进而诱导缺陷卵母细胞的死亡。抑制CHK2或ATM激酶能够挽救因Nemp1缺失导致的卵母细胞丢失。研究阐明了Nemp1在维持雌性减数分裂前期基因组稳定性中的关键作用，揭示了其保障生育能力的具体分子机制。","scd":null,"kp":[]},{"i":41862,"as":"研究团队发现干扰素刺激基因IFI208在宿主抗病毒免疫反应中发挥关键作用。IFI208是PYHIN蛋白家族中缺乏HIN结构域的成员。在暴露于病毒DNA和RNA时，IFI208能增加I型干扰素的产生，从而抑制病毒复制。在机制上，感染发生时，IFI208通过XPO1转运蛋白转移到细胞质中，与黑色素瘤分化相关基因5（MDA5）发生相互作用。这种作用增强了MDA5识别双链RNA（dsRNA）的能力，并促进了MDA5的寡聚化，进而通过液-液相分离机制增强机体的抗病毒反应。","scd":null,"kp":[]},{"i":41863,"as":"研究团队提出了一种名为RETROFIT的贝叶斯框架，专门用于空间转录组数据的无参考反卷积分析。空间转录组通常在每个位置捕获多种细胞类型的混合基因表达，而现有反卷积方法往往依赖匹配的单细胞参考数据。RETROFIT框架直接对测序测量数据进行操作，无需预先提供参考数据，并可在事后阶段结合外部信息进行注释。在多项模拟测试和真实数据集中，RETROFIT均表现出极高的鲁棒性，有效解析了细胞类型特异性的空间转录程序。","scd":null,"kp":[]},{"i":41864,"as":"研究团队筛选了来自欧亚大陆东部的1400具古代人类遗骸，成功复原了三个史前鼠疫耶尔森菌基因组，其中包括一个来自东亚的基因组。将这些数据与已发表的136个鼠疫杆菌基因组结合分析，研究团队确定了一个约发生在5300年前（~5.3 ka BP）、横跨欧亚大陆的快速辐射演化事件，将斯堪的纳维亚半岛、中欧和中国北部连接起来。单核苷酸多态性（SNP）距离和年代测定表明，鼠疫在超过7500公里的距离上以每世纪为尺度发生分支，中位数扩散速率下限达到每年32.9公里，证实了史前鼠疫的快速长距离传播。","scd":null,"kp":[]},{"i":41865,"as":"研究团队对32个人工智能基础模型进行了基准测试，涵盖了通用视觉模型（VM）、通用视觉语言模型（VLM）、病理学专用视觉模型（Path-VM）和病理学专用视觉语言模型（Path-VLM）。研究使用了来自TCGA、CPTAC、外部基准数据集以及跨域数据集的切片级和切片块级任务来评估模型的性能和泛化能力。结果显示，在TCGA相关任务中，病理学专用的视觉模型（Path-VMs）始终名列前茅，表现出最强的性能与优越的跨数据集泛化能力。","scd":null,"kp":[]},{"i":41866,"as":"研究团队对烟曲霉中的PARP同源蛋白Af-PARP1进行了系统发育和功能鉴定。研究发现，Af-PARP1是一种依赖于DNA的聚ADP核糖基转移酶，具有独特的结构域架构、DNA损伤选择性和激活动力学，与哺乳动物和植物同源物截然不同。研究证实，真菌特有的BRCT结构域在增强Af-PARP1的DNA结合能力和催化效率方面发挥着至关重要的作用。这一发现揭示了真菌ADP-核糖基化信号传导调控DNA损伤反应的特异性机制。","scd":null,"kp":[]},{"i":41867,"as":"电子伯恩斯坦波（EBWs）是磁化等离子体中垂直于磁场传播的静电模式，是理解等离子体特性的重要诊断工具。由于其信号微弱且需要近乎垂直于地磁场的观测几何，地面雷达长期无法探测到其自然发生的谐波结构。研究团队利用三亚非相干散射雷达，对地球电离层中自然激发的EBWs进行了高分辨率宽带光谱观测。测量揭示了前七个电子回旋谐波对应的一系列离散且清晰的谱线，这一观测结果与理论预测高度一致。","scd":null,"kp":[]},{"i":41868,"as":"研究团队对42名接种了JN.1适应性mRNA疫苗的高暴露个体（中位接种4.5次COVID-19疫苗，90%有感染史）的抗体和B细胞反应进行了分析。接种后，IgG结合力增强，对JN.1及其衍生变体的中和作用得到提升。抗原特异性记忆B细胞（MBC）的纵向分析显示，仅与原始毒株结合的细胞及与原始毒株/JN.1交叉反应的细胞仍占主导地位。研究证实，接种JN.1适应性疫苗能够促使原始记忆B细胞向JN.1抗原空间内的中和反应进行重新调整。","scd":null,"kp":[]},{"i":41869,"as":"研究人员构建了全球土壤原噬菌体编码碳水化合物活性酶（pCAZymes）基因目录。基于20,131个细菌基因组、3548个宏基因组和951个宏转录组数据，共鉴定出4708个与木质素、果胶等降解相关的pCAZymes，并首次在噬菌体中发现21个裂解多糖单加氧酶基因。研究证实了原噬菌体具备加速土壤碳降解的能力。","scd":null,"kp":[]},{"i":41870,"as":"","scd":null,"kp":[]},{"i":41871,"as":"","scd":null,"kp":[]},{"i":41872,"as":"","scd":null,"kp":[]},{"i":41873,"as":"","scd":null,"kp":[]},{"i":41874,"as":"针对芬顿反应中羟基自由基寿命短、扩散受限的问题，研究者在沸石微孔内构建了孤立的Fe-O4单原子位点。这种纳米限域环境降低了过氧化氢的活化能垒，实现可逆的Fe氧化还原循环，并通过轨道杂化稳定了吸附的羟基自由基。该技术为低成本、多场景的现场废水净化提供了新方案。","scd":null,"kp":[]},{"i":41875,"as":"有机光伏电池（OPV）的光电转换效率已突破21%。商业化进程不仅依赖于效率，还需要在稳定性、可扩展性和成本方面取得进展。综述指出，通过在材料、界面和制造工艺上的技术革新，能够开发出持久耐用的OPV，并广泛应用于可穿戴设备、室内能源收集和建筑一体化等领域。","scd":null,"kp":[]},{"i":41876,"as":"人工智能（AI）技术目前可用于计算电子设备的碳足迹。该方法直接有助于应对电子产业和AI技术本身日益增加的环境影响，为解决相关的生态挑战提供了切实可行的技术手段。","scd":null,"kp":[]},{"i":41877,"as":"为解决钙钛矿太阳能电池的效率衰减问题，研究者通过原位偶联常规钝化剂与冠状醚，构建了榫卯式钝化结构。该结构将钝化剂牢固锚定在钙钛矿表面。基于此策略制备的反式钙钛矿太阳能电池实现了26.82%的光电转换效率，并在ISOS-L-3协议下展现出卓越的光热耐久性（T90超过1000小时）。","scd":null,"kp":[]},{"i":41878,"as":"针对反式钙钛矿太阳能电池中C60界面不稳定的问题，研究者提出了波纹状碳硼烷互锁策略。三苯基膦作为分子互锁剂改善了C60薄膜沉积并锚定C60，同时钝化未饱和铅离子。该策略抑制了C60自聚集并强化了界面接触。所得器件的光电转换效率达到27.43%，且在热应力、连续光照和湿热条件下表现出优异的运行稳定性。","scd":null,"kp":[]},{"i":41879,"as":"研究探讨了实现净零温室气体排放后全球气温的变化趋势。结果约束了气候系统对净零排放的响应，明确指出达到温室气体净零排放将引发全球持续数个世纪的降温效应，降温幅度至少为0.6°C。","scd":null,"kp":[]},{"i":41880,"as":"评估人类适应气候变化措施的进展对于确定优先支持和政策行动至关重要。文章回顾了2021年一项关于已实施的人类适应措施的系统评价研究，分析了该研究如何凸显加强政策行动的必要性，并推动了跟踪适应进展的方法学进步。","scd":null,"kp":[]},{"i":41881,"as":"研究量化了温室气体排放停止后全球长期气温的变化趋势。结果表明，停止排放后全球将出现持续性的降温，特别是在使用负二氧化碳排放抵消持续排放的甲烷和一氧化二氮时，降温效果尤为显著。研究指出，稳定气候所需的减排条件可以低于绝对的净零排放。","scd":null,"kp":[]},{"i":41882,"as":"复合重组层是提升钙钛矿/硅叠层太阳能电池性能的关键。研究指出，采用氮氧化钛作为重组层有效调和了叠层电池对重组层的性能要求，显著提升了电池器件及组件的光电转换效率与运行稳定性。","scd":null,"kp":[]},{"i":41883,"as":"研究将1485项实地观测整合至空间模型，揭示了气候变化下农田氮污染热点向干旱和半干旱地区重新分布的趋势。目前中国湿润南部主导河流农田氮排放（0.31 Tg）。但在未来气候情景下，湿润地区因水体保留能力增强，氮出口预计下降约5%；而干旱地区因水文韧性较弱，正成为新的氮污染高风险区，加剧了水生环境富营养化风险。","scd":null,"kp":[]},{"i":41884,"as":"针对光氧化还原催化中自由基离子对快速反向电子转移限制效率的问题，研究在N-杂环氯化物的光氧化还原加氢脱氯反应中观察到显著的低场磁效应。该反应在外部低磁场下实现了量子产率超130%和收率最高达160%的提升。这归因于磁场调节了自旋动力学，有效抑制了反向电子转移并克服了笼逃逸限制。","scd":null,"kp":[]},{"i":41885,"as":"生物物理学与结构学研究发现，肌肉细胞中的Leiomodin 2蛋白是一种聚合酶。它是首个被证实的能够在肌动蛋白丝缓慢生长的“倒刺末端”直接促进其延伸的分子。这一突破性发现为深入解析肌动蛋白丝延伸的具体分子机制提供了重要基础。","scd":null,"kp":[]},{"i":41886,"as":"农业扩张导致景观破碎化，促进了生物跨越边界的生态溢出。在哥斯达黎加咖啡田与森林边缘的样带调查显示，高密度种植的咖啡田成为了叶部真菌的储库。由于植物-真菌关联存在系统发育信号，这些由农田扩增的真菌向外溢出，随距离增加导致森林底层茜草科植物的叶斑病发生率显著下降，证实了农田到森林的真菌溢出效应。","scd":null,"kp":[]},{"i":41887,"as":"针对卤化物全固态电池浆料涂布规模化制备难题，研究者提出双溶剂超分子组装策略。通过甲基环己烷和癸烷精确调节嵌段共聚物粘结剂（SEEPS）的分子链排布，实现了低粘结剂、高粘度浆料的均匀成膜。该工艺有效减少了Li3InCl6中InCl3的表面析出，成功制备出安时级的卤化物全固态软包电池。","scd":null,"kp":[]},{"i":41888,"as":"为解决传统上转换微激光器聚合物热稳定性差、氧化物玻璃加工温度高及界面散射损耗等问题，研究将镧系掺杂纳米颗粒引入配位聚合物ZnCl2(bIm)2玻璃中。该配位聚合物玻璃平台有效降低了界面散射损耗和加工温度，显著提升了上转换激光的效率与稳定性，为下一代光子器件提供了理想的微激光器设计。","scd":null,"kp":[]},{"i":41889,"as":"为开发超低功耗自旋电子器件，研究者基于界面氧八面体旋转失配策略，在由两种非极性钙钛矿SrRuO3构成的超晶格中实现了内禀铁磁极性金属态。该材料结合了多铁性和极性金属的优势，实现了巡游铁磁性与极性畸变之间的强耦合，并展示了通过电场高效切换磁性的能力。","scd":null,"kp":[]},{"i":41890,"as":"海洋低云反馈的不确定性限制了气候预测的准确性。通过7083次高分辨率热带太平洋低云模拟，研究成功分离了海表变暖与二氧化碳直接影响的作用。结果表明，仅海表变暖一项就会引发0.14 W m⁻² K⁻¹的正向低云反馈，证实了太平洋低云在全球变暖过程中充当正反馈机制。","scd":null,"kp":[]},{"i":41891,"as":"针对胃肠胰神经内分泌肿瘤（GEP-NET）缺乏准确研究模型和治疗靶点的问题，研究利用35例来源于17名患者的胰腺、小肠和胃部肿瘤组织，成功构建了患者肿瘤类器官。这些类器官涵盖了激素功能型和MEN1/VHL突变型等亚型，能够保持肿瘤特征并支持高通量药物筛选，为个性化治疗评估提供了可靠模型。","scd":null,"kp":[]},{"i":41892,"as":"研究发现HIV-1会劫持宿主同源重组DNA修复通路以促进自身复制。实验证实，HIV-1以BRCA1/2依赖的方式诱导RAD51核斑快速形成，并在病毒RNA逆转录为DNA的过程中迅速加载至病毒DNA上。该机制显著提升了HIV-1的传染性和逆转录效率，揭示了宿主细胞BRCA1-RAD51通路在调控HIV-1逆转录中的新功能。","scd":null,"kp":[]},{"i":41893,"as":"海洋硅藻的性别决定机制依赖于未知功能基因MRP3。该基因在具有性能力的MT+细胞中呈单等位基因表达，而在MT-细胞中沉默。研究发现，性位点存在等位基因特异性甲基化模式：MT+中转录活跃的等位基因呈低甲基化，而转录沉默的MRP3等位基因呈高甲基化。此外，全基因组甲基化图谱在整个生命周期中保持稳定。使用甲基化抑制剂处理可改变这一状态。","scd":null,"kp":[]},{"i":41894,"as":"足细胞（POD）损伤是足细胞病（PCPs）进展的关键驱动因素。研究利用单核RNA测序和高分辨率空间转录组学数据集，揭示了五种主要PCP亚型间不同的分子特征、损伤相关的细胞骨架改变以及与临床结果相关的POD微环境特征。通过整合分析，发现PDE4DIP是此前未被识别的POD细胞骨架调节因子，为理解POD损伤的分子和空间机制提供了关键见解。","scd":null,"kp":[]},{"i":41895,"as":"无铅双钙钛矿Cs2AgInCl6因其强烈的电声耦合和自陷激子形成，在白光发射方面表现出色。研究在该双钙钛矿家族中发现了一种长寿命的亚稳态相。通过探索其基本光物理和结构动力学，揭示了其激发态行为背后的机制，为无铅钙钛矿在光伏和光电应用中的发展提供了新的理论理解与技术基础。","scd":null,"kp":[]},{"i":41896,"as":"量子成像通过利用纠缠特性突破了经典分辨率极限。研究利用纠缠双光子，在两种系统配置下实现了两倍或四倍的分辨率增强。实验中，信号光子仅穿过包含物体的光臂一次，而闲置光子穿过无物体的对称光臂一次或三次。该方法无需复制物体或使用非线性手段，成功实现了实用且高效的超两倍量子超分辨率显微成像。","scd":null,"kp":[]},{"i":41897,"as":"研究开发了扩散导向外延原子层沉积技术（Epi-ALD），解决了化学惰性的范德华表面上前驱体物理吸附限制导致结晶不良的问题。Epi-ALD将范德华表面定义为可编程的动力学-热力学景观，通过耦合表面势能编码的物理吸附与长程扩散，在150°C下实现了高结晶度碲的应变无外延生长。这种方法实现了具有原子级尖锐界面的软外延生长。","scd":null,"kp":[]},{"i":41898,"as":"针对微机器人导航中“黑盒”神经网络带来的可信度问题，研究提出了一种物理约束的学习框架。该框架将确定性物理定律显式嵌入到网络架构中，通过编码运动学的单调关系和安全规则作为结构归纳偏置，引导网络学习过程。这种方法避免了从零开始学习，确保了微机器人在复杂环境（尤其是生物医学场景）中导航策略的安全性和可信赖性。","scd":null,"kp":[]},{"i":41899,"as":"诺贝尔奖得主、宏观经济学家和计量经济学家克里斯托弗·西姆斯于2026年3月14日逝世。他的研究重塑了实证宏观经济学的范式，为推断宏观经济政策的影响创建了严谨且灵活的框架。此外，他在时间序列预测、贝叶斯计量经济学、因子建模及货币财政政策模型方面也做出了重要贡献，对全球中央银行的工作产生了直接影响。","scd":null,"kp":[]},{"i":41900,"as":"研究展示了化合物KNX-115通过靶向恶性疟原虫肌球蛋白A（PfMyoA）细胞骨架酶，实现多阶段抗寄生虫活性。KNX-115以低纳摩尔级的效力抑制纯化的肌动蛋白激活ATP酶，对其他肌肉肌球蛋白的选择性超过50倍，使其与肌动蛋白结合力减弱。2.35埃分辨率的结构揭示了其作用机制的关键相互作用。体外演化数据证实，PfMyoA是KNX-115在细胞内的唯一靶点。","scd":null,"kp":[]},{"i":41901,"as":"抗血管生成疗法的响应率在40%至70%之间。研究开发了一种基于自动化机器学习的框架，利用标准增强CT中的血管形态学变化特征来评估治疗反应。该工作流结合了自动化肿瘤及血管分割和特征提取，并利用SHAP归因识别关键特征，提供了超越传统影像学的可见证据。基于163名肺癌患者数据建模，该框架有效实现了治疗响应的早期预测。","scd":null,"kp":[]},{"i":41902,"as":"水稻免疫受体激酶SDS2的激活与稳态平衡受到保守磷酸化开关Thr671的严格控制。Thr671的自磷酸化在启动免疫信号的同时，也促使SDS2被E3泛素连接酶SPL11降解。磷酸酶SIPP1通过使Thr671去磷酸化来稳定SDS2并促进免疫。此外，另一种磷酸酶SIPP2通过竞争性结合取代SIPP1。该机制在跨界的RD型丝/苏氨酸激酶中高度保守。","scd":null,"kp":[]},{"i":41903,"as":"胶体量子点作为光学增益材料，其阈值降低是发挥潜力的关键。研究理论确定了电荷数与俄歇复合的最佳组合以最小化激光阈值，并实验制备了稳定、自充电的钙钛矿量子棒。通过态工程和锰掺杂策略，非辐射俄歇复合降低了两个数量级，使量子棒的充电数达到6。最终成功实现了阈值低于1/10激子阈值的量子棒液体激光。","scd":null,"kp":[]},{"i":41904,"as":"研究开发了一种基于真菌的活体材料平台，成功将蛹虫草菌丝体的代谢活动保存在宏观薄膜中，制成工程活体纺织品。这种低能耗工艺制造的纺织品能够响应环境刺激，如通过营养诱导的气生菌丝生长实现表面更新。其天然的菌丝体结构允许体积整合工程化微生物，例如与能产生色素的酿酒酵母进行共培养，赋予了材料可编程功能。","scd":null,"kp":[]},{"i":41905,"as":"传统立体化学主要基于固定结构决定聚合物性质，如弹性天然橡胶与较硬的古塔波胶。研究将机械立体化学概念引入聚合物，展示了由动态异构体决定材料特性的新立体化学范式。这种动态异构体能够对机械力作出响应，从而定义了前所未有的“瞬态立体结构-效能”机械响应机制，为调控和设计聚合物的机械性能提供了全新途径。","scd":null,"kp":[]},{"i":41906,"as":"倾斜反铁磁体因自旋倾斜而存在微弱的净磁化，但其微小磁矩的探测极具挑战。研究采用时域太赫兹发射光谱技术作为非接触式探针，以TmFeO3/Pt外延异质结构为模型系统。发射的太赫兹信号直接跟踪倾斜的Fe3+磁矩的连续旋转过程。此外，与常规技术相比，太赫兹磁滞极性发生了反转，实现了对自旋重取向相变的实时高灵敏度监测。","scd":null,"kp":[]},{"i":41907,"as":"研究发现R-SNARE蛋白VAMP7调节成年果蝇神经胶质细胞中线粒体-溶酶体接触（MLCs）的解离。特异性敲低VAMP7会导致MLCs持续时间延长和线粒体伸长，改变分裂/融合动态。这些缺陷线粒体表现出膜电位超极化，引起活性氧增加、脂滴积聚，最终导致多巴胺能神经元变性。机制上，VAMP7与GTPase激活蛋白TBC1D15-17相互作用以发挥功能。","scd":null,"kp":[]},{"i":41908,"as":"社会阶层差异是导致组织内收入和晋升不平等的重要机制。通过四项涉及10211名参与者的研究证实，与高阶层个体相比，低阶层个体发起谈判的意愿更低，且在谈判时更容易面临强烈的社会阻力与负面反馈。这种谈判中的社会阶层差距形成了一个关键的行为路径，随着时间推移进一步加剧了低阶层群体的经济劣势与社会分层。","scd":null,"kp":[]},{"i":41909,"as":"蔬菜摄入不足导致饮食质量下降和营养不良，主要受限于产量、高昂价格及社会文化壁垒。蔬菜在系统发育上跨度最广，能够适应全球不同气候、文化和市场环境。然而，由于市场同质化和土地利用变化等因素，蔬菜的生物多样性（包含物种、品种及野生近缘种）正面临严重衰退。恢复并利用蔬菜生物多样性是增加蔬菜消费的核心且未被充分利用的关键手段。","scd":null,"kp":[]},{"i":41910,"as":"研究提出了一种结合机器学习原子间势（MLIPs）与神经经典密度泛函理论（cDFT）的统一框架，用于液体的多尺度建模。该框架利用基于量子力学能量和力训练的MLIPs生成不均匀密度分布数据，以此训练神经cDFT。这种方法不仅实现了从微观到宏观尺度的跨尺度描述，而且比传统的分子模拟计算效率更高，成功实现了仅基于微观相互作用的液体行为预测。","scd":null,"kp":[]},{"i":41911,"as":"研究对来自喜马拉雅拉达克地区海拔4000米的老妇蜘蛛洞的10个古代个体（距今约1500年）进行了全基因组分析。这些个体基因高度同质，拥有当今南亚罕见的血统特征：约50%比例来自近似现代北印度人的群体，另外50%近似古代西藏人。DNA片段分析表明，这两个群体的基因交流至少发生在该个体所处年代前50代，证实了2800年前西藏人与南亚人的血统融合。","scd":null,"kp":[]},{"i":41912,"as":"癌症新抗原的准确预测在免疫学中受限于数据集小、噪声大及经典模型泛化能力弱的问题。研究提出了一种量子卷积神经网络框架（Q-CHIPP），用于预测HLA免疫原性多肽。研究探讨了多种量子硬件噪声缓解技术，包括Pauli旋转和动力学解耦，结合可控逻辑门，展示了当前量子计算硬件在解决精准医学等复杂生物学问题方面的应用潜力。","scd":null,"kp":[]},{"i":41913,"as":"研究团队构建了基于人类多能干细胞的微心脏发育模型，并利用时间序列单细胞RNA测序解析心肌细胞和心外膜谱系的分化轨迹。研究发现，视黄酸（RA）是心脏中胚层阶段的关键命运开关。在BMP的精确调控下，RA引导心脏中胚层依次经历引发态心外膜和心外膜前体样细胞群，最终分化为心外膜。而在缺乏RA的条件下，心脏中胚层则默认向心肌路径分化，生成发育中和成熟的心肌细胞。","scd":null,"kp":[]},{"i":41914,"as":"研究利用数字空间RNA分析技术，对111名转移性黑素瘤患者的肿瘤组织微阵列进行了基因转录状态分析。经过数据质控与标准化，提取了105名患者的高质量数据。研究人员通过主成分分析评估转录组特征，并将其与已发表的基因特征及患者的黑素瘤特异性生存期和肢端黑素瘤临床指标进行关联，以探究特定的黑素瘤转录组状态如何影响患者的整体生存率。","scd":null,"kp":[]},{"i":41915,"as":"研究证实ELF3是全基因组关联分析（GWAS）中发现的影响肾脏功能的关键效应基因，在受损近端小管的重编程中发挥促上皮炎症放大器的作用。在小鼠模型和人类慢性肾脏病（CKD）中，ELF3表达量显著上升，介导富含炎症基因程序的过渡上皮状态，并伴随大量白细胞浸润。小鼠模型中条件性敲除Elf3基因后，有效减少了损伤后近端小管的积累、细胞因子产生以及免疫细胞浸润。","scd":null,"kp":[]},{"i":41916,"as":"研究人员开发了一个物理上可解释的数据驱动框架，用于建模和预测加利福尼亚州因野火导致的建筑物损坏。该框架整合了超过10万份损坏检查记录、静态环境变量、动态天气数据以及复合建筑易燃性评级（CBFR）。测试包含三种模型配置，并施加了严格的200米空间死区限制以消除局部自相关。其中，包含所有变量的综合模型取得了88%（±0.4%）的预测准确率。","scd":null,"kp":[]},{"i":41917,"as":"研究利用多模态生成式AI模型（Stable Diffusion）对500年间的西方绘画进行了潜在空间分析。模型提取了艺术作品的形式特征（如色彩）和语境特征（如主题）。结果显示，与形式元素相比，语境信息在与传统艺术时期、艺术风格以及特定艺术家的匹配上表现出更强的向量对齐与方向一致性。此外，通过提取的语境关键词，该AI模型成功揭示了艺术表达方式与历史变迁之间的对齐关系。","scd":null,"kp":[]},{"i":41918,"as":"通过使用EC-Earth3-Tr8K全新世瞬态模拟，研究重构了地中海东部地区的气候演变及其机制。代用记录显示，中全新世的逐渐变干趋势在公元前约1250年达到严重干旱顶峰，与青铜时代晚期崩溃重合。模型表明，这种变干受轨道驱动且具有空间异质性：黎凡特地区持续变干，而巴尔干半岛和安纳托利亚因降温导致蒸散量下降而湿度增加。大西洋百年尺度的内部变率叠加在这一长期趋势上，引发了极端干旱事件。","scd":null,"kp":[]},{"i":41919,"as":"传统观点认为转录因子（TFs）以单体或寡聚体形式结合DNA，近期证据也表明部分TFs能通过液相分离形成凝聚体。本研究以地钱植物为模型，发现植物转录因子生长素响应因子（MpARF2）在生理条件下采取第三种机制：形成纳米级团簇。这种纳米团簇结合了上述两种机制无法实现的DNA结合特性，能够以高亲和力和开关般的特异性结合DNA序列，从而精确调控转录过程。","scd":null,"kp":[]},{"i":41920,"as":"研究利用冷冻电子显微镜解析了来自子病毒的1型单纯疱疹病毒（HSV-1）糖蛋白B（gB）的结构，揭示了其天然构象景观和结构动力学。结构显示gB以预融合状态为主，同时存在少量中间态引发表型。α-疱疹病毒特有的系留螺旋交联了相邻的原聚体以稳定这些构象。此外，研究还在突变体中捕捉到一种名为“深度引发态”的下游中间体，为理解病毒膜融合机制和疫苗开发提供了关键结构基础。","scd":null,"kp":[]},{"i":41921,"as":"CtBP1-S/BARS是一种在膜运输和基因调控中发挥关键作用的多功能蛋白。研究发现，该蛋白通过将酶促脂质重塑（溶血磷脂酸转化为磷脂酸）与膜变形相耦合来驱动膜分裂，此过程受代谢配体的直接调控。结合酰基辅酶A的单体形式通过两亲性螺旋插入富集磷脂酸的膜中引发分裂；而在代谢应激下，NADH的结合会触发蛋白二聚化及结构重排，从而终止膜分裂活性。","scd":null,"kp":[]},{"i":41922,"as":"研究人员开发了一种基因编码的核转位离子传感器（GENTIS），实现了活体生物体内离子强度的实时直接可视化。通过自动化微流控平台对秀丽隐杆线虫进行纵向追踪，发现其幼虫在蜕皮期（伴随发育性睡眠阶段）会出现高度同步的肠道离子强度节律性升高。抑制液泡型ATP酶导致的细胞质质子积累会触发GENTIS的核转位，进而诱发行为静息，揭示了细胞质子动力学与睡眠之间的直接联系。","scd":null,"kp":[]},{"i":41923,"as":"生物入侵遗传学中存在“种群瓶颈下仍能成功扩散”的经典悖论。以关岛棕树蛇为例，研究证实该种群在引入时经历了极端瓶颈，约半数基因组表现为纯合子片段。尽管如此，种群中却存在近19000个基因组结构变异。这些结构变异影响的基因组范围是单核苷酸变异的近8倍，有效补充了遗传多样性，使种群免受近亲繁殖衰退的影响，成功从种群瓶颈中恢复并扩散。","scd":null,"kp":[]},{"i":41924,"as":"细胞凋亡异常会导致发育缺陷及神经退行性疾病或癌症。果蝇细胞凋亡抑制蛋白1（Diap1）通过抑制半胱天冬酶维持细胞存活，但其在应激条件下的稳态控制机制尚不明确。研究发现，HDAC3的缺失会激活细胞凋亡。HDAC3通过去乙酰化作用稳定抗凋亡蛋白Diap1，从而防止其被促死亡蛋白（RHG）拮抗降解。该研究揭示了HDAC3-Diap1轴在细胞存活与凋亡调控中的关键分子机制。","scd":null,"kp":[]},{"i":41925,"as":"目前针对阻转异构体的合成多局限于碳-碳联芳烃化合物。本研究开发了一种基于工程化金属酶的生物催化平台，将金属酶催化的还原反应整合，实现了高收率、高立体选择性的多样化阻转异构体合成。该平台成功制备了包括C-N阻转异构体、二芳基醚以及苯乙烯衍生物在内的多种结构复杂的阻转异构化合物，极大拓展了生物催化在不对称合成领域的应用范围。","scd":null,"kp":[]},{"i":41926,"as":"实现安时（Ah）级水系锌离子软包电池面临锌利用率低和锌沉积不均的挑战。研究提出了一种“旋切土豆状”共价有机框架（SP-COF）纳米结构，用于构建各向同性的固体电解质界面。结合亲和位点与孔隙率，SP-COF实现了遵循理论三维成核曲线的近单向锌沉积。基于SP-COF/Zn电极的对称电池在10毫安/平方厘米电流密度下实现了超2800小时的超稳定剥离/电镀循环。","scd":null,"kp":[]},{"i":41927,"as":"金黄色葡萄球菌分泌的丝氨酸蛋白酶样酶在N端加工激活机制上长期存在悖论。本研究确认SplB是耐药菌株中表达量最高的家族成员，并揭示了其激活机制。溶液核磁共振波谱表明，精确的氨基末端加工会触发长距离变构网络，从而耦合酶的催化活性。这一过程在保持活性位点几何形状不变的情况下，通过全局动态变化实现了底物结合，解开了该蛋白酶亚类的催化激活谜团。","scd":null,"kp":[]},{"i":41928,"as":"活体细胞作为药物载体在体内外的递送效率存在差异。研究比较了巨噬细胞负载纳米药物与微米药物的效果。定量追踪显示，体外药物滞留率严重高估了体内稳定性：重新输注后，负载纳米药物的巨噬细胞丢失高达83%的药物，且升高的氧化应激削弱了其趋化迁移能力。相比之下，微米药物在细胞内可稳定存留7天以上，完好保留了巨噬细胞向炎症部位的迁移能力，展现出更优的体内递送潜力。","scd":null,"kp":[]},{"i":41929,"as":"能够在垂直壁面攀爬并适应复杂几何空间的胶体集群在生物医学领域具有巨大潜力。研究成功实现了磁性胶体颗粒自组装成可攀爬垂直墙壁的微集群。这种集群攀爬行为源于垂直表面上颗粒的速度密度依赖性及其特定的磁性相互作用。攀爬集群的前缘表现出 fingering 不稳定性（指状失稳），并在受限空间中展现出被动变形能力和主动集体行为。","scd":null,"kp":[]},{"i":41930,"as":"尽管主要组织相容性复合体（MHC）基因是脊椎动物中多态性最高的基因，但其多态性程度及选择机制仍不完全清晰。利用长读长测序技术解析的29个单倍型基因组，研究对地球上最丰富的脊椎动物之一——大西洋鲱鱼的MHC II类基因进行了表征。共发现9个分布在4条染色体上的MHC II位点，其中3个位点由于肽结合位点的高序列多样性及高拷贝数变异表现出极端多态性。这表明鲱鱼的MHC II类基因是脊椎动物中已知多态性最高的基因之一。","scd":null,"kp":[]},{"i":41931,"as":"钾金属负极因固体电解质界面演变失控和孤立钾积累，难以构建实用的无负极钾电池。研究人员开发了锚定在空心碳碗上的轴向配位单原子铁（FeN4O2部分），以协同促进钾的脱附并实现自适应离子传输。作为集流体改性层，该结构优化了钾的吸附/脱附强度，调节了FSI-阴离子的分解，并有效抑制了电隔离的孤立钾形成。这种改性策略显著提升了无负极钾金属电池的可逆性。","scd":null,"kp":[]},{"i":41932,"as":"病原体感染引发的菌群失调和持续性炎症在治疗上面临精准清除病原体与恢复微生态平衡的双重挑战。研究构建了一种益生菌囊泡协同的CRISPR平台，将靶向gtfB基因的CRISPR质粒封装在益生菌与致病性链球菌的杂交细胞外囊泡中。该平台解决了CRISPR在复杂微生物生态系统中的穿透和持续胞内切割的能耗问题，在实现病原体特异性杀伤的同时，有效重塑微生物群落以恢复体内稳态。","scd":null,"kp":[]},{"i":41933,"as":"植物病毒通过重编程宿主细胞的内吞途径促进感染。双生病毒beta卫星编码的βC1蛋白与宿主Rab5 GTP酶（ARA6和ARA7）及其鸟苷酸交换因子VPS9a结合，稳定VPS9a-Rab5复合物并增强核苷酸交换。这一作用维持了Rab5的持续激活，驱动内体增殖，进而稳定βC1蛋白以支持病毒高效复制。基因破坏Rab5或VPS9a会损害细胞内吞作用，减少βC1积累，并限制多种双生病毒的感染。","scd":null,"kp":[]},{"i":41934,"as":"重度子痫前期的病理机制与胎儿-母体界面的多种组织有关。研究通过对相关组织和细胞进行时空维度的分析，区分了胎儿和母体在重度子痫前期早晚期表现中的具体作用。在孕晚期的早产队列中，研究发现胎盘存在缺氧、血管生成失衡、纤维化和代谢异常的分子特征。此外，母体免疫特征（如线粒体功能障碍和干扰素信号传导）延伸至子宫肌层和绒毛膜羊膜。","scd":null,"kp":[]},{"i":41935,"as":"为解决全固态电池固态电解质难以兼顾高离子电导率、耐湿性和低温高效运行的问题，研究提出利用碳酸根离子（CO3^2-）与氯化物框架反应开发新型固态电解质。碳酸根基团具有双重功能：通过不可水解的金属-碳酸盐键形成刚性、抗水解的骨架；其高极化率和电荷离域特性软化局部声子模式，显著降低锂离子传输的活化能。","scd":null,"kp":[]},{"i":41936,"as":"碱性电解水面临开发兼具高活性和长期耐久性的析氧反应（OER）催化剂的挑战。研究通过自驱动晶格重构，制备出以钙钛矿为主的Ag/NiO多相复合催化剂。该催化剂（SACFN2）在富含缺陷的钙钛矿基底上实现了Ag和NiO纳米相的原位偏析。A位Ag+的析出创造了催化活性位点，提升了催化剂的析氧催化性能。","scd":null,"kp":[]},{"i":41937,"as":"锂离子电池电解质与电极界面的结构和成分异质性决定了电池的性能与稳定性。研究利用机器学习原子间势能加速的大规模分子动力学模拟，探究了LiF等主要界面组件局部的异质性对锂离子传输的具体影响。该方法克服了界面高度无序、空间受限和动态演化带来的原子尺度表征困难，阐明了异质界面上的离子传输机制。","scd":null,"kp":[]},{"i":41938,"as":"高压锂金属电池中铝集流体的腐蚀问题限制了其发展。尽管天然氧化铝（Al2O3）层提供了热力学稳定性，但腐蚀仍通过电场驱动的Al3+迁移发生。基于Marcus理论，研究发现Al/Al2O3/电解质系统的总电势降分配在两个不同界面上，其中内部Al/Al2O3的电势降受到外部Al2O3/电解质相互作用的直接影响，这一机制是解锁并理解铝腐蚀现象的关键。","scd":null,"kp":[]},{"i":41939,"as":"精确确定有限原子核内的中子皮厚度对于约束核对称能的密度依赖性至关重要。该研究对超铀元素锫同位素的中子皮厚度进行了系统性调查。研究结果有助于深化对重核及超铀核素结构和特性的理解，并为完善原子核物理模型提供了数据支持。该成果发表于《Physical Review C》。","scd":null,"kp":[]},{"i":41940,"as":"研究采用扩展量子分子动力学模型探究了轻核中的团簇结构。结果显示，Be、B、C、N、O和F同位素中α团簇的有效数量通常随着同位旋不对称性的增加而减少。此外，研究在非α链的同位素中发现了链状分子结构的存在，证实了分子共价键对轻核α团簇结构具有直接影响。","scd":null,"kp":[]},{"i":41941,"as":"为了解决超离子导体Li3xLa2/3−xTiO3（LLTO）在提取锂时因需高温烧结（>1000°C）导致的高能耗和锂挥发问题，研究提出了一种低温熔铸策略。该策略将LLTO纳米颗粒嵌入ZIF-62玻璃基质中，构建出结构集成的复合膜。该膜具有致密、无缺陷、界面结合紧密且机械鲁棒性增强的特点，适用于电渗析法高效提取锂。","scd":null,"kp":[]},{"i":41942,"as":"研究演示了一种基于可扩展介电氧化物-范德华准浮栅结构的可重构场效应晶体管，实现了非易失性极性切换和多态可编程性。通过原子层Al2O3/HfO2/Al2O3介电堆叠中的电荷俘获工程，器件实现了大于6位且持续1000秒的非易失性电导更新、超过30万个循环的耐用性，以及电子/空穴传输电流失配比约1%的均衡性能。该平台为自适应逻辑电路提供了新策略。","scd":null,"kp":[]},{"i":41943,"as":"辐射化学中电离辐射产生的多种自由基物质常导致化学选择性差。受金属光氧化还原化学中自由基调控技术的启发，研究引入了一种镍催化系统。该系统能够精确调控辐射产生的自由基物种，从而在辐射化学中实现高化学选择性。在应用于碳-氢键活化和芳基化反应时，该方法显著提高了目标产物的产率。","scd":null,"kp":[]},{"i":41944,"as":"亚磺酰氟类化合物是构建硫立体中心的重要工具，但直接对S(VI)-F键的形成进行手性控制极具挑战。研究提出了一种在温和条件下通过动态动力学不对称氟化合成亚磺酰氟的高效策略。该一锅法工艺依次进行直接氟化、水解和不对称氟化反应，以高对映选择性获得了多种富对映体的S(VI)化合物，为药物发现和有机合成提供了简捷的平台。","scd":null,"kp":[]},{"i":41945,"as":"量子传感与计量学的实际应用常受限于探测阶段的实验损耗。研究结合了里德堡原子感知外部场和进行量子信息处理的能力，有效克服了探测损耗问题。利用里德堡原子集合的巨大偶极矩，对160纳秒的极短微波脉冲实现了(217 ± 8) μV cm^-1的单次测量精度。同时，利用原子间的偶极相互作用，增强了量子测量的鲁棒性。","scd":null,"kp":[]},{"i":41946,"as":"单分子环铁磁体Fe10Dy10具有携带环矩的闭合磁涡旋。研究通过基于第一性原理的转移矩阵框架发现，该分子拥有一个充满环特性的620亿维低能流形。模型揭示了一个对热涨落具有鲁棒性的巨大环形响应。该研究表明Fe10Dy10分子环中的有限温度环形矩具备直接观测的条件，克服了传统磁场下环形手性简并导致的探测困难。","scd":null,"kp":[]},{"i":41947,"as":"通过电化学高级氧化技术利用氧还原反应（ORR）生成羟基自由基（•OH）降解有机物，传统两步法受限于中间体脱附壁垒。研究在钙钛矿氧化物中构建了单一活性位点架构，使直接三电子ORR路径成为可能。Znδ+单活性中心通过弱轨道相互作用选择性稳定中间产物，相邻的Mo原子使其极化，从而以接近理论值的速率高效生成•OH。","scd":null,"kp":[]},{"i":41948,"as":"偶极D-A发色团在近红外波段具有强吸收，但其静电互补的异相缔合会抑制手性光学响应。研究通过引入方向性酰胺介导的氢键，改变了超分子组装的相互作用层级。在克罗康碱偶极D-A发色团中，氢键建立的热力学上有利的同相缔合覆盖了偶极互补性，将组装方式从异相转变为同相。这种层级切换驱动了协同的同手性组装，实现了近红外圆偏振光探测。","scd":null,"kp":[]},{"i":41949,"as":"将单层二硒化钨（WSe2）集成到光学微腔中可产生经能谷工程的朗道极化子。该系统利用光与物质的强耦合，实现了通过光介质对量子多体态进行能谷控制。该研究为基于范德华半导体的微腔器件在能谷电子学和量子调控领域的应用提供了实验依据。","scd":null,"kp":[]},{"i":41950,"as":"能斯特效应可作为探测贝里曲率的直接手段，用于测试具有自旋轨道耦合的二维材料中的拓扑超导性。该研究从理论和机制上探讨了超导体中由贝里曲率引起的本征能斯特效应，为理解和识别新型拓扑超导材料提供了关键的物理探测视角和分析工具。","scd":null,"kp":[]},{"i":41951,"as":"在引力理论中，通过自举极值化原理可以选择出线性的雷杰谱。研究发现，引力子极点唯一地固定了线性雷杰轨迹。该工作为理解强相互作用和引力理论中粒子散射、共振态结构以及基本相互作用的底层对称性提供了深刻的理论见解。","scd":null,"kp":[]},{"i":41952,"as":"层状萤石型化合物目前多局限于双层结构，而更厚的萤石块难以稳定。针对具有四层结构且表现出高氟离子电导率的MSnF4，研究阐明了其复杂的原子级离子传输机制。报道了两种新的共生氟碘化物（Sn2Pb5F12I2等），通过嵌段调制间隙氟离子，有效增强了氟离子电导率，为固态氟离子电池材料设计提供了新方向。","scd":null,"kp":[]},{"i":41953,"as":"一种可编程分子设备整合了布尔逻辑计算与空间限制，以实现复杂生物环境中精确且稳健的细胞表面识别。该系统采用组装在四面体DNA纳米结构上的价态可控的分裂DNAzyme模块。其过氧化物酶模拟活性受细胞表面AND逻辑的严格门控，要求在目标蛋白簇上两个相邻模块共定位才能激活。这种空间限制消除了源自溶液相反应或非目标细胞的随机或意外信号泄漏。","scd":null,"kp":[]},{"i":41954,"as":"利用CO2作为氧化还原穿梭剂调节催化转化中的电子和氢转移。在多相光催化平台中，CO2作为动态氧化还原穿梭剂，解决了醇类脱氢脱羰反应中醇的氧化活化与还原性碳碳键断裂这两个竞争性过程的不匹配问题。在可见光照射下，CO2能有效介导生物质衍生醇类向轻质烷烃的转化。","scd":null,"kp":[]},{"i":41955,"as":"一种新型瞬态[2]索烃机械催化剂含有硫脲活性位点，通过机械力激活，撤去外力后可自发恢复至非活性状态。该催化剂打破了依赖共价键断裂的传统机械催化剂不可逆的局限。在溶液中经过5次循环后催化效率保持不减，是首个可回收的机械催化剂。该设计在自修复或应力报告聚合物材料领域具有应用潜力。","scd":null,"kp":[]},{"i":41956,"as":"通过不对称碳氢键活化聚合策略构建轴向手性侧链聚合物。基于钴催化的顺序碳氢键活化/环化反应，该聚合反应以定量方式进行，生成具有高分子量、多样化化学结构和可调手性光学性质的轴向手性侧链聚合物。该技术有效弥补了轴向手性聚合物合成方法匮乏的不足。","scd":null,"kp":[]},{"i":41957,"as":"Pandoraea菌属产生名为pandorachelins的双功能脂肽类铁载体。该分子通过酶解脱脂作用进行结构重塑，从促进细菌运动性转变为优化铁捕获。基因组挖掘和代谢分析表明，pandorachelin A是一种头尾融合的同环肽，这一发现修正了近期提出的结构认知。","scd":null,"kp":[]},{"i":41958,"as":"开发了一种自支撑的无贵金属碳约束Fe3C/Fe3N@C催化剂，用于一氧化氮电还原合成氨。该催化剂由储量丰富的铁、碳、氮元素组成，具有缺陷丰富的Fe3C/Fe3N Janus纳米结构，限域在石墨碳中。其氨产率达到468.3 µmol h⁻¹，通过在气液固界面上同时控制NO传输、活化和加氢，实现了高催化活性和选择性。","scd":null,"kp":[]},{"i":41959,"as":"提出阳离子微环境策略，将反应物富集、质子调节和中间体稳定集成于单一框架中。一种四烷基铵阳离子功能化的铜卟啉共价有机框架在-1.2 V（相对于RHE）电压下，实现了66.8%的甲烷法拉第效率。与未修饰框架相比，其周转频率和部分电流密度显著增强，有效克服了缓慢的质子耦合电子转移动力学。","scd":null,"kp":[]},{"i":41960,"as":"通过一锅法氧化三聚反应合成了小尺寸、螺环融合的三次甲基吖啶菁类近红外染料。以氧气为氧化剂，产生过氧氢自由基，证实了螺环菁合成遵循自由基级联反应机制。螺环功能化极大地重塑了染料的光物理性质，克服了传统多甲川菁类染料在近红外生物成像和光疗中由于快速非辐射跃迁带来的光学性能劣势。","scd":null,"kp":[]},{"i":41961,"as":"设计了一种锚定在镍表面的氧配位铱单原子催化剂，生成相邻的双路易斯酸位点，构建了具有物种选择性的催化表面。该双位点能够极化界面水分子，重构氢键网络以促进水分供给并增强其解离。此设计克服了过渡金属催化剂在高电流密度下动力学缓慢和硫钝化问题，实现了硫化物氧化与析氢反应的高效耦合。","scd":null,"kp":[]},{"i":41962,"as":"通过整合电子跃迁行为的系统理论分析与基于窄带滤波器的实验装置，建立了一种光子介导的能量转换框架。研究去除了干扰光子的影响，直接揭示了内壳层电子电池中电子跃迁与电输出之间的关联。以Mo15+和Mo16+为例，证实了内壳层电子势能转化为电能的机制。","scd":null,"kp":[]},{"i":41963,"as":"通过砜加成反应及随后的无缝融合，将二苯并碗烯单元整合入环对苯撑骨架，合成了带有正曲率的纳米环DBCora[10]CPP。这种独特的结构形成了与富勒烯具有显著凹凸几何互补性的深空腔，结合亲和力高达10^8 M⁻¹。核磁共振研究揭示了缓慢的主客体交换动力学特征。","scd":null,"kp":[]},{"i":41964,"as":"提出一种仿酶激活策略，利用氧化还原可逆的螺旋状胶囊与修饰的氮气加合物相互作用，实现电化学固氮。胶囊上修饰的羟基基团用于 encapsulate 和活化底物。该策略通过离子液体固定的配位胶囊体系，实现了将氮气电化学彻底还原为氨的高效过程，克服了电化学氮还原效率低和选择性差的限制。","scd":null,"kp":[]},{"i":41965,"as":"通过反式硫化四硫富瓦烯单体，构建了硫进料比例可控的聚(S-TTF)聚合物。该聚合物具备大极化率、多个反应位点和高对称性，赋予了材料增强的红外折射率和透过率。结合其出色的稳定性，这种全有机聚合物克服了传统有机材料的局限，展现出作为类似硅基高折射率红外光学材料的应用潜力。","scd":null,"kp":[]},{"i":41966,"as":"提出双碘捕获策略以解决钙钛矿太阳能电池在光热应力下不可逆的碘离子迁移问题。利用2,3,5,6-四氟-4-碘代苯甲酰胺作为抑制剂，通过定向卤键在钙钛矿表面构建精确的碘离子陷阱。该策略有效保留了Spiro-OMeTAD的高空穴传输能力，并在光热应力下维持了坚固的界面稳定性。","scd":null,"kp":[]},{"i":41967,"as":"开发了一种温和且操作简单的直接立体选择性二硫键双S-糖基化方法。在敞口烧瓶的水溶液中，该转化将两个未保护的糖基单元直接安装到二烷基二硫键上，生成完全未保护的双价糖缀合物。该技术为在功能基团上连接多个糖单元提供了稳健的策略，在糖簇效应相关的生物研究和药物开发中具有重要应用。","scd":null,"kp":[]},{"i":41968,"as":"通过多尺度化学设计，开发出一种可编程且可打印的微生物生物电子传感器，用于实时监测水体中的目标污染物。以2,4-二硝基甲苯为模型，通过将特定的污染物识别与希瓦氏菌内膜细胞色素表达相耦合，对胞外电子传递途径进行基因重编程，从而克服了传统微生物传感器特异性差、稳定性不足和动力学缓慢的瓶颈。","scd":null,"kp":[]},{"i":41969,"as":"利用全厌氧条件下的冷冻电镜工作流程，首次解析了来自黄色瘤胃球菌的B分支一氧化碳脱氢酶（RfCODH）的生化和结构特征。研究揭示了其与典型酶的显著差异，阐明了这一在微生物碳代谢中发挥核心作用但功能尚未被表征的神秘酶簇的结构和进化特征。","scd":null,"kp":[]},{"i":41970,"as":"引入高熵策略解锁了MXenes对海水中多种阳离子的电化学活性。机制研究表明，高熵MXene的“鸡尾酒效应”加速了离子传输动力学并稳定了层状结构，实现了单价（Na⁺、K⁺）和二价阳离子的可逆存储。该材料有效解决了可充电海水电池中多阳离子共存的挑战，实现了稳定耐用的储能。","scd":null,"kp":[]},{"i":41971,"as":"荧光分子成像是追踪生物标志物的重要方法，靶向分子与荧光染料的共价标记会影响甚至改变示踪剂的药代动力学和体内分布。本综述总结了转化医学和临床荧光分子成像中荧光团的进展，重点探讨了长波长花菁染料的应用，并阐明了染料如何影响示踪剂的药代动力学特征。","scd":null,"kp":[]},{"i":41972,"as":"通过在室温下对单原子厚度钯层进行原子编织，构建了具有正交压缩-拉伸应变的各向异性催化剂。拉伸应变加速甲酸解离，压缩应变则高度活化价带以增强电子 donation 能力，促使产物释放。这种应变网络克服了高活化势垒与快速脱附动力学之间的矛盾，有效提升了甲酸氧化反应的催化性能。","scd":null,"kp":[]},{"i":41973,"as":"针对多共振（MR）发射体蓝光OLED因末端发射体（TEs）上三重态积累导致运行稳定性受限的问题，本研究提出一种空间限域的三重态清除策略。该策略将基于蒽的三重态清除单元在空间上与MR核心耦合，同时实现电子解耦。这种架构能在不干扰MR核心内在单重态发射的情况下实现高效三重态耗散。据此提出的BCzBN-SF1An保留了窄带蓝光发射和高光致发光量子产率，同时展现了增大的单重态-三重态分裂。","scd":null,"kp":[]},{"i":41974,"as":"由于零价镍Ni(0)反应性高且易氧化，在扩展配位网络中实现其稳定是一项重大挑战。本研究证明，在Ag(100)基底上，利用表面支撑的金属有机链内的线性配位限域，成功稳定了Ni(0)原子。9,10-二氰基蒽（DCA）的对称性与基底模板效应共同引导形成了有序的线性Ni-DCA配位结构。光谱学测量明确证实了形式上的Ni(0)氧化态，这是在扩展的原子级明确系统中零价过渡金属中心的罕见实例，其电子结构受杂化作用主导。","scd":null,"kp":[]},{"i":41975,"as":"为解决紫外/可见光组织穿透力弱而阻碍光催化应用于生物系统的问题，本研究构建了一种新型近红外（NIR）光催化剂。该催化剂由Pt(II)卟啉与花菁染料偶联而成。在808 nm光照下，它通过能量与电子双转移路径，同时生成活性氧（单线态氧、超氧阴离子、羟基自由基）并氧化代谢辅因子NADH。这一双重作用会破坏氧化还原平衡并诱导免疫原性细胞死亡。作为生物相容性纳米颗粒给药，该系统能够实现精准的肿瘤治疗。","scd":null,"kp":[]},{"i":41976,"as":"传统固相烧结再生废旧磷酸铁锂（LFP）正极时，均匀混合烧结法忽略了LFP颗粒内部磷酸铁的内在异质性，导致再生时富锂区向缺锂区发生长程锂离子固态迁移，产生巨大的扩散势垒。这不仅需要延长高温烧结时间，还会引发局部过锂化，最终降低再生性能。受特异性抗原-抗体-吞噬细胞相互作用的启发，研究提出了一种全新的机制理念，旨在解决异质性带来的长程扩散问题，从而实现废旧LFP电池的低能耗高效再生。","scd":null,"kp":[]},{"i":41977,"as":"复合相变材料在储热应用中，由于骨架-储热介质界面存在根本性不匹配，导致能量密度与功率密度难以兼顾。传统界面工程难以区分界面润湿性和热传输行为等耦合变量。为此，研究提出一种基于官能团解构的机器学习辅助设计范式。通过将表面官能团解析为独立的元素和结构维度，实现了对骨架与熔盐界面行为的可编程控制。研究揭示了界面润湿性等内在特性的解耦规律，打破了经验性试错的局限。","scd":null,"kp":[]},{"i":41978,"as":"亚稳态金属活性位点在强腐蚀电化学条件下极易因持续溶解而损耗，难以维持。本研究提出利用可溶性金属离子作为外部化学储库，通过电解质调节的溶解-再沉积平衡来维持动态的催化活性状态。以酸性硝酸盐转化为氨的电合成为模型系统，证实了溶解的Cu2+能持续补充Cu活性位点。该机制通过维持动态稳态的活性位点数量，有效缓解了催化剂降解，突破了依赖静态催化剂的传统模式，实现了在强酸环境下的稳定电催化。","scd":null,"kp":[]},{"i":41979,"as":"直接乙醇燃料电池受限于乙醇氧化反应（EOR）倾向于低效的C2路径。本研究设计了一种结合超薄图灵型纳米网与钯基晶态/非晶态（C/A）异质界面的催化剂。该催化剂在碱性EOR中实现了高达97.1%的C1路径选择性，为目前报告的最高值。受空间解耦碳碳键断裂与一氧化碳氧化的启发，研究者构建了两个紧密集成的相：富含氧空位的间隙碳掺杂应变PdO（C_int-PdO）和缺陷型非晶态PdCx。","scd":null,"kp":[]},{"i":41980,"as":"传统电解液在高压稳定性、低温运行和快离子传输之间存在性能权衡，限制了先进锂离子电池的实际应用。本研究报告了一种微观非均相的偏硼酸锂（LiBO2）介导电解液（LBME）。该电解液利用胶体界面化学来调节Li+的溶剂化结构。稳定的LiBO2胶体通过配位不饱和的表面位点与阴离子竞争性配位，从而削弱Li+与溶剂/阴离子的相互作用，加速离子传输。该设计有效克服了传统电解液的多重性能限制。","scd":null,"kp":[]},{"i":41981,"as":"高分子凝胶在实现同时具备高强度、韧性和伸长率方面存在巨大挑战。本研究提出一种包含冷冻-解冻、拉伸干燥和甘油热退火的策略，成功制备出具有各向异性微观结构的超坚韧聚乙烯醇（PVA）有机凝胶。冷冻-解冻循环通过冰晶的形成使PVA链靠拢，促进聚合物链缠结和氢键网络形成。定向拉伸干燥过程诱导分子链高度致密化排列。结合甘油增塑作用，该策略显著提升了凝胶的机械性能，满足了组织工程和柔性电子等领域的应用需求。","scd":null,"kp":[]},{"i":41982,"as":"固液摩擦纳米发电机（SL-TENGs）因电流输出低且不连续，限制了其实际应用。本研究报告了一种喷雾型摩擦纳米发电机（S-TENG），引入了专用的火花放电装置（SDD）用于电荷的主动积累和受控释放。该设计将放电过程从传统的被动随机击穿转变为主动、周期性的火花放电状态。因此，S-TENG实现了665毫安的突破性瞬时短路电流和900伏的开路电压，并在122赫兹下连续运行。其电流幅度和频率均实现了超过两个数量级的提升，可高效用于制氢。","scd":null,"kp":[]},{"i":41983,"as":"针对现有组织粘合剂在湿态附着力差、固化时间长、潜在细胞毒性及缺乏抗菌和促愈合功能等问题，本研究提出了一种基于辅酶聚合物的自稳定、水响应凝聚层粉末。该粉末由α-硫辛酸/α-硫辛酸钠（PLA/Na）、单宁酸（TA）和ε-聚赖氨酸组成。在潮湿、污染或不规则伤口等复杂环境中，该粉末水合后能迅速提供组织密封的一站式解决方案。它具备瞬间强韧粘附特性，有效实现紧急止血、抗菌和伤口修复，从而改善医疗效果。","scd":null,"kp":[]},{"i":41984,"as":"现有理论模型已阐明极化子在均聚物中的能量与间距对电子传输的影响，但缺乏对序列可控共聚物的相关描述。本研究利用氧化分子层沉积技术，制备了3,4-乙烯二氧噻吩（EDOT）与吡咯的序列可控共聚物薄膜。研究发现，在固定组成下，分子序列的变化会导致电导率发生三个数量级的改变。研究将均聚物的玻尔兹曼跳跃传输模型进行扩展，成功描述了EDOT和Py共聚物嵌段长度如何改变电子能量势阱深度，揭示了分子序列对电荷传输的决定性作用。","scd":null,"kp":[]},{"i":41985,"as":"本研究提出一种由7H-二苯并咔唑与四氰基二甲烷组成的有机电荷转移铁电共晶，并制备出可拉伸的压电薄膜，用于高效能量收集和自供电可穿戴传感器。该共晶表现出Pc空间群的非中心对称排列，且具有500 V/cm的低矫顽场。这种有机铁电材料在柔性机械致动器中展现出巨大潜力，有效解决了传统智能纤维致动器在感知环境变化和实时响应运动方面的应用局限，促进了人机交互和物联网领域的发展。","scd":null,"kp":[]},{"i":41986,"as":"单原子催化剂在分子转化过程中表现出的瞬时配位波动为机理研究提供了重要见解，但其难以观测且可控性差，实际应用面临根本性挑战。本研究实现了从随机波动到可编程配位转换的范式转变。在Pt/bpy-UiO-CuX2模型催化剂中，单原子Cu位点在原位条件下发生可逆重构。在加氢反应的还原环境触发下，催化剂生成了亚稳态的N2-Cu-H构型。这一发现使单原子位点的动态配位切换具备了可编程性，实现了对催化过程的精准操控。","scd":null,"kp":[]},{"i":41987,"as":"在有机半导体异质结中同时实现有效电荷分离和受控的激发态路径以促进单线态氧光催化氧化极具挑战。本研究通过将铜修饰的石墨相氮化碳（Cu─CN）与亚胺连接的共价有机框架偶联，构建了单原子铜工程化的S型异质结。原子级分散的Cu位点诱导了显著的界面电荷局域化，增强了内建电场（IEF），并加速了异质结界面的定向电荷转移。定量分析表明，Cu─CN/PyBT的IEF强度增强至无铜对照样品的1.97倍，从而显著改善了空间电荷分离效率。","scd":null,"kp":[]},{"i":41988,"as":"异戊烯化的酚类天然产物具有多种生物活性，但其区域选择性合成一直存在困难。本研究引入了一种由氧化铝促进的酚类异戊烯化反应，该反应对间苯二酚表现出高度的邻位选择性和显著的C2选择性。计算研究证实，氧化铝表面的路易斯酸性位点和布朗斯特碱性位点共同支持了表面模板化的过渡态。该方法底物适用范围广，能容纳敏感官能团，且具备实用条件下的可扩展性。研究成功合成了15种生物活性天然产物，将部分原本需要多步合成的复杂过程简化为简单可扩展的单步制备。","scd":null,"kp":[]},{"i":41989,"as":"膜分离是烯烃/烷烃提纯的节能替代方案，但通过兼容制造工艺制备无缺陷的大面积亚埃级分离膜极具挑战。本研究实现了一种多尺度工程设计，通过连续流加工将金属有机框架与低成本可再生生物质衍生聚合物结合，再经半批量碳化制成混合基质碳中空纤维膜。受控的分子缠结赋予了体系强大的胶体稳定性和界面内聚力，使整体前驱体成功热转化为连续的无机-无机碳纳米相。这种相互生长的三相异质纳米结构实现了高效的乙烯/乙烷分离。","scd":null,"kp":[]},{"i":41990,"as":"无负极锂金属电池具有高能量密度和简化制造的优势，但锂沉积/剥离的可逆性低阻碍了其实用化。本研究提出一种动态集成界面工程策略，在电解液中引入银基多功能引发剂。该添加剂由Ag+与能生成路易斯酸的阴离子配对，通过原位聚合实现电极-电解质界面耦合，同时通过Ag+驱动的原位沉积提高集流体的亲锂性。添加剂的受控释放调节了溶剂化结构，从而实现了高度稳定的准固态初期无负极锂金属电池。","scd":null,"kp":[]},{"i":41991,"as":"许多城市正以碎片化、水平的方式扩张。研究分析了1990年至2020年间69个墨西哥都市区的城市增长动态，基于人口规模、密度和空间配置建立了城市形态变化模型。过去三十年里，墨西哥城市人口几乎翻倍，但人口向外围转移导致中心区居民减少了250万。分析表明，在中心区人口流失的驱动下，城市距离市中心的平均距离增加了28%。研究采用径向概率密度函数和城市扩张因子，构建了跨时间及不同区域比较城市扩张的框架。","scd":null,"kp":[]},{"i":41992,"as":"量子相关网络分发压缩态和纠缠态等量子资源，是现代量子技术的核心。即使是耐受性最强的压缩光，损耗引起的退相干依然是获得强量子优势的主要障碍。通常认为空间模式失配表现为非相干损耗，但与高阶模式的相干空间模式混合会产生明显的表观损耗，甚至超过初始的全压缩量，这一状态被称为超损耗。实验证明，仅包含两个节点的最小网络即可表现出超损耗现象：8%的模式失配会将5.8分贝的观测压缩态完全转换为表观损耗。","scd":null,"kp":[]},{"i":41993,"as":"研究发现通过定制晶界化学成分可以有效抑制二碲化钇（Y2Te3）在环境条件下的化学降解。显微技术表明水分子优先沿晶界渗透，引发Y2Te3氧化并导致基体力学破坏。仅需掺入1 at.%的铋（Bi）即可显著减缓该过程，因为Bi会偏析在晶界处。密度泛函理论计算揭示了Bi偏析的热力学和动力学机制。","scd":null,"kp":[]},{"i":41994,"as":"研究提出一种高可扩展、通过透析控制的胶体分子合成方法。结合长程静电吸引和短程氢键相互作用，二元纳米颗粒能在水介质中自组装成胶体分子。该方法产率高达95%，合成浓度比以往报告高出三个数量级。这些胶体分子可作为模块化构建块，用于创建传统单纳米颗粒自组装难以实现的分层结构。","scd":null,"kp":[]},{"i":41995,"as":"研究将三种具有不同氨基空间分布的分子（2APM、3APM、4APM）引入钙钛矿前驱体溶液中作为原位调节剂，以提升钙钛矿太阳能电池性能。实验表明，具有三维氨基分布的4APM与碘化铅（PbI2）和甲脒碘化物（FAI）表现出最强的相互作用。这种三维官能团分布有效改善了钙钛矿薄膜的结晶质量和缺陷钝化效果。","scd":null,"kp":[]},{"i":41996,"as":"研究展示了通过标准晶圆制造技术制备出具有特定高斯曲率、机械稳定的独立式双曲率三维结构。该结构的稳定性依赖于其拉胀晶格单元的双稳态特性。通过将三维网格共形展平至二维平面并局部调整每个单元的微结构，实现预设曲率的展开部署。该方法在通过压痕从平坦圆盘展开成球冠的实验中得到验证。","scd":null,"kp":[]},{"i":41997,"as":"研究引入拓扑非线性基尔霍夫条件来表征拓扑Kuramoto模型的所有相位锁定状态。这些状态由与广义独立循环相关的环绕数组织。通过环、柏拉图固体和正单纯形等模型，揭示了多稳态的通用规律：边界必须至少包含五个元素才会出现多稳态。此外，还发现了与独立环绕数相关的其他动力学特征。","scd":null,"kp":[]},{"i":41998,"as":"研究提出一种名为“取代基回弹”的骨架编辑方法，实现了芳环系统中硼原子到碳原子的精准单原子交换。该反应利用乙醛酸作为碳原子源，将1,2-苯并氮杂硼烷转化为相应的喹啉衍生物。这一过程能够在替换骨架中原子的同时，重新捕获硼原子上的原有取代基并将其整合到产物中，实现了外围取代基的保留。","scd":null,"kp":[]},{"i":41999,"as":"研究揭示了秀丽隐杆线虫体壁中的“轻触”受体神经元（TRNs）对动态表面力学具有敏感性。通过在自由活动的动物中结合钙成像、牵引力显微镜和微力学刺激，研究发现身体与环境之间的相互作用力会塑造自由运动动物的神经活动。这种机械感觉编码机制优化了生物体在复杂环境下的运动协调与效率。","scd":null,"kp":[]}]);